{"code":"import { useEffect, useState } from "react";

interface Shift {
  id: number;
  date: string;
  startTime: string;
  endTime: string;
  location: string;
  claimedBy?: string;
}

export function ShiftClaimBoard() {
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchShifts();
  }, []);

  const fetchShifts = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/shifts-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch shifts: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setShifts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleClaimShift = async (id: number) => {
    try {
      const response = await fetch(`/api/shifts-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ claimedBy: "current-user" }),
      });

      if (!response.ok) {
        throw new Error(`Failed to claim shift: ${response.status} ${response.statusText}`);
      }

      // Refresh the shifts list
      await fetchShifts();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDeleteShift = async (id: number) => {
    try {
      const response = await fetch(`/api/shifts-api/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error(`Failed to delete shift: ${response.status} ${response.statusText}`);
      }

      // Refresh the shifts list
      await fetchShifts();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (shifts.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No open shifts available.
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Open Shifts</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {shifts.map((shift) => (
          <div 
            key={shift.id} 
            style={{ 
              border: "1px solid #ccc", 
              borderRadius: "8px", 
              padding: "15px", 
              display: "flex", 
              justifyContent: "space-between", 
              alignItems: "center", 
              flexWrap: "wrap"
            }}
          >
            <div style={{ flex: "1", minWidth: "200px" }}>
              <p><strong>Date:</strong> {shift.date}</p>
              <p><strong>Time:</strong> {shift.startTime} - {shift.endTime}</p>
              <p><strong>Location:</strong> {shift.location}</p>
              {shift.claimedBy && (
                <p><strong>Claimed by:</strong> {shift.claimedBy}</p>
              )}
            </div>
            <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
              {!shift.claimedBy && (
                <button 
                  onClick={() => handleClaimShift(shift.id)}
                  style={{ 
                    backgroundColor: "#007bff", 
                    color: "white", 
                    border: "none", 
                    borderRadius: "4px", 
                    padding: "8px 12px", 
                    cursor: "pointer"
                  }}
                >
                  Claim Shift
                </button>
              )}
              <button 
                onClick={() => handleDeleteShift(shift.id)}
                style={{ 
                  backgroundColor: "#dc3545", 
                  color: "white", 
                  border: "none", 
                  borderRadius: "4px", 
                  padding: "8px 12px", 
                  cursor: "pointer"
                }}
              >
                Delete Shift
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface Walk {
  id: string;
  date: string;
  time: string;
  duration: number;
  status: "pending" | "accepted" | "declined";
}

export function WalkBookingView() {
  const [walks, setWalks] = useState<Walk[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [newWalk, setNewWalk] = useState({
    date: "",
    time: "",
    duration: 30,
  });

  useEffect(() => {
    fetchWalks();
  }, []);

  const fetchWalks = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/walks-api/");
      if (!response.ok) throw new Error("Failed to fetch walks");
      const data = await response.json();
      setWalks(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    } finally {
      setLoading(false);
    }
  };

  const handleBookWalk = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/walks-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newWalk),
      });
      if (!response.ok) throw new Error("Failed to book walk");
      await fetchWalks();
      setNewWalk({ date: "", time: "", duration: 30 });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
  };

  const handleAccept = async (id: string) => {
    try {
      const response = await fetch(`/api/walks-api/accept/${id}`, {
        method: "PUT",
      });
      if (!response.ok) throw new Error("Failed to accept walk");
      await fetchWalks();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
  };

  const handleDecline = async (id: string) => {
    try {
      const response = await fetch(`/api/walks-api/decline/${id}`, {
        method: "PUT",
      });
      if (!response.ok) throw new Error("Failed to decline walk");
      await fetchWalks();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/walks-api/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) throw new Error("Failed to delete walk");
      await fetchWalks();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  return (
    <div style={{
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      maxWidth: "600px",
      margin: "0 auto",
      padding: "20px",
    }}>
      <h1 style={{ textAlign: "center" }}>Walk Booking</h1>

      <h2>Book a New Walk</h2>
      <form onSubmit={handleBookWalk} style={{ marginBottom: "30px" }}>
        <div style={{ marginBottom: "10px" }}>
          <label>Date: </label>
          <input
            type="date"
            value={newWalk.date}
            onChange={(e) => setNewWalk({...newWalk, date: e.target.value})}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label>Time: </label>
          <input
            type="time"
            value={newWalk.time}
            onChange={(e) => setNewWalk({...newWalk, time: e.target.value})}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label>Duration (minutes): </label>
          <input
            type="number"
            min="15"
            max="120"
            value={newWalk.duration}
            onChange={(e) => setNewWalk({...newWalk, duration: parseInt(e.target.value) || 30})}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>
        <button
          type="submit"
          style={{
            backgroundColor: "#007bff",
            color: "white",
            padding: "10px 20px",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer",
          }}
        >
          Book Walk
        </button>
      </form>

      <h2>Your Walks</h2>
      {error && <p style={{ color: "red" }}>Error: {error}</p>}

      {walks.length === 0 ? (
        <p>No walks booked yet.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {walks.map((walk) => (
            <div key={walk.id} style={{
              border: "1px solid #ddd",
              borderRadius: "8px",
              padding: "15px",
              backgroundColor: "#f9f9f9",
            }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <strong>{walk.date}</strong> at {walk.time} ({walk.duration} mins)
                  <br />
                  Status: {walk.status}
                </div>
                <div style={{ display: "flex", gap: "5px" }}>
                  {walk.status === "pending" && (
                    <>
                      <button
                        onClick={() => handleAccept(walk.id)}
                        style={{
                          backgroundColor: "#28a745",
                          color: "white",
                          border: "none",
                          padding: "5px 10px",
                          borderRadius: "4px",
                          cursor: "pointer",
                        }}
                      >
                        Accept
                      </button>
                      <button
                        onClick={() => handleDecline(walk.id)}
                        style={{
                          backgroundColor: "#dc3545",
                          color: "white",
                          border: "none",
                          padding: "5px 10px",
                          borderRadius: "4px",
                          cursor: "pointer",
                        }}
                      >
                        Decline
                      </button>
                    </>
                  )}
                  <button
                    onClick={() => handleDelete(walk.id)}
                    style={{
                      backgroundColor: "#6c757d",
                      color: "white",
                      border: "none",
                      padding: "5px 10px",
                      borderRadius: "4px",
                      cursor: "pointer",
                    }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface Withdrawal {
  id: number;
  item_id: number;
  quantity: number;
  status: "pending" | "approved" | "rejected";
  created_at: string;
}

interface InventoryItem {
  id: number;
  name: string;
  quantity: number;
  unit: string;
}

export function ApprovalQueue() {
  const [withdrawals, setWithdrawals] = useState<Withdrawal[]>([]);
  const [inventoryItems, setInventoryItems] = useState<InventoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchAllData() {
      try {
        setLoading(true);
        const [withdrawalsRes, inventoryRes] = await Promise.all([
          fetch("/api/inventory-api/withdrawals?status=pending"),
          fetch("/api/inventory-api/inventory"),
        ]);

        if (!withdrawalsRes.ok || !inventoryRes.ok) {
          throw new Error("Failed to fetch data");
        }

        const withdrawalsData = await withdrawalsRes.json();
        const inventoryData = await inventoryRes.json();

        setWithdrawals(withdrawalsData);
        setInventoryItems(inventoryData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchAllData();
  }, []);

  const handleApprove = async (id: number) => {
    try {
      const res = await fetch(`/api/inventory-api/withdrawals/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "approved" }),
      });

      if (!res.ok) {
        throw new Error("Failed to approve withdrawal");
      }

      // Refresh data
      const [withdrawalsRes, inventoryRes] = await Promise.all([
        fetch("/api/inventory-api/withdrawals?status=pending"),
        fetch("/api/inventory-api/inventory"),
      ]);

      if (!withdrawalsRes.ok || !inventoryRes.ok) {
        throw new Error("Failed to refresh data after approval");
      }

      const withdrawalsData = await withdrawalsRes.json();
      const inventoryData = await inventoryRes.json();

      setWithdrawals(withdrawalsData);
      setInventoryItems(inventoryData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleReject = async (id: number) => {
    try {
      const res = await fetch(`/api/inventory-api/withdrawals/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "rejected" }),
      });

      if (!res.ok) {
        throw new Error("Failed to reject withdrawal");
      }

      // Refresh data
      const [withdrawalsRes, inventoryRes] = await Promise.all([
        fetch("/api/inventory-api/withdrawals?status=pending"),
        fetch("/api/inventory-api/inventory"),
      ]);

      if (!withdrawalsRes.ok || !inventoryRes.ok) {
        throw new Error("Failed to refresh data after rejection");
      }

      const withdrawalsData = await withdrawalsRes.json();
      const inventoryData = await inventoryRes.json();

      setWithdrawals(withdrawalsData);
      setInventoryItems(inventoryData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const getInventoryName = (itemId: number) => {
    const item = inventoryItems.find(i => i.id === itemId);
    return item ? item.name : "Unknown Item";
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (withdrawals.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No pending withdrawals to approve.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Pending Withdrawals</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {withdrawals.map((withdrawal) => (
          <div
            key={withdrawal.id}
            style={{
              border: "1px solid #ccc",
              borderRadius: "8px",
              padding: "15px",
              display: "flex",
              flexDirection: "column",
              gap: "10px",
            }}
          >
            <div>
              <strong>{getInventoryName(withdrawal.item_id)}</strong>
            </div>
            <div>
              Quantity: {withdrawal.quantity}
            </div>
            <div>
              Requested on: {new Date(withdrawal.created_at).toLocaleDateString()}
            </div>
            <div
              style={{
                display: "flex",
                justifyContent: "flex-end",
                gap: "10px",
                flexWrap: "wrap",
              }}
            >
              <button
                onClick={() => handleApprove(withdrawal.id)}
                style={{
                  backgroundColor: "#4CAF50",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  padding: "8px 16px",
                  cursor: "pointer",
                }}
              >
                Approve
              </button>
              <button
                onClick={() => handleReject(withdrawal.id)}
                style={{
                  backgroundColor: "#f44336",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  padding: "8px 16px",
                  cursor: "pointer",
                }}
              >
                Reject
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import {
  deleteReservation,
  getAllReservations,
  getReservationById,
  insertReservation,
  updateReservation
} from "../db/reservations-table";

export const router = Router();

// Get all reservations
router.get("/", (req: Request, res: Response) => {
  try {
    const reservations = getAllReservations();
    res.json(reservations);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservations" });
  }
});

// Get a reservation by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const reservation = getReservationById(id);
    if (!reservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    res.json(reservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservation" });
  }
});

// Create a new reservation
router.post("/", (req: Request, res: Response) => {
  try {
    const { memberId, plotId, startDate, endDate } = req.body;

    if (!memberId || !plotId || !startDate || !endDate) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const id = insertReservation(memberId, plotId, startDate, endDate);
    res.status(201).json({ id });
  } catch (error) {
    res.status(500).json({ error: "Failed to create reservation" });
  }
});

// Update a reservation
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const { memberId, plotId, startDate, endDate } = req.body;

    if (!memberId || !plotId || !startDate || !endDate) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    updateReservation(id, memberId, plotId, startDate, endDate);
    res.json({ message: "Reservation updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update reservation" });
  }
});

// Delete a reservation
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    deleteReservation(id);
    res.json({ message: "Reservation deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete reservation" });
  }
});
"}

