      return res.status(400).json({
        error: "Missing required fields: roomId, startDate, endDate, bookerId"
      });
    }

    const room = getRoomById(Number(roomId));
    if (!room) {
      return res.status(404).json({ error: "Room not found" });
    }

    const newId = insertBooking(
      Number(roomId),
      startDate,
      endDate,
      Number(bookerId)
    );

    res.status(201).json({ id: newId });
  } catch (error) {
    res.status(500).json({ error: "Failed to create booking" });
  }
});

// Update a booking
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { roomId, startDate, endDate, bookerId } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    if (!roomId || !startDate || !endDate || !bookerId) {
      return res.status(400).json({
        error: "Missing required fields: roomId, startDate, endDate, bookerId"
      });
    }

    const existingBooking = getBookingById(id);
    if (!existingBooking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    updateBooking(
      id,
      Number(roomId),
      startDate,
      endDate,
      Number(bookerId)
    );

    res.json({ message: "Booking updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update booking" });
  }
});

// Delete a booking
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const existingBooking = getBookingById(id);
    if (!existingBooking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    deleteBooking(id);

    res.json({ message: "Booking deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete booking" });
  }
});
