  amount: number;
  status: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS grant_requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    applicant_id INTEGER NOT NULL,
    amount REAL NOT NULL,
    status TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllGrantRequests(): GrantRequest[] {
  const stmt = db.prepare(`SELECT * FROM grant_requests`);
  return stmt.all() as unknown as GrantRequest[];
}

export function getGrantRequestById(id: number): GrantRequest | undefined {
  const stmt = db.prepare(`SELECT * FROM grant_requests WHERE id = ?`);
  return stmt.get(id) as unknown as GrantRequest | undefined;
}

export function insertGrantRequest(
  applicantId: number,
  amount: number,
  status: string
): number {
  const stmt = db.prepare(
    `INSERT INTO grant_requests (applicant_id, amount, status) VALUES (?, ?, ?)`
  );
  const result = stmt.run(applicantId, amount, status);
  return Number(result.lastInsertRowid);
}

