  id: number,
  applicantId: number,
  amount: number,
  status: string
): void {
  const stmt = db.prepare(
    `UPDATE grant_requests SET applicant_id = ?, amount = ?, status = ? WHERE id = ?`
  );
  stmt.run(applicantId, amount, status, id);
}

