{"code":"import { useEffect, useState } from "react";

interface Submission {
  id: number;
  title: string;
  author: string;
  status: "submitted" | "under-review" | "approved" | "rejected";
  createdAt: string;
}

export function SubmissionQueue() {
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchSubmissions();
  }, []);

  const fetchSubmissions = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/submissions-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch submissions: ${response.status}`);
      }
      const data = await response.json();
      setSubmissions(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleAdvanceToReview = async (id: number) => {
    try {
      const response = await fetch(`/api/role-based-access-control/submissions/${id}/advance-to-review`, {
        method: "PUT",
      });
      if (!response.ok) {
        throw new Error(`Failed to advance submission: ${response.status}`);
      }
      await fetchSubmissions();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/submissions-api/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete submission: ${response.status}`);
      }
      await fetchSubmissions();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (submissions.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No manuscripts submitted yet.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Submission Queue</h1>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: "15px",
        }}
      >
        {submissions.map((submission) => (
          <div
            key={submission.id}
            style={{
              border: "1px solid #ccc",
              borderRadius: "8px",
              padding: "15px",
              display: "flex",
              flexDirection: "column",
              gap: "10px",
            }}
          >
            <div style={{ display: "flex", justifyContent: "space-between" }}>
              <h3 style={{ margin: 0 }}>{submission.title}</h3>
              <span
                style={{
                  backgroundColor: getStatusColor(submission.status),
                  color: "white",
                  padding: "4px 8px",
                  borderRadius: "4px",
                  fontSize: "0.9em",
                }}
              >
                {submission.status}
              </span>
            </div>
            <p style={{ margin: 0, color: "#666" }}>
              Author: {submission.author}
            </p>
            <p style={{ margin: 0, color: "#666" }}>
              Submitted: {new Date(submission.createdAt).toLocaleDateString()}
            </p>
            <div
              style={{
                display: "flex",
                gap: "10px",
                flexWrap: "wrap",
              }}
            >
              {submission.status === "submitted" && (
                <button
                  onClick={() => handleAdvanceToReview(submission.id)}
                  style={{
                    backgroundColor: "#007bff",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "6px 12px",
                    cursor: "pointer",
                  }}
                >
                  Advance to Review
                </button>
              )}
              <button
                onClick={() => handleDelete(submission.id)}
                style={{
                  backgroundColor: "#dc3545",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  padding: "6px 12px",
                  cursor: "pointer",
                }}
              >
                Delete
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function getStatusColor(status: string) {
  switch (status) {
    case "submitted":
      return "#17a2b8";
    case "under-review":
      return "#ffc107";
    case "approved":
      return "#28a745";
    case "rejected":
      return "#dc3545";
    default:
      return "#6c757d";
  }
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to the export endpoint
  if (req.method !== "POST" || !req.path.startsWith("/export")) {
    next();
    return;
  }

  // Check if the user is the owner
  // This is a placeholder implementation - in a real app,
  // you'd check the authenticated user against the resource owner
  const isOwner = req.headers["x-user-role"] === "owner";

  if (!isOwner) {
    res.status(403).json({ error: "Forbidden: Export access restricted to owners" });
    return;
  }

  next();
}
"}

