      setCheckIns(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleCheckOut = async (id: number) => {
    try {
      const response = await fetch(`/api/check-in-check-out-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ checkOutDate: new Date().toISOString() }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // Refresh the list after successful checkout
      await fetchCheckIns();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/check-in-check-out-api/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // Refresh the list after successful delete
      await fetchCheckIns();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (checkIns.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No check-in/check-out history found.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>My Check-In/Check-Out History</h1>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: "15px",
        }}
      >
        {checkIns.map((record) => (
          <div
            key={record.id}
            style={{
              border: "1px solid #ccc",
              borderRadius: "8px",
              padding: "15px",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              flexWrap: "wrap",
            }}
          >
            <div>
              <strong>Pet Name:</strong> {record.petName}
              <br />
              <strong>Check In:</strong> {new Date(record.checkInDate).toLocaleDateString()}
              <br />
              <strong>Check Out:</strong> {record.checkOutDate ? new Date(record.checkOutDate).toLocaleDateString() : "Not checked out yet"}
            </div>
            <div style={{ display: "flex", gap: "10px", marginTop: "10px" }}>
              {!record.checkOutDate && (
                <button
                  onClick={() => handleCheckOut(record.id)}
                  style={{
                    backgroundColor: "#4CAF50",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "8px 12px",
                    cursor: "pointer",
                  }}
                >
                  Check Out
                </button>
              )}
              <button
                onClick={() => handleDelete(record.id)}
                style={{
                  backgroundColor: "#f44336",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  padding: "8px 12px",
                  cursor: "pointer",
                }}
              >
                Delete
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
"}

{"code":"import { FC, useEffect, useState } from "react";

interface TimesheetEntry {
  id?: number;
  date: string;
  client: string;
  hours: number;
}

export function TimesheetEntryForm() {
  const [entries, setEntries] = useState<TimesheetEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    date: "",
    client: "",
    hours: ""
  });

  useEffect(() => {
    fetchEntries();
  }, []);

  const fetchEntries = async () => {
    try {
      const response = await fetch("/api/timesheets-api/");
      if (!response.ok) throw new Error("Failed to fetch timesheet entries");
      const data = await response.json();
      setEntries(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const newEntry: TimesheetEntry = {
      date: formData.date,
      client: formData.client,
      hours: Number(formData.hours)
    };

    try {
      const response = await fetch("/api/timesheets-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newEntry)
      });

      if (!response.ok) throw new Error("Failed to create timesheet entry");

      // Reset form
      setFormData({ date: "", client: "", hours: "" });

      // Refresh entries
      await fetchEntries();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Timesheet Entry</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="date" style={{ display: "block", marginBottom: "5px" }}>Date:</label>
          <input
            type="date"
            id="date"
            name="date"
            value={formData.date}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="client" style={{ display: "block", marginBottom: "5px" }}>Client:</label>
          <input
            type="text"
            id="client"
            name="client"
            value={formData.client}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="hours" style={{ display: "block", marginBottom: "5px" }}>Hours:</label>
          <input
            type="number"
            id="hours"
            name="hours"
            value={formData.hours}
            onChange={handleChange}
            required
            min="0"
            step="0.25"
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
          />
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: "#007bff", 
            color: "white", 
            border: "none", 
            padding: "10px 20px", 
            borderRadius: "4px", 
            cursor: "pointer", 
            fontSize: "16px" 
          }}
        >
          Submit Entry
        </button>
      </form>

      <h2 style={{ textAlign: "center" }}>Recent Entries</h2>

      {entries.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No entries found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {entries.map(entry => (
            <div 
              key={entry.id} 
              style={{ 
                padding: "15px", 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center" 
              }}
            >
              <div>
                <strong>{entry.date}</strong> - {entry.client}: {entry.hours} hours
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteAppointment,
  getAllAppointments,
  getAppointmentById,
  insertAppointment,
  updateAppointment
} from "../db/appointments-table";

export const router = Router();

// Get all appointments
router.get("/", (req: Request, res: Response) => {
  try {
    const appointments = getAllAppointments();
    res.json(appointments);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch appointments" });
  }
});

// Get appointment by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid appointment ID" });
    }

    const appointment = getAppointmentById(id);
    if (!appointment) {
      return res.status(404).json({ error: "Appointment not found" });
    }

    res.json(appointment);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch appointment" });
  }
});

// Create new appointment
router.post("/", (req: Request, res: Response) => {
  try {
    const { patientId, doctorId, scheduledTime } = req.body;

    if (!patientId || !doctorId || !scheduledTime) {
      return res.status(400).json({
        error: "Patient ID, doctor ID, and scheduled time are required"
      });
    }

    const id = insertAppointment(patientId, doctorId, scheduledTime);
    res.status(201).json({ id });
  } catch (error) {
    res.status(500).json({ error: "Failed to create appointment" });
  }
});

// Update appointment
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid appointment ID" });
    }

    const { patientId, doctorId, scheduledTime } = req.body;

    if (!patientId || !doctorId || !scheduledTime) {
      return res.status(400).json({
        error: "Patient ID, doctor ID, and scheduled time are required"
      });
    }

    const existingAppointment = getAppointmentById(id);
    if (!existingAppointment) {
      return res.status(404).json({ error: "Appointment not found" });
    }

    updateAppointment(id, patientId, doctorId, scheduledTime);
    res.json({ message: "Appointment updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update appointment" });
  }
});

// Delete appointment
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid appointment ID" });
    }

    const existingAppointment = getAppointmentById(id);
    if (!existingAppointment) {
      return res.status(404).json({ error: "Appointment not found" });
    }

    deleteAppointment(id);
    res.json({ message: "Appointment deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete appointment" });
  }
});
"}

