  cost: number;
}

export function UsageDashboard() {
  const [records, setRecords] = useState<UsageRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newRecord, setNewRecord] = useState({
    date: "",
    kWh: "",
    cost: ""
  });

  const memberId = "123"; // In a real app, this would come from auth context or route params

  useEffect(() => {
    fetchUsageData();
  }, []);

  const fetchUsageData = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/usage-api/member/${memberId}`);
      if (!response.ok) {
        throw new Error(`Failed to fetch data: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setRecords(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewRecord({
      ...newRecord,
      [name]: value
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch(`/api/usage-api/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...newRecord,
          kWh: parseFloat(newRecord.kWh),
          cost: parseFloat(newRecord.cost)
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to add record: ${response.status} ${response.statusText}`);
      }

      // Refresh data after successful submission
      await fetchUsageData();

      // Reset form
      setNewRecord({
        date: "",
        kWh: "",
        cost: ""
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/usage-api/${id}`, {
        method: "DELETE"
      });

      if (!response.ok) {
        throw new Error(`Failed to delete record: ${response.status} ${response.statusText}`);
      }

      // Refresh data after successful deletion
      await fetchUsageData();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

