{"code":"import { Router, type Request, type Response } from "express";
import { 
  getAllInvoices,
  getInvoiceById,
  insertInvoice,
  updateInvoice,
  deleteInvoice
} from "../db/invoices-table";

export const router = Router();

// Get all invoices
router.get("/", (req: Request, res: Response) => {
  try {
    const invoices = getAllInvoices();
    res.json(invoices);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch invoices" });
  }
});

// Get invoice by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid invoice ID" });
    }

    const invoice = getInvoiceById(id);
    if (!invoice) {
      return res.status(404).json({ error: "Invoice not found" });
    }

    res.json(invoice);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch invoice" });
  }
});

// Create new invoice
router.post("/", (req: Request, res: Response) => {
  try {
    const { clientId, title, description, amount, status, dueDate } = req.body;

    // Validate required fields
    if (!clientId || !title || !description || !amount || !status || !dueDate) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const id = insertInvoice(clientId, title, description, amount, status, dueDate);

    // Fetch the created invoice to send back
    const newInvoice = getInvoiceById(id);
    if (!newInvoice) {
      return res.status(500).json({ error: "Failed to retrieve created invoice" });
    }

    res.status(201).json(newInvoice);
  } catch (error) {
    res.status(500).json({ error: "Failed to create invoice" });
  }
});

// Update existing invoice
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid invoice ID" });
    }

    const { clientId, title, description, amount, status, dueDate } = req.body;

    // Validate required fields
    if (!clientId || !title || !description || !amount || !status || !dueDate) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const existingInvoice = getInvoiceById(id);
    if (!existingInvoice) {
      return res.status(404).json({ error: "Invoice not found" });
    }

    updateInvoice(id, clientId, title, description, amount, status, dueDate);

    // Fetch updated invoice
    const updatedInvoice = getInvoiceById(id);
    if (!updatedInvoice) {
      return res.status(500).json({ error: "Failed to retrieve updated invoice" });
    }

    res.json(updatedInvoice);
  } catch (error) {
    res.status(500).json({ error: "Failed to update invoice" });
  }
});

// Delete invoice
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid invoice ID" });
    }

    const existingInvoice = getInvoiceById(id);
    if (!existingInvoice) {
      return res.status(404).json({ error: "Invoice not found" });
    }

    deleteInvoice(id);

    res.json({ message: "Invoice deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete invoice" });
  }
});
"}

