{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./recipe-box.db");

interface Tag {
  id: number;
  name: string;
}

const createTagsTable = () => {
  const sql = `
    CREATE TABLE IF NOT EXISTS tags (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT UNIQUE NOT NULL
    )`;
  db.exec(sql);
};

createTagsTable();

export const getAllTags = (): Tag[] => {
  const stmt = db.prepare("SELECT * FROM tags ORDER BY name");
  return stmt.all() as unknown as Tag[];
};

export const getTagById = (id: number): Tag | undefined => {
  const stmt = db.prepare("SELECT * FROM tags WHERE id = ?");
  return stmt.get(id) as unknown as Tag | undefined;
};

export const insertTag = (name: string): number => {
  const stmt = db.prepare("INSERT INTO tags (name) VALUES (?)");
  const result = stmt.run(name);
  return Number(result.lastInsertRowid);
};

export const updateTag = (id: number, name: string): number => {
  const stmt = db.prepare("UPDATE tags SET name = ? WHERE id = ?");
  const result = stmt.run(name, id);
  return Number(result.changes);
};

export const deleteTag = (id: number): number => {
  const stmt = db.prepare("DELETE FROM tags WHERE id = ?");
  const result = stmt.run(id);
  return Number(result.changes);
};

// Seed data
if (getAllTags().length === 0) {
  insertTag("Vegetarian");
  insertTag("Vegan");
