{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as auditionsRouter } from "../routes/auditions-api";
import { router as exportServiceRouter } from "../routes/export-service";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check ownership for export service routes
  if (!req.path.startsWith('/export')) {
    next();
    return;
  }

  // Check if the user is the owner
  const ownerToken = req.headers['x-owner-token'] as string | undefined;

  if (!ownerToken) {
    res.status(401).json({ error: 'Owner token required' });
    return;
  }

  // In a real implementation, we would verify the token signature
  // For now, we'll just check if it matches a hardcoded owner token
  // This is a simplified version - in practice, you'd want proper JWT verification
  const expectedToken = process.env.OWNER_TOKEN;

  if (!expectedToken) {
    res.status(500).json({ error: 'Server configuration error: OWNER_TOKEN not set' });
    return;
  }

  // Simple token comparison (in reality, this should verify a JWT signature)
  if (ownerToken !== expectedToken) {
    res.status(403).json({ error: 'Access denied: Invalid owner token' });
    return;
  }

  next();
}
"}

