{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as registrationsRouter } from "../routes/registrations-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply guard to requests targeting the registrations API
  if (!req.path.startsWith("/api/registrations")) {
    next();
    return;
  }

  // Check if user is parent scoped
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify properly
  // For this implementation, we'll just check if it's a valid format
  try {
    const payload = JSON.parse(atob(token.split('.')[1] || ''));

    // Check if the user has parent scope
    if (payload.role !== "parent") {
      res.status(403).json({ error: "Forbidden: Parent access required" });
      return;
    }

    // Verify token signature
    const expectedSignature = createHmac("sha256", secret)
      .update(token.split(".").slice(0, 2).join("."))
      .digest("hex");

    const actualSignature = token.split(".")[2];

    const isEqual = timingSafeEqual(
      Buffer.from(expectedSignature),
      Buffer.from(actualSignature || "")
    );

    if (!isEqual) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    next();
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
  }
}
"}

