{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./parts-tracker.db");

interface RequestRow {
  id: number;
  mechanic_id: number;
  part_name: string;
  quantity: number;
  status: "pending" | "fulfilled" | "rejected";
  requested_at: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    mechanic_id INTEGER NOT NULL,
    part_name TEXT NOT NULL,
    quantity INTEGER NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending',
    requested_at TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllRequests(): RequestRow[] {
  const stmt = db.prepare("SELECT * FROM requests ORDER BY requested_at DESC");
  return stmt.all() as unknown as RequestRow[];
}

export function getRequestById(id: number): RequestRow | undefined {
  const stmt = db.prepare("SELECT * FROM requests WHERE id = ?");
  return stmt.get(id) as unknown as RequestRow | undefined;
}

export function insertRequest(
  mechanicId: number,
  partName: string,
  quantity: number
): number {
  const stmt = db.prepare(
    "INSERT INTO requests (mechanic_id, part_name, quantity, requested_at) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(mechanicId, partName, quantity, new Date().toISOString());
  return Number(result.lastInsertRowid);
}

export function updateRequestStatus(
  id: number,
  status: "pending" | "fulfilled" | "rejected"
): void {
  const stmt = db.prepare("UPDATE requests SET status = ? WHERE id = ?");
  stmt.run(status, id);
}

export function deleteRequest(id: number): void {
  const stmt = db.prepare("DELETE FROM requests WHERE id = ?");
  stmt.run(id);
}

// Sample data initialization
if (getAllRequests().length === 0) {
  const mechanicIds = [1, 2, 3];
  const partNames = ["Brake Pads", "Chain", "Tire", "Handlebars"];
  const quantities = [2, 1, 4, 1];

  for (let i = 0; i < 4; i++) {
    insertRequest(
      mechanicIds[i % mechanicIds.length],
      partNames[i],
      quantities[i]
    );
  }
}
"}

