{"code":"import { Router, type Request, type Response, type NextFunction } from "express";
import { FeedItem, insertFeedItem, getFeedItemsByUserId, markFeedItemAsRead } from "../db/feed-items-table";
import { middleware } from "../middleware/multiple-login-methods";

export const router = Router();

router.use(middleware);

router.get("/items", (req: Request, res: Response) => {
  const userId = Number(req.query.userId);
  if (isNaN(userId)) {
    res.status(400).send("Invalid user ID");
    return;
  }
  const items = getFeedItemsByUserId(userId);
  res.json(items);
});

router.post("/items", (req: Request, res: Response) => {
  const { userId, title, link, content, tags } = req.body;
  if (typeof userId !== "number" || typeof title !== "string" || typeof link !== "string" || typeof content !== "string" || typeof tags !== "string") {
    res.status(400).send("Invalid input");
    return;
  }
  insertFeedItem(userId, title, link, content, tags);
  res.status(201).send("Feed item added");
});

router.put("/items/:itemId/mark-as-read", (req: Request, res: Response) => {
  const itemId = Number(req.params.itemId);
  if (isNaN(itemId)) {
    res.status(400).send("Invalid item ID");
    return;
  }
  markFeedItemAsRead(itemId);
  res.send("Feed item marked as read");
});
