{"code":"import { Router, type Request, type Response } from "express";
import { db, deleteDocument, getAllDocuments, getDocumentById, insertDocument, updateDocument } from "../db/documents-table";

export const router = Router();

// GET /documents - Get all documents
router.get("/documents", (req: Request, res: Response) => {
  try {
    const documents = getAllDocuments();
    res.json(documents);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch documents" });
  }
});

// GET /documents/:id - Get a document by ID
router.get("/documents/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid document ID" });
    }

    const document = getDocumentById(id);
    if (!document) {
      return res.status(404).json({ error: "Document not found" });
    }

    res.json(document);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch document" });
  }
});

// POST /documents - Create a new document
router.post("/documents", (req: Request, res: Response) => {
  try {
    const { title, content, author } = req.body;

    if (!title || !content || !author) {
      return res.status(400).json({ error: "Title, content, and author are required" });
    }

    const id = insertDocument(title, content, author);
    const createdDocument = getDocumentById(id);

    if (!createdDocument) {
      return res.status(500).json({ error: "Failed to retrieve created document" });
    }

    res.status(201).json(createdDocument);
  } catch (error) {
    res.status(500).json({ error: "Failed to create document" });
  }
});

// PUT /documents/:id - Update a document
router.put("/documents/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid document ID" });
    }

    const { title, content, author } = req.body;

    if (!title || !content || !author) {
      return res.status(400).json({ error: "Title, content, and author are required" });
    }

    const existingDocument = getDocumentById(id);
    if (!existingDocument) {
      return res.status(404).json({ error: "Document not found" });
    }

    updateDocument(id, title, content, author);
    const updatedDocument = getDocumentById(id);

    if (!updatedDocument) {
      return res.status(500).json({ error: "Failed to retrieve updated document" });
    }

    res.json(updatedDocument);
  } catch (error) {
    res.status(500).json({ error: "Failed to update document" });
  }
});

// DELETE /documents/:id - Delete a document
router.delete("/documents/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid document ID" });
    }

    const existingDocument = getDocumentById(id);
    if (!existingDocument) {
      return res.status(404).json({ error: "Document not found" });
    }

    deleteDocument(id);
    res.json({ message: "Document deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete document" });
  }
});
"}

{"code":"import { useEffect, useState } from "react";

interface TourSlot {
  id: string;
  date: string;
  time: string;
  capacity: number;
  booked: number;
}

interface Docent {
  id: string;
  name: string;
  email: string;
}

export function TourBookingView() {
  const [tourSlots, setTourSlots] = useState<TourSlot[]>([]);
  const [docent, setDocent] = useState<Docent | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedSlotId, setSelectedSlotId] = useState<string | null>(null);

  useEffect(() => {
    fetchTourSlots();
    fetchDocent();
  }, []);

  const fetchTourSlots = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/tours-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch tour slots: ${response.status}`);
      }
      const slots = await response.json();
      setTourSlots(slots);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const fetchDocent = async () => {
    try {
      const response = await fetch("/api/docent-authentication/");
      if (!response.ok) {
        throw new Error(`Failed to fetch docent info: ${response.status}`);
      }
      const docentData = await response.json();
      setDocent(docentData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleBookSlot = async (slotId: string) => {
    try {
      const response = await fetch(`/api/tours-api/${slotId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ docentId: docent?.id }),
      });

      if (!response.ok) {
        throw new Error(`Failed to book slot: ${response.status}`);
      }

      // Refresh the data after booking
      await fetchTourSlots();
      setSelectedSlotId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Tour Booking</h1>
      <p style={{ textAlign: "center", marginBottom: "30px" }}>
        Available Slots for Docents
      </p>

      {tourSlots.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>
          No available tour slots.
        </p>
      ) : (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "15px",
          }}
        >
          {tourSlots.map((slot) => (
            <div
              key={slot.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: "8px",
                padding: "15px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                flexWrap: "wrap",
              }}
            >
              <div>
                <strong>{slot.date}</strong> at {slot.time}
                <br />
                Capacity: {slot.booked}/{slot.capacity}
              </div>
              <button
                onClick={() => handleBookSlot(slot.id)}
                disabled={slot.booked >= slot.capacity || selectedSlotId !== null}
                style={{
                  backgroundColor: slot.booked >= slot.capacity ? "#ccc" : "#007bff",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  padding: "8px 16px",
                  cursor: slot.booked >= slot.capacity ? "default" : "pointer",
                  marginLeft: "10px",
                }}
              >
                {slot.booked >= slot.capacity ? "Full" : "Sign Up"}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

