{"code":"import { Router, type Request, type Response } from "express";
import { MediaRow, insertMedia, getMediaById, getAllMedia, updateMedia, deleteMedia } from "../db/media-table";

export const router = Router();

router.post("/media", (req: Request, res: Response) => {
  const { filename, filepath, metadata, recognizedFaces, albumId, sharedWith } = req.body;
  insertMedia(filename, filepath, metadata, recognizedFaces, albumId, sharedWith);
  res.status(201).send({ message: "Media inserted successfully" });
});

router.get("/media/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const media = getMediaById(id);
  if (media) {
    res.json(media);
  } else {
    res.status(404).send({ message: "Media not found" });
  }
});

router.get("/media", (req: Request, res: Response) => {
  const mediaList = getAllMedia();
  res.json(mediaList);
});

router.put("/media/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { filename, filepath, metadata, recognizedFaces, albumId, sharedWith } = req.body;
  updateMedia(id, filename, filepath, metadata, recognizedFaces, albumId, sharedWith);
  res.send({ message: "Media updated successfully" });
});

router.delete("/media/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  deleteMedia(id);
  res.send({ message: "Media deleted successfully" });
});
