{"code":"import { useEffect, useState } from "react";

export function HousekeeperCleaningMark() {
  const [rooms, setRooms] = useState<Room[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchRooms();
  }, []);

  const fetchRooms = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/housekeeping-api/rooms');
      if (!response.ok) {
        throw new Error(`Failed to fetch rooms: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setRooms(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const markAsCleaned = async (roomId: string) => {
    try {
      const response = await fetch(`/api/housekeeping-api/rooms/${roomId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ cleaned: true }),
      });

      if (!response.ok) {
        throw new Error(`Failed to mark room as cleaned: ${response.status} ${response.statusText}`);
      }

      // Refresh the room list
      await fetchRooms();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Housekeeper Cleaning Mark</h1>
      {rooms.length === 0 ? (
        <p style={{ textAlign: 'center' }}>No rooms available.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {rooms.map(room => (
            <div 
              key={room.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center'
              }}
            >
              <span>{room.name}</span>
              <button 
                onClick={() => markAsCleaned(room.id)}
                disabled={room.cleaned}
                style={{ 
                  backgroundColor: room.cleaned ? '#4CAF50' : '#2196F3', 
                  color: 'white', 
                  border: 'none', 
                  borderRadius: '4px', 
                  padding: '8px 16px', 
                  cursor: room.cleaned ? 'default' : 'pointer'
                }}
              >
                {room.cleaned ? 'Cleaned' : 'Mark as Cleaned'}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

interface Room {
  id: string;
  name: string;
  cleaned: boolean;
}
"}

