    user_id INTEGER NOT NULL,
    habit_name TEXT NOT NULL,
    date TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllHabits(): HabitRow[] {
  const stmt = db.prepare(`SELECT * FROM habits`);
  return stmt.all() as unknown as HabitRow[];
}

