  userId: number,
  habitName: string,
  date: string
): number {
  const stmt = db.prepare(
    `INSERT INTO habits (user_id, habit_name, date) VALUES (?, ?, ?)`
  );
  const result = stmt.run(userId, habitName, date);
  return Number(result.lastInsertRowid);
}

