  id: number,
  userId: number,
  habitName: string,
  date: string
): void {
  const stmt = db.prepare(
    `UPDATE habits SET user_id = ?, habit_name = ?, date = ? WHERE id = ?`
  );
  stmt.run(userId, habitName, date, id);
}

