  const [rooms, setRooms] = useState<Room[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchRooms();
  }, []);

  const fetchRooms = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/housekeeping-api/rooms");
      if (!response.ok) {
        throw new Error(`Failed to fetch rooms: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setRooms(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const updateRoomStatus = async (roomId: number, newStatus: Room["status"]) => {
    try {
      const response = await fetch(`/api/housekeeping-api/rooms/${roomId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: newStatus }),
      });

      if (!response.ok) {
        throw new Error(`Failed to update room: ${response.status} ${response.statusText}`);
      }

      // Refresh the room list after successful update
      fetchRooms();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
