{"code":"import { useEffect, useState } from "react";

interface Audition {
  id: string;
  title: string;
  date: string;
  location: string;
}

interface SignupFormData {
  auditionId: string;
  actorName: string;
  email: string;
}

export function AuditionSignupForm() {
  const [auditions, setAuditions] = useState<Audition[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState<SignupFormData>({
    auditionId: "",
    actorName: "",
    email: "",
  });

  useEffect(() => {
    fetchAuditions();
  }, []);

  const fetchAuditions = async () => {
    try {
      const response = await fetch("/api/auditions-api/auditions");
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setAuditions(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch(`/api/auditions-api/auditions`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // Reset form after successful submission
      setFormData({
        auditionId: "",
        actorName: "",
        email: "",
      });

      // Refresh auditions list
      fetchAuditions();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;

  const formStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "16px",
    maxWidth: "500px",
    margin: "0 auto",
    padding: "16px",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
  };

  const inputGroupStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "4px",
  };

  const inputStyle: React.CSSProperties = {
    padding: "8px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    fontSize: "16px",
  };

  const buttonStyle: React.CSSProperties = {
    padding: "10px 16px",
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "16px",
  };

  return (
    <div style={formStyle}>
      <h2>Audition Signup</h2>
      <p>Please select an audition and fill out your details below.</p>

      <form onSubmit={handleSubmit}>
        <div style={inputGroupStyle}>
          <label htmlFor="auditionId">Audition:</label>
          <select
            id="auditionId"
            name="auditionId"
            value={formData.auditionId}
            onChange={handleInputChange}
            style={inputStyle}
            required
          >
            <option value="">Select an audition</option>
            {auditions.map((audition) => (
              <option key={audition.id} value={audition.id}>
                {audition.title} - {audition.date} at {audition.location}
              </option>
            ))}
          </select>
        </div>

        <div style={inputGroupStyle}>
          <label htmlFor="actorName">Your Name:</label>
          <input
            type="text"
            id="actorName"
            name="actorName"
            value={formData.actorName}
            onChange={handleInputChange}
            style={inputStyle}
            required
          />
        </div>

        <div style={inputGroupStyle}>
          <label htmlFor="email">Email:</label>
          <input
            type="email"
            id="email"
            name="email"
            value={formData.email}
            onChange={handleInputChange}
            style={inputStyle}
            required
          />
        </div>

        <button type="submit" style={buttonStyle}>Sign Up</button>
      </form>
    </div>
  );
}
"}

