{"code":"import { useEffect, useState } from "react";

interface Child {
  id: number;
  name: string;
  age: number;
  session: string;
}

export function ChildListView() {
  const [children, setChildren] = useState<Child[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentUserRole, setCurrentUserRole] = useState<string>("user"); // Default role

  useEffect(() => {
    const fetchChildren = async () => {
      try {
        const response = await fetch("/api/registrations-api/");
        if (!response.ok) {
          throw new Error(`Failed to fetch children: ${response.status}`);
        }
        const data = await response.json();
        setChildren(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchChildren();
  }, []);

  const handleDelete = async (id: number) => {
    if (currentUserRole !== "supervisor") return;

    try {
      const response = await fetch(`/api/registrations-api/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error(`Failed to delete child: ${response.status}`);
      }

      // Refresh the list after deletion
      const updatedResponse = await fetch("/api/registrations-api/");
      if (!updatedResponse.ok) {
        throw new Error(`Failed to refresh children list: ${updatedResponse.status}`);
      }
      const updatedData = await updatedResponse.json();
      setChildren(updatedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (children.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No children registered yet.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Registered Children</h1>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: "15px",
        }}
      >
        {children.map((child) => (
          <div
            key={child.id}
            style={{
              border: "1px solid #ccc",
              borderRadius: "8px",
              padding: "15px",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            <div>
              <strong>{child.name}</strong> - Age: {child.age}, Session: {child.session}
            </div>
            {currentUserRole === "supervisor" && (
              <button
                onClick={() => handleDelete(child.id)}
                style={{
                  backgroundColor: "#ff4d4d",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  padding: "8px 12px",
                  cursor: "pointer",
                }}
              >
                Delete
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}
"}

