{"code":"import type { Request, Response, NextFunction } from "express";
import { router } from "../routes/garden-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to the specific reassignment endpoint
  if (req.method !== "POST" || req.path !== "/api/garden/reassign") {
    return next();
  }

  // Check if the actor has the coordinator flag set
  const isCoordinator = req.body.actor?.coordinator;
  if (isCoordinator) {
    next();
  } else {
    res.status(403).send("Forbidden: Reassignment requires coordinator privileges.");
  }
}
