        if (!response.ok) throw new Error(`Failed to fetch items: ${response.status}`);
        const data = await response.json();
        setItems(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  useEffect(() => {
    const fetchSelectedItems = async () => {
      try {
        const response = await fetch(`/api/box-api/${memberId}/${weekDate}`);
        if (!response.ok) throw new Error(`Failed to fetch selected items: ${response.status}`);
        const data = await response.json();
        setSelectedItems(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      }
    };

    fetchSelectedItems();
  }, [memberId, weekDate]);

  const handleSelectItem = async (item: BoxItem) => {
    try {
      const response = await fetch(`/api/box-api/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          memberId,
          weekDate,
          itemId: item.id,
          itemName: item.name
        })
      });

      if (!response.ok) throw new Error(`Failed to select item: ${response.status}`);

      // Refresh data
      const itemsResponse = await fetch(`/api/box-api/`);
      const itemsData = await itemsResponse.json();
      setItems(itemsData);

      const selectedResponse = await fetch(`/api/box-api/${memberId}/${weekDate}`);
      const selectedData = await selectedResponse.json();
      setSelectedItems(selectedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDeselectItem = async (itemId: string) => {
    try {
      const response = await fetch(`/api/box-api/${memberId}/${weekDate}/${itemId}`, {
        method: "DELETE"
      });

      if (!response.ok) throw new Error(`Failed to deselect item: ${response.status}`);

      // Refresh data
      const itemsResponse = await fetch(`/api/box-api/`);
      const itemsData = await itemsResponse.json();
      setItems(itemsData);

      const selectedResponse = await fetch(`/api/box-api/${memberId}/${weekDate}`);
      const selectedData = await selectedResponse.json();
      setSelectedItems(selectedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Weekly Box Customization</h1>

      <h2>Available Items</h2>
      {items.length === 0 ? (
        <p>No items available.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
          {items.map(item => (
            <div key={item.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "10px", flex: "1 1 200px" }}>
              <h3>{item.name}</h3>
              <p>{item.description}</p>
              <button 
                onClick={() => handleSelectItem(item)}
                style={{ backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", padding: "5px 10px", cursor: "pointer" }}
              >
                Add to Box
              </button>
            </div>
          ))}
        </div>
      )}

      <h2>Selected Items</h2>
      {selectedItems.length === 0 ? (
        <p>No items selected for this week.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
          {selectedItems.map(item => (
            <div key={item.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "10px", flex: "1 1 200px" }}>
              <h3>{item.name}</h3>
              <button 
                onClick={() => handleDeselectItem(item.id)}
                style={{ backgroundColor: "#dc3545", color: "white", border: "none", borderRadius: "4px", padding: "5px 10px", cursor: "pointer" }}
              >
                Remove
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface Subscriber {
  id: string;
  email: string;
  name: string;
}

export function CampaignComposer() {
  const [subscribers, setSubscribers] = useState<Subscriber[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [newSubscriber, setNewSubscriber] = useState({
    email: "",
    name: ""
  });

  useEffect(() => {
    fetchSubscribers();
  }, []);

  const fetchSubscribers = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/mailing-list-engine/subscribers");
      if (!response.ok) {
        throw new Error(`Failed to fetch subscribers: ${response.status}`);
      }
      const data = await response.json();
      setSubscribers(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleAddSubscriber = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/mailing-list-engine/subscribers", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newSubscriber)
      });
      if (!response.ok) {
        throw new Error(`Failed to add subscriber: ${response.status}`);
      }
      setNewSubscriber({ email: "", name: "" });
      fetchSubscribers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDeleteSubscriber = async (id: string) => {
    try {
      const response = await fetch(`/api/mailing-list-engine/subscribers/${id}`, {
        method: "DELETE"
      });
      if (!response.ok) {
        throw new Error(`Failed to delete subscriber: ${response.status}`);
      }
      fetchSubscribers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const formStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
    marginBottom: "20px"
  };

  const inputStyle: React.CSSProperties = {
    padding: "8px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    fontSize: "16px"
  };

  const buttonStyle: React.CSSProperties = {
    padding: "8px 16px",
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "16px"
  };

  const listContainerStyle: React.CSSProperties = {
    display: "flex",
    flexWrap: "wrap",
    gap: "15px"
  };

  const cardStyle: React.CSSProperties = {
    border: "1px solid #ddd",
    borderRadius: "8px",
    padding: "15px",
    width: "250px",
    boxSizing: "border-box"
  };

  const deleteButtonStyle: React.CSSProperties = {
    padding: "4px 8px",
    backgroundColor: "#dc3545",
    color: "white",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "14px"
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1>Campaign Composer</h1>
      <p>Manage your subscriber list and send newsletters.</p>

      <h2>Add New Subscriber</h2>
      <form onSubmit={handleAddSubscriber} style={formStyle}>
        <input
          type="email"
          placeholder="Email address"
          value={newSubscriber.email}
          onChange={(e) => setNewSubscriber({...newSubscriber, email: e.target.value})}
          style={inputStyle}
          required
        />
        <input
          type="text"
          placeholder="Full name"
          value={newSubscriber.name}
          onChange={(e) => setNewSubscriber({...newSubscriber, name: e.target.value})}
          style={inputStyle}
          required
        />
        <button type="submit" style={buttonStyle}>Add Subscriber</button>
      </form>

      <h2>Subscribers ({subscribers.length})</h2>
      {subscribers.length === 0 ? (
        <p>No subscribers found.</p>
      ) : (
        <div style={listContainerStyle}>
          {subscribers.map((subscriber) => (
            <div key={subscriber.id} style={cardStyle}>
              <p><strong>{subscriber.name}</strong></p>
              <p>{subscriber.email}</p>
              <button 
                onClick={() => handleDeleteSubscriber(subscriber.id)}
                style={deleteButtonStyle}
              >
                Remove
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

