{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteIncident,
  getAllIncidents,
  getIncidentById,
  insertIncident,
  updateIncident
} from "../db/incidents-table";

export const router = Router();

// Get all incidents
router.get("/", (req: Request, res: Response) => {
  try {
    const incidents = getAllIncidents();
    return res.json(incidents);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch incidents" });
  }
});

// Get incident by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid incident ID" });
    }

    const incident = getIncidentById(id);
    if (!incident) {
      return res.status(404).json({ error: "Incident not found" });
    }

    return res.json(incident);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch incident" });
  }
});

// Create new incident
router.post("/", (req: Request, res: Response) => {
  try {
    const { residentId, timestamp, description } = req.body;

    if (!residentId || !timestamp || !description) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const id = insertIncident(residentId, timestamp, description);
    const newIncident = getIncidentById(id);

    if (!newIncident) {
      return res.status(500).json({ error: "Failed to create incident" });
    }

    return res.status(201).json(newIncident);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create incident" });
  }
});

// Update incident
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid incident ID" });
    }

    const { residentId, timestamp, description } = req.body;

    if (!residentId || !timestamp || !description) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const updatedId = updateIncident(id, residentId, timestamp, description);
    const updatedIncident = getIncidentById(updatedId);

    if (!updatedIncident) {
      return res.status(404).json({ error: "Incident not found" });
    }

    return res.json(updatedIncident);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update incident" });
  }
});

// Delete incident
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid incident ID" });
    }

    const deletedId = deleteIncident(id);
    if (deletedId === 0) {
      return res.status(404).json({ error: "Incident not found" });
    }

    return res.json({ message: "Incident deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete incident" });
  }
});
"}

