{"code":"import { useEffect, useState } from "react";

interface Booking {
  id: number;
  date: string;
  time: string;
  laneNumber: number;
  memberId: number;
}

interface RangeOfficer {
  id: number;
  name: string;
  email: string;
}

export function LaneBookingForm() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [rangeOfficers, setRangeOfficers] = useState<RangeOfficer[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    date: "",
    time: "",
    laneNumber: "",
    memberId: ""
  });

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [bookingsRes, officersRes] = await Promise.all([
          fetch("/api/bookings-api/bookings"),
          fetch("/api/bookings-api/range-officers")
        ]);

        if (!bookingsRes.ok || !officersRes.ok) {
          throw new Error("Failed to fetch data");
        }

        const bookingsData = await bookingsRes.json();
        const officersData = await officersRes.json();

        setBookings(bookingsData);
        setRangeOfficers(officersData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch("/api/bookings-api/bookings", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          date: formData.date,
          time: formData.time,
          laneNumber: parseInt(formData.laneNumber),
          memberId: parseInt(formData.memberId)
        })
      });

      if (!response.ok) {
        throw new Error("Failed to create booking");
      }

      // Refresh data
      const [bookingsRes, officersRes] = await Promise.all([
        fetch("/api/bookings-api/bookings"),
        fetch("/api/bookings-api/range-officers")
      ]);

      if (!bookingsRes.ok || !officersRes.ok) {
        throw new Error("Failed to refresh data");
      }

      const bookingsData = await bookingsRes.json();
      const officersData = await officersRes.json();

      setBookings(bookingsData);
      setRangeOfficers(officersData);

      // Reset form
      setFormData({
        date: "",
        time: "",
        laneNumber: "",
        memberId: ""
      });

    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Book a Lane</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <label>Date: </label>
          <input
            type="date"
            name="date"
            value={formData.date}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label>Time: </label>
          <input
            type="time"
            name="time"
            value={formData.time}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label>Lane Number: </label>
          <input
            type="number"
            name="laneNumber"
            value={formData.laneNumber}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            required
