{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply scope checking to GET requests to /members/:id
  if (req.method !== "GET" || !req.path.startsWith("/members/")) {
    next();
    return;
  }

  // Extract user ID from request (assuming it's set by auth middleware)
  const authenticatedUserId = (req as any).user?.id;

  // If no authenticated user, allow request to proceed (let other middleware handle it)
  if (!authenticatedUserId) {
    next();
    return;
  }

  // Extract target member ID from URL path
  const pathParts = req.path.split("/");
  const targetMemberId = pathParts[3];

  // If no target member ID, allow request to proceed
  if (!targetMemberId) {
    next();
    return;
  }

  // Check if the authenticated user is trying to access their own data
  if (authenticatedUserId === targetMemberId) {
    next();
    return;
  }

  // If the authenticated user is not accessing their own data, reject the request
  res.status(403).json({ error: "Forbidden: Access denied" });
}
"}

{"code":"import { useEffect, useState } from "react";

interface Submission {
  id: number;
  title: string;
  author: string;
  status: string;
  submittedDate: string;
}

export function EditorReviewQueue() {
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchSubmissions();
  }, []);

  const fetchSubmissions = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/submissions-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch submissions: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setSubmissions(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleAdvanceToReview = async (id: number) => {
    try {
      const response = await fetch(`/api/role-based-access-control/submissions/${id}/advance-to-review`, {
        method: 'PUT',
      });
      if (!response.ok) {
        throw new Error(`Failed to advance submission: ${response.status} ${response.statusText}`);
      }
      // Refresh the list after successful update
      await fetchSubmissions();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (submissions.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No submissions ready for editorial review.</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Editor Review Queue</h1>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        {submissions.map((submission) => (
          <div 
            key={submission.id} 
            style={{ 
              border: '1px solid #ccc', 
              borderRadius: '8px', 
              padding: '15px', 
              display: 'flex', 
              justifyContent: 'space-between', 
              alignItems: 'center'
            }}
          >
            <div>
              <h3>{submission.title}</h3>
              <p><strong>Author:</strong> {submission.author}</p>
              <p><strong>Status:</strong> {submission.status}</p>
              <p><strong>Submitted:</strong> {new Date(submission.submittedDate).toLocaleDateString()}</p>
            </div>
            <button 
              onClick={() => handleAdvanceToReview(submission.id)}
              style={{ 
                backgroundColor: '#007bff', 
                color: 'white', 
                border: 'none', 
                borderRadius: '4px', 
                padding: '8px 16px', 
                cursor: 'pointer'
