    id INTEGER PRIMARY KEY AUTOINCREMENT,
    kitchen_space_id INTEGER NOT NULL,
    date TEXT NOT NULL,
    time_slot TEXT NOT NULL,
    cleaning_fee REAL NOT NULL
  )
`;

