  const stmt = db.prepare("SELECT * FROM bookings WHERE id = ?");
  return stmt.get(id) as unknown as BookingRow | undefined;
}

export function insertBooking(
  kitchenSpaceId: number,
  date: string,
  timeSlot: string,
  cleaningFee: number
): number {
  const stmt = db.prepare(
    "INSERT INTO bookings (kitchen_space_id, date, time_slot, cleaning_fee) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(kitchenSpaceId, date, timeSlot, cleaningFee);
  return Number(result.lastInsertRowid);
}

