{"code":"import { useEffect, useState } from "react";

interface TimesheetEntry {
  id?: number;
  matterId: number;
  date: string;
  hours: number;
  description: string;
}

interface Matter {
  id: number;
  name: string;
}

export function TimesheetEntryForm() {
  const [matters, setMatters] = useState<Matter[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState<TimesheetEntry>({
    matterId: 0,
    date: new Date().toISOString().split('T')[0],
    hours: 0,
    description: '',
  });

  useEffect(() => {
    const fetchMatters = async () => {
      try {
        const response = await fetch('/api/timesheets-api/');
        if (!response.ok) {
          throw new Error(`Failed to fetch matters: ${response.status}`);
        }
        const data = await response.json();
        setMatters(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchMatters();
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: name === 'hours' ? Number(value) : value,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch('/api/timesheets-api/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        throw new Error(`Failed to submit timesheet entry: ${response.status}`);
      }

      // Reset form after successful submission
      setFormData({
        matterId: 0,
        date: new Date().toISOString().split('T')[0],
        hours: 0,
        description: '',
      });

      // Refresh matters list
      const refreshResponse = await fetch('/api/timesheets-api/');
      if (refreshResponse.ok) {
        const refreshedData = await refreshResponse.json();
        setMatters(refreshedData);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Enter Timesheet</h1>

      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        <div>
          <label htmlFor="matterId" style={{ display: 'block', marginBottom: '5px' }}>Matter:</label>
          <select
            id="matterId"
