{"code":"import type { Request, Response, NextFunction } from "express";
import { router as auditionsRouter } from "../routes/auditions-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check casting notes access for requests to the auditions API
  if (!req.path.startsWith("/api/auditions")) {
    next();
    return;
  }

  // For casting note related routes, check role
  const castingNoteRoutes = ["/api/auditions/:id/casting-notes"];

  if (castingNoteRoutes.some(route => req.path.includes(route))) {
    // In a real implementation, this would check user roles from a token
    // For now, we'll simulate the role check
    const userRole = req.headers["x-user-role"] as string | undefined;

    if (userRole !== "director") {
      // Return empty array or null for non-directors
      res.status(200).json([]);
      return;
    }
  }

  next();
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteExpense,
  getAllExpenses,
  getExpenseById,
  insertExpense,
  updateExpense
} from "../db/expenses-table";

export const router = Router();

// Get all expenses
router.get("/", (req: Request, res: Response) => {
  try {
    const expenses = getAllExpenses();
    res.json(expenses);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch expenses" });
  }
});

// Get expense by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid expense ID" });
    }

    const expense = getExpenseById(id);
    if (!expense) {
      return res.status(404).json({ error: "Expense not found" });
    }

    res.json(expense);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch expense" });
  }
});

// Create new expense
router.post("/", (req: Request, res: Response) => {
  try {
    const { amount, date, category, account_id } = req.body;

    if (
      typeof amount !== "number" ||
      !date ||
      !category ||
      typeof account_id !== "number"
    ) {
      return res.status(400).json({
        error: "Amount, date, category, and account_id are required"
      });
    }

    const newId = insertExpense(amount, date, category, account_id);
    const newExpense = getExpenseById(newId);

    if (!newExpense) {
      return res.status(500).json({ error: "Failed to create expense" });
    }

    res.status(201).json(newExpense);
  } catch (error) {
    res.status(500).json({ error: "Failed to create expense" });
  }
});

// Update expense
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid expense ID" });
    }

    const { amount, date, category, account_id } = req.body;

    if (
      typeof amount !== "number" ||
      !date ||
      !category ||
      typeof account_id !== "number"
    ) {
      return res.status(400).json({
        error: "Amount, date, category, and account_id are required"
      });
    }

    const updatedId = updateExpense(id, amount, date, category, account_id);
    const updatedExpense = getExpenseById(updatedId);

    if (!updatedExpense) {
      return res.status(404).json({ error: "Expense not found" });
    }

    res.json(updatedExpense);
  } catch (error) {
    res.status(500).json({ error: "Failed to update expense" });
  }
});

// Delete expense
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid expense ID" });
    }

    const deletedId = deleteExpense(id);
    if (deletedId === 0) {
      return res.status(404).json({ error: "Expense not found" });
    }

    res.json({ message: "Expense deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete expense" });
  }
