  const [shifts, setShifts] = useState<Shift[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchShifts();
  }, []);

  const fetchShifts = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/shifts-api/');
      if (!response.ok) {
        throw new Error('Failed to fetch shifts');
      }
      const data = await response.json();
      setShifts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleSignup = async (shiftId: number) => {
    try {
      const response = await fetch(`/api/shifts-api/${shiftId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ signedUp: true }),
      });

      if (!response.ok) {
        throw new Error('Failed to sign up for shift');
      }

      // Refresh the shifts list
      await fetchShifts();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Shift Signup</h1>
      {shifts.length === 0 ? (
        <p style={{ textAlign: 'center' }}>No shifts available.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {shifts.map(shift => (
            <div 
              key={shift.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center'
              }}
            >
              <div>
                <strong>{new Date(shift.date).toLocaleDateString()}</strong>
                <br />
                {shift.startTime} - {shift.endTime}
              </div>
              <button 
                onClick={() => handleSignup(shift.id)}
                disabled={shift.signedUp}
                style={{ 
                  backgroundColor: shift.signedUp ? '#ccc' : '#007bff', 
                  color: 'white', 
                  border: 'none', 
                  borderRadius: '4px', 
                  padding: '8px 12px', 
                  cursor: shift.signedUp ? 'default' : 'pointer'
                }}
              >
                {shift.signedUp ? 'Signed Up' : 'Sign Up'}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

