{"code":"import { Router, type Request, type Response } from "express";
import { 
  getAllServiceEvents,
  getServiceEventById,
  insertServiceEvent,
  updateServiceEvent,
  deleteServiceEvent
} from "../db/service-events-table";

export const router = Router();

// Get all service events
router.get("/", (req: Request, res: Response) => {
  try {
    const events = getAllServiceEvents();
    res.json(events);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch service events" });
  }
});

// Get a specific service event by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const event = getServiceEventById(id);
    if (!event) {
      return res.status(404).json({ error: "Service event not found" });
    }

    res.json(event);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch service event" });
  }
});

// Create a new service event
router.post("/", (req: Request, res: Response) => {
  try {
    const { applianceId, serviceDate, notes } = req.body;

    if (!applianceId || !serviceDate || !notes) {
      return res.status(400).json({ error: "Missing required fields: applianceId, serviceDate, notes" });
    }

    const id = insertServiceEvent(applianceId, serviceDate, notes);
    const newEvent = getServiceEventById(id);

    if (!newEvent) {
      return res.status(500).json({ error: "Failed to create service event" });
    }

    res.status(201).json(newEvent);
  } catch (error) {
    res.status(500).json({ error: "Failed to create service event" });
  }
});

// Update a service event
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const { applianceId, serviceDate, notes } = req.body;

    if (!applianceId || !serviceDate || !notes) {
      return res.status(400).json({ error: "Missing required fields: applianceId, serviceDate, notes" });
    }

    const existingEvent = getServiceEventById(id);
    if (!existingEvent) {
      return res.status(404).json({ error: "Service event not found" });
    }

    updateServiceEvent(id, applianceId, serviceDate, notes);
    const updatedEvent = getServiceEventById(id);

    if (!updatedEvent) {
      return res.status(500).json({ error: "Failed to update service event" });
    }

    res.json(updatedEvent);
  } catch (error) {
    res.status(500).json({ error: "Failed to update service event" });
  }
});

// Delete a service event
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const existingEvent = getServiceEventById(id);
    if (!existingEvent) {
      return res.status(404).json({ error: "Service event not found" });
    }

    deleteServiceEvent(id);
    res.json({ message: "Service event deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete service event" });
  }
});
"}

