{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/product-analytics.db"
);

interface EventRow {
  id: number;
  event_type: string;
  user_id: number;
  timestamp: string;
  properties: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_type TEXT NOT NULL,
    user_id INTEGER NOT NULL,
    timestamp TEXT NOT NULL,
    properties TEXT
  )
`;

db.exec(createTableSql);

export function getAllEvents(): EventRow[] {
  const stmt = db.prepare(`SELECT * FROM events`);
  return stmt.all() as unknown as EventRow[];
}

export function getEventById(id: number): EventRow | undefined {
  const stmt = db.prepare(`SELECT * FROM events WHERE id = ?`);
  return stmt.get(id) as unknown as EventRow | undefined;
}

export function insertEvent(
  eventType: string,
  userId: number,
  timestamp: string,
  properties?: Record<string, unknown>
): number {
  const propertiesStr = properties ? JSON.stringify(properties) : null;
  const stmt = db.prepare(
    `INSERT INTO events (event_type, user_id, timestamp, properties) VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(eventType, userId, timestamp, propertiesStr);
  return Number(result.lastInsertRowid);
}

export function updateEvent(
  id: number,
  eventType?: string,
  userId?: number,
  timestamp?: string,
  properties?: Record<string, unknown>
): boolean {
  const updates: string[] = [];
  const params: (string | number | null)[] = [];

  if (eventType !== undefined) {
    updates.push("event_type = ?");
    params.push(eventType);
  }

  if (userId !== undefined) {
    updates.push("user_id = ?");
    params.push(userId);
  }

  if (timestamp !== undefined) {
    updates.push("timestamp = ?");
    params.push(timestamp);
  }

  if (properties !== undefined) {
    updates.push("properties = ?");
    params.push(JSON.stringify(properties));
  }

  if (updates.length === 0) return false;

  params.push(id);

  const sql = `UPDATE events SET ${updates.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  const result = stmt.run(...params);
  return result.changes > 0;
}

export function deleteEvent(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM events WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
}

