}

export function getEntryById(id: number): MileageEntry | undefined {
  const stmt = db.prepare("SELECT * FROM mileage_entries WHERE id = ?");
  return stmt.get(id) as unknown as MileageEntry | undefined;
}

export function insertEntry(entry: Omit<MileageEntry, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO mileage_entries (trip_id, date, miles, purpose, tax_year) VALUES (?, ?, ?, ?, ?)"
  );
  const result = stmt.run(entry.trip_id, entry.date, entry.miles, entry.purpose, entry.tax_year);
  return Number(result.lastInsertRowid);
}

export function updateEntry(id: number, entry: Partial<Omit<MileageEntry, "id">>): boolean {
  const fields = [];
  const values = [];

  if (entry.trip_id !== undefined) {
    fields.push("trip_id = ?");
    values.push(entry.trip_id);
  }

  if (entry.date !== undefined) {
