    values.push(entry.purpose);
  }

  if (entry.tax_year !== undefined) {
    fields.push("tax_year = ?");
    values.push(entry.tax_year);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE mileage_entries SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
