{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteRecipe,
  getAllRecipes,
  getRecipeById,
  insertRecipe,
  updateRecipe
} from "../db/recipes-table";
import {
  createSearchIndex,
  db as searchDb,
  getAllRecipes as getSearchRecipes,
  getRecipeById as getSearchRecipeById,
  insertRecipe as insertSearchRecipe,
  searchRecipesByIngredient
} from "../db/search-index";

export const router = Router();

// Get all recipes
router.get("/", (req: Request, res: Response) => {
  try {
    const recipes = getAllRecipes();
    return res.json(recipes);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch recipes" });
  }
});

// Get recipe by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid recipe ID" });
  }

  const recipe = getRecipeById(id);

  if (!recipe) {
    return res.status(404).json({ error: "Recipe not found" });
  }

  return res.json(recipe);
});

// Create a new recipe
router.post("/", (req: Request, res: Response) => {
  const { title, ingredients, tags } = req.body;

  if (!title || !ingredients) {
    return res.status(400).json({ error: "Title and ingredients are required" });
  }

  try {
    const id = insertRecipe(title, ingredients, tags || "");
    const recipe = getRecipeById(id);

    // Update search index
    insertSearchRecipe(title, ingredients);
    createSearchIndex(id, ingredients);

    return res.status(201).json(recipe);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create recipe" });
  }
});

// Update a recipe
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { title, ingredients, tags } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid recipe ID" });
  }

  if (!title || !ingredients) {
    return res.status(400).json({ error: "Title and ingredients are required" });
  }

  const existingRecipe = getRecipeById(id);

  if (!existingRecipe) {
    return res.status(404).json({ error: "Recipe not found" });
  }

  try {
    const updatedId = updateRecipe(id, title, ingredients, tags || "");
    const recipe = getRecipeById(updatedId);

    // Update search index
    insertSearchRecipe(title, ingredients);
    createSearchIndex(id, ingredients);

    return res.json(recipe);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update recipe" });
  }
});

// Delete a recipe
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid recipe ID" });
  }

  const existingRecipe = getRecipeById(id);

  if (!existingRecipe) {
    return res.status(404).json({ error: "Recipe not found" });
  }

  try {
    deleteRecipe(id);
    return res.json({ message: "Recipe deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete recipe" });
  }
});

// Search recipes by ingredient
router.get("/search/:ingredient", (req: Request, res: Response) => {
  const ingredient = req.params.ingredient;

  if (!ingredient) {
    return res.status(400).json({ error: "Ingredient parameter is required" });
  }

  try {
    const recipes = searchRecipesByIngredient(ingredient);
    return res.json(recipes);
  } catch (error) {
    return res.status(500).json({ error: "Failed to search recipes" });
  }
});
