export function getAllServers(): ServerRow[] {
  const stmt = db.prepare("SELECT * FROM servers");
  return stmt.all() as unknown as ServerRow[];
}

export function getServerById(id: number): ServerRow | undefined {
  const stmt = db.prepare("SELECT * FROM servers WHERE id = ?");
  return stmt.get(id) as unknown as ServerRow | undefined;
}

export function insertServer(name: string, ownerId: number, config: string): number {
  const stmt = db.prepare(
    "INSERT INTO servers (name, owner_id, config, created_at) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(name, ownerId, config, new Date().toISOString());
  return Number(result.lastInsertRowid);
}

export function updateServer(id: number, name: string, ownerId: number, config: string): void {
  const stmt = db.prepare(
    "UPDATE servers SET name = ?, owner_id = ?, config = ? WHERE id = ?"
  );
  stmt.run(name, ownerId, config, id);
}

export function deleteServer(id: number): void {
  const stmt = db.prepare("DELETE FROM servers WHERE id = ?");
  stmt.run(id);
}

// Seed data
if (getAllServers().length === 0) {
  const sampleServers = [
    { name: "Minecraft Survival", ownerId: 1, config: "{\"port\": 25565, \"version\": \"1.19\"}" },
    { name: "CS:GO Competitive", ownerId: 2, config: "{\"port\": 27015, \"maxPlayers\": 10}" },
    { name: "Rust Server", ownerId: 3, config: "{\"port\": 28015, \"maxPlayers\": 50}" },
    { name: "Valheim World", ownerId: 4, config: "{\"port\": 8080, \"version\": \"0.200.1\"}" },
    { name: "Ark Server", ownerId: 5, config: "{\"port\": 7777, \"maxPlayers\": 70}" }
  ];

  for (const server of sampleServers) {
    insertServer(server.name, server.ownerId, server.config);
  }
}
"}

{"code":"import { useEffect, useState } from "react";

interface Shift {
  id: number;
  date: string;
  startTime: string;
  endTime: string;
}

interface Booking {
  id: number;
  shiftId: number;
  memberId: number;
  status: string;
}

export function MemberView() {
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchMemberData() {
      try {
        setLoading(true);
        const [shiftsResponse, bookingsResponse] = await Promise.all([
          fetch("/api/shift-booking-api/shifts"),
          fetch("/api/shift-booking-api/bookings"),
        ]);

        if (!shiftsResponse.ok || !bookingsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const shiftsData = await shiftsResponse.json();
        const bookingsData = await bookingsResponse.json();

        // Filter bookings to only show the current member's bookings
        const memberBookings = bookingsData.filter(
          (booking: Booking) => booking.memberId === 1
        );

        setShifts(shiftsData);
        setBookings(memberBookings);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchMemberData();
  }, []);

  const handleBookShift = async (shiftId: number) => {
    try {
      const response = await fetch("/api/shift-booking-api/bookings", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          shiftId,
          memberId: 1,
          status: "confirmed",
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to book shift");
      }

      // Refresh data after successful booking
      const [shiftsResponse, bookingsResponse] = await Promise.all([
        fetch("/api/shift-booking-api/shifts"),
        fetch("/api/shift-booking-api/bookings"),
      ]);

      if (shiftsResponse.ok && bookingsResponse.ok) {
        const shiftsData = await shiftsResponse.json();
        const bookingsData = await bookingsResponse.json();
        const memberBookings = bookingsData.filter(
          (booking: Booking) => booking.memberId === 1
        );

        setShifts(shiftsData);
        setBookings(memberBookings);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleCancelBooking = async (bookingId: number) => {
    try {
      const response = await fetch(
        `/api/shift-booking-api/bookings/${bookingId}`,
        {
          method: "DELETE",
        }
      );

      if (!response.ok) {
        throw new Error("Failed to cancel booking");
      }

      // Refresh data after successful cancellation
      const [shiftsResponse, bookingsResponse] = await Promise.all([
        fetch("/api/shift-booking-api/shifts"),
        fetch("/api/shift-booking-api/bookings"),
      ]);

      if (shiftsResponse.ok && bookingsResponse.ok) {
        const shiftsData = await shiftsResponse.json();
        const bookingsData = await bookingsResponse.json();
        const memberBookings = bookingsData.filter(
          (booking: Booking) => booking.memberId === 1
        );

        setShifts(shiftsData);
        setBookings(memberBookings);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  const bookedShiftIds = new Set(bookings.map((b) => b.shiftId));

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>My Shift Bookings</h1>

      {bookings.length === 0 ? (
        <p style={{ textAlign: "center", color: "#666" }}>
          You don't have any bookings yet.
        </p>
      ) : (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "15px",
          }}
        >
          {bookings.map((booking) => {
            const shift = shifts.find((s) => s.id === booking.shiftId);
            return shift ? (
              <div
                key={booking.id}
                style={{
                  border: "1px solid #ddd",
                  borderRadius: "8px",
                  padding: "15px",
                  backgroundColor: "#f9f9f9",
                }}
              >
                <div style={{ marginBottom: "10px" }}>
                  <strong>Date:</strong> {shift.date}
                </div>
                <div style={{ marginBottom: "10px" }}>
                  <strong>Time:</strong> {shift.startTime} - {shift.endTime}
                </div>
                <div style={{ marginBottom: "10px" }}>
                  <strong>Status:</strong> {booking.status}
                </div>
                <button
                  onClick={() => handleCancelBooking(booking.id)}
                  style={{
                    backgroundColor: "#ff4d4d",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "8px 12px",
                    cursor: "pointer",
                  }}
                >
                  Cancel Booking
                </button>
              </div>
            ) : null;
          })}
        </div>
      )}

      <h2 style={{ textAlign: "center", marginTop: "30px" }}>Available Shifts</h2>

      {shifts.length === 0 ? (
        <p style={{ textAlign: "center", color: "#666" }}>
          No shifts available.
        </p>
      ) : (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "15px",
          }}
        >
          {shifts
            .filter((shift) => !bookedShiftIds.has(shift.id))
            .map((shift) => (
              <div
                key={shift.id}
                style={{
                  border: "1px solid #ddd",
                  borderRadius: "8px",
                  padding: "15px",
                  backgroundColor: "#fff",
                }}
              >
                <div style={{ marginBottom: "10px" }}>
                  <strong>Date:</strong> {shift.date}
                </div>
                <div style={{ marginBottom: "10px" }}>
                  <strong>Time:</strong> {shift.startTime} - {shift.endTime}
