  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid subscriber ID" });
    }

    const subscriber = getSubscriberById(id);
    if (!subscriber) {
      return res.status(404).json({ error: "Subscriber not found" });
    }

    return res.json(subscriber);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch subscriber" });
  }
});

// Create a new subscriber
router.post("/subscribers", (req: Request, res: Response) => {
  try {
    const { email, name } = req.body;

    if (!email || !name) {
      return res.status(400).json({ error: "Email and name are required" });
    }

    const newSubscriber = insertSubscriber(email, name);
    return res.status(201).json(newSubscriber);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create subscriber" });
  }
});

// Update a subscriber
router.put("/subscribers/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid subscriber ID" });
    }

    const { email, name } = req.body;

    if (!email || !name) {
      return res.status(400).json({ error: "Email and name are required" });
    }

    const updatedSubscriber = updateSubscriber(id, email, name);
    if (!updatedSubscriber) {
      return res.status(404).json({ error: "Subscriber not found" });
    }

    return res.json(updatedSubscriber);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update subscriber" });
  }
});

// Delete a subscriber
router.delete("/subscribers/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid subscriber ID" });
    }

    const deletedCount = deleteSubscriber(id);
    if (deletedCount === 0) {
      return res.status(404).json({ error: "Subscriber not found" });
    }

    return res.json({ message: "Subscriber deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete subscriber" });
  }
});
