import {
  db,
  deleteAudition,
  getAllAuditions,
  getAuditionById,
  insertAudition,
  updateAudition
} from "../db/auditions-table";

export const router = Router();

// GET /auditions - Get all auditions
router.get("/auditions", (req: Request, res: Response) => {
  const auditions = getAllAuditions();
  res.json(auditions);
});

// GET /auditions/:id - Get a specific audition by ID
router.get("/auditions/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const audition = getAuditionById(id);

  if (!audition) {
    return res.status(404).json({ error: "Audition not found" });
  }

  res.json(audition);
});

// POST /auditions - Create a new audition
router.post("/auditions", (req: Request, res: Response) => {
  const { actorId, showId, slotTime, signupStatus } = req.body;

  // Validate required fields
  if (!actorId || !showId || !slotTime || !signupStatus) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  try {
    const id = insertAudition(actorId, showId, slotTime, signupStatus);
    const newAudition = getAuditionById(id);

    if (!newAudition) {
      return res.status(500).json({ error: "Failed to retrieve created audition" });
    }

    res.status(201).json(newAudition);
  } catch (error) {
    res.status(500).json({ error: "Failed to create audition" });
  }
});

// PUT /auditions/:id - Update an existing audition
router.put("/auditions/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { actorId, showId, slotTime, signupStatus } = req.body;

  // Validate required fields
  if (!actorId || !showId || !slotTime || !signupStatus) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const existingAudition = getAuditionById(id);

  if (!existingAudition) {
    return res.status(404).json({ error: "Audition not found" });
  }

  try {
    updateAudition(id, actorId, showId, slotTime, signupStatus);
    const updatedAudition = getAuditionById(id);

    if (!updatedAudition) {
      return res.status(500).json({ error: "Failed to retrieve updated audition" });
    }

    res.json(updatedAudition);
  } catch (error) {
    res.status(500).json({ error: "Failed to update audition" });
  }
});

// DELETE /auditions/:id - Delete an audition
router.delete("/auditions/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  const existingAudition = getAuditionById(id);

  if (!existingAudition) {
    return res.status(404).json({ error: "Audition not found" });
  }

  try {
    deleteAudition(id);
    res.json({ message: "Audition deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete audition" });
  }
});
"}

