{"code":"import { useEffect, useState } from "react";

interface HousekeepingRecord {
  id: number;
  roomId: number;
  status: "pending" | "cleaned";
  lastUpdated: string;
}

export function HousekeeperCleanMark() {
  const [records, setRecords] = useState<HousekeepingRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchRecords();
  }, []);

  const fetchRecords = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/housekeeping-records-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch records: ${response.status}`);
      }
      const data = await response.json();
      setRecords(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const markAsCleaned = async (id: number) => {
    try {
      const response = await fetch(`/api/housekeeping-records-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "cleaned" }),
      });

      if (!response.ok) {
        throw new Error(`Failed to update record: ${response.status}`);
      }

      // Refresh the list after successful update
      await fetchRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (records.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No pending housekeeping records found.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1>Housekeeper Clean Mark</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {records
          .filter((record) => record.status === "pending")
          .map((record) => (
            <div
              key={record.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: "8px",
                padding: "15px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <span>Room #{record.roomId}</span>
              <button
                onClick={() => markAsCleaned(record.id)}
                style={{
                  backgroundColor: "#4CAF50",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  padding: "8px 16px",
                  cursor: "pointer",
                }}
              >
                Mark as Cleaned
              </button>
            </div>
          ))}
      </div>
    </div>
  );
}
"}

