  getAllTimesheets,
  getTimesheetById,
  insertTimesheet,
  updateTimesheet
} from "../db/timesheets-table";

export const router = Router();

// Get all timesheets for the logged-in user
router.get("/", (req: Request, res: Response) => {
  const userId = Number(req.query.userId);

  if (isNaN(userId)) {
    return res.status(400).json({ error: "Invalid user ID" });
  }

  const timesheets = getAllTimesheets().filter(ts => ts.user_id === userId);

  res.json(timesheets);
});

// Get a specific timesheet by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid timesheet ID" });
  }

  const timesheet = getTimesheetById(id);

  if (!timesheet) {
    return res.status(404).json({ error: "Timesheet not found" });
  }

  res.json(timesheet);
});

// Create a new timesheet entry
router.post("/", (req: Request, res: Response) => {
  const { userId, date, client, task, hours } = req.body;

  if (!userId || !date || !client || !task || hours === undefined) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newId = insertTimesheet(userId, date, client, task, hours);

  res.status(201).json({ id: newId });
});

// Update an existing timesheet entry
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { userId, date, client, task, hours } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid timesheet ID" });
  }

  if (!userId || !date || !client || !task || hours === undefined) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const existingTimesheet = getTimesheetById(id);

  if (!existingTimesheet) {
    return res.status(404).json({ error: "Timesheet not found" });
  }

  updateTimesheet(id, userId, date, client, task, hours);

  res.json({ message: "Timesheet updated successfully" });
});

// Delete a timesheet entry
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid timesheet ID" });
  }

  const existingTimesheet = getTimesheetById(id);

  if (!existingTimesheet) {
    return res.status(404).json({ error: "Timesheet not found" });
  }

  // Check if the user is a supervisor (this is a placeholder)
