{"code":"import { FC, useEffect, useState } from "react";

interface Booking {
  id: number;
  date: string;
  time: string;
  lane: number;
  supervisorId: number;
}

export function SupervisorDeleteGuard() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    try {
      const response = await fetch('/api/bookings-api/');
      if (!response.ok) {
        throw new Error('Failed to fetch bookings');
      }
      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: number) => {
    try {
      // First check if the current user is the supervisor of this booking
      const roleCheckResponse = await fetch(`/api/supervisor-role-check/${id}`);
      if (!roleCheckResponse.ok) {
        throw new Error('You are not authorized to delete this booking');
      }

      // If we get here, the user is a supervisor, proceed with deletion
      const deleteResponse = await fetch(`/api/bookings-api/${id}`, {
        method: 'DELETE',
      });

      if (!deleteResponse.ok) {
        throw new Error('Failed to delete booking');
      }

      // Refresh the list after successful deletion
      fetchBookings();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) return <div style={{ textAlign: 'center' }}>Loading...</div>;

  if (error) return <div style={{ textAlign: 'center', color: 'red' }}>{error}</div>;

  if (bookings.length === 0) return <div style={{ textAlign: 'center' }}>No bookings found.</div>;

  return (
    <div style={{ maxWidth: 800, margin: '0 auto', padding: '20px', fontFamily: 'system-ui' }}>
      <h1>Supervisor Delete Guard</h1>
      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr style={{ borderBottom: '1px solid #ccc' }}>
            <th style={{ padding: '10px', textAlign: 'left' }}>Date</th>
            <th style={{ padding: '10px', textAlign: 'left' }}>Time</th>
            <th style={{ padding: '10px', textAlign: 'left' }}>Lane</th>
            <th style={{ padding: '10px', textAlign: 'left' }}>Actions</th>
          </tr>
        </thead>
        <tbody>
          {bookings.map(booking => (
            <tr key={booking.id} style={{ borderBottom: '1px solid #eee' }}>
              <td style={{ padding: '10px' }}>{booking.date}</td>
              <td style={{ padding: '10px' }}>{booking.time}</td>
              <td style={{ padding: '10px' }}>{booking.lane}</td>
