{"code":"import { FC, useEffect, useState } from "react";

interface Transaction {
  id: string;
  description: string;
  amount: number;
  date: string;
}

export function OwnerOnlyExportButton() {
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [hasPermission, setHasPermission] = useState<boolean | null>(null);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchExportGuard = async () => {
      try {
        const response = await fetch("/api/export-guard/history");
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        setHasPermission(data.canExport);
      } catch (err) {
        setError("Failed to check export permission.");
        setHasPermission(false);
      } finally {
        setIsLoading(false);
      }
    };

    const fetchTransactions = async () => {
      try {
        const response = await fetch("/api/expenses-api/");
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        setTransactions(data);
      } catch (err) {
        setError("Failed to fetch transactions.");
      }
    };

    fetchExportGuard();
    fetchTransactions();
  }, []);

  const handleExport = async () => {
    try {
      const response = await fetch("/api/expenses-api/export", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ transactions }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "club-expenses-export.csv";
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (err) {
      setError("Failed to export transactions.");
    }
  };

  if (isLoading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (hasPermission === false) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Access denied.</div>;
  }

  if (hasPermission === null) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Checking permissions...</div>;
  }

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px" }}>
      <button 
        onClick={handleExport}
        style={{
          backgroundColor: "#4CAF50",
          border: "none",
          color: "white",
          padding: "10px 20px",
          textAlign: "center",
          textDecoration: "none",
          display: "inline-block",
          fontSize: "16px",
          margin: "4px 2px",
          cursor: "pointer",
          borderRadius: "4px",
        }}
      >
        Export All Transactions
      </button>
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import { db as commentsDb, getAllComments, getCommentById, insertComment, updateComment, deleteComment } from "../db/comments-table";
import { db as photosDb, getPhotoById } from "../db/photos-table";

export const router = Router();

// Get all comments
router.get("/", (req: Request, res: Response) => {
  try {
    const comments = getAllComments();
    return res.json(comments);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch comments" });
  }
});

// Get a specific comment by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid comment ID" });
    }

    const comment = getCommentById(id);
    if (!comment) {
      return res.status(404).json({ error: "Comment not found" });
    }

    return res.json(comment);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch comment" });
  }
});

// Create a new comment
router.post("/", (req: Request, res: Response) => {
  try {
    const { photoId, authorId, commentText, timestamp } = req.body;

    if (!photoId || !authorId || !commentText || !timestamp) {
      return res.status(400).json({ error: "Missing required fields: photoId, authorId, commentText, timestamp" });
    }

    const photo = getPhotoById(photoId);
    if (!photo) {
      return res.status(404).json({ error: "Photo not found" });
    }

    const newCommentId = insertComment(photoId, authorId, commentText, timestamp);
    const newComment = getCommentById(newCommentId);

    return res.status(201).json(newComment);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create comment" });
  }
});

// Update a comment
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid comment ID" });
    }

    const { photoId, authorId, commentText, timestamp } = req.body;

    if (!photoId || !authorId || !commentText || !timestamp) {
      return res.status(400).json({ error: "Missing required fields: photoId, authorId, commentText, timestamp" });
    }

    const existingComment = getCommentById(id);
    if (!existingComment) {
      return res.status(404).json({ error: "Comment not found" });
    }

    updateComment(id, photoId, authorId, commentText, timestamp);
    const updatedComment = getCommentById(id);

    return res.json(updatedComment);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update comment" });
  }
});

// Delete a comment
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid comment ID" });
    }

    const existingComment = getCommentById(id);
    if (!existingComment) {
      return res.status(404).json({ error: "Comment not found" });
    }

    deleteComment(id);
    return res.json({ message: "Comment deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete comment" });
  }
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check requests that involve exporting consignment data
  if (!(req.method === "POST" && req.path === "/consignment/export")) {
    next();
    return;
  }

  // Check if the user is authenticated and is the owner
  const ownerAccount = req.body.ownerAccount;
  const authenticatedUser = req.headers["x-authenticated-user"];

  if (!ownerAccount || !authenticatedUser) {
    res.status(403).json({ error: "Access denied: Owner account required" });
    return;
  }

  // For this example, we assume the authenticated user is the owner
  // In a real implementation, you'd verify this through your auth system
  if (ownerAccount !== authenticatedUser) {
    res.status(403).json({ error: "Access denied: Not the owner account" });
    return;
  }

  next();
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check tokens for API routes
  if (!req.path.startsWith("/api/")) {
    next();
    return;
  }

  const authHeader = req.headers["authorization"];
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Simple token validation - in a real system, you'd decode and verify the JWT signature
  // For this implementation, we'll assume the token is a simple string that matches the secret
  const expectedToken = createHmac("sha256", secret).update("api-access").digest("hex");

  try {
    const expectedBuffer = Buffer.from(expectedToken);
    const providedBuffer = Buffer.from(token);

    if (expectedBuffer.length !== providedBuffer.length) {
      res.status(401).json({ error: "Unauthorized: Invalid token" });
      return;
    }

    const isValid = timingSafeEqual(expectedBuffer, providedBuffer);

    if (!isValid) {
      res.status(401).json({ error: "Unauthorized: Invalid token" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}
"}

