{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./orchestra.db");

interface RehearsalRow {
  musician_id: number;
  rehearsal_id: number;
  attendance_status: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS rehearsals (
    musician_id INTEGER NOT NULL,
    rehearsal_id INTEGER NOT NULL,
    attendance_status TEXT NOT NULL,
    PRIMARY KEY (musician_id, rehearsal_id)
  );
`;

db.exec(createTableSql);

export function getAllRehearsals(): RehearsalRow[] {
  const stmt = db.prepare("SELECT * FROM rehearsals;");
  return stmt.all() as unknown as RehearsalRow[];
}

export function getRehearsalById(musicianId: number, rehearsalId: number): RehearsalRow | undefined {
  const stmt = db.prepare(
    "SELECT * FROM rehearsals WHERE musician_id = ? AND rehearsal_id = ?;"
  );
  return stmt.get(musicianId, rehearsalId) as unknown as RehearsalRow | undefined;
}

export function insertRehearsal(
  musicianId: number,
  rehearsalId: number,
  attendanceStatus: string
): number {
  const stmt = db.prepare(
    "INSERT INTO rehearsals (musician_id, rehearsal_id, attendance_status) VALUES (?, ?, ?);"
  );
  const result = stmt.run(musicianId, rehearsalId, attendanceStatus);
  return Number(result.lastInsertRowid);
}

export function updateRehearsal(
  musicianId: number,
  rehearsalId: number,
  attendanceStatus: string
): number {
  const stmt = db.prepare(
    "UPDATE rehearsals SET attendance_status = ? WHERE musician_id = ? AND rehearsal_id = ?;"
  );
  const result = stmt.run(attendanceStatus, musicianId, rehearsalId);
  return Number(result.changes);
}

export function deleteRehearsal(musicianId: number, rehearsalId: number): number {
  const stmt = db.prepare(
    "DELETE FROM rehearsals WHERE musician_id = ? AND rehearsal_id = ?;"
  );
  const result = stmt.run(musicianId, rehearsalId);
  return Number(result.changes);
}

// Seed data
if (getAllRehearsals().length === 0) {
  insertRehearsal(1, 101, "present");
  insertRehearsal(2, 101, "absent");
  insertRehearsal(3, 102, "present");
  insertRehearsal(4, 102, "late");
  insertRehearsal(5, 103, "present");
}
"}

