import { router as housekeepingApiRouter } from "../routes/housekeeping-api";
import { router as reassignmentGuardRouter } from "../routes/reassignment-guard";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check reassignment requests
  if (!(req.method === "PUT" && req.path.startsWith("/tasks/"))) {
    next();
    return;
  }

  // Check if user is supervisor
  const userRole = req.headers["x-user-role"];
  if (userRole !== "supervisor") {
    res.status(403).json({ error: "Reassignment requires supervisor role" });
    return;
  }

