{"code":"import { useEffect, useState } from "react";

interface Doctor {
  id: number;
  name: string;
  specialty: string;
}

interface TimeSlot {
  id: number;
  date: string;
  time: string;
  doctorId: number;
}

interface Appointment {
  id: number;
  date: string;
  time: string;
  doctorId: number;
}

export function AppointmentBookingView() {
  const [doctors, setDoctors] = useState<Doctor[]>([]);
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>([]);
  const [selectedDoctorId, setSelectedDoctorId] = useState<number | null>(null);
  const [selectedTimeSlotId, setSelectedTimeSlotId] = useState<number | null>(null);
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [doctorsRes, timeSlotsRes, appointmentsRes] = await Promise.all([
          fetch("/api/appointments-api/"),
          fetch("/api/appointments-api/time-slots"),
          fetch("/api/appointments-api/appointments"),
        ]);

        if (!doctorsRes.ok || !timeSlotsRes.ok || !appointmentsRes.ok) {
          throw new Error("Failed to fetch data");
        }

        const doctorsData = await doctorsRes.json();
        const timeSlotsData = await timeSlotsRes.json();
        const appointmentsData = await appointmentsRes.json();

        setDoctors(doctorsData);
        setTimeSlots(timeSlotsData);
        setAppointments(appointmentsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleBookAppointment = async () => {
    if (!selectedDoctorId || !selectedTimeSlotId) return;

    try {
      const response = await fetch("/api/appointments-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          doctorId: selectedDoctorId,
          timeSlotId: selectedTimeSlotId,
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to book appointment");
      }

      // Refresh data after booking
      const [doctorsRes, timeSlotsRes, appointmentsRes] = await Promise.all([
        fetch("/api/appointments-api/"),
        fetch("/api/appointments-api/time-slots"),
        fetch("/api/appointments-api/appointments"),
      ]);

      if (!doctorsRes.ok || !timeSlotsRes.ok || !appointmentsRes.ok) {
        throw new Error("Failed to refresh data");
      }

      const doctorsData = await doctorsRes.json();
      const timeSlotsData = await timeSlotsRes.json();
      const appointmentsData = await appointmentsRes.json();

      setDoctors(doctorsData);
      setTimeSlots(timeSlotsData);
      setAppointments(appointmentsData);

      // Reset selections
      setSelectedDoctorId(null);
      setSelectedTimeSlotId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  const filteredTimeSlots = timeSlots.filter(
    (slot) => slot.doctorId === selectedDoctorId
  );

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Book an Appointment</h1>

      <div style={{ marginBottom: "20px" }}>
        <label htmlFor="doctorSelect" style={{ display: "block", marginBottom: "5px" }}>
          Select a Doctor:
        </label>
        <select
          id="doctorSelect"
          value={selectedDoctorId || ""}
          onChange={(e) => setSelectedDoctorId(Number(e.target.value))}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="">Choose a doctor</option>
          {doctors.map((doctor) => (
            <option key={doctor.id} value={doctor.id}>
              {doctor.name} - {doctor.specialty}
            </option>
          ))}
        </select>
      </div>

      {selectedDoctorId && (
        <div style={{ marginBottom: "20px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>
            Select a Time Slot:
          </label>
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              gap: "10px",
            }}
          >
            {filteredTimeSlots.length > 0 ? (
              filteredTimeSlots.map((slot) => (
                <button
                  key={slot.id}
                  onClick={() => setSelectedTimeSlotId(slot.id)}
                  style={{
                    padding: "10px 15px",
                    backgroundColor: selectedTimeSlotId === slot.id ? "#007bff" : "#f8f9fa",
                    color: selectedTimeSlotId === slot.id ? "white" : "black",
                    border: "1px solid #007bff",
                    borderRadius: "4px",
                    cursor: "pointer",
                    flex: "1 1 calc(50% - 10px)",
                    minWidth: "120px",
                    textAlign: "center",
                  }}
                >
                  {slot.date} at {slot.time}
                </button>
              ))
            ) : (
              <p>No available time slots for this doctor.</p>
            )}
          </div>
        </div>
      )}

      <button
        onClick={handleBookAppointment}
        disabled={!selectedDoctorId || !selectedTimeSlotId}
        style={{
          width: "100%",
          padding: "12px",
          backgroundColor: selectedDoctorId && selectedTimeSlotId ? "#28a745" : "#6c757d",
          color: "white",
          border: "none",
          borderRadius: "4px",
          cursor: selectedDoctorId && selectedTimeSlotId ? "pointer" : "default",
        }}
      >
        Book Appointment
      </button>

      <h2 style={{ marginTop: "30px", textAlign: "center" }}>Your Appointments</h2>
      {appointments.length > 0 ? (
        <table
          style={{
            width: "100%",
            borderCollapse: "collapse",
            marginTop: "10px",
          }}
        >
          <thead>
            <tr>
              <th style={{ border: "1px solid #ddd", padding: "8px" }}>Date</th>
              <th style={{ border: "1px solid #ddd", padding: "8px" }}>Time</th>
              <th style={{ border: "1px solid #ddd", padding: "8px" }}>Doctor</th>
            </tr>
          </thead>
          <tbody>
            {appointments.map((appointment) => {
              const doctor = doctors.find((doc) => doc.id === appointment.doctorId);
              return (
                <tr key={appointment.id}>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {appointment.date}
                  </td>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {appointment.time}
                  </td>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {doctor ? doctor.name : "Unknown Doctor"}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      ) : (
        <p style={{ textAlign: "center", padding: "20px" }}>No appointments booked yet.</p>
      )}
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface Incident {
  id: number;
  residentId: number;
  timestamp: string;
  description: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS incidents (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    residentId INTEGER NOT NULL,
    timestamp TEXT NOT NULL,
    description TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllIncidents(): Incident[] {
  const stmt = db.prepare(`SELECT * FROM incidents`);
  return stmt.all() as unknown as Incident[];
}

export function getIncidentById(id: number): Incident | undefined {
  const stmt = db.prepare(`SELECT * FROM incidents WHERE id = ?`);
  return stmt.get(id) as unknown as Incident | undefined;
}

export function insertIncident(
  residentId: number,
  timestamp: string,
  description: string
): number {
  const stmt = db.prepare(
    `INSERT INTO incidents (residentId, timestamp, description) VALUES (?, ?, ?)`
  );
  const result = stmt.run(residentId, timestamp, description);
  return Number(result.lastInsertRowid);
}

export function updateIncident(
  id: number,
  residentId: number,
  timestamp: string,
  description: string
): number {
  const stmt = db.prepare(
    `UPDATE incidents SET residentId = ?, timestamp = ?, description = ? WHERE id = ?`
  );
  const result = stmt.run(residentId, timestamp, description, id);
  return Number(result.changes);
}

export function deleteIncident(id: number): number {
  const stmt = db.prepare(`DELETE FROM incidents WHERE id = ?`);
  const result = stmt.run(id);
  return Number(result.changes);
}

// Sample data insertion
if (getAllIncidents().length === 0) {
  insertIncident(101, "2023-05-15T08:30:00Z", "Unusual activity near the park.");
  insertIncident(102, "2023-05-15T14:15:00Z", "Suspicious vehicle parked for hours.");
  insertIncident(103, "2023-05-16T19:45:00Z", "Noise complaint from residential area.");
  insertIncident(104, "2023-05-17T10:00:00Z", "Missing pet reported in neighborhood.");
  insertIncident(105, "2023-05-17T21:30:00Z", "Fire truck seen in residential street.");
}
"}

