{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./bookstore.db");

interface Book {
  id: number;
  title: string;
  price: number;
  condition: string;
  consignerId: number;
  sellerId: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS books (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    price REAL NOT NULL,
    condition TEXT NOT NULL,
    consignerId INTEGER NOT NULL,
    sellerId INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllBooks(): Book[] {
  const stmt = db.prepare("SELECT * FROM books");
  return stmt.all() as unknown as Book[];
}

export function getBookById(id: number): Book | undefined {
  const stmt = db.prepare("SELECT * FROM books WHERE id = ?");
  return stmt.get(id) as unknown as Book | undefined;
}

export function insertBook(book: Omit<Book, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO books (title, price, condition, consignerId, sellerId) VALUES (?, ?, ?, ?, ?)"
  );
  const result = stmt.run(book.title, book.price, book.condition, book.consignerId, book.sellerId);
  return Number(result.lastInsertRowid);
}

export function updateBook(id: number, book: Partial<Omit<Book, "id">>): boolean {
  const fields = [];
  const values = [];

  if (book.title !== undefined) {
    fields.push("title = ?");
    values.push(book.title);
  }

  if (book.price !== undefined) {
    fields.push("price = ?");
    values.push(book.price);
  }

  if (book.condition !== undefined) {
    fields.push("condition = ?");
    values.push(book.condition);
  }

  if (book.consignerId !== undefined) {
    fields.push("consignerId = ?");
    values.push(book.consignerId);
  }

  if (book.sellerId !== undefined) {
    fields.push("sellerId = ?");
    values.push(book.sellerId);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE books SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
}

export function deleteBook(id: number): boolean {
  const stmt = db.prepare("DELETE FROM books WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

// Insert sample data if table is empty
if (getAllBooks().length === 0) {
  insertBook({
    title: "The Great Gatsby",
    price: 12.99,
    condition: "Good",
    consignerId: 1,
    sellerId: 2
  });

  insertBook({
    title: "To Kill a Mockingbird",
    price: 15.50,
    condition: "Excellent",
    consignerId: 2,
    sellerId: 1
  });

  insertBook({
