{"code":"import { useEffect, useState } from "react";

interface Reservation {
  id: string;
  customerName: string;
  vehicleType: string;
  startTime: string;
  endTime: string;
  status: string;
}

export function OwnerExportPanel() {
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchReservations();
  }, []);

  const fetchReservations = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/reservations-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch reservations: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setReservations(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleExport = async () => {
    try {
      const response = await fetch('/api/reservations-api/exports', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({}),
      });

      if (!response.ok) {
        throw new Error(`Failed to export reservations: ${response.status} ${response.statusText}`);
      }

      const exportData = await response.json();
      const exportId = exportData.id;

      // Poll for export completion
      let exportResult;
      while (!exportResult || exportResult.status === 'processing') {
        const resultResponse = await fetch(`/api/reservations-api/exports/${exportId}`);
        if (!resultResponse.ok) {
          throw new Error(`Failed to get export result: ${resultResponse.status} ${resultResponse.statusText}`);
        }
        exportResult = await resultResponse.json();
        await new Promise(resolve => setTimeout(resolve, 1000));
      }

      // Download the CSV file
      window.open(`/api/reservations-api/exports/${exportId}/download`, '_blank');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui' }}>
      <h1 style={{ textAlign: 'center' }}>Reservation History</h1>
      <button 
        onClick={handleExport}
        style={{ 
          backgroundColor: '#007bff', 
          color: 'white', 
          border: 'none', 
          padding: '10px 20px', 
          borderRadius: '5px', 
          cursor: 'pointer', 
          marginBottom: '20px', 
          display: 'block', 
          margin: '0 auto'
        }}
      >
        Export to CSV
      </button>

      {reservations.length === 0 ? (
        <p style={{ textAlign: 'center' }}>No reservations found.</p>
      ) : (
        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: '2px solid #ddd' }}>
                <th style={{ padding: '10px', textAlign: 'left' }}>Customer Name</th>
                <th style={{ padding: '10px', textAlign: 'left' }}>Vehicle Type</th>
                <th style={{ padding: '10px', textAlign: 'left' }}>Start Time</th>
                <th style={{ padding: '10px', textAlign: 'left' }}>End Time</th>
                <th style={{ padding: '10px', textAlign: 'left' }}>Status</th>
              </tr>
            </thead>
            <tbody>
              {reservations.map(reservation => (
                <tr key={reservation.id} style={{ borderBottom: '1px solid #ddd' }}>
                  <td style={{ padding: '10px' }}>{reservation.customerName}</td>
                  <td style={{ padding: '10px' }}>{reservation.vehicleType}</td>
                  <td style={{ padding: '10px' }}>{new Date(reservation.startTime).toLocaleString()}</td>
                  <td style={{ padding: '10px' }}>{new Date(reservation.endTime).toLocaleString()}</td>
                  <td style={{ padding: '10px' }}>{reservation.status}</td>
                </tr>
              ))}
            </tbody>
          </table>
