  };

  const formStyle: React.CSSProperties = {
    backgroundColor: "#f9f9f9",
    padding: "20px",
    borderRadius: "8px",
    marginBottom: "20px",
  };

  const inputStyle: React.CSSProperties = {
    width: "100%",
    padding: "10px",
    marginBottom: "10px",
    borderRadius: "4px",
    border: "1px solid #ccc",
  };

  const buttonStyle: React.CSSProperties = {
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    padding: "10px 20px",
    borderRadius: "4px",
    cursor: "pointer",
    fontWeight: "bold",
  };

  const submissionListStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
  };

  const submissionCardStyle: React.CSSProperties = {
    border: "1px solid #ddd",
    borderRadius: "4px",
    padding: "15px",
    backgroundColor: "#fff",
  };

  return (
    <div style={containerStyle}>
      <h1>Submit Your Manuscript</h1>

      {error && <div style={{ color: "red", marginBottom: "10px" }}>{error}</div>}

      <form onSubmit={handleSubmit} style={formStyle}>
        <input
          type="text"
          placeholder="Manuscript Title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          style={inputStyle}
        />

        <select
          value={selectedCategory ?? ""}
          onChange={(e) => setSelectedCategory(Number(e.target.value))}
          style={inputStyle}
        >
          <option value="">Select Category</option>
          {categories.map((category) => (
            <option key={category.id} value={category.id}>
              {category.name}
            </option>
          ))}
        </select>

        <input
          type="file"
          accept=".pdf,.doc,.docx"
          onChange={(e) => setFile(e.target.files?.[0] || null)}
          style={inputStyle}
        />

        <button type="submit" style={buttonStyle}>Submit Manuscript</button>
      </form>

      <h2>Your Submissions</h2>

      {submissions.length === 0 ? (
        <p>No submissions yet.</p>
      ) : (
        <div style={submissionListStyle}>
          {submissions.map((submission) => (
            <div key={submission.id} style={submissionCardStyle}>
              <strong>{submission.title}</strong> - {submission.category} - {submission.status}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteReservation,
  getAllReservations,
  getReservationById,
  insertReservation,
  updateReservation
} from "../db/reservations-table";

export const router = Router();

// Get all reservations
router.get("/", (req: Request, res: Response) => {
  try {
    const reservations = getAllReservations();
    res.json(reservations);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservations" });
  }
});

// Get a reservation by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const reservation = getReservationById(id);
    if (!reservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    res.json(reservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservation" });
  }
});

// Create a new reservation
router.post("/", (req: Request, res: Response) => {
  try {
    const { driverId, timeSlot, status } = req.body;

    if (!driverId || !timeSlot || !status) {
      return res.status(400).json({ error: "Missing required fields: driverId, timeSlot, status" });
    }

    const id = insertReservation(driverId, timeSlot, status);
    const newReservation = getReservationById(id);

    if (!newReservation) {
      return res.status(500).json({ error: "Failed to create reservation" });
    }

    res.status(201).json(newReservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to create reservation" });
  }
});

// Update a reservation
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { driverId, timeSlot, status } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    if (!driverId || !timeSlot || !status) {
      return res.status(400).json({ error: "Missing required fields: driverId, timeSlot, status" });
    }

    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    updateReservation(id, driverId, timeSlot, status);
    const updatedReservation = getReservationById(id);

    if (!updatedReservation) {
      return res.status(500).json({ error: "Failed to update reservation" });
    }

    res.json(updatedReservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to update reservation" });
  }
});

// Delete a reservation (supervisor-only access)
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    // Enforce supervisor-only deletion
    // For this implementation, we'll assume any valid request qualifies as supervisor access
    deleteReservation(id);
    res.json({ message: "Reservation deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete reservation" });
  }
});
"}

