{"code":"import { useEffect, useState } from "react";

interface PartRequest {
  id: number;
  partId: number;
  quantity: number;
  status: "pending" | "fulfilled" | "rejected";
  createdAt: string;
}

interface Part {
  id: number;
  name: string;
  description: string;
  stockQuantity: number;
}

export function PartRequestQueue() {
  const [requests, setRequests] = useState<PartRequest[]>([]);
  const [parts, setParts] = useState<Part[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchRequestsAndParts() {
      try {
        setLoading(true);
        const [requestsRes, partsRes] = await Promise.all([
          fetch("/api/parts-api/requests"),
          fetch("/api/parts-api/parts"),
        ]);

        if (!requestsRes.ok || !partsRes.ok) {
          throw new Error("Failed to fetch data");
        }

        const [requestsData, partsData] = await Promise.all([
          requestsRes.json(),
          partsRes.json(),
        ]);

        setRequests(requestsData);
        setParts(partsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchRequestsAndParts();
  }, []);

  const updateRequestStatus = async (
    requestId: number,
    status: "fulfilled" | "rejected"
  ) => {
    try {
      const res = await fetch(`/api/parts-api/requests/${requestId}/status`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status }),
      });

      if (!res.ok) {
        throw new Error("Failed to update request status");
      }

      // Refresh data after successful update
      const [requestsRes, partsRes] = await Promise.all([
        fetch("/api/parts-api/requests"),
        fetch("/api/parts-api/parts"),
      ]);

      if (!requestsRes.ok || !partsRes.ok) {
        throw new Error("Failed to refresh data");
      }

      const [requestsData, partsData] = await Promise.all([
        requestsRes.json(),
        partsRes.json(),
      ]);

      setRequests(requestsData);
      setParts(partsData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleFulfill = (requestId: number) => {
    updateRequestStatus(requestId, "fulfilled");
  };

  const handleReject = (requestId: number) => {
    updateRequestStatus(requestId, "rejected");
  };

  const getPartName = (partId: number) => {
    const part = parts.find(p => p.id === partId);
    return part ? part.name : "Unknown Part";
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;
  }

  if (requests.length === 0) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No pending requests</div>;
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Part Request Queue</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {requests
          .filter(req => req.status === "pending")
          .map(request => (
            <div
              key={request.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: "8px",
                padding: "15px",
                display: "flex",
                flexDirection: "column",
                gap: "10px",
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <span>
                  <strong>{getPartName(request.partId)}</strong> - Quantity: {request.quantity}
                </span>
                <span style={{ backgroundColor: "#f0f0f0", padding: "4px 8px", borderRadius: "4px" }}>
                  {request.status}
                </span>
              </div>
              <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
                <button
                  onClick={() => handleFulfill(request.id)}
                  style={{
                    backgroundColor: "#4caf50",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "8px 12px",
                    cursor: "pointer",
                  }}
                >
                  Fulfill
                </button>
                <button
                  onClick={() => handleReject(request.id)}
                  style={{
                    backgroundColor: "#f44336",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "8px 12px",
                    cursor: "pointer",
                  }}
                >
                  Reject
                </button>
              </div>
            </div>
          ))}
      </div>
    </div>
  );
}
"}

