{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteMachineReport,
  getAllMachineReports,
  getMachineReportById,
  insertMachineReport,
  updateMachineReport
} from "../db/machine-reports-table";

export const router = Router();

// Get all machine reports
router.get("/", (req: Request, res: Response) => {
  try {
    const reports = getAllMachineReports();
    return res.json(reports);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch reports" });
  }
});

// Get a specific machine report by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid report ID" });
    }

    const report = getMachineReportById(id);
    if (!report) {
      return res.status(404).json({ error: "Report not found" });
    }

    return res.json(report);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch report" });
  }
});

// Create a new machine report
router.post("/", (req: Request, res: Response) => {
  try {
    const { member_id, machine_id, report_text } = req.body;

    if (!member_id || !machine_id || !report_text) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const newId = insertMachineReport(member_id, machine_id, report_text);
    const newReport = getMachineReportById(newId);

    return res.status(201).json(newReport);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create report" });
  }
});

// Update an existing machine report
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { member_id, machine_id, report_text } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid report ID" });
    }

    if (!member_id || !machine_id || !report_text) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const updatedId = updateMachineReport(id, member_id, machine_id, report_text);
    const updatedReport = getMachineReportById(updatedId);

    if (!updatedReport) {
      return res.status(404).json({ error: "Report not found" });
    }

    return res.json(updatedReport);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update report" });
  }
});

// Delete a machine report (supervisor-only access)
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid report ID" });
    }

    // In a real app, we'd check for supervisor role here
    // For now, we'll just enforce that the report exists
    const existingReport = getMachineReportById(id);
    if (!existingReport) {
      return res.status(404).json({ error: "Report not found" });
    }

    const deletedRows = deleteMachineReport(id);
    if (deletedRows === 0) {
      return res.status(404).json({ error: "Report not found" });
    }

    return res.json({ message: "Report deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete report" });
  }
});
"}

{"code":"import { useEffect, useState } from "react";

interface AgingBatch {
  id: number;
  cheeseType: string;
  startDate: string;
  endDate?: string;
  status: 'active' | 'completed' | 'failed';
}

export function BatchLogForm() {
  const [batches, setBatches] = useState<AgingBatch[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    cheeseType: '',
    startDate: '',
    endDate: '',
    status: 'active' as 'active' | 'completed' | 'failed',
  });
  const [editingId, setEditingId] = useState<number | null>(null);

  useEffect(() => {
    fetchBatches();
  }, []);

  const fetchBatches = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/aging-batches-api/');
      if (!response.ok) throw new Error('Failed to fetch batches');
      const data = await response.json();
      setBatches(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const url = editingId 
        ? `/api/aging-batches-api/${editingId}`
        : '/api/aging-batches-api/';

      const method = editingId ? 'PUT' : 'POST';

      const response = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });

      if (!response.ok) throw new Error('Failed to save batch');

      // Reset form
      setFormData({
        cheeseType: '',
        startDate: '',
        endDate: '',
        status: 'active',
      });
      setEditingId(null);

      // Refresh data
      await fetchBatches();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleEdit = (batch: AgingBatch) => {
    setFormData({
      cheeseType: batch.cheeseType,
      startDate: batch.startDate,
      endDate: batch.endDate || '',
      status: batch.status,
    });
    setEditingId(batch.id);
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/aging-batches-api/${id}`, {
        method: 'DELETE',
      });

      if (!response.ok) throw new Error('Failed to delete batch');

      await fetchBatches();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui' }}>
      <h1 style={{ textAlign: 'center' }}>Cheese Aging Batch Log</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>Cheese Type:</label>
          <input
            type="text"
            name="cheeseType"
            value={formData.cheeseType}
            onChange={handleChange}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>Start Date:</label>
          <input
            type="date"
            name="startDate"
            value={formData.startDate}
            onChange={handleChange}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>End Date (optional):</label>
          <input
            type="date"
            name="endDate"
            value={formData.endDate}
            onChange={handleChange}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>Status:</label>
          <select
            name="status"
            value={formData.status}
            onChange={handleChange}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
          >
            <option value="active">Active</option>
            <option value="completed">Completed</option>
            <option value="failed">Failed</option>
          </select>
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: '#4CAF50', 
            color: 'white', 
            padding: '10px 15px', 
            border: 'none', 
            borderRadius: '4px', 
            cursor: 'pointer' 
          }}
        >
          {editingId ? 'Update Batch' : 'Add Batch'}
        </button>
      </form>

      <h2 style={{ textAlign: 'center' }}>Aging Batches</h2>

      {batches.length === 0 ? (
        <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No batches found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {batches.map(batch => (
            <div 
              key={batch.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center', 
                flexWrap: 'wrap'
              }}
            >
              <div>
                <strong>{batch.cheeseType}</strong><br />
                Start: {new Date(batch.startDate).toLocaleDateString()}<br />
                End: {batch.endDate ? new Date(batch.endDate).toLocaleDateString() : 'N/A'}<br />
                Status: {batch.status}
              </div>
              <div style={{ display: 'flex', gap: '5px', marginTop: '10px' }}>
                <button 
                  onClick={() => handleEdit(batch)}
                  style={{ 
                    backgroundColor: '#2196F3', 
                    color: 'white', 
                    border: 'none', 
                    padding: '5px 10px', 
                    borderRadius: '4px', 
                    cursor: 'pointer' 
                  }}
                >
                  Edit
                </button>
                <button 
                  onClick={() => handleDelete(batch.id)}
                  style={{ 
                    backgroundColor: '#f44336', 
                    color: 'white', 
                    border: 'none', 
                    padding: '5px 10px', 
                    borderRadius: '4px', 
                    cursor: 'pointer' 
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

