{"code":"import { useEffect, useState } from "react";

interface Session {
  id: number;
  tutor: string;
  date: string;
  topic: string;
}

export function SessionSearch() {
  const [sessions, setSessions] = useState<Session[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [filter, setFilter] = useState<"tutor" | "date" | "topic">("tutor");

  useEffect(() => {
    fetchSessions();
  }, []);

  const fetchSessions = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/sessions-table/`);
      if (!response.ok) {
        throw new Error(`Failed to fetch sessions: ${response.status}`);
      }
      const data = await response.json();
      setSessions(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    fetchSessions();
  };

  const filteredSessions = sessions.filter(session => {
    if (!searchTerm) return true;
    switch (filter) {
      case "tutor":
        return session.tutor.toLowerCase().includes(searchTerm.toLowerCase());
      case "date":
        return session.date.toLowerCase().includes(searchTerm.toLowerCase());
      case "topic":
        return session.topic.toLowerCase().includes(searchTerm.toLowerCase());
      default:
        return true;
    }
  });

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Session Search</h1>

      <form onSubmit={handleSearch} style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc", width: "100%" }}
        />
        <select
          value={filter}
          onChange={(e) => setFilter(e.target.value as "tutor" | "date" | "topic")}
          style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc", width: "100%" }}
        >
          <option value="tutor">Search by Tutor</option>
          <option value="date">Search by Date</option>
          <option value="topic">Search by Topic</option>
        </select>
        <button type="submit" style={{ padding: "10px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "5px", cursor: "pointer" }}>
          Search
        </button>
      </form>

      {filteredSessions.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No sessions found.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
          {filteredSessions.map((session) => (
            <div key={session.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px", width: "100%", maxWidth: "300px" }}>
              <h3>{session.tutor}</h3>
              <p><strong>Date:</strong> {session.date}</p>
              <p><strong>Topic:</strong> {session.topic}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { FC, useEffect, useState } from "react";

interface Book {
  id: number;
  title: string;
  price: number;
  condition: string;
}

export function ListingForm() {
  const [title, setTitle] = useState("");
  const [price, setPrice] = useState("");
  const [condition, setCondition] = useState("");
  const [books, setBooks] = useState<Book[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    fetchBooks();
  }, []);

  const fetchBooks = async () => {
    try {
      const response = await fetch("/api/books-api/");
      if (!response.ok) throw new Error("Failed to fetch books");
      const data = await response.json();
      setBooks(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!title || !price || !condition) return;

    try {
      const response = await fetch("/api/books-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          title,
          price: Number(price),
          condition
        })
      });

      if (!response.ok) throw new Error("Failed to add book");

      // Reset form
      setTitle("");
      setPrice("");
      setCondition("");

      // Refresh the list
      await fetchBooks();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  return (
    <div style={{
      maxWidth: "600px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
