{"code":"import { FC, useEffect, useState } from "react";

interface AttendanceRecord {
  id: number;
  supervisorId: number;
  date: string;
  status: string;
}

export function SupervisorDeletionGuard() {
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [supervisorId, setSupervisorId] = useState<number>(1); // Example supervisor ID

  useEffect(() => {
    fetchRecords();
  }, []);

  const fetchRecords = async () => {
    try {
      const response = await fetch(`/api/attendance-records-api/`);
      if (!response.ok) {
        throw new Error(`Failed to fetch records: ${response.status}`);
      }
      const data = await response.json();
      setRecords(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleDelete = async (id: number) => {
    try {
      // Check if the record belongs to the current supervisor
      const record = records.find(r => r.id === id);
      if (!record) return;

      if (record.supervisorId === supervisorId) {
        alert("You cannot delete your own attendance record.");
        return;
      }

      const response = await fetch(`/api/attendance-records-api/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error(`Failed to delete record: ${response.status}`);
      }

      // Refresh the list after successful deletion
      fetchRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center" }}>{error}</div>;

  if (records.length === 0) {
    return <div style={{ textAlign: "center" }}>No attendance records found.</div>;
  }

  return (
    <div style={{ maxWidth: 800, margin: "0 auto", padding: 20, fontFamily: "system-ui" }}>
      <h2>Attendance Records</h2>
      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead>
          <tr style={{ borderBottom: "1px solid #ccc" }}>
            <th style={{ textAlign: "left", padding: 10 }}>Date</th>
            <th style={{ textAlign: "left", padding: 10 }}>Status</th>
            <th style={{ textAlign: "left", padding: 10 }}>Actions</th>
          </tr>
        </thead>
        <tbody>
          {records.map(record => (
            <tr key={record.id} style={{ borderBottom: "1px solid #eee" }}>
              <td style={{ padding: 10 }}>{record.date}</td>
              <td style={{ padding: 10 }}>{record.status}</td>
              <td style={{ padding: 10 }}>
                <button 
                  onClick={() => handleDelete(record.id)}
                  style={{ 
                    backgroundColor: "#dc3545", 
                    color: "white", 
                    border: "none", 
                    padding: "5px 10px", 
                    borderRadius: 4, 
                    cursor: "pointer" 
                  }}
                >
                  Delete
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
"}

