{"code":"import { FC, useEffect, useState } from "react";

interface Submission {
  id: string;
  title: string;
  authorId: string;
}

interface Export {
  id: string;
  submissionId: string;
  status: string;
}

export function ExportHistoryGuard() {
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [exports, setExports] = useState<Export[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentUserId, setCurrentUserId] = useState<string | null>(null);

  useEffect(() => {
    const fetchUserData = async () => {
      try {
        const userResponse = await fetch('/api/user');
        if (!userResponse.ok) throw new Error('Failed to fetch user data');
        const userData = await userResponse.json();
        setCurrentUserId(userData.id);
      } catch (err) {
        setError('Failed to load user data');
        setLoading(false);
      }
    };

    const fetchSubmissions = async () => {
      try {
        const response = await fetch('/api/submissions-api/submissions');
        if (!response.ok) throw new Error('Failed to fetch submissions');
        const data = await response.json();
        setSubmissions(data);
      } catch (err) {
        setError('Failed to load submissions');
      } finally {
        setLoading(false);
      }
    };

    const fetchExports = async () => {
      try {
        const response = await fetch('/api/submissions-api/exports');
        if (!response.ok) throw new Error('Failed to fetch exports');
        const data = await response.json();
        setExports(data);
      } catch (err) {
        setError('Failed to load exports');
      }
    };

    fetchUserData();
    fetchSubmissions();
    fetchExports();
  }, []);

  const handleExport = async (submissionId: string) => {
    try {
      const response = await fetch(`/api/export-guard-service/export/${submissionId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      });

      if (!response.ok) throw new Error('Export failed');

      // Refresh data after successful export
      const submissionsResponse = await fetch('/api/submissions-api/submissions');
      const exportsResponse = await fetch('/api/submissions-api/exports');

      if (submissionsResponse.ok && exportsResponse.ok) {
        const submissionsData = await submissionsResponse.json();
        const exportsData = await exportsResponse.json();

        setSubmissions(submissionsData);
        setExports(exportsData);
      }
    } catch (err) {
      setError('Export failed');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Export History</h1>

      {submissions.length === 0 ? (
        <p>No submissions found.</p>
      ) : (
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ borderBottom: '1px solid #ccc' }}>
              <th style={{ textAlign: 'left', padding: '10px' }}>Title</th>
              <th style={{ textAlign: 'left', padding: '10px' }}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {submissions.map((submission) => {
              const hasExport = exports.some(e => e.submissionId === submission.id);
              const canExport = currentUserId === submission.authorId;

              return (
                <tr key={submission.id} style={{ borderBottom: '1px solid #eee' }}>
                  <td style={{ padding: '10px' }}>{submission.title}</td>
                  <td style={{ padding: '10px' }}>
                    {canExport && !hasExport ? (
                      <button 
                        onClick={() => handleExport(submission.id)}
                        style={{ 
                          backgroundColor: '#007bff', 
                          color: 'white', 
                          border: 'none', 
                          borderRadius: '4px', 
                          padding: '8px 12px', 
                          cursor: 'pointer' 
                        }}
                      >
                        Export
                      </button>
                    ) : null}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

export function QuestionTimer() {
  const [timeLeft, setTimeLeft] = useState<number>(10);
  const [isActive, setIsActive] = useState<boolean>(true);

  useEffect(() => {
    let interval: NodeJS.Timeout | null = null;

    if (isActive && timeLeft > 0) {
      interval = setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      // Handle timer completion
      console.log("Time's up!");
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isActive, timeLeft]);

  const handleReset = () => {
    setTimeLeft(10);
    setIsActive(true);
  };

  const handlePause = () => {
    setIsActive(false);
  };

  const handleStart = () => {
    setIsActive(true);
  };

  return (
    <div style={{
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      justifyContent: "center",
      minHeight: "100vh",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      backgroundColor: "#f5f5f5",
      padding: "20px",
    }}>
      <div style={{
        backgroundColor: "white",
        borderRadius: "12px",
        padding: "30px",
        boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
        textAlign: "center",
        maxWidth: "400px",
        width: "100%",
      }}>
        <h1 style={{
          color: "#333",
          marginBottom: "20px",
          fontSize: "24px",
        }}>
          Next Question In:
        </h1>

        <div style={{
          fontSize: "64px",
          fontWeight: "bold",
          color: timeLeft <= 3 ? "#ff4757" : "#2ed573",
          marginBottom: "30px",
          fontFamily: "monospace",
        }}>
          {timeLeft}
        </div>

        <div style={{
          display: "flex",
          gap: "10px",
          justifyContent: "center",
          flexWrap: "wrap",
        }}>
          <button 
            onClick={handleStart}
            disabled={isActive}
            style={{
              backgroundColor: "#2ed573",
              color: "white",
              border: "none",
              borderRadius: "8px",
              padding: "10px 20px",
              cursor: isActive ? "default" : "pointer",
              fontSize: "16px",
              fontWeight: "500",
              transition: "background-color 0.2s",
            }}
          >
            Start
          </button>

          <button 
            onClick={handlePause}
            disabled={!isActive}
            style={{
              backgroundColor: "#ffa502",
              color: "white",
              border: "none",
              borderRadius: "8px",
              padding: "10px 20px",
              cursor: !isActive ? "default" : "pointer",
              fontSize: "16px",
              fontWeight: "500",
              transition: "background-color 0.2s",
            }}
          >
            Pause
          </button>

          <button 
            onClick={handleReset}
            style={{
              backgroundColor: "#3742fa",
              color: "white",
              border: "none",
              borderRadius: "8px",
              padding: "10px 20px",
              cursor: "pointer",
              fontSize: "16px",
              fontWeight: "500",
              transition: "background-color 0.2s",
            }}
          >
            Reset
          </button>
        </div>
      </div>
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface Schedule {
  id: string;
  name: string;
  sourcePath: string;
  destinationPath: string;
  scheduleExpression: string;
  isEnabled: boolean;
}

export function BackupConfigurationUi() {
  const [schedules, setSchedules] = useState<Schedule[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    name: "",
    sourcePath: "",
    destinationPath: "",
    scheduleExpression: "",
    isEnabled: true
  });

  const [editingId, setEditingId] = useState<string | null>(null);

  useEffect(() => {
    fetchSchedules();
  }, []);

  const fetchSchedules = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/backup-scheduler/status');
      if (!response.ok) throw new Error('Failed to fetch schedules');
      const data = await response.json();
      setSchedules(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value, type } = e.target as HTMLInputElement | HTMLTextAreaElement;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? (e.target as HTMLInputElement).checked : value
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = editingId 
        ? await fetch(`/api/backup-scheduler/schedule/${editingId}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(formData)
          })
        : await fetch('/api/backup-scheduler/schedule', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(formData)
          });

      if (!response.ok) throw new Error('Failed to save schedule');

      // Reset form and refetch data
      setFormData({
        name: "",
        sourcePath: "",
        destinationPath: "",
        scheduleExpression: "",
        isEnabled: true
      });
      setEditingId(null);
      fetchSchedules();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleEdit = (schedule: Schedule) => {
    setFormData({
      name: schedule.name,
      sourcePath: schedule.sourcePath,
      destinationPath: schedule.destinationPath,
      scheduleExpression: schedule.scheduleExpression,
      isEnabled: schedule.isEnabled
    });
    setEditingId(schedule.id);
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/backup-scheduler/schedule/${id}`, {
        method: 'DELETE'
      });
      if (!response.ok) throw new Error('Failed to delete schedule');
      fetchSchedules();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const containerStyle: React.CSSProperties = {
    maxWidth: '800px',
    margin: '0 auto',
    padding: '20px',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
  };

  const cardStyle: React.CSSProperties = {
    border: '1px solid #ddd',
    borderRadius: '8px',
    padding: '16px',
    marginBottom: '16px',
    backgroundColor: '#f9f9f9'
  };

  const inputStyle: React.CSSProperties = {
    width: '100%',
    padding: '8px',
    marginBottom: '12px',
    borderRadius: '4px',
    border: '1px solid #ccc'
  };

  const buttonStyle: React.CSSProperties = {
    backgroundColor: '#007bff',
    color: 'white',
    border: 'none',
    padding: '8px 16px',
    borderRadius: '4px',
    cursor: 'pointer',
    marginRight: '8px'
  };

  const buttonGroupStyle: React.CSSProperties = {
    display: 'flex',
    flexWrap: 'wrap',
    gap: '8px'
  };

  if (loading) return <div style={containerStyle}>Loading...</div>;

  if (error) return (
    <div style={containerStyle}>
      <h2>Error</h2>
      <p>{error}</p>
    </div>
  );

  return (
    <div style={containerStyle}>
      <h1>Backup Configuration</h1>

      <form onSubmit={handleSubmit} style={cardStyle}>
        <h2>{editingId ? 'Edit Schedule' : 'Create New Schedule'}</h2>

        <input
          type="text"
          name="name"
          placeholder="Schedule Name"
          value={formData.name}
          onChange={handleInputChange}
          style={inputStyle}
        />

        <input
          type="text"
          name="sourcePath"
          placeholder="Source Path"
          value={formData.sourcePath}
          onChange={handleInputChange}
          style={inputStyle}
        />

        <input
          type="text"
          name="destinationPath"
          placeholder="Destination Path"
          value={formData.destinationPath}
          onChange={handleInputChange}
          style={inputStyle}
        />

        <input
          type="text"
          name="scheduleExpression"
          placeholder="Cron Expression"
          value={formData.scheduleExpression}
          onChange={handleInputChange}
          style={inputStyle}
        />

        <label>
          <input
            type="checkbox"
            name="isEnabled"
            checked={formData.isEnabled}
            onChange={handleInputChange}
          /> Enable Schedule
        </label>

        <button type="submit" style={buttonStyle}>Save Schedule</button>
      </form>

      <h2>Saved Schedules</h2>

      {schedules.length === 0 ? (
        <p>No schedules found.</p>
      ) : (
        <div>
          {schedules.map(schedule => (
            <div key={schedule.id} style={cardStyle}>
              <h3>{schedule.name}</h3>
              <p><strong>Source:</strong> {schedule.sourcePath}</p>
              <p><strong>Destination:</strong> {schedule.destinationPath}</p>
              <p><strong>Schedule:</strong> {schedule.scheduleExpression}</p>
              <p><strong>Status:</strong> {schedule.isEnabled ? 'Enabled' : 'Disabled'}</p>

              <div style={buttonGroupStyle}>
                <button onClick={() => handleEdit(schedule)} style={buttonStyle}>Edit</button>
                <button onClick={() => handleDelete(schedule.id)} style={buttonStyle}>Delete</button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
