{"code":"import { Router, type Request, type Response } from "express";
import { db, deleteStop, getAllStops, getStopById, insertStop, updateStop } from "../db/stops-table";

export const router = Router();

// Get all stops
router.get("/stops", (req: Request, res: Response) => {
  try {
    const stops = getAllStops();
    res.json(stops);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch stops" });
  }
});

// Get a stop by ID
router.get("/stops/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const stop = getStopById(id);
    if (!stop) {
      return res.status(404).json({ error: "Stop not found" });
    }
    res.json(stop);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch stop" });
  }
});

// Create a new stop
router.post("/stops", (req: Request, res: Response) => {
  try {
    const { tripId, stopNumber, location, note } = req.body;

    // Validate required fields
    if (typeof tripId !== "number" || typeof stopNumber !== "number" || !location) {
      return res.status(400).json({ error: "Invalid input data" });
    }

    const newId = insertStop(tripId, stopNumber, location, note);
    res.status(201).json({ id: newId, tripId, stopNumber, location, note });
  } catch (error) {
    res.status(500).json({ error: "Failed to create stop" });
  }
});

// Update a stop
router.put("/stops/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { tripId, stopNumber, location, note } = req.body;

    // Validate required fields
    if (typeof tripId !== "number" || typeof stopNumber !== "number" || !location) {
      return res.status(400).json({ error: "Invalid input data" });
    }

    const existingStop = getStopById(id);
    if (!existingStop) {
      return res.status(404).json({ error: "Stop not found" });
    }

    updateStop(id, tripId, stopNumber, location, note);
    res.json({ id, tripId, stopNumber, location, note });
  } catch (error) {
    res.status(500).json({ error: "Failed to update stop" });
  }
});

// Delete a stop
router.delete("/stops/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const existingStop = getStopById(id);
    if (!existingStop) {
      return res.status(404).json({ error: "Stop not found" });
    }

    deleteStop(id);
    res.json({ message: "Stop deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete stop" });
  }
});
