  if (!docentId || !exhibitId || !date) {
    return res.status(400).json({ error: "Missing required fields: docentId, exhibitId, date" });
  }

  const existingTour = getTourById(id);

  if (!existingTour) {
    return res.status(404).json({ error: "Tour not found" });
  }

  updateTour(id, docentId, exhibitId, date);
  const updatedTour = getTourById(id);

  if (!updatedTour) {
    return res.status(500).json({ error: "Failed to update tour" });
  }

  res.json(updatedTour);
