{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("parking_garage.db");

interface Reservation {
  id: number;
  driverId: number;
  spotNumber: string;
  reservedTime: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS reservations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    driverId INTEGER NOT NULL,
    spotNumber TEXT NOT NULL,
    reservedTime TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllReservations(): Reservation[] {
  const stmt = db.prepare("SELECT * FROM reservations");
  return stmt.all() as unknown as Reservation[];
}

export function getReservationById(id: number): Reservation | undefined {
  const stmt = db.prepare("SELECT * FROM reservations WHERE id = ?");
  return stmt.get(id) as unknown as Reservation | undefined;
}

export function insertReservation(
  driverId: number,
  spotNumber: string,
  reservedTime: string
): number {
  const stmt = db.prepare(
    "INSERT INTO reservations (driverId, spotNumber, reservedTime) VALUES (?, ?, ?)"
  );
  const result = stmt.run(driverId, spotNumber, reservedTime);
  return Number(result.lastInsertRowid);
}

export function updateReservation(
  id: number,
  driverId: number,
  spotNumber: string,
  reservedTime: string
): void {
  const stmt = db.prepare(
    "UPDATE reservations SET driverId = ?, spotNumber = ?, reservedTime = ? WHERE id = ?"
  );
  stmt.run(driverId, spotNumber, reservedTime, id);
}

export function deleteReservation(id: number): void {
  const stmt = db.prepare("DELETE FROM reservations WHERE id = ?");
  stmt.run(id);
}

