      } catch (err: unknown) {
        if (err instanceof Error) {
          setError("Error loading submissions: " + err.message);
        } else {
          setError("Error loading submissions: Unknown error");
        }
      }
    };

    fetchCategories();
    fetchSubmissions();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || selectedCategory === null || !file) {
      setError("Please fill all fields and select a file.");
      return;
    }

    try {
      const formData = new FormData();
      formData.append("title", title);
      formData.append("categoryId", selectedCategory.toString());
      formData.append("manuscript", file);

      const response = await fetch("/api/submissions-api/", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) {
        throw new Error(`Failed to submit manuscript: ${response.status}`);
      }

      // Reset form
      setTitle("");
      setSelectedCategory(null);
      setFile(null);
      setError(null);

      // Refresh submissions
      const submissionsResponse = await fetch("/api/submissions-api/");
      if (submissionsResponse.ok) {
        const submissionsData = await submissionsResponse.json();
        setSubmissions(submissionsData);
      }
    } catch (err: unknown) {
      if (err instanceof Error) {
        setError("Error submitting manuscript: " + err.message);
      } else {
        setError("Error submitting manuscript: Unknown error");
      }
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  const containerStyle: React.CSSProperties = {
    maxWidth: "800px",
    margin: "0 auto",
    padding: "20px",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
  };

  const formStyle: React.CSSProperties = {
    backgroundColor: "#f9f9f9",
    padding: "20px",
    borderRadius: "8px",
    marginBottom: "20px",
  };

  const inputStyle: React.CSSProperties = {
    width: "100%",
    padding: "10px",
    marginBottom: "10px",
    borderRadius: "4px",
    border: "1px solid #ccc",
  };

  const buttonStyle: React.CSSProperties = {
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    padding: "10px 20px",
    borderRadius: "4px",
    cursor: "pointer",
    fontWeight: "bold",
  };

  const submissionListStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
  };

  const submissionCardStyle: React.CSSProperties = {
    border: "1px solid #ddd",
    borderRadius: "4px",
    padding: "15px",
    backgroundColor: "#fff",
  };

  return (
    <div style={containerStyle}>
      <h1>Submit Your Manuscript</h1>

      {error && <div style={{ color: "red", marginBottom: "10px" }}>{error}</div>}

      <form onSubmit={handleSubmit} style={formStyle}>
        <input
          type="text"
          placeholder="Manuscript Title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          style={inputStyle}
        />

        <select
          value={selectedCategory ?? ""}
          onChange={(e) => setSelectedCategory(Number(e.target.value))}
          style={inputStyle}
        >
          <option value="">Select Category</option>
          {categories.map((category) => (
            <option key={category.id} value={category.id}>
              {category.name}
            </option>
          ))}
        </select>

        <input
          type="file"
          accept=".pdf,.doc,.docx"
          onChange={(e) => setFile(e.target.files?.[0] || null)}
          style={inputStyle}
        />

        <button type="submit" style={buttonStyle}>Submit Manuscript</button>
      </form>

      <h2>Your Submissions</h2>

      {submissions.length === 0 ? (
        <p>No submissions yet.</p>
      ) : (
        <div style={submissionListStyle}>
          {submissions.map((submission) => (
            <div key={submission.id} style={submissionCardStyle}>
              <strong>{submission.title}</strong> - {submission.category} - {submission.status}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import { db, deleteDeviceState, getAllDeviceStates, getDeviceStateById, insertDeviceState, updateDeviceState } from "../db/device-states-table";

export const router = Router();

// Get all device states
router.get("/", (req: Request, res: Response) => {
  try {
    const deviceStates = getAllDeviceStates();
    res.json(deviceStates);
  } catch (error) {
    res.status(500).json({ error: "Failed to retrieve device states" });
  }
});

// Get a specific device state by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const deviceState = getDeviceStateById(id);
    if (!deviceState) {
      return res.status(404).json({ error: "Device state not found" });
    }

    res.json(deviceState);
  } catch (error) {
    res.status(500).json({ error: "Failed to retrieve device state" });
  }
});

// Create a new device state
router.post("/", (req: Request, res: Response) => {
  try {
    const { deviceId, state, timestamp } = req.body;

    if (!deviceId || !state || !timestamp) {
      return res.status(400).json({ error: "Missing required fields: deviceId, state, or timestamp" });
    }

    const newId = insertDeviceState(deviceId, state, timestamp);
    res.status(201).json({ id: newId, deviceId, state, timestamp });
  } catch (error) {
    res.status(500).json({ error: "Failed to create device state" });
  }
});

// Update an existing device state
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const { deviceId, state, timestamp } = req.body;

    if (!deviceId || !state || !timestamp) {
      return res.status(400).json({ error: "Missing required fields: deviceId, state, or timestamp" });
    }

    const existingDeviceState = getDeviceStateById(id);
    if (!existingDeviceState) {
      return res.status(404).json({ error: "Device state not found" });
    }

    updateDeviceState(id, deviceId, state, timestamp);
    res.json({ id, deviceId, state, timestamp });
  } catch (error) {
    res.status(500).json({ error: "Failed to update device state" });
  }
});

// Delete a device state
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const existingDeviceState = getDeviceStateById(id);
    if (!existingDeviceState) {
      return res.status(404).json({ error: "Device state not found" });
    }

    deleteDeviceState(id);
    res.json({ message: "Device state deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete device state" });
  }
});
"}

