          style={{
            display: "flex",
            flexWrap: "wrap",
            gap: "10px",
          }}
        >
          {timeSlots.map((slot) => {
            const date = new Date(slot);
            const formattedTime = date.toLocaleTimeString([], {
              hour: "2-digit",
              minute: "2-digit",
            });
            const isSelected = selectedTimeSlot === slot;

            return (
              <button
                key={slot}
                onClick={() => setSelectedTimeSlot(slot)}
                style={{
                  padding: "10px 15px",
                  border: "1px solid #ccc",
                  borderRadius: "5px",
                  backgroundColor: isSelected ? "#007bff" : "white",
                  color: isSelected ? "white" : "black",
                  cursor: "pointer",
                  flex: "1 1 calc(50% - 10px)",
                }}
              >
                {formattedTime}
              </button>
            );
          })}
        </div>
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h2>Your Reservations</h2>
        {reservations.length === 0 ? (
          <p>No reservations found.</p>
        ) : (
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>Start Time</th>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>End Time</th>
              </tr>
            </thead>
            <tbody>
              {reservations.map((reservation) => {
                const start = new Date(reservation.startTime);
                const end = new Date(reservation.endTime);
                return (
                  <tr key={reservation.id}>
                    <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                      {start.toLocaleString()}
                    </td>
                    <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                      {end.toLocaleString()}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>

      <div style={{ textAlign: "center" }}>
        <button
          onClick={handleReserve}
          disabled={!selectedTimeSlot}
          style={{
            padding: "10px 20px",
            backgroundColor: selectedTimeSlot ? "#28a745" : "#ccc",
            color: "white",
            border: "none",
            borderRadius: "5px",
            cursor: selectedTimeSlot ? "pointer" : "default",
          }}
        >
          Reserve Selected Slot
        </button>
      </div>
    </div>
  );
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check deletion requests
  if (req.method !== "DELETE") {
    next();
    return;
  }

  // For this middleware, we assume role checking is handled by a prior middleware
  // If there's no user object, we can't determine role, so we allow the request
  // In a real implementation, you'd want to ensure a prior auth middleware sets req.user
  const userRole = (req as any).user?.role;

  // If user has no role or is not supervisor, reject
  if (!userRole || userRole !== "supervisor") {
    res.status(403).json({ error: "Deletion access denied. Supervisor role required." });
    return;
  }

  // Allow supervisor to proceed
  next();
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./food-bank.db");

interface Donation {
  id: number;
  itemName: string;
  quantity: number;
  date: string;
  loggedByUserId: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS donations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    itemName TEXT NOT NULL,
    quantity INTEGER NOT NULL,
    date TEXT NOT NULL,
    loggedByUserId INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllDonations(): Donation[] {
  const stmt = db.prepare("SELECT * FROM donations");
  return stmt.all() as unknown as Donation[];
}

export function getDonationById(id: number): Donation | undefined {
  const stmt = db.prepare("SELECT * FROM donations WHERE id = ?");
  return stmt.get(id) as unknown as Donation | undefined;
}

export function insertDonation(
  itemName: string,
  quantity: number,
  date: string,
  loggedByUserId: number
): number {
  const stmt = db.prepare(
    "INSERT INTO donations (itemName, quantity, date, loggedByUserId) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(itemName, quantity, date, loggedByUserId);
  return Number(result.lastInsertRowid);
}

export function updateDonation(
  id: number,
  itemName: string,
  quantity: number,
  date: string,
  loggedByUserId: number
): number {
  const stmt = db.prepare(
    "UPDATE donations SET itemName = ?, quantity = ?, date = ?, loggedByUserId = ? WHERE id = ?"
  );
  const result = stmt.run(itemName, quantity, date, loggedByUserId, id);
  return Number(result.changes);
}

export function deleteDonation(id: number): number {
  const stmt = db.prepare("DELETE FROM donations WHERE id = ?");
  const result = stmt.run(id);
  return Number(result.changes);
}

// Seed data
if (getAllDonations().length === 0) {
  insertDonation("Rice", 50, "2023-05-15", 1);
