{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "./backend/src/db/childcare-shift-rotation.db"
);

interface ShiftDelete {
  supervisorId: number;
  shiftId: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS shift_deletes (
    supervisor_id INTEGER NOT NULL,
    shift_id INTEGER NOT NULL,
    PRIMARY KEY (supervisor_id, shift_id)
  )
`;

db.exec(createTableSql);

export function getAllShiftDeletes(): ShiftDelete[] {
  const stmt = db.prepare(`SELECT * FROM shift_deletes`);
  return stmt.all() as unknown as ShiftDelete[];
}

export function getShiftDeleteById(
  supervisorId: number,
  shiftId: number
): ShiftDelete | undefined {
  const stmt = db.prepare(
    `SELECT * FROM shift_deletes WHERE supervisor_id = ? AND shift_id = ?`
  );
  return stmt.get(supervisorId, shiftId) as unknown as ShiftDelete | undefined;
}

export function insertShiftDelete(
  supervisorId: number,
  shiftId: number
): number {
  const stmt = db.prepare(
    `INSERT INTO shift_deletes (supervisor_id, shift_id) VALUES (?, ?)`
  );
  const result = stmt.run(supervisorId, shiftId);
  return Number(result.lastInsertRowid);
}

export function deleteShiftDelete(
  supervisorId: number,
  shiftId: number
): void {
  const stmt = db.prepare(
    `DELETE FROM shift_deletes WHERE supervisor_id = ? AND shift_id = ?`
  );
  stmt.run(supervisorId, shiftId);
}

// Insert sample data if table is empty
if (getAllShiftDeletes().length === 0) {
  insertShiftDelete(1, 101);
  insertShiftDelete(2, 102);
  insertShiftDelete(3, 103);
  insertShiftDelete(1, 104);
  insertShiftDelete(2, 105);
}
"}

