      {batches.length === 0 ? (
        <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No batches found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {batches.map(batch => (
            <div 
              key={batch.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center' 
              }}
            >
              <div>
                <strong>{batch.cheeseType}</strong> - {batch.startDate}
                <br />
                Status: {batch.status}
              </div>
              <div>
                <button 
                  onClick={() => handleEdit(batch)}
                  style={{ 
                    backgroundColor: '#17a2b8', 
                    color: 'white', 
                    border: 'none', 
                    padding: '5px 10px', 
                    borderRadius: '4px', 
                    cursor: 'pointer', 
                    marginRight: '5px' 
                  }}
                >
                  Edit
                </button>
                <button 
                  onClick={() => handleDelete(batch.id)}
                  style={{ 
                    backgroundColor: '#dc3545', 
                    color: 'white', 
                    border: 'none', 
                    padding: '5px 10px', 
                    borderRadius: '4px', 
                    cursor: 'pointer' 
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
