{"code":"import { useEffect, useState } from "react";

interface Server {
  id: string;
  name: string;
  status: "running" | "stopped" | "starting" | "stopping";
  gameType: string;
  port: number;
}

export function ServerManagementDashboard() {
  const [servers, setServers] = useState<Server[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newServerName, setNewServerName] = useState("");
  const [newServerGameType, setNewServerGameType] = useState("");
  const [newServerPort, setNewServerPort] = useState("");

  const fetchServers = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/server-orchestration-daemon/servers");
      if (!response.ok) {
        throw new Error(`Failed to fetch servers: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setServers(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchServers();
  }, []);

  const handleCreateServer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newServerName || !newServerGameType || !newServerPort) return;

    try {
      const response = await fetch("/api/server-orchestration-daemon/servers", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: newServerName,
          gameType: newServerGameType,
          port: Number(newServerPort)
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to create server: ${response.status} ${response.statusText}`);
      }

      // Reset form
      setNewServerName("");
      setNewServerGameType("");
      setNewServerPort("");

      // Refresh server list
      await fetchServers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleStartServer = async (id: string) => {
    try {
      const response = await fetch(`/api/server-orchestration-daemon/servers/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "start" })
      });

      if (!response.ok) {
        throw new Error(`Failed to start server: ${response.status} ${response.statusText}`);
      }

      await fetchServers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleStopServer = async (id: string) => {
    try {
      const response = await fetch(`/api/server-orchestration-daemon/servers/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "stop" })
      });

      if (!response.ok) {
        throw new Error(`Failed to stop server: ${response.status} ${response.statusText}`);
      }

      await fetchServers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDeleteServer = async (id: string) => {
    try {
      const response = await fetch(`/api/server-orchestration-daemon/servers/${id}`, {
        method: "DELETE"
      });

      if (!response.ok) {
        throw new Error(`Failed to delete server: ${response.status} ${response.statusText}`);
      }

      await fetchServers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const containerStyle: React.CSSProperties = {
    maxWidth: "800px",
    margin: "0 auto",
    padding: "20px",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif"
  };

  const headingStyle: React.CSSProperties = {
    textAlign: "center",
    color: "#333"
  };

  const formStyle: React.CSSProperties = {
    backgroundColor: "#f5f5f5",
    padding: "20px",
    borderRadius: "8px",
    marginBottom: "20px"
  };

  const inputGroupStyle: React.CSSProperties = {
    marginBottom: "15px"
  };

  const inputStyle: React.CSSProperties = {
    width: "100%",
    padding: "10px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    boxSizing: "border-box"
  };

  const buttonStyle: React.CSSProperties = {
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    padding: "10px 15px",
    borderRadius: "4px",
    cursor: "pointer",
    marginRight: "10px",
    fontSize: "16px"
  };

  const buttonStyleDisabled: React.CSSProperties = {
    backgroundColor: "#6c757d",
    color: "white",
    border: "none",
    padding: "10px 15px",
    borderRadius: "4px",
    cursor: "default",
    fontSize: "16px"
  };

  const serverListStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "15px"
  };

  const serverCardStyle: React.CSSProperties = {
    border: "1px solid #ddd",
    borderRadius: "8px",
    padding: "15px",
    backgroundColor: "#fff"
  };

  const serverHeaderStyle: React.CSSProperties = {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    marginBottom: "10px"
  };

  const serverNameStyle: React.CSSProperties = {
    fontWeight: "bold",
    fontSize: "18px",
    color: "#333"
  };

  const serverStatusStyle: React.CSSProperties = {
    padding: "4px 8px",
    borderRadius: "4px",
    fontSize: "14px"
  };

  const runningStatusStyle: React.CSSProperties = {
    ...serverStatusStyle,
    backgroundColor: "#d4edda",
    color: "#155724"
  };

  const stoppedStatusStyle: React.CSSProperties = {
    ...serverStatusStyle,
    backgroundColor: "#f8f9fa",
    color: "#6c757d"
  };

  const startingStatusStyle: React.CSSProperties = {
    ...serverStatusStyle,
    backgroundColor: "#fff3cd",
    color: "#856404"
  };

  const stoppingStatusStyle: React.CSSProperties = {
    ...serverStatusStyle,
    backgroundColor: "#f8cecc",
    color: "#721c24"
  };

  const serverDetailsStyle: React.CSSProperties = {
    marginBottom: "10px"
  };

  const serverActionsStyle: React.CSSProperties = {
    display: "flex",
    gap: "10px"
  };

  if (loading) {
    return (
      <div style={containerStyle}>
        <h1 style={headingStyle}>Server Management Dashboard</h1>
        <p>Loading...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div style={containerStyle}>
        <h1 style={headingStyle}>Server Management Dashboard</h1>
        <p>Error: {error}</p>
      </div>
    );
  }

  return (
    <div style={containerStyle}>
      <h1 style={headingStyle}>Server Management Dashboard</h1>

      <form onSubmit={handleCreateServer} style={formStyle}>
        <div style={inputGroupStyle}>
          <input
            type="text"
            placeholder="Server Name"
            value={newServerName}
            onChange={(e) => setNewServerName(e.target.value)}
            style={inputStyle}
          />
        </div>
        <div style={inputGroupStyle}>
          <input
            type="text"
            placeholder="Game Type"
            value={newServerGameType}
            onChange={(e) => setNewServerGameType(e.target.value)}
            style={inputStyle}
          />
        </div>
        <div style={inputGroupStyle}>
          <input
            type="number"
            placeholder="Port"
            value={newServerPort}
            onChange={(e) => setNewServerPort(e.target.value)}
            style={inputStyle}
          />
        </div>
        <button type="submit" style={buttonStyle}>Create Server</button>
      </form>

      <div style={serverListStyle}>
        {servers.length === 0 ? (
          <p>No servers found.</p>
        ) : (
          servers.map((server) => (
            <div key={server.id} style={serverCardStyle}>
              <div style={serverHeaderStyle}>
                <span style={serverNameStyle}>{server.name}</span>
                <span 
                  style={
                    server.status === "running" ? runningStatusStyle :
                    server.status === "stopped" ? stoppedStatusStyle :
                    server.status === "starting" ? startingStatusStyle :
                    stoppingStatusStyle
                  }
                >
                  {server.status.charAt(0).toUpperCase() + server.status.slice(1)}
                </span>
              </div>
              <div style={serverDetailsStyle}>
                <p>Game Type: {server.gameType}</p>
                <p>Port: {server.port}</p>
              </div>
              <div style={serverActionsStyle}>
                {server.status === "stopped" ? (
                  <button onClick={() => handleStartServer(server.id)} style={buttonStyle}>Start</button>
                ) : server.status === "running" ? (
                  <button onClick={() => handleStopServer(server.id)} style={buttonStyle}>Stop</button>
                ) : (
                  <button disabled style={buttonStyleDisabled}>Action</button>
                )}
                <button onClick={() => handleDeleteServer(server.id)} style={{...buttonStyle, backgroundColor: "#dc3545"}}>Delete</button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import { db, deleteServer, getAllServers, getServerById, insertServer, updateServer } from "../db/servers-table";

export const router = Router();

// GET /servers - List all servers
router.get("/servers", (req: Request, res: Response) => {
  try {
    const servers = getAllServers();
    return res.json(servers);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch servers" });
  }
});

// GET /servers/:id - Get a specific server by ID
router.get("/servers/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid server ID" });
    }

    const server = getServerById(id);
    if (!server) {
      return res.status(404).json({ error: "Server not found" });
    }

    return res.json(server);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch server" });
  }
});

// POST /servers - Create a new server
router.post("/servers", (req: Request, res: Response) => {
  try {
    const { name, ownerId, config } = req.body;

    if (!name || !ownerId || !config) {
      return res.status(400).json({ error: "Name, owner ID, and config are required" });
    }

    const id = insertServer(name, ownerId, config);
    const newServer = getServerById(id);

    if (!newServer) {
      return res.status(500).json({ error: "Failed to retrieve created server" });
    }

    return res.status(201).json(newServer);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create server" });
  }
});

// PUT /servers/:id - Update a server
router.put("/servers/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid server ID" });
    }

    const { name, ownerId, config } = req.body;

    if (!name || !ownerId || !config) {
      return res.status(400).json({ error: "Name, owner ID, and config are required" });
    }

    const existingServer = getServerById(id);
    if (!existingServer) {
      return res.status(404).json({ error: "Server not found" });
    }

    updateServer(id, name, ownerId, config);
    const updatedServer = getServerById(id);

    if (!updatedServer) {
      return res.status(500).json({ error: "Failed to retrieve updated server" });
    }

    return res.json(updatedServer);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update server" });
  }
});

// DELETE /servers/:id - Delete a server
router.delete("/servers/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid server ID" });
    }

    const existingServer = getServerById(id);
    if (!existingServer) {
      return res.status(404).json({ error: "Server not found" });
    }

    deleteServer(id);
    return res.json({ message: "Server deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete server" });
  }
});
"}

