{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check export-related requests
  if (!(req.method === "POST" && req.path === "/export/history")) {
    next();
    return;
  }

  const authHeader = req.headers["authorization"];
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Basic token structure validation
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  const [header, payload, signature] = parts;

  // Verify signature using HMAC-SHA256
  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const actualSignature = signature;

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(actualSignature, "base64url");

    if (!timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Invalid token signature" });
    return;
  }

  // Decode payload to check ownership
  try {
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());

    // Assuming the payload contains an 'owner' field that must match a known owner ID
    // For this implementation, we'll assume owner ID is hardcoded or configurable
    const ownerId = process.env.OWNER_ID;

    if (!ownerId) {
      res.status(500).json({ error: "Server configuration error" });
      return;
    }

    if (decodedPayload.owner !== ownerId) {
      res.status(403).json({ error: "Forbidden: Export access restricted to owner" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Invalid token payload" });
    return;
  }

  next();
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./parts.db");

interface Part {
  id: number;
  name: string;
  stock_level: number;
  purchase_price: number;
  last_purchase_date: string | null;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS parts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    stock_level INTEGER NOT NULL,
    purchase_price REAL NOT NULL,
    last_purchase_date TEXT
  )
`;

db.exec(createTableSql);

export function getAllParts(): Part[] {
  const stmt = db.prepare("SELECT * FROM parts");
  return stmt.all() as unknown as Part[];
}

export function getPartById(id: number): Part | undefined {
  const stmt = db.prepare("SELECT * FROM parts WHERE id = ?");
  return stmt.get(id) as unknown as Part | undefined;
}

export function insertPart(part: Omit<Part, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO parts (name, stock_level, purchase_price, last_purchase_date) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(part.name, part.stock_level, part.purchase_price, part.last_purchase_date);
  return Number(result.lastInsertRowid);
}

export function updatePart(id: number, part: Partial<Omit<Part, "id">>): boolean {
  const fields = [];
  const values = [];

  if (part.name !== undefined) {
    fields.push("name = ?");
    values.push(part.name);
  }

  if (part.stock_level !== undefined) {
    fields.push("stock_level = ?");
    values.push(part.stock_level);
  }

  if (part.purchase_price !== undefined) {
    fields.push("purchase_price = ?");
    values.push(part.purchase_price);
  }

  if (part.last_purchase_date !== undefined) {
    fields.push("last_purchase_date = ?");
    values.push(part.last_purchase_date);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE parts SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
}

export function deletePart(id: number): boolean {
  const stmt = db.prepare("DELETE FROM parts WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

// Seed data
if (getAllParts().length === 0) {
  insertPart({
    name: "Mountain Bike Frame",
    stock_level: 12,
    purchase_price: 249.99,
