{"code":"import { Router, type Request, type Response } from "express";
import { getAllComplaints, getComplaintById, insertComplaint, updateComplaint, deleteComplaint } from "../db/complaints-table";

export const router = Router();

// Get all complaints in the review queue
router.get("/", (req: Request, res: Response) => {
  try {
    const complaints = getAllComplaints();
    return res.json(complaints);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch complaints" });
  }
});

// Get a specific complaint by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid complaint ID" });
    }

    const complaint = getComplaintById(id);
    if (!complaint) {
      return res.status(404).json({ error: "Complaint not found" });
    }

    return res.json(complaint);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch complaint" });
  }
});

// Create a new complaint
router.post("/", (req: Request, res: Response) => {
  try {
    const { text, status, created_at, updated_at } = req.body;

    if (!text || !status || !created_at || !updated_at) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const id = insertComplaint(text, status, created_at, updated_at);
    return res.status(201).json({ id });
  } catch (error) {
    return res.status(500).json({ error: "Failed to create complaint" });
  }
});

// Update a complaint
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid complaint ID" });
    }

    const { text, status, updated_at } = req.body;

    if (!text || !status || !updated_at) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const existingComplaint = getComplaintById(id);
    if (!existingComplaint) {
      return res.status(404).json({ error: "Complaint not found" });
    }

    updateComplaint(id, text, status, updated_at);
    return res.json({ message: "Complaint updated successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to update complaint" });
  }
});

// Delete a complaint
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid complaint ID" });
    }

    const existingComplaint = getComplaintById(id);
    if (!existingComplaint) {
      return res.status(404).json({ error: "Complaint not found" });
    }

    deleteComplaint(id);
    return res.json({ message: "Complaint deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete complaint" });
  }
});
"}

{"code":"import { useEffect, useState } from "react";

