      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="name" style={{ display: "block", marginBottom: "5px" }}>Pet Name:</label>
          <input
            type="text"
            id="name"
            name="name"
            value={formData.name}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="ownerName" style={{ display: "block", marginBottom: "5px" }}>Owner Name:</label>
          <input
            type="text"
            id="ownerName"
            name="ownerName"
            value={formData.ownerName}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="contactInfo" style={{ display: "block", marginBottom: "5px" }}>Contact Info:</label>
          <input
            type="text"
            id="contactInfo"
            name="contactInfo"
            value={formData.contactInfo}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="notes" style={{ display: "block", marginBottom: "5px" }}>Notes:</label>
          <textarea
            id="notes"
            name="notes"
            value={formData.notes}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd", minHeight: "80px" }}
          />
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: "#007bff", 
            color: "white", 
            padding: "10px 20px", 
            border: "none", 
            borderRadius: "4px", 
            cursor: "pointer" 
          }}
        >
          {editingId ? "Update Pet" : "Check In Pet"}
        </button>

        {editingId && (
          <button 
            type="button" 
            onClick={resetForm}
            style={{ 
              backgroundColor: "#6c757d", 
              color: "white", 
              padding: "10px 20px", 
              border: "none", 
              borderRadius: "4px", 
              cursor: "pointer", 
              marginLeft: "10px" 
            }}
          >
            Cancel Edit
          </button>
        )}
      </form>

      <h2 style={{ textAlign: "center" }}>Checked In Pets</h2>

      {pets.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No pets currently checked in.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {pets
            .filter(pet => pet.checkedIn)
            .map(pet => (
              <div key={pet.id} style={{ 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                padding: "15px", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center" 
              }}>
                <div>
                  <strong>{pet.name}</strong> - {pet.ownerName}
                  <br />
                  <small>{pet.contactInfo}</small>
                  <br />
                  <small>{pet.notes}</small>
                </div>
                <div>
                  <button 
                    onClick={() => handleCheckOut(pet.id)}
                    style={{ 
                      backgroundColor: "#dc3545", 
                      color: "white", 
                      padding: "5px 10px", 
                      border: "none", 
                      borderRadius: "4px", 
                      cursor: "pointer" 
                    }}
                  >
                    Check Out
                  </button>
                </div>
              </div>
            ))}
        </div>
      )}

      <h2 style={{ textAlign: "center", marginTop: "30px" }}>Checked Out Pets</h2>

      {pets.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No pets checked out.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {pets
            .filter(pet => !pet.checkedIn)
            .map(pet => (
              <div key={pet.id} style={{ 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                padding: "15px", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center" 
              }}>
                <div>
                  <strong>{pet.name}</strong> - {pet.ownerName}
                  <br />
                  <small>{pet.contactInfo}</small>
                  <br />
                  <small>{pet.notes}</small>
                </div>
                <div>
                  <button 
                    onClick={() => handleEdit(pet)}
                    style={{ 
                      backgroundColor: "#28a745", 
                      color: "white", 
                      padding: "5px 10px", 
                      border: "none", 
                      borderRadius: "4px", 
                      cursor: "pointer" 
                    }}
                  >
                    Check In
                  </button>
                </div>
              </div>
            ))}
        </div>
      )}
    </div>
  );
}
"}

