{"code":"import { Router, type Request, type Response } from "express";
import { getAllComplaints, getComplaintById, updateAuditLog } from "../db/complaints-table";

export const router = Router();

router.get("/", (req: Request, res: Response) => {
  const complaints = getAllComplaints().map(complaint => ({
    id: complaint.id,
    metadata: complaint.metadata
  }));
  res.json(complaints);
});

router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const complaint = getComplaintById(id);
  if (complaint) {
    res.json({
      id: complaint.id,
      metadata: complaint.metadata
    });
  } else {
    res.status(404).send("Complaint not found");
  }
});

router.post("/:id/audit", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const auditLogEntry = req.body.auditLog;
  if (typeof auditLogEntry === "string") {
    updateAuditLog(id, auditLogEntry);
    res.status(200).send("Audit log updated");
  } else {
    res.status(400).send("Invalid audit log entry");
  }
});
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/neighborhood-watch-incident-log.db"
);

export interface Incident {
  id: number;
  residentId: number;
  timestamp: string;
  description: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS incidents (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    residentId INTEGER NOT NULL,
    timestamp TEXT NOT NULL,
    description TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllIncidents(): Incident[] {
  const stmt = db.prepare(`SELECT * FROM incidents`);
  return stmt.all() as unknown as Incident[];
}

export function getIncidentById(id: number): Incident | undefined {
  const stmt = db.prepare(
    `SELECT * FROM incidents WHERE id = ?`
  );
  return stmt.get(id) as unknown as Incident | undefined;
}

export function insertIncident(
  residentId: number,
  timestamp: string,
  description: string
): number {
  const stmt = db.prepare(
    `INSERT INTO incidents (residentId, timestamp, description) VALUES (?, ?, ?)`
  );
  const result = stmt.run(residentId, timestamp, description);
  return Number(result.lastInsertRowid);
}

export function updateIncident(
  id: number,
  residentId: number,
  timestamp: string,
  description: string
): number {
  const stmt = db.prepare(
    `UPDATE incidents SET residentId = ?, timestamp = ?, description = ? WHERE id = ?`
  );
  const result = stmt.run(residentId, timestamp, description, id);
  return Number(result.changes);
}

export function deleteIncident(id: number): number {
  const stmt = db.prepare(`DELETE FROM incidents WHERE id = ?`);
  const result = stmt.run(id);
  return Number(result.changes);
}

// Seed data
if (getAllIncidents().length === 0) {
