export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  const token = req.body.token;
  if (!token) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Basic token structure validation
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const [header, payload, signature] = parts;

  // Verify signature
  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const signatureBuffer = Buffer.from(signature, "base64url");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

  try {
    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Decode payload (basic base64url decoding)
  const decodedPayload = Buffer.from(payload, "base64url").toString("utf8");
  let payloadObj;
  try {
    payloadObj = JSON.parse(decodedPayload);
  } catch {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Assign role based on payload
  if (payloadObj.role === "admin") {
    (req as any).role = "admin";
  } else if (payloadObj.role === "client") {
    (req as any).role = "client";
  } else {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  next();
}
"}

{"code":"import { useEffect, useState } from "react";

interface Batch {
  id: string;
  cheeseType: string;
  startDate: string;
  agingPeriod: number;
  currentStatus: string;
}

export function BatchList() {
  const [batches, setBatches] = useState<Batch[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [userRole, setUserRole] = useState<string>("user"); // Default role

  useEffect(() => {
    const fetchBatches = async () => {
      try {
        const response = await fetch("/api/aging-batches-api/");
        if (!response.ok) {
          throw new Error(`Failed to fetch batches: ${response.status}`);
        }
        const data = await response.json();
        setBatches(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    const fetchUserRole = async () => {
      try {
        const response = await fetch("/api/user-role"); // Assuming this endpoint exists
        if (!response.ok) {
          throw new Error(`Failed to fetch user role: ${response.status}`);
        }
        const data = await response.json();
        setUserRole(data.role);
      } catch (err) {
        console.error("Error fetching user role:", err);
      }
    };

    fetchBatches();
    fetchUserRole();
  }, []);

  const handleDelete = async (id: string) => {
    if (userRole !== "supervisor") return;

    try {
      const response = await fetch(`/api/aging-batches-api/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete batch: ${response.status}`);
      }
      // Refresh the list after deletion
      const updatedResponse = await fetch("/api/aging-batches-api/");
      if (!updatedResponse.ok) {
        throw new Error(`Failed to refresh batches: ${updatedResponse.status}`);
      }
      const updatedData = await updatedResponse.json();
      setBatches(updatedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (batches.length === 0) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No batches found.</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "system-ui, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Aging Batches</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
        {batches.map((batch) => (
          <div 
            key={batch.id} 
            style={{ 
              border: "1px solid #ccc", 
              borderRadius: "8px", 
              padding: "15px", 
              display: "flex", 
              justifyContent: "space-between", 
              alignItems: "center"
            }}
          >
            <div>
              <strong>{batch.cheeseType}</strong> - Started: {new Date(batch.startDate).toLocaleDateString()} - Aging Period: {batch.agingPeriod} days - Status: {batch.currentStatus}
            </div>
            {userRole === "supervisor" && (
              <button 
                onClick={() => handleDelete(batch.id)}
                style={{ 
                  backgroundColor: "#ff4d4d", 
                  color: "white", 
                  border: "none", 
                  borderRadius: "4px", 
                  padding: "5px 10px", 
                  cursor: "pointer"
                }}
              >
                Delete
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface Batch {
  id: string;
  cheeseType: string;
  agingPeriod: number;
  status: "pending" | "approved" | "rejected";
}

export function BatchApprovalQueue() {
  const [batches, setBatches] = useState<Batch[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchBatches();
  }, []);

  const fetchBatches = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/cheese-aging-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setBatches(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = async (id: string) => {
    try {
      const response = await fetch(`/api/cheese-aging-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "approved" }),
      });
      if (!response.ok) {
        throw new Error(`Failed to approve batch: ${response.status} ${response.statusText}`);
      }
      fetchBatches();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleReject = async (id: string) => {
    try {
      const response = await fetch(`/api/cheese-aging-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "rejected" }),
      });
      if (!response.ok) {
        throw new Error(`Failed to reject batch: ${response.status} ${response.statusText}`);
      }
      fetchBatches();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (batches.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No pending batches to approve.
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Batch Approval Queue</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {batches
          .filter(batch => batch.status === "pending")
          .map(batch => (
            <div 
              key={batch.id} 
              style={{ 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                padding: "15px", 
                display: "flex", 
                flexDirection: "column", 
                gap: "10px"
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <span><strong>Cheese Type:</strong> {batch.cheeseType}</span>
                <span><strong>Aging Period:</strong> {batch.agingPeriod} days</span>
              </div>
              <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
                <button 
                  onClick={() => handleApprove(batch.id)}
                  style={{ 
                    backgroundColor: "#4CAF50", 
                    color: "white", 
                    border: "none", 
                    borderRadius: "4px", 
                    padding: "8px 12px", 
                    cursor: "pointer"
                  }}
                >
                  Approve
                </button>
                <button 
                  onClick={() => handleReject(batch.id)}
                  style={{ 
                    backgroundColor: "#f44336", 
                    color: "white", 
                    border: "none", 
                    borderRadius: "4px", 
                    padding: "8px 12px", 
                    cursor: "pointer"
                  }}
                >
                  Reject
                </button>
              </div>
            </div>
          ))}
      </div>
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./petboarding.db");

interface PetRow {
  id: number;
  owner_id: number;
  species: string;
  check_in: string;
  check_out: string | null;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS pets (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    owner_id INTEGER NOT NULL,
    species TEXT NOT NULL,
    check_in TEXT NOT NULL,
    check_out TEXT
  )
`;

db.exec(createTableSql);

export function getAllPets(): PetRow[] {
  const stmt = db.prepare("SELECT * FROM pets");
  return stmt.all() as unknown as PetRow[];
}

export function getPetById(id: number): PetRow | undefined {
  const stmt = db.prepare("SELECT * FROM pets WHERE id = ?");
  return stmt.get(id) as unknown as PetRow | undefined;
}

export function insertPet(pet: Omit<PetRow, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO pets (owner_id, species, check_in, check_out) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(pet.owner_id, pet.species, pet.check_in, pet.check_out);
  return Number(result.lastInsertRowid);
}

export function updatePet(id: number, pet: Partial<Omit<PetRow, "id">>): boolean {
  const fields = [];
  const values: (number | string | null)[] = [];

  if (pet.owner_id !== undefined) {
    fields.push("owner_id = ?");
    values.push(pet.owner_id);
  }

  if (pet.species !== undefined) {
    fields.push("species = ?");
    values.push(pet.species);
  }

  if (pet.check_in !== undefined) {
    fields.push("check_in = ?");
    values.push(pet.check_in);
  }

  if (pet.check_out !== undefined) {
    fields.push("check_out = ?");
    values.push(pet.check_out);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE pets SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
}

export function deletePet(id: number): boolean {
  const stmt = db.prepare("DELETE FROM pets WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

// Insert sample data if table is empty
if (getAllPets().length === 0) {
  insertPet({
