{"code":"import { Router, type Request, type Response } from "express";
import { db, deleteRoom, getAllRooms, getRoomById, insertRoom, updateRoom } from "../db/rooms-table";

export const router = Router();

// Get all rooms
router.get("/", (req: Request, res: Response) => {
  try {
    const rooms = getAllRooms();
    res.json(rooms);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch rooms" });
  }
});

// Get a room by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const room = getRoomById(id);

    if (!room) {
      return res.status(404).json({ error: "Room not found" });
    }

    res.json(room);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch room" });
  }
});

// Create a new room
router.post("/", (req: Request, res: Response) => {
  try {
    const { roomId, cleaningStatus } = req.body;

    if (!roomId || !cleaningStatus) {
      return res.status(400).json({ error: "Room ID and cleaning status are required" });
    }

    const newId = insertRoom(roomId, cleaningStatus);
    const createdRoom = getRoomById(newId);

    if (!createdRoom) {
      return res.status(500).json({ error: "Failed to create room" });
    }

    res.status(201).json(createdRoom);
  } catch (error) {
    res.status(500).json({ error: "Failed to create room" });
  }
});

// Update a room
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { roomId, cleaningStatus } = req.body;

    if (!roomId || !cleaningStatus) {
      return res.status(400).json({ error: "Room ID and cleaning status are required" });
    }

    const existingRoom = getRoomById(id);

    if (!existingRoom) {
      return res.status(404).json({ error: "Room not found" });
    }

    updateRoom(id, roomId, cleaningStatus);
    const updatedRoom = getRoomById(id);

    if (!updatedRoom) {
      return res.status(500).json({ error: "Failed to update room" });
    }

    res.json(updatedRoom);
  } catch (error) {
    res.status(500).json({ error: "Failed to update room" });
  }
});

// Delete a room
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const existingRoom = getRoomById(id);

    if (!existingRoom) {
      return res.status(404).json({ error: "Room not found" });
    }

    deleteRoom(id);
    res.json({ message: "Room deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete room" });
  }
});
"}

