{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./community-kitchen.db");

interface BookingRow {
  id: number;
  kitchen_id: number;
  date: string;
  time_slot: string;
  guest_count: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS bookings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    kitchen_id INTEGER NOT NULL,
    date TEXT NOT NULL,
    time_slot TEXT NOT NULL,
    guest_count INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllBookings(): BookingRow[] {
  const stmt = db.prepare("SELECT * FROM bookings");
  return stmt.all() as unknown as BookingRow[];
}

export function getBookingById(id: number): BookingRow | undefined {
  const stmt = db.prepare("SELECT * FROM bookings WHERE id = ?");
  return stmt.get(id) as unknown as BookingRow | undefined;
}

export function insertBooking(
  kitchenId: number,
  date: string,
  timeSlot: string,
  guestCount: number
): number {
  const stmt = db.prepare(
    "INSERT INTO bookings (kitchen_id, date, time_slot, guest_count) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(kitchenId, date, timeSlot, guestCount);
  return Number(result.lastInsertRowid);
}

export function updateBooking(
  id: number,
  kitchenId: number,
  date: string,
  timeSlot: string,
  guestCount: number
): void {
  const stmt = db.prepare(
    "UPDATE bookings SET kitchen_id = ?, date = ?, time_slot = ?, guest_count = ? WHERE id = ?"
  );
  stmt.run(kitchenId, date, timeSlot, guestCount, id);
}

export function deleteBooking(id: number): void {
  const stmt = db.prepare("DELETE FROM bookings WHERE id = ?");
  stmt.run(id);
}

