    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h2 style={{ textAlign: "center" }}>Approve Timesheet Entry</h2>
      <div style={{ backgroundColor: "#f9f9f9", borderRadius: "8px", padding: "15px", marginBottom: "20px" }}>
        <p><strong>Partner:</strong> {timesheet.partnerName}</p>
        <p><strong>Client:</strong> {timesheet.clientName}</p>
        <p><strong>Hours:</strong> {timesheet.hours}</p>
        <p><strong>Date:</strong> {timesheet.date}</p>
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", gap: "10px" }}>
        <button 
          onClick={onReject}
          style={{ flex: 1, padding: "10px", backgroundColor: "#dc3545", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
        >
          Reject
        </button>
        <button 
          onClick={onApprove}
          style={{ flex: 1, padding: "10px", backgroundColor: "#28a745", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
        >
          Approve
        </button>
      </div>
    </div>
  );
}
