{"code":"import { useEffect, useState } from "react";

interface Member {
  id: string;
  name: string;
  email: string;
}

interface BoxCustomization {
  id: string;
  memberId: string;
  items: string[];
}

export function BoxCustomizer() {
  const [members, setMembers] = useState<Member[]>([]);
