      try {
        const [membersResponse, customizationsResponse] = await Promise.all([
          fetch("/api/membership-api/members"),
          fetch("/api/membership-api/box-customizations"),
        ]);

        if (!membersResponse.ok || !customizationsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const membersData = await membersResponse.json();
        const customizationsData = await customizationsResponse.json();

        setMembers(membersData);
        setCustomizations(customizationsData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleMemberChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setSelectedMemberId(e.target.value);
  };

  const handleItemChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const item = e.target.value;
    if (e.target.checked) {
      setItems([...items, item]);
    } else {
      setItems(items.filter(i => i !== item));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedMemberId) return;

    try {
      const response = await fetch(`/api/membership-api/box-customizations`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          memberId: selectedMemberId,
          items,
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to save customization");
      }

      // Refresh data
      const [membersResponse, customizationsResponse] = await Promise.all([
        fetch("/api/membership-api/members"),
        fetch("/api/membership-api/box-customizations"),
      ]);

      if (!membersResponse.ok || !customizationsResponse.ok) {
        throw new Error("Failed to refresh data");
      }

      const membersData = await membersResponse.json();
      const customizationsData = await customizationsResponse.json();

      setMembers(membersData);
      setCustomizations(customizationsData);
      setItems([]);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={containerStyle}>
