        <p>No customizations found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {customizations.map(customization => {
            const member = members.find(m => m.id === customization.memberId);
            return (
              <div key={customization.id} style={cardStyle}>
                <strong>{member?.name || "Unknown Member"}</strong>
                <ul>
                  {customization.items.map((item, index) => (
                    <li key={index}>{item}</li>
                  ))}
                </ul>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

