import { Page, getAllPages, getPageById, insertPage } from "../db/pages-table";

export const router = Router();

router.get("/pages", (req: Request, res: Response) => {
  const pages: Page[] = getAllPages();
  res.json(pages);
});

router.get("/pages/:id", (req: Request, res: Response) => {
  const pageId: number = Number(req.params.id);
  const page: Page | undefined = getPageById(pageId);
  if (page) {
    res.json(page);
  } else {
    res.status(404).send("Page not found");
  }
});

router.post("/pages", (req: Request, res: Response) => {
  const { title, content, parentId }: { title: string; content: string; parentId: number | null } = req.body;
  insertPage(title, content, parentId);
  res.status(201).send("Page created");
});
