                key={room.id}
                style={{
                  border: "1px solid #ccc",
                  borderRadius: "8px",
                  padding: "15px",
                  width: "200px",
                  boxSizing: "border-box",
                }}
              >
                <h3>{room.name}</h3>
                <p>Capacity: {room.capacity}</p>
                <p>Amenities: {room.amenities.join(", ")}</p>
              </div>
            ))}
          </div>
