                <th style={{ border: "1px solid #ddd", padding: "8px" }}>Room</th>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>Start</th>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>End</th>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {bookings.map((booking) => {
                const room = rooms.find((r) => r.id === booking.roomId);
                return (
                  <tr key={booking.id}>
                    <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                      {room?.name || "Unknown Room"}
                    </td>
                    <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                      {new Date(booking.startTime).toLocaleString()}
                    </td>
                    <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                      {new Date(booking.endTime).toLocaleString()}
                    </td>
                    <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                      <button
                        onClick={async () => {
                          const response = await fetch(
                            `/api/bookings-api/${booking.id}`,
                            { method: "DELETE" }
                          );
                          if (response.ok) {
                            // Refresh data after deletion
                            const [roomsResponse, bookingsResponse] =
                              await Promise.all([
                                fetch("/api/room-availability-service/rooms"),
                                fetch("/api/bookings-api/"),
                              ]);
                            if (roomsResponse.ok && bookingsResponse.ok) {
                              const roomsData = await roomsResponse.json();
                              const bookingsData = await bookingsResponse.json();
                              setRooms(roomsData);
                              setBookings(bookingsData);
                            }
                          }
                        }}
                        style={{
                          backgroundColor: "#dc3545",
                          color: "white",
                          border: "none",
                          borderRadius: "4px",
                          padding: "5px 10px",
                          cursor: "pointer",
