                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("bike-share-fleet.db");

interface Repair {
  id: number;
  bike_id: number;
  mechanic_id: number;
  part_name: string;
  date: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS repairs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    bike_id INTEGER NOT NULL,
    mechanic_id INTEGER NOT NULL,
    part_name TEXT NOT NULL,
    date TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllRepairs(): Repair[] {
  const stmt = db.prepare("SELECT * FROM repairs");
  return stmt.all() as unknown as Repair[];
}

export function getRepairById(id: number): Repair | undefined {
  const stmt = db.prepare("SELECT * FROM repairs WHERE id = ?");
  return stmt.get(id) as unknown as Repair | undefined;
}

export function insertRepair(
  bikeId: number,
  mechanicId: number,
  partName: string,
  date: string
): number {
  const stmt = db.prepare(
    "INSERT INTO repairs (bike_id, mechanic_id, part_name, date) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(bikeId, mechanicId, partName, date);
  return Number(result.lastInsertRowid);
}

export function updateRepair(
  id: number,
  bikeId: number,
  mechanicId: number,
  partName: string,
  date: string
): void {
  const stmt = db.prepare(
    "UPDATE repairs SET bike_id = ?, mechanic_id = ?, part_name = ?, date = ? WHERE id = ?"
  );
  stmt.run(bikeId, mechanicId, partName, date, id);
}

export function deleteRepair(id: number): void {
  const stmt = db.prepare("DELETE FROM repairs WHERE id = ?");
  stmt.run(id);
}

// Insert sample data if table is empty
if (getAllRepairs().length === 0) {
  insertRepair(1, 101, "Brake Pad", "2023-06-15");
  insertRepair(2, 102, "Chain", "2023-06-18");
  insertRepair(3, 103, "Tire", "2023-06-20");
  insertRepair(4, 101, "Handlebar", "2023-06-22");
  insertRepair(5, 104, "Pedal", "2023-06-25");
}
"}

