  useEffect(() => {
    fetchSlots();
  }, []);

  const fetchSlots = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/scheduling-api/slots');
      if (!response.ok) {
        throw new Error(`Failed to fetch slots: ${response.status} ${response.statusText}`);
