{"code":"import { Router, type Request, type Response } from "express";
import {
  getAllReservations,
  getReservationById,
  insertReservation,
  updateReservation,
  deleteReservation
} from "../db/reservations-table";

export const router = Router();

// Get all reservations
router.get("/", (req: Request, res: Response) => {
  try {
    const reservations = getAllReservations();
    res.json(reservations);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservations" });
  }
});

// Get a reservation by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const reservation = getReservationById(id);
    if (!reservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    res.json(reservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservation" });
  }
});

// Create a new reservation
router.post("/", (req: Request, res: Response) => {
  try {
    const { memberId, plotId, reservationDate } = req.body;

    if (!memberId || !plotId || !reservationDate) {
      return res.status(400).json({ error: "Member ID, plot ID, and reservation date are required" });
    }

    const newId = insertReservation(memberId, plotId, reservationDate);
    const createdReservation = getReservationById(newId);

    if (!createdReservation) {
      return res.status(500).json({ error: "Failed to create reservation" });
    }

    res.status(201).json(createdReservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to create reservation" });
  }
});

// Update a reservation
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const { memberId, plotId, reservationDate } = req.body;

    if (!memberId || !plotId || !reservationDate) {
      return res.status(400).json({ error: "Member ID, plot ID, and reservation date are required" });
    }

    const updatedId = updateReservation(id, memberId, plotId, reservationDate);
    const updatedReservation = getReservationById(updatedId);

    if (!updatedReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    res.json(updatedReservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to update reservation" });
  }
});

// Delete a reservation
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const deletedCount = deleteReservation(id);

    if (deletedCount === 0) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    res.json({ message: "Reservation deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete reservation" });
  }
});
"}

{"code":"import { useEffect, useState } from "react";

interface Member {
  id: string;
  name: string;
  email: string;
  allocation: number;
}

export function AdminAllocationPanel() {
  const [members, setMembers] = useState<Member[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newMember, setNewMember] = useState({
    name: "",
    email: "",
    allocation: ""
  });

  useEffect(() => {
    fetchMembers();
  }, []);

  const fetchMembers = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/co-op-allocation-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch members: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setMembers(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewMember({
      ...newMember,
      [name]: value
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/co-op-allocation-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: newMember.name,
          email: newMember.email,
          allocation: Number(newMember.allocation)
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to add member: ${response.status} ${response.statusText}`);
      }

      setNewMember({ name: "", email: "", allocation: "" });
      fetchMembers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const updateMember = async (id: string, allocation: number) => {
    try {
      const response = await fetch(`/api/co-op-allocation-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ allocation })
      });

      if (!response.ok) {
        throw new Error(`Failed to update member: ${response.status} ${response.statusText}`);
      }

      fetchMembers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const deleteMember = async (id: string) => {
    try {
      const response = await fetch(`/api/co-op-allocation-api/${id}`, {
        method: "DELETE"
      });

      if (!response.ok) {
        throw new Error(`Failed to delete member: ${response.status} ${response.statusText}`);
      }

      fetchMembers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Co-op Member Energy Allocations</h1>

      <div style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>Add New Member</h2>
        <form onSubmit={handleSubmit}>
          <input
            type="text"
            name="name"
            placeholder="Name"
            value={newMember.name}
            onChange={handleInputChange}
            style={{ width: "100%", marginBottom: "10px", padding: "8px" }}
            required
          />
          <input
            type="email"
            name="email"
            placeholder="Email"
            value={newMember.email}
            onChange={handleInputChange}
            style={{ width: "100%", marginBottom: "10px", padding: "8px" }}
            required
          />
          <input
            type="number"
            name="allocation"
            placeholder="Energy Allocation (kWh)"
            value={newMember.allocation}
            onChange={handleInputChange}
            style={{ width: "100%", marginBottom: "10px", padding: "8px" }}
            required
          />
          <button type="submit" style={{ backgroundColor: "#007bff", color: "white", border: "none", padding: "10px 15px", borderRadius: "4px", cursor: "pointer" }}>
            Add Member
          </button>
        </form>
      </div>

      <h2>Current Members</h2>
      {members.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No members found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {members.map(member => (
            <div key={member.id} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "10px", border: "1px solid #ccc", borderRadius: "8px" }}>
              <div style={{ flex: 1 }}>
                <strong>{member.name}</strong> ({member.email})
                <br />
                <span>Allocation: {member.allocation} kWh</span>
              </div>
              <div style={{ display: "flex", gap: "10px" }}>
                <input
                  type="number"
                  defaultValue={member.allocation}
                  onBlur={(e) => {
                    const newAllocation = Number(e.target.value);
                    if (!isNaN(newAllocation)) {
                      updateMember(member.id, newAllocation);
                    }
                  }}
                  style={{ width: "100px", padding: "5px" }}
                />
                <button 
                  onClick={() => deleteMember(member.id)}
                  style={{ backgroundColor: "#dc3545", color: "white", border: "none", padding: "5px 10px", borderRadius: "4px", cursor: "pointer" }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import { middleware } from "../middleware/sso-via-oidc";
import { 
  addTagToBookmark,
  db,
  deleteBookmark,
  getAllBookmarks,
  getBookmarkById,
  getTagsForBookmark,
  insertBookmark,
  updateBookmark
} from "../db/bookmarks-table";

export const router = Router();

// GET /bookmarks - Get all bookmarks
router.get("/bookmarks", (req: Request, res: Response) => {
  try {
    const bookmarks = getAllBookmarks();
    res.json(bookmarks);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch bookmarks" });
  }
});

// GET /bookmarks/:id - Get a specific bookmark by ID
router.get("/bookmarks/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid bookmark ID" });
    }

    const bookmark = getBookmarkById(id);
    if (!bookmark) {
      return res.status(404).json({ error: "Bookmark not found" });
    }

    res.json(bookmark);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch bookmark" });
  }
});

// POST /bookmarks - Create a new bookmark
router.post("/bookmarks", (req: Request, res: Response) => {
  try {
    const { title, url, notes } = req.body;

    if (!title || !url) {
      return res.status(400).json({ error: "Title and URL are required" });
    }

    const newBookmark = insertBookmark(title, url, notes || null);
    res.status(201).json(newBookmark);
  } catch (error) {
    res.status(500).json({ error: "Failed to create bookmark" });
  }
});

// PUT /bookmarks/:id - Update an existing bookmark
router.put("/bookmarks/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid bookmark ID" });
    }

    const { title, url, notes } = req.body;

    if (!title || !url) {
      return res.status(400).json({ error: "Title and URL are required" });
    }

    const updatedBookmark = updateBookmark(id, title, url, notes || null);
    res.json(updatedBookmark);
  } catch (error) {
    res.status(500).json({ error: "Failed to update bookmark" });
  }
});

// DELETE /bookmarks/:id - Delete a bookmark
router.delete("/bookmarks/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid bookmark ID" });
    }

    const bookmark = getBookmarkById(id);
    if (!bookmark) {
      return res.status(404).json({ error: "Bookmark not found" });
    }

    deleteBookmark(id);
    res.json({ message: "Bookmark deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete bookmark" });
  }
});

// GET /bookmarks/:id/tags - Get tags for a specific bookmark
router.get("/bookmarks/:id/tags", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid bookmark ID" });
    }

    const tags = getTagsForBookmark(id);
    res.json(tags);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch tags" });
  }
});

// POST /bookmarks/:id/tags - Add a tag to a bookmark
router.post("/bookmarks/:id/tags", (req: Request, res: Response) => {
  try {
    const bookmarkId = Number(req.params.id);
    if (isNaN(bookmarkId)) {
      return res.status(400).json({ error: "Invalid bookmark ID" });
    }

    const { tagName } = req.body;
    if (!tagName) {
      return res.status(400).json({ error: "Tag name is required" });
    }

    addTagToBookmark(bookmarkId, tagName);
    res.json({ message: "Tag added successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to add tag" });
  }
});

// Apply SSO middleware to all routes
router.use(middleware);
"}

{"code":"import { useEffect, useState } from "react";

interface Slot {
  id: string;
  startTime: string;
  endTime: string;
  claimedBy?: string;
}

export function AirtimeSlotClaimUi() {
  const [slots, setSlots] = useState<Slot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchSlots();
  }, []);

  const fetchSlots = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/scheduling-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch slots: ${response.status}`);
      }
      const data = await response.json();
      setSlots(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleClaimSlot = async (slotId: string) => {
    try {
      const response = await fetch(`/api/scheduling-api/${slotId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ claimedBy: 'current-dj' }),
      });

      if (!response.ok) {
        throw new Error(`Failed to claim slot: ${response.status}`);
      }

      // Refresh the slot list
      await fetchSlots();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const emptyMessage = {
    textAlign: 'center' as const,
    padding: '20px' as const,
    fontStyle: 'italic' as const,
    color: '#666' as const,
  };

  const gridStyle = {
    display: 'flex' as const,
    flexWrap: 'wrap' as const,
    gap: '15px' as const,
    maxWidth: '800px' as const,
    margin: '0 auto' as const,
    padding: '20px' as const,
  };

  const cardStyle = {
    border: '1px solid #ddd' as const,
    borderRadius: '8px' as const,
    padding: '15px' as const,
    width: '100%' as const,
    boxSizing: 'border-box' as const,
    display: 'flex' as const,
    flexDirection: 'column' as const,
    justifyContent: 'space-between' as const,
  };

  const buttonStyle = {
    backgroundColor: '#007bff' as const,
    color: 'white' as const,
    border: 'none' as const,
    borderRadius: '4px' as const,
    padding: '8px 12px' as const,
    cursor: 'pointer' as const,
    marginTop: '10px' as const,
  };

  const timeStyle = {
    fontSize: '1.1em' as const,
    fontWeight: 'bold' as const,
    marginBottom: '5px' as const,
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ fontFamily: 'system-ui, sans-serif', maxWidth: '800px', margin: '0 auto', padding: '20px' }}>
      <h1>Airtime Slot Claim</h1>
      <p>Available slots:</p>

      {slots.length === 0 ? (
        <div style={emptyMessage}>No available slots.</div>
      ) : (
        <div style={gridStyle}>
          {slots.map((slot) => (
            <div key={slot.id} style={cardStyle}>
              <div>
                <div style={timeStyle}>{slot.startTime} - {slot.endTime}</div>
                <div>{slot.claimedBy ? `Claimed by: ${slot.claimedBy}` : 'Available'}</div>
              </div>
              {!slot.claimedBy && (
                <button 
                  style={buttonStyle}
                  onClick={() => handleClaimSlot(slot.id)}
                >
                  Claim Slot
                </button>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface Channel {
  id: string;
  name: string;
}

interface Message {
  id: string;
  channelId: string;
  content: string;
  timestamp: string;
}

export function ChatInterface() {
  const [channels, setChannels] = useState<Channel[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);
  const [selectedChannelId, setSelectedChannelId] = useState<string | null>(null);
  const [newMessageContent, setNewMessageContent] = useState("");
  const [newChannelName, setNewChannelName] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Fetch channels
  useEffect(() => {
    const fetchChannels = async () => {
      setLoading(true);
      try {
        const response = await fetch('/api/channels-api/channels');
        if (!response.ok) throw new Error('Failed to fetch channels');
        const data = await response.json();
        setChannels(data);

        // Select first channel if none selected
        if (!selectedChannelId && data.length > 0) {
          setSelectedChannelId(data[0].id);
        }
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchChannels();
  }, [selectedChannelId]);

  // Fetch messages for selected channel
  useEffect(() => {
    const fetchMessages = async () => {
      if (!selectedChannelId) return;

      setLoading(true);
      try {
        const response = await fetch(`/api/channels-api/messages/channel/${selectedChannelId}`);
        if (!response.ok) throw new Error('Failed to fetch messages');
        const data = await response.json();
        setMessages(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchMessages();
  }, [selectedChannelId]);

  const handleCreateChannel = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newChannelName.trim()) return;

    setLoading(true);
    try {
      const response = await fetch('/api/channels-api/channels', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: newChannelName }),
      });

      if (!response.ok) throw new Error('Failed to create channel');

      const createdChannel = await response.json();
      setChannels([...channels, createdChannel]);
      setNewChannelName("");

      // Select newly created channel
      setSelectedChannelId(createdChannel.id);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedChannelId || !newMessageContent.trim()) return;

    setLoading(true);
    try {
      const response = await fetch('/api/channels-api/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          channelId: selectedChannelId,
          content: newMessageContent,
        }),
      });

      if (!response.ok) throw new Error('Failed to send message');

      const createdMessage = await response.json();
      setMessages([...messages, createdMessage]);
      setNewMessageContent("");
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const formatTime = (timestamp: string) => {
    const date = new Date(timestamp);
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
    }}>
      <h1 style={{ textAlign: 'center' }}>Team Chat</h1>

      {error && (
        <div style={{
          backgroundColor: '#ffebee',
          color: '#c62828',
          padding: '10px',
          borderRadius: '4px',
          marginBottom: '20px',
        }}>
          Error: {error}
        </div>
      )}

      {loading && <p>Loading...</p>}

      {!loading && (
        <>
          {/* Channels List */}
          <div style={{ marginBottom: '20px' }}>
            <h2>Channels</h2>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
              {channels.map(channel => (
                <button
                  key={channel.id}
                  onClick={() => setSelectedChannelId(channel.id)}
                  style={{
                    padding: '10px 15px',
                    border: '1px solid #ccc',
                    borderRadius: '4px',
                    backgroundColor: selectedChannelId === channel.id ? '#007bff' : '#fff',
                    color: selectedChannelId === channel.id ? '#fff' : '#000',
                    cursor: 'pointer',
                    flex: '1 1 auto',
                    minWidth: '100px',
                  }}
                >
                  #{channel.name}
                </button>
              ))}
            </div>

            <form onSubmit={handleCreateChannel} style={{ marginTop: '10px' }}>
              <input
                type="text"
                value={newChannelName}
                onChange={(e) => setNewChannelName(e.target.value)}
                placeholder="New channel name"
                style={{
                  width: '100%',
                  padding: '10px',
                  border: '1px solid #ccc',
                  borderRadius: '4px',
                  marginBottom: '10px',
                }}
              />
              <button
                type="submit"
                style={{
                  padding: '10px 15px',
                  backgroundColor: '#28a745',
                  color: '#fff',
                  border: 'none',
                  borderRadius: '4px',
                  cursor: 'pointer',
                }}
              >
                Create Channel
              </button>
            </form>
          </div>

          {/* Messages Area */}
          <div>
            <h2>
              {selectedChannelId 
                ? channels.find(c => c.id === selectedChannelId)?.name || 'Channel'
                : 'Select a Channel'}
            </h2>

            {messages.length === 0 ? (
              <p>No messages yet. Be the first to post!</p>
            ) : (
              <div style={{ marginBottom: '20px' }}>
                {messages.map(message => (
                  <div
                    key={message.id}
                    style={{
                      padding: '10px',
                      borderBottom: '1px solid #eee',
                      display: 'flex',
                      justifyContent: 'space-between',
                    }}
                  >
                    <span>{message.content}</span>
                    <span style={{ color: '#666', fontSize: '0.9em' }}>
                      {formatTime(message.timestamp)}
                    </span>
                  </div>
                ))}
              </div>
            )}

            {selectedChannelId && (
              <form onSubmit={handleSendMessage}>
                <textarea
                  value={newMessageContent}
                  onChange={(e) => setNewMessageContent(e.target.value)}
                  placeholder="Type your message..."
                  style={{
                    width: '100%',
                    padding: '10px',
                    border: '1px solid #ccc',
                    borderRadius: '4px',
                    marginBottom: '10px',
                    resize: 'vertical',
                  }}
                  rows={3}
                />
                <button
                  type="submit"
                  style={{
                    padding: '10px 15px',
                    backgroundColor: '#007bff',
                    color: '#fff',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: 'pointer',
                  }}
                >
                  Send Message
                </button>
              </form>
            )}
          </div>
        </>
      )}
    </div>
  );
}
"}

