{"code":"import { useEffect, useState } from "react";

interface RepairLog {
  id: number;
  bikeId: number;
  description: string;
  date: string;
}

interface Bike {
  id: number;
  name: string;
}

export function RepairLogForm() {
  const [bikes, setBikes] = useState<Bike[]>([]);
  const [repairLogs, setRepairLogs] = useState<RepairLog[]>([]);
  const [formData, setFormData] = useState({
    bikeId: "",
    description: "",
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [bikesResponse, logsResponse] = await Promise.all([
          fetch("/api/maintenance-records-api/"),
          fetch("/api/maintenance-records-api/"),
        ]);

        if (!bikesResponse.ok || !logsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const bikesData = await bikesResponse.json();
        const logsData = await logsResponse.json();

        setBikes(bikesData);
        setRepairLogs(logsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch("/api/maintenance-records-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          bikeId: Number(formData.bikeId),
          description: formData.description,
          date: new Date().toISOString().split("T")[0],
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to submit repair log");
      }

      // Refresh data after successful submission
      const [bikesResponse, logsResponse] = await Promise.all([
        fetch("/api/maintenance-records-api/"),
        fetch("/api/maintenance-records-api/"),
      ]);

      if (!bikesResponse.ok || !logsResponse.ok) {
        throw new Error("Failed to refresh data");
      }

      const bikesData = await bikesResponse.json();
      const logsData = await logsResponse.json();

      setBikes(bikesData);
      setRepairLogs(logsData);

      // Reset form
      setFormData({ bikeId: "", description: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;

  const headingStyle: React.CSSProperties = {
    textAlign: "center",
    marginBottom: "20px",
  };

  const formStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "15px",
    maxWidth: "600px",
    margin: "0 auto",
    padding: "20px",
    fontFamily: "system-ui, sans-serif",
  };

  const inputStyle: React.CSSProperties = {
    width: "100%",
    padding: "10px",
    borderRadius: "5px",
    border: "1px solid #ccc",
    boxSizing: "border-box",
  };

  const buttonStyle: React.CSSProperties = {
    padding: "10px 15px",
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: "5px",
    cursor: "pointer",
    fontSize: "16px",
  };

  const recentLogsStyle: React.CSSProperties = {
    marginTop: "30px",
    maxWidth: "600px",
    margin: "0 auto",
    fontFamily: "system-ui, sans-serif",
  };

  const logItemStyle: React.CSSProperties = {
    padding: "10px",
    borderBottom: "1px solid #eee",
  };

  return (
    <div>
      <h1 style={headingStyle}>Repair Log Form</h1>

      <form style={formStyle} onSubmit={handleSubmit}>
        <div>
          <label htmlFor="bikeId">Bike ID:</label>
          <input
            id="bikeId"
            name="bikeId"
            type="number"
            value={formData.bikeId}
            onChange={handleChange}
            style={inputStyle}
            required
          />
        </div>

        <div>
          <label htmlFor="description">Description:</label>
          <textarea
            id="description"
            name="description"
            value={formData.description}
            onChange={handleChange}
            style={inputStyle}
            required
            rows={4}
          />
        </div>

        <button type="submit" style={buttonStyle}>Submit Repair Log</button>
      </form>

      <h2 style={headingStyle}>Recent Repair Logs</h2>

      <div style={recentLogsStyle}>
        {repairLogs.length === 0 ? (
          <p>No repair logs found.</p>
        ) : (
          repairLogs.map((log) => (
            <div key={log.id} style={logItemStyle}>
              <strong>Bike ID:</strong> {log.bikeId}<br />
              <strong>Description:</strong> {log.description}<br />
              <strong>Date:</strong> {log.date}
            </div>
          ))
        )}
      </div>
    </div>
  );
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { router as feedingsApiRouter } from "../routes/feedings-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check ownership for requests to the feedings API routes
  if (!req.path.startsWith("/api/feedings")) {
    next();
    return;
  }

  // For this example, we'll assume the owner is identified by a fixed ID
  // In a real implementation, this would check the authenticated user
  const ownerID = "owner123";

  // Check if the request has an owner ID in the headers or params
  const requestOwnerID = req.headers["x-owner-id"] as string || req.params.ownerId;

  // If the owner ID doesn't match, reject the request
  if (requestOwnerID !== ownerID) {
    res.status(403).json({ error: "Forbidden: Access denied to this resource." });
    return;
  }

  // If the owner matches, proceed to the next middleware/route handler
  next();
}
"}

