      <h1 style={{ textAlign: "center" }}>Report Broken Machine</h1>

      {machines.length === 0 ? (
        <p style={{ textAlign: "center" }}>No machines available.</p>
      ) : (
        <>
          <div style={{ marginBottom: "20px" }}>
            <h2>Select a Machine</h2>
            <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
