  ]),
  getTourById: (id: number) => Promise.resolve({ id: 1, title: "Ancient Civilizations", docentId: 101 }),
  updateTour: (id: number, tourData: any) => Promise.resolve({ id, ...tourData }),
  deleteTour: (id: number) => Promise.resolve(true)
};

