router.get("/tours", async (req: Request, res: Response) => {
  try {
    const tours = await mockDatabase.getTours();
    return res.json(tours);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch tours" });
  }
});

// GET /tours/:id - Get a specific tour by ID
router.get("/tours/:id", async (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid tour ID" });
  }

  try {
    const tour = await mockDatabase.getTourById(id);
    if (!tour) {
      return res.status(404).json({ error: "Tour not found" });
    }
    return res.json(tour);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch tour" });
  }
});

// POST /tours - Create a new tour
router.post("/tours", async (req: Request, res: Response) => {
  const { title, docentId } = req.body;

  if (!title || !docentId) {
    return res.status(400).json({ error: "Title and docent ID are required" });
  }

  try {
    const newTour = await mockDatabase.createTour({ title, docentId });
    return res.status(201).json(newTour);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create tour" });
  }
});

// PUT /tours/:id - Update a tour
router.put("/tours/:id", async (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { title, docentId } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid tour ID" });
  }

  if (!title || !docentId) {
    return res.status(400).json({ error: "Title and docent ID are required" });
  }

  try {
    const updatedTour = await mockDatabase.updateTour(id, { title, docentId });
    if (!updatedTour) {
      return res.status(404).json({ error: "Tour not found" });
    }
    return res.json(updatedTour);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update tour" });
  }
});

// DELETE /tours/:id - Delete a tour
router.delete("/tours/:id", async (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid tour ID" });
  }

  try {
    const deleted = await mockDatabase.deleteTour(id);
    if (!deleted) {
      return res.status(404).json({ error: "Tour not found" });
    }
    return res.json({ message: "Tour deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete tour" });
  }
});
