{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "./manuscript-submission-tracker.db"
);

interface SubmissionCategory {
  id: number;
  name: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS submission_categories (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE
  )
`;

db.exec(createTableSql);

export function getAllSubmissionCategories(): SubmissionCategory[] {
  const stmt = db.prepare(
    "SELECT id, name FROM submission_categories ORDER BY name ASC"
  );
  return stmt.all() as unknown as SubmissionCategory[];
}

export function getSubmissionCategoryById(id: number): SubmissionCategory | undefined {
  const stmt = db.prepare(
    "SELECT id, name FROM submission_categories WHERE id = ?"
  );
  return stmt.get(id) as unknown as SubmissionCategory | undefined;
}

export function insertSubmissionCategory(name: string): number {
  const stmt = db.prepare(
    "INSERT INTO submission_categories (name) VALUES (?)"
  );
  const result = stmt.run(name);
  return Number(result.lastInsertRowid);
}

export function updateSubmissionCategory(id: number, name: string): boolean {
  const stmt = db.prepare(
    "UPDATE submission_categories SET name = ? WHERE id = ?"
  );
  const result = stmt.run(name, id);
  return result.changes > 0;
}

export function deleteSubmissionCategory(id: number): boolean {
  const stmt = db.prepare(
    "DELETE FROM submission_categories WHERE id = ?"
  );
  const result = stmt.run(id);
  return result.changes > 0;
}

// Seed data
