      setError(err instanceof Error ? err.message : "Unknown error");
    } finally {
      setLoading(false);
    }
  };

  const handleAddItem = () => {
    setNewInvoice({
      ...newInvoice,
      items: [...newInvoice.items, { description: "", quantity: 1, price: 0 }]
    });
  };

  const handleItemChange = (index: number, field: string, value: string | number) => {
    const updatedItems = [...newInvoice.items];
    (updatedItems[index] as any)[field] = value;
    setNewInvoice({ ...newInvoice, items: updatedItems });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/billing-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...newInvoice, status: "draft" })
      });
      if (!response.ok) throw new Error(await response.text());
      await fetchInvoices();
      setNewInvoice({ 
        clientName: "", 
        email: "", 
        items: [{ description: "", quantity: 1, price: 0 }] 
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
  };

  const handleSend = async (id: string) => {
    try {
      const response = await fetch(`/api/billing-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "sent" })
      });
      if (!response.ok) throw new Error(await response.text());
      await fetchInvoices();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/billing-api/${id}`, {
        method: "DELETE"
      });
      if (!response.ok) throw new Error(await response.text());
      await fetchInvoices();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Invoice Editor</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>Create New Invoice</h2>
        <div style={{ marginBottom: "15px" }}>
          <label>Client Name:</label><br />
          <input
            type="text"
            value={newInvoice.clientName}
            onChange={(e) => setNewInvoice({...newInvoice, clientName: e.target.value})}
            style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            required
          />
        </div>
        <div style={{ marginBottom: "15px" }}>
          <label>Email:</label><br />
          <input
            type="email"
            value={newInvoice.email}
            onChange={(e) => setNewInvoice({...newInvoice, email: e.target.value})}
            style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            required
          />
        </div>
        <h3>Items</h3>
        {newInvoice.items.map((item, index) => (
          <div key={index} style={{ marginBottom: "15px", padding: "10px", border: "1px solid #eee", borderRadius: "4px" }}>
            <input
              placeholder="Description"
              value={item.description}
              onChange={(e) => handleItemChange(index, "description", e.target.value)}
              style={{ width: "100%", padding: "8px", marginBottom: "5px" }}
              required
            />
            <div style={{ display: "flex", gap: "10px" }}>
              <input
                type="number"
                placeholder="Quantity"
                value={item.quantity}
                onChange={(e) => handleItemChange(index, "quantity", Number(e.target.value))}
                style={{ width: "50%", padding: "8px" }}
                min="1"
                required
              />
              <input
                type="number"
                placeholder="Price"
                value={item.price}
                onChange={(e) => handleItemChange(index, "price", Number(e.target.value))}
                style={{ width: "50%", padding: "8px" }}
                min="0"
                step="0.01"
                required
              />
            </div>
          </div>
        ))}
        <button type="button" onClick={handleAddItem} style={{ padding: "8px 16px", backgroundColor: "#f0f0f0", border: "none", borderRadius: "4px", cursor: "pointer", marginRight: "10px" }}>
          Add Item
        </button>
        <button type="submit" style={{ padding: "8px 16px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}>
          Create Invoice
        </button>
      </form>

      <h2>Invoices</h2>
      {invoices.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No invoices found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {invoices.map(invoice => (
            <div key={invoice.id} style={{ padding: "15px", border: "1px solid #ccc", borderRadius: "8px" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <strong>{invoice.clientName}</strong> ({invoice.email})
                </div>
                <span style={{ backgroundColor: invoice.status === "paid" ? "green" : invoice.status === "sent" ? "orange" : "gray", color: "white", padding: "4px 8px", borderRadius: "4px" }}>
                  {invoice.status.charAt(0).toUpperCase() + invoice.status.slice(1)}
                </span>
              </div>
              <div style={{ marginTop: "10px" }}>
                {invoice.items.map((item, i) => (
                  <div key={i} style={{ display: "flex", justifyContent: "space-between", padding: "5px 0" }}>
                    <span>{item.description}</span>
                    <span>{item.quantity} x ${item.price.toFixed(2)}</span>
                  </div>
                ))}
              </div>
              <div style={{ marginTop: "10px", display: "flex", gap: "10px", flexWrap: "wrap" }}>
                {invoice.status !== "sent" && (
                  <button 
                    onClick={() => handleSend(invoice.id)}
                    style={{ padding: "6px 12px", backgroundColor: "#28a745", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
                  >
                    Send
                  </button>
                )}
                <button 
                  onClick={() => handleDelete(invoice.id)}
                  style={{ padding: "6px 12px", backgroundColor: "#dc3545", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

