{"code":"import { useEffect, useState } from "react";

interface Session {
  id: number;
  studentName: string;
  subject: string;
  date: string;
  duration: number;
  notes: string;
}

export function SessionLogView() {
  const [sessions, setSessions] = useState<Session[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchSessions();
  }, []);

  const fetchSessions = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/sessions-table/");
      if (!response.ok) {
        throw new Error(`Failed to fetch sessions: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setSessions(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/session-deletion-guard/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete session: ${response.status} ${response.statusText}`);
      }
      // Remove deleted session from state
      setSessions(sessions.filter(session => session.id !== id));
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (sessions.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No completed sessions found.
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Session Log</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
        {sessions.map((session) => (
          <div 
            key={session.id} 
            style={{ 
              border: "1px solid #ccc", 
              borderRadius: "8px", 
              padding: "15px", 
              display: "flex", 
              justifyContent: "space-between", 
              alignItems: "center", 
              flexWrap: "wrap"
            }}
          >
            <div style={{ flex: "1", minWidth: "200px" }}>
              <h3>{session.studentName}</h3>
              <p><strong>Subject:</strong> {session.subject}</p>
              <p><strong>Date:</strong> {session.date}</p>
              <p><strong>Duration:</strong> {session.duration} minutes</p>
              <p><strong>Notes:</strong> {session.notes}</p>
            </div>
            <button 
              onClick={() => handleDelete(session.id)}
              style={{ 
                backgroundColor: "#ff4d4d", 
                color: "white", 
                border: "none", 
                borderRadius: "4px", 
                padding: "8px 12px", 
                cursor: "pointer", 
                marginLeft: "10px"
              }}
            >
              Delete
