        setLoading(false);
      } catch (err) {
        setError("Failed to verify ownership status.");
        setLoading(false);
      }
    };

    checkOwnership();
  }, []);

  const handleExport = async () => {
    try {
      const response = await fetch('/api/harvest-api/', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }

      const data = await response.json();
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'harvest-log.json';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (err) {
      setError("Failed to export harvest log.");
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (isOwner === false) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Access denied. Only owners can export the harvest log.</div>;
  }

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h2 style={{ textAlign: 'center' }}>Harvest Log Export</h2>
      <p style={{ textAlign: 'center' }}>Download the complete harvest log as a JSON file.</p>
