{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteTimesheet,
  getAllTimesheets,
  getTimesheetById,
  insertTimesheet,
  updateTimesheet
} from "../db/timesheets-table";

export const router = Router();

// Get all timesheets for the logged-in user
router.get("/", (req: Request, res: Response) => {
  try {
    const timesheets = getAllTimesheets();
    // In a real app, we would filter by logged-in user
    // For now, we return all timesheets as per requirements
    res.json(timesheets);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// Get a specific timesheet by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID format" });
  }

  const timesheet = getTimesheetById(id);

  if (!timesheet) {
    return res.status(404).json({ error: "Timesheet not found" });
  }

  res.json(timesheet);
});

// Create a new timesheet entry
router.post("/", (req: Request, res: Response) => {
  const { associateId, date, client, hours } = req.body;

  if (!associateId || !date || !client || !hours) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  try {
    const newId = insertTimesheet(associateId, date, client, hours);
    const newTimesheet = getTimesheetById(newId);

    if (!newTimesheet) {
      return res.status(500).json({ error: "Failed to create timesheet" });
    }

    res.status(201).json(newTimesheet);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// Update an existing timesheet entry
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { associateId, date, client, hours } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID format" });
  }

  if (!associateId || !date || !client || !hours) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const existingTimesheet = getTimesheetById(id);

  if (!existingTimesheet) {
    return res.status(404).json({ error: "Timesheet not found" });
  }

  try {
    updateTimesheet(id, associateId, date, client, hours);
    const updatedTimesheet = getTimesheetById(id);

    if (!updatedTimesheet) {
      return res.status(500).json({ error: "Failed to update timesheet" });
    }

    res.json(updatedTimesheet);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// Delete a timesheet entry
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID format" });
  }

  const existingTimesheet = getTimesheetById(id);

  if (!existingTimesheet) {
    return res.status(404).json({ error: "Timesheet not found" });
  }

  try {
    deleteTimesheet(id);
    res.json({ message: "Timesheet deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});
"}

