{"code":"import { Router, type Request, type Response } from "express";
import { cacheMessage, getMessagesForTopic } from "../db/message-cache-table";

export const router = Router();

router.put("/:topic", (req: Request, res: Response) => {
  const topic = req.params.topic;
  const message = req.body.message;
  const timestamp = Date.now();

  if (typeof topic !== "string" || typeof message !== "string") {
    res.status(400).send("Invalid input");
    return;
  }

  cacheMessage(topic, message, timestamp);
  res.status(201).send("Message cached");
});

router.post("/:topic", (req: Request, res: Response) => {
  const topic = req.params.topic;
  const message = req.body.message;
  const timestamp = Date.now();

  if (typeof topic !== "string" || typeof message !== "string") {
    res.status(400).send("Invalid input");
    return;
  }

  cacheMessage(topic, message, timestamp);
  res.status(201).send("Message cached");
});

router.get("/:topic", (req: Request, res: Response) => {
  const topic = req.params.topic;

  if (typeof topic !== "string") {
    res.status(400).send("Invalid input");
    return;
  }

  const messages = getMessagesForTopic(topic);
  res.status(200).json(messages);
});
