{"code":"import { useEffect, useState } from "react";

interface CheckInData {
  id: string;
  memberId: string;
  dogName: string;
  checkInTime: string;
}

interface AuditTrailEntry {
  id: string;
  memberId: string;
  action: string;
  timestamp: string;
}

export function CheckInForm() {
  const [memberId, setMemberId] = useState("");
  const [dogName, setDogName] = useState("");
  const [checkIns, setCheckIns] = useState<CheckInData[]>([]);
  const [auditTrail, setAuditTrail] = useState<AuditTrailEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  // Load check-ins and audit trail on component mount
  useEffect(() => {
    fetchCheckIns();
    fetchAuditTrail();
  }, []);

  const fetchCheckIns = async () => {
    setLoading(true);
    try {
      const response = await fetch("/api/check-in-api/");
      if (!response.ok) throw new Error("Failed to fetch check-ins");
      const data = await response.json();
      setCheckIns(data);
    } catch (err) {
      setError("Error loading check-ins: " + (err as Error).message);
    } finally {
      setLoading(false);
    }
  };

  const fetchAuditTrail = async () => {
    setLoading(true);
    try {
      const response = await fetch("/api/audit-trail-service/");
      if (!response.ok) throw new Error("Failed to fetch audit trail");
      const data = await response.json();
      setAuditTrail(data);
    } catch (err) {
      setError("Error loading audit trail: " + (err as Error).message);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError("");

    try {
      const response = await fetch("/api/check-in-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ memberId, dogName }),
      });

      if (!response.ok) throw new Error("Failed to check in dog");

      // Refresh data after successful check-in
      await fetchCheckIns();
      await fetchAuditTrail();

      // Reset form
      setMemberId("");
      setDogName("");
    } catch (err) {
      setError("Error checking in dog: " + (err as Error).message);
    } finally {
      setLoading(false);
    }
  };

  const formStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "16px",
    maxWidth: "500px",
    margin: "0 auto",
    padding: "20px",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
  };

  const inputGroupStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "8px",
  };

  const inputStyle: React.CSSProperties = {
    padding: "10px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    fontSize: "16px",
  };

  const buttonStyle: React.CSSProperties = {
    padding: "10px 16px",
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "16px",
    fontWeight: "bold",
  };

  const listContainerStyle: React.CSSProperties = {
    maxWidth: "800px",
    margin: "20px auto",
    padding: "0 20px",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
  };

  const itemStyle: React.CSSProperties = {
    padding: "12px",
    marginBottom: "8px",
    border: "1px solid #eee",
    borderRadius: "4px",
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
  };

  const emptyMessageStyle: React.CSSProperties = {
    textAlign: "center",
    padding: "20px",
    fontStyle: "italic",
    color: "#666",
  };

  return (
    <div>
      <h1>Check-In Form</h1>
      <form onSubmit={handleSubmit} style={formStyle}>
        <div style={inputGroupStyle}>
          <label htmlFor="memberId">Member ID:</label>
          <input
            id="memberId"
            type="text"
            value={memberId}
            onChange={(e) => setMemberId(e.target.value)}
            style={inputStyle}
            required
          />
        </div>

        <div style={inputGroupStyle}>
          <label htmlFor="dogName">Dog Name:</label>
          <input
            id="dogName"
            type="text"
            value={dogName}
            onChange={(e) => setDogName(e.target.value)}
            style={inputStyle}
            required
          />
        </div>

        <button type="submit" style={buttonStyle} disabled={loading}>
          {loading ? "Checking In..." : "Check In Dog"}
        </button>
      </form>

      {error && <p style={{ color: "red", textAlign: "center" }}>{error}</p>}

      <div style={listContainerStyle}>
        <h2>Recent Check-Ins</h2>
        {loading ? (
          <p>Loading...</p>
        ) : checkIns.length === 0 ? (
          <p style={emptyMessageStyle}>No recent check-ins.</p>
        ) : (
          <div>
            {checkIns.map((checkIn) => (
              <div key={checkIn.id} style={itemStyle}>
                <span>
                  Member: {checkIn.memberId} | Dog: {checkIn.dogName} | Time: {new Date(checkIn.checkInTime).toLocaleString()}
                </span>
              </div>
            ))}
          </div>
        )}
      </div>

      <div style={listContainerStyle}>
        <h2>Audit Trail</h2>
        {loading ? (
          <p>Loading...</p>
        ) : auditTrail.length === 0 ? (
          <p style={emptyMessageStyle}>No audit trail entries.</p>
        ) : (
          <div>
            {auditTrail.map((entry) => (
              <div key={entry.id} style={itemStyle}>
                <span>
                  Action: {entry.action} | Member: {entry.memberId} | Time: {new Date(entry.timestamp).toLocaleString()}
                </span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
"}

