export function WineCatalog() {
  const [wines, setWines] = useState<Wine[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newWine, setNewWine] = useState({
    name: "",
    vintage: "",
    region: "",
    grapeVarieties: ""
  });

  useEffect(() => {
    fetchWines();
  }, []);

  const fetchWines = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/wines-api/");
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setWines(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/wines-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: newWine.name,
          vintage: parseInt(newWine.vintage),
          region: newWine.region,
          grapeVarieties: newWine.grapeVarieties.split(",").map(g => g.trim())
        })
      });
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      setNewWine({
        name: "",
        vintage: "",
        region: "",
        grapeVarieties: ""
      });
      fetchWines();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/wines-api/${id}`, {
        method: "DELETE"
      });
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      fetchWines();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Wine Catalog</h1>

      <div style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>Create New Wine</h2>
        <form onSubmit={handleCreate}>
          <div style={{ marginBottom: "10px" }}>
            <input
              type="text"
              placeholder="Name"
              value={newWine.name}
              onChange={(e) => setNewWine({...newWine, name: e.target.value})}
              style={{ width: "100%", padding: "8px" }}
              required
            />
          </div>
          <div style={{ marginBottom: "10px" }}>
            <input
              type="text"
              placeholder="Vintage"
              value={newWine.vintage}
              onChange={(e) => setNewWine({...newWine, vintage: e.target.value})}
              style={{ width: "100%", padding: "8px" }}
              required
            />
          </div>
          <div style={{ marginBottom: "10px" }}>
            <input
              type="text"
              placeholder="Region"
              value={newWine.region}
              onChange={(e) => setNewWine({...newWine, region: e.target.value})}
              style={{ width: "100%", padding: "8px" }}
              required
            />
          </div>
          <div style={{ marginBottom: "10px" }}>
            <input
              type="text"
              placeholder="Grape Varieties (comma separated)"
              value={newWine.grapeVarieties}
              onChange={(e) => setNewWine({...newWine, grapeVarieties: e.target.value})}
              style={{ width: "100%", padding: "8px" }}
              required
            />
          </div>
          <button type="submit" style={{ backgroundColor: "#007bff", color: "white", border: "none", padding: "10px 20px", borderRadius: "4px", cursor: "pointer" }}>Add Wine</button>
        </form>
      </div>

      <h2>Wine List</h2>
      {wines.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No wines found.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
          {wines.map(wine => (
            <div key={wine.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px", width: "250px", boxSizing: "border-box" }}>
              <h3>{wine.name}</h3>
              <p><strong>Vintage:</strong> {wine.vintage}</p>
              <p><strong>Region:</strong> {wine.region}</p>
              <p><strong>Grapes:</strong> {wine.grapeVarieties.join(", ")}</p>
              <button 
                onClick={() => handleDelete(wine.id)}
                style={{ backgroundColor: "#dc3545", color: "white", border: "none", padding: "5px 10px", borderRadius: "4px", cursor: "pointer", marginTop: "10px" }}
              >
                Delete
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/git-service.db"
);

interface Repository {
  id: number;
  name: string;
  description: string;
  owner_id: number;
  created_at: string;
  updated_at: string;
}

interface Issue {
  id: number;
  repository_id: number;
  title: string;
  description: string;
  author_id: number;
  status: "open" | "closed";
  created_at: string;
  updated_at: string;
}

interface PullRequest {
  id: number;
  repository_id: number;
  title: string;
  description: string;
  author_id: number;
  status: "open" | "closed" | "merged";
  created_at: string;
  updated_at: string;
}

const initSql = `
  CREATE TABLE IF NOT EXISTS repositories (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT,
    owner_id INTEGER NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS issues (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    repository_id INTEGER NOT NULL,
    title TEXT NOT NULL,
    description TEXT,
    author_id INTEGER NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('open', 'closed')),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS pull_requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    repository_id INTEGER NOT NULL,
    title TEXT NOT NULL,
    description TEXT,
    author_id INTEGER NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('open', 'closed', 'merged')),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );
`;

db.exec(initSql);

export function getAllRepositories(): Repository[] {
  const stmt = db.prepare(
    "SELECT * FROM repositories ORDER BY created_at DESC"
  );
  return stmt.all() as unknown as Repository[];
}

export function getRepositoryById(id: number): Repository | undefined {
  const stmt = db.prepare(
    "SELECT * FROM repositories WHERE id = ?"
  );
  return stmt.get(id) as unknown as Repository | undefined;
}

export function insertRepository(
  name: string,
  description: string,
  owner_id: number
): number {
  const stmt = db.prepare(
    "INSERT INTO repositories (name, description, owner_id, created_at, updated_at) VALUES (?, ?, ?, datetime('now'), datetime('now'))"
  );
  const result = stmt.run(name, description, owner_id);
  return Number(result.lastInsertRowid);
}

export function updateRepository(
  id: number,
  name: string,
  description: string
): void {
  const stmt = db.prepare(
    "UPDATE repositories SET name = ?, description = ?, updated_at = datetime('now') WHERE id = ?"
  );
  stmt.run(name, description, id);
}

export function deleteRepository(id: number): void {
  const stmt = db.prepare(
    "DELETE FROM repositories WHERE id = ?"
  );
  stmt.run(id);
}

// Sample data initialization
if (getAllRepositories().length === 0) {
  const repo1Id = insertRepository(
    "frontend-app",
    "A modern web application",
    1
  );
  const repo2Id = insertRepository(
    "backend-api",
    "RESTful API service",
    2
  );
  const repo3Id = insertRepository(
    "mobile-app",
    "Cross-platform mobile app",
    1
  );

  // Insert some sample issues
  const issueStmt = db.prepare(
    "INSERT INTO issues (repository_id, title, description, author_id, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?, datetime('now'), datetime('now'))"
  );
  issueStmt.run(repo1Id, "Login page broken", "User can't login after password reset.", 1, "open");
  issueStmt.run(repo2Id, "Slow database queries", "API response times are too long.", 2, "open");

  // Insert some sample pull requests
  const prStmt = db.prepare(
    "INSERT INTO pull_requests (repository_id, title, description, author_id, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?, datetime('now'), datetime('now'))"
  );
  prStmt.run(repo1Id, "Fix login bug", "This PR fixes the login issue.", 1, "open");
  prStmt.run(repo2Id, "Optimize queries", "Improved performance of database queries.", 2, "merged");
}
"}

