{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process GET requests to /dns-query endpoint
  if (req.method !== "GET" || !req.path?.startsWith("/dns-query")) {
    next();
    return;
  }

  // Check if parental controls are enabled
  const parentalControlsEnabled = process.env.PARENTAL_CONTROLS_ENABLED === "true";
  if (!parentalControlsEnabled) {
    next();
    return;
  }

  // Get query parameters
  const query = req.query.q as string | undefined;
  const searchEngine = req.query.search_engine as string | undefined;

  // If no query or search engine specified, allow through
  if (!query || !searchEngine) {
    next();
    return;
  }

  // Check if query contains adult content indicators
  const adultContentIndicators = [
    "adult", "porn", "xxx", "sex", "nude", "nsa", "fetish"
  ];

  const normalizedQuery = query.toLowerCase();
  const hasAdultContent = adultContentIndicators.some(indicator => 
    normalizedQuery.includes(indicator)
  );

  // If adult content detected, block the request
  if (hasAdultContent) {
    res.status(403).json({
      error: "Parental controls blocked access to adult content",
      blocked: true
    });
    return;
  }

  // For supported search engines, enforce safe search
  const supportedSearchEngines = ["google", "bing", "duckduckgo"];
  if (supportedSearchEngines.includes(searchEngine.toLowerCase())) {
    // Add safe search parameter if not already present
    const safeSearchParam = req.query.safe || "active";

    // If safe search is not active, we might want to enforce it
    // But since this is a DNS-level blocking middleware,
    // we'll just pass through and let the DNS resolver handle it
  }

  // Allow the request to proceed
  next();
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deletePartRequest,
  getAllPartRequests,
  getPartRequestById,
  insertPartRequest,
  updatePartRequest
} from "../db/part-requests-table";

export const router = Router();

// Get all part requests
router.get("/", (req: Request, res: Response) => {
  try {
    const partRequests = getAllPartRequests();
    res.json(partRequests);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch part requests" });
  }
});

// Get a specific part request by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const partRequest = getPartRequestById(id);
    if (!partRequest) {
      return res.status(404).json({ error: "Part request not found" });
    }

    res.json(partRequest);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch part request" });
  }
});

// Create a new part request
router.post("/", (req: Request, res: Response) => {
  try {
    const { mechanicId, partType, status } = req.body;

    if (!mechanicId || !partType || !status) {
      return res.status(400).json({ error: "Missing required fields: mechanicId, partType, status" });
    }

    const id = insertPartRequest(mechanicId, partType, status);
    res.status(201).json({ id });
  } catch (error) {
    res.status(500).json({ error: "Failed to create part request" });
  }
});

// Update an existing part request
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { mechanicId, partType, status } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    if (!mechanicId || !partType || !status) {
      return res.status(400).json({ error: "Missing required fields: mechanicId, partType, status" });
    }

    const existingPartRequest = getPartRequestById(id);
    if (!existingPartRequest) {
      return res.status(404).json({ error: "Part request not found" });
    }

    updatePartRequest(id, mechanicId, partType, status);
    res.json({ message: "Part request updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update part request" });
  }
});

// Delete a part request (supervisor-only)
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const existingPartRequest = getPartRequestById(id);
    if (!existingPartRequest) {
      return res.status(404).json({ error: "Part request not found" });
    }

    deletePartRequest(id);
    res.json({ message: "Part request deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete part request" });
  }
});
