  clientId: number;
  totalAmount: number;
}

interface InvoiceItemRow {
  id: number;
  invoiceId: number;
  description: string;
  quantity: number;
  price: number;
}

const createInvoicesTable = `
  CREATE TABLE IF NOT EXISTS invoices (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    clientId INTEGER NOT NULL,
    totalAmount REAL NOT NULL
  );
`;

const createInvoiceItemsTable = `
  CREATE TABLE IF NOT EXISTS invoice_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    invoiceId INTEGER NOT NULL,
    description TEXT NOT NULL,
    quantity INTEGER NOT NULL,
    price REAL NOT NULL,
    FOREIGN KEY (invoiceId) REFERENCES invoices(id)
  );
`;

db.exec(createInvoicesTable);
db.exec(createInvoiceItemsTable);

export function getAllInvoices(): InvoiceRow[] {
  const stmt = db.prepare("SELECT * FROM invoices");
  return stmt.all() as unknown as InvoiceRow[];
}

export function getInvoiceById(id: number): InvoiceRow | undefined {
  const stmt = db.prepare("SELECT * FROM invoices WHERE id = ?");
  return stmt.get(id) as unknown as InvoiceRow | undefined;
}

export function insertInvoice(clientId: number, totalAmount: number): number {
  const stmt = db.prepare(
    "INSERT INTO invoices (clientId, totalAmount) VALUES (?, ?)"
  );
  const result = stmt.run(clientId, totalAmount);
  return Number(result.lastInsertRowid);
}

export function updateInvoice(
  id: number,
  clientId: number,
  totalAmount: number
): void {
  const stmt = db.prepare(
    "UPDATE invoices SET clientId = ?, totalAmount = ? WHERE id = ?"
  );
