{"code":"import { Router, type Request, type Response } from "express";
import {
  deleteBooking,
  getAllBookings,
  getBookingById,
  insertBooking,
  updateBooking
} from "../db/bookings-table";

export const router = Router();

// Get all bookings
router.get("/", (req: Request, res: Response) => {
  const bookings = getAllBookings();
  res.json(bookings);
});

// Get a booking by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid booking ID" });
  }

  const booking = getBookingById(id);

  if (!booking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  res.json(booking);
});

// Create a new booking
router.post("/", (req: Request, res: Response) => {
  const { guestId, roomId, checkInDate, checkOutDate } = req.body;

  if (!guestId || !roomId || !checkInDate || !checkOutDate) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newId = insertBooking(guestId, roomId, checkInDate, checkOutDate);

  res.status(201).json({ id: newId, guestId, roomId, checkInDate, checkOutDate });
});

// Update a booking
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { guestId, roomId, checkInDate, checkOutDate } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid booking ID" });
  }

  if (!guestId || !roomId || !checkInDate || !checkOutDate) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const existingBooking = getBookingById(id);

  if (!existingBooking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  updateBooking(id, guestId, roomId, checkInDate, checkOutDate);

  res.json({ id, guestId, roomId, checkInDate, checkOutDate });
});

// Delete a booking
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid booking ID" });
  }

  const existingBooking = getBookingById(id);

  if (!existingBooking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  deleteBooking(id);

  res.json({ message: "Booking deleted successfully" });
});
