{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if credentials are provided
  if (!req.body || !req.body.username || !req.body.password) {
    res.status(400).json({ error: "Username and password required" });
    return;
  }

  // In a real implementation, we would verify credentials against a database
  // For now, we'll just simulate a successful login
  const username = req.body.username;
  const password = req.body.password;

  // Simulate session creation
  const sessionId = createHmac("sha256", process.env.JWT_SECRET || "").update(username + password).digest("hex");

  // Set session cookie
  res.cookie("sessionId", sessionId, { httpOnly: true, secure: false });

  // Send success response
  res.json({ message: "Login successful" });
}
"}

