{"code":"import { useEffect, useState } from "react";

export function OwnerOnlyExportPanel() {
  const [bookings, setBookings] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    try {
      const response = await fetch('/api/bookings-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch bookings: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleExport = async () => {
    try {
      const response = await fetch('/api/export-service/export', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ bookings }),
      });

      if (!response.ok) {
        throw new Error(`Export failed: ${response.status} ${response.statusText}`);
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'booking-history.csv';
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred during export');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <h1 style={{ textAlign: 'center' }}>Owner-Only Export Panel</h1>
      <p style={{ textAlign: 'center' }}>Export the full booking history</p>

      <div style={{ marginBottom: '20px', textAlign: 'center' }}>
        <button 
          onClick={handleExport}
          style={{
            backgroundColor: '#007bff',
            color: 'white',
            border: 'none',
            padding: '10px 20px',
            borderRadius: '5px',
            cursor: 'pointer',
            fontSize: '16px'
          }}
        >
          Export All Bookings
        </button>
      </div>

      <div style={{
        border: '1px solid #ccc',
        borderRadius: '5px',
        padding: '10px',
        overflowX: 'auto'
      }}>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ borderBottom: '1px solid #ccc' }}>
              <th style={{ padding: '8px', textAlign: 'left' }}>ID</th>
              <th style={{ padding: '8px', textAlign: 'left' }}>Room</th>
              <th style={{ padding: '8px', textAlign: 'left' }}>Start Date</th>
              <th style={{ padding: '8px', textAlign: 'left' }}>End Date</th>
              <th style={{ padding: '8px', textAlign: 'left' }}>User</th>
            </tr>
          </thead>
          <tbody>
            {bookings.length === 0 ? (
              <tr>
                <td colSpan={5} style={{ padding: '8px', textAlign: 'center' }}>
                  No bookings found.
                </td>
              </tr>
            ) : (
              bookings.map(booking => (
                <tr key={booking.id} style={{ borderBottom: '1px solid #eee' }}>
                  <td style={{ padding: '8px' }}>{booking.id}</td>
                  <td style={{ padding: '8px' }}>{booking.room}</td>
                  <td style={{ padding: '8px' }}>{new Date(booking.startDate).toLocaleDateString()}</td>
                  <td style={{ padding: '8px' }}>{new Date(booking.endDate).toLocaleDateString()}</td>
                  <td style={{ padding: '8px' }}>{booking.user}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
"}

{"code":"import { FC, useEffect, useState } from "react";

interface Truck {
  id: string;
  name: string;
  location: string;
}

export function SupervisorDeleteGuard() {
  const [trucks, setTrucks] = useState<Truck[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchTrucks();
  }, []);

  const fetchTrucks = async () => {
    try {
      const response = await fetch("/api/routes-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch trucks: ${response.status}`);
      }
      const data = await response.json();
      setTrucks(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    // Check if the truck belongs to the supervisor
    const truck = trucks.find(t => t.id === id);
    if (!truck) return;

    // Simulate supervisor guard logic - reject deletion if it's their own truck
    const supervisorResponse = await fetch(`/api/supervisor-guard/${id}`);
    if (!supervisorResponse.ok) {
      setError("Failed to verify supervisor access");
      return;
    }

    const supervisorData = await supervisorResponse.json();
    if (supervisorData.isOwnTruck) {
      alert("You cannot delete your own truck.");
      return;
    }

    // Proceed with deletion if not their own truck
    const deleteResponse = await fetch(`/api/routes-api/${id}`, {
      method: "DELETE",
    });

    if (deleteResponse.ok) {
      fetchTrucks(); // Refresh the list after successful deletion
    } else {
      setError("Failed to delete truck");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  if (trucks.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No trucks available.
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "system-ui, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Supervisor Truck Management</h1>
      <table style={{ width: "100%", borderCollapse: "collapse", marginBottom: "20px" }}>
        <thead>
          <tr style={{ borderBottom: "1px solid #ccc" }}>
            <th style={{ padding: "10px", textAlign: "left" }}>Name</th>
            <th style={{ padding: "10px", textAlign: "left" }}>Location</th>
            <th style={{ padding: "10px", textAlign: "left" }}>Actions</th>
          </tr>
        </thead>
        <tbody>
          {trucks.map((truck) => (
            <tr key={truck.id} style={{ borderBottom: "1px solid #eee" }}>
              <td style={{ padding: "10px" }}>{truck.name}</td>
              <td style={{ padding: "10px" }}>{truck.location}</td>
              <td style={{ padding: "10px" }}>
                <button
                  onClick={() => handleDelete(truck.id)}
                  style={{
                    backgroundColor: "#dc3545",
                    color: "white",
                    border: "none",
                    padding: "5px 10px",
                    borderRadius: "4px",
                    cursor: "pointer",
                  }}
                >
                  Delete
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
"}

