// Get a shift by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid shift ID" });
  }

  const shift = getShiftById(id);
  if (!shift) {
    return res.status(404).json({ error: "Shift not found" });
  }

  res.json(shift);
});

// Create a new shift
router.post("/", (req: Request, res: Response) => {
  const { parentId, shiftDate, role } = req.body;

  if (!parentId || !shiftDate || !role) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  try {
    const newId = insertShift(parentId, shiftDate, role);
    const newShift = getShiftById(newId);
    res.status(201).json(newShift);
  } catch (err) {
    res.status(500).json({ error: "Failed to create shift" });
  }
});

// Update a shift
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { parentId, shiftDate, role } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid shift ID" });
  }

  if (!parentId || !shiftDate || !role) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const existingShift = getShiftById(id);
  if (!existingShift) {
    return res.status(404).json({ error: "Shift not found" });
  }

  try {
    updateShift(id, parentId, shiftDate, role);
    const updatedShift = getShiftById(id);
    res.json(updatedShift);
  } catch (err) {
    res.status(500).json({ error: "Failed to update shift" });
  }
});

// Delete a shift (supervisor-only)
router.delete("/:id", (req: Request, res: Response) => {
  const shiftId = Number(req.params.id);
  const supervisorId = Number(req.body.supervisorId); // Assuming supervisorId is passed in body

  if (isNaN(shiftId) || isNaN(supervisorId)) {
    return res.status(400).json({ error: "Invalid shift ID or supervisor ID" });
  }

  const shift = getShiftById(shiftId);
  if (!shift) {
    return res.status(404).json({ error: "Shift not found" });
  }

  // Check if this supervisor has already deleted this shift
  const existingDelete = getShiftDeleteById(supervisorId, shiftId);
  if (existingDelete) {
    return res.status(400).json({ error: "Shift already deleted by this supervisor" });
  }

  try {
    // Record the deletion
    insertShiftDelete(supervisorId, shiftId);
    // Actually delete the shift
    deleteShift(shiftId);
    res.json({ message: "Shift deleted successfully" });
  } catch (err) {
    res.status(500).json({ error: "Failed to delete shift" });
  }
});
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./data.db");

interface BoxCustomization {
  id: number;
  member_id: number;
  contents: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS box_customizations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    member_id INTEGER NOT NULL,
    contents TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllBoxCustomizations(): BoxCustomization[] {
  const stmt = db.prepare("SELECT * FROM box_customizations");
  return stmt.all() as unknown as BoxCustomization[];
}

export function getBoxCustomizationById(id: number): BoxCustomization | undefined {
  const stmt = db.prepare("SELECT * FROM box_customizations WHERE id = ?");
  return stmt.get(id) as unknown as BoxCustomization | undefined;
}

export function insertBoxCustomization(memberId: number, contents: string): number {
  const stmt = db.prepare(
    "INSERT INTO box_customizations (member_id, contents) VALUES (?, ?)"
  );
  const result = stmt.run(memberId, contents);
  return Number(result.lastInsertRowid);
}

export function updateBoxCustomization(
  id: number,
  memberId: number,
  contents: string
): void {
  const stmt = db.prepare(
    "UPDATE box_customizations SET member_id = ?, contents = ? WHERE id = ?"
  );
  stmt.run(memberId, contents, id);
}

export function deleteBoxCustomization(id: number): void {
  const stmt = db.prepare("DELETE FROM box_customizations WHERE id = ?");
  stmt.run(id);
}

