  insertBoxCustomization(2, "Local honey and nuts");
  insertBoxCustomization(3, "Fresh bread and dairy");
  insertBoxCustomization(4, "Seasonal produce bundle");
  insertBoxCustomization(5, "Herbal tea and spices");
}
