{"code":"import { FC, useEffect, useState } from "react";

interface Operation {
  id: string;
  operation: string;
  status: "pending" | "processing" | "completed" | "failed";
  result?: string;
}

export function PdfToolInterface() {
  const [operations, setOperations] = useState<Operation[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [operationType, setOperationType] = useState<string>("merge");

  // Fetch operations
  useEffect(() => {
    const fetchOperations = async () => {
      try {
        const response = await fetch("/api/pdf-processing-api/status/all");
        if (!response.ok) throw new Error("Failed to fetch operations");
        const data = await response.json();
        setOperations(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Unknown error");
      } finally {
        setLoading(false);
      }
    };

    fetchOperations();
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setSelectedFile(e.target.files[0]);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedFile) return;

    const formData = new FormData();
    formData.append("file", selectedFile);
    formData.append("operation", operationType);

    try {
      const response = await fetch("/api/pdf-processing-api/process", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) throw new Error("Failed to process PDF");
      const data = await response.json();
      setOperations([...operations, data]);
      setSelectedFile(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/pdf-processing-api/status/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) throw new Error("Failed to delete operation");
      setOperations(operations.filter(op => op.id !== id));
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  return (
    <div style={containerStyle}>
      <h1 style={{ textAlign: "center", marginBottom: "20px" }}>PDF Toolkit</h1>

      <form onSubmit={handleSubmit} style={formStyle}>
        <input
          type="file"
          accept="application/pdf"
          onChange={handleFileChange}
          style={{ marginBottom: "10px" }}
        />

        <select
          value={operationType}
          onChange={(e) => setOperationType(e.target.value)}
          style={{ width: "100%", marginBottom: "10px" }}
        >
          <option value="merge">Merge</option>
          <option value="split">Split</option>
          <option value="sign">Sign</option>
          <option value="redact">Redact</option>
          <option value="convert">Convert</option>
          <option value="ocr">OCR</option>
        </select>

        <button type="submit" style={buttonStyle}>Process PDF</button>
      </form>

      {error && <p style={{ color: "red", textAlign: "center" }}>{error}</p>}

      <h2 style={{ textAlign: "center", marginTop: "30px" }}>Processing History</h2>

      {operations.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No operations yet.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {operations.map((op) => (
            <div key={op.id} style={cardStyle}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <span><strong>{op.operation}</strong></span>
                <span style={{ backgroundColor: getStatusColor(op.status), padding: "4px 8px", borderRadius: "4px" }}>
                  {op.status}
                </span>
              </div>
              <div style={{ marginTop: "10px", fontSize: "0.9em" }}>
                {op.result ? (
                  <span>Result: {op.result}</span>
                ) : (
                  <span>No result yet</span>
                )}
              </div>
              <div style={{ marginTop: "10px", textAlign: "right" }}>
                <button 
                  onClick={() => handleDelete(op.id)}
                  style={{ ...buttonStyle, backgroundColor: "#ff4d4d" }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

const containerStyle = {
  maxWidth: "600px",
  margin: "0 auto",
  padding: "20px",
  fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
};

const formStyle = {
  backgroundColor: "#f5f5f5",
  padding: "20px",
  borderRadius: "8px",
  marginBottom: "20px",
};

const cardStyle = {
  border: "1px solid #ddd",
  borderRadius: "8px",
  padding: "15px",
  backgroundColor: "#fff",
};

const buttonStyle = {
  backgroundColor: "#007bff",
  color: "white",
  border: "none",
  padding: "10px 15px",
  borderRadius: "4px",
  cursor: "pointer",
  width: "100%",
};

function getStatusColor(status: string) {
  switch (status) {
    case "completed": return "#28a745";
    case "failed": return "#dc3545";
    case "processing": return "#ffc107";
    default: return "#6c757d";
  }
}
"}

