    }

    if (status !== "present" && status !== "absent") {
      return res.status(400).json({ error: "Status must be either 'present' or 'absent'" });
    }

    const existingRecord = getAttendanceById(id);
    if (!existingRecord) {
      return res.status(404).json({ error: "Attendance record not found" });
    }

    updateAttendance(id, singerId, date, status);
    const updatedRecord = getAttendanceById(id);

    if (!updatedRecord) {
      return res.status(500).json({ error: "Failed to update attendance record" });
    }

    res.json(updatedRecord);
  } catch (error) {
    res.status(500).json({ error: "Failed to update attendance record" });
  }
});

// Delete an attendance record
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const existingRecord = getAttendanceById(id);
    if (!existingRecord) {
      return res.status(404).json({ error: "Attendance record not found" });
    }

    deleteAttendance(id);
    res.json({ message: "Attendance record deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete attendance record" });
  }
});
"}

{"code":"import { useEffect, useState } from "react";

interface Asset {
