{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/self-hosted-workflow-automation.db"
);

export interface Workflow {
  id: number;
  name: string;
  description: string;
  created_at: string;
  updated_at: string;
}

export interface WorkflowExecution {
  id: number;
  workflow_id: number;
  status: "pending" | "running" | "completed" | "failed";
  started_at: string;
  completed_at: string | null;
}

const initSql = `
  CREATE TABLE IF NOT EXISTS workflows (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS workflow_executions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    workflow_id INTEGER NOT NULL,
    status TEXT NOT NULL,
    started_at TEXT NOT NULL,
    completed_at TEXT,
    FOREIGN KEY (workflow_id) REFERENCES workflows (id)
  );
`;

db.exec(initSql);

export function getAllWorkflows(): Workflow[] {
  const stmt = db.prepare(
    "SELECT * FROM workflows ORDER BY created_at DESC"
  );
  return stmt.all() as unknown as Workflow[];
}

export function getWorkflowById(id: number): Workflow | undefined {
  const stmt = db.prepare(
    "SELECT * FROM workflows WHERE id = ?"
  );
  return stmt.get(id) as Workflow | undefined;
}

export function insertWorkflow(
  name: string,
  description: string
): number {
  const stmt = db.prepare(
    "INSERT INTO workflows (name, description, created_at, updated_at) VALUES (?, ?, datetime('now'), datetime('now'))"
  );
  const result = stmt.run(name, description);
  return Number(result.lastInsertRowid);
}

export function updateWorkflow(
  id: number,
  name: string,
  description: string
): void {
  const stmt = db.prepare(
    "UPDATE workflows SET name = ?, description = ?, updated_at = datetime('now') WHERE id = ?"
  );
  stmt.run(name, description, id);
}

export function deleteWorkflow(id: number): void {
  const stmt = db.prepare("DELETE FROM workflows WHERE id = ?");
  stmt.run(id);
}

export function getAllExecutions(): WorkflowExecution[] {
  const stmt = db.prepare(
    "SELECT * FROM workflow_executions ORDER BY started_at DESC"
  );
  return stmt.all() as unknown as WorkflowExecution[];
}

export function getExecutionsByWorkflowId(
  workflowId: number
): WorkflowExecution[] {
  const stmt = db.prepare(
    "SELECT * FROM workflow_executions WHERE workflow_id = ? ORDER BY started_at DESC"
  );
  return stmt.all(workflowId) as unknown as WorkflowExecution[];
}

export function insertExecution(
  workflowId: number,
  status: "pending" | "running" | "completed" | "failed"
): number {
  const stmt = db.prepare(
    "INSERT INTO workflow_executions (workflow_id, status, started_at) VALUES (?, ?, datetime('now'))"
  );
  const result = stmt.run(workflowId, status);
  return Number(result.lastInsertRowid);
}

// Seed data
if (getAllWorkflows().length === 0) {
  const workflow1Id = insertWorkflow(
    "Email Notification",
    "Send email notifications when events occur"
  );
  insertExecution(workflow1Id, "completed");

  const workflow2Id = insertWorkflow(
    "Data Backup",
    "Automated backup of critical data"
  );
  insertExecution(workflow2Id, "running");

  const workflow3Id = insertWorkflow(
    "Report Generation",
    "Generate daily reports from database"
  );
  insertExecution(workflow3Id, "pending");

  const workflow4Id = insertWorkflow(
    "System Monitoring",
    "Monitor system health and alert on issues"
  );
  insertExecution(workflow4Id, "failed");

  const workflow5Id = insertWorkflow(
    "User Registration",
    "Handle new user registration process"
  );
  insertExecution(workflow5Id, "completed");
}
