{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteShiftSignup,
  getAllShiftSignups,
  getShiftSignupById,
  insertShiftSignup,
  updateShiftSignup
} from "../db/shift-signups-table";

export const router = Router();

// GET /shifts - Get all shift signups
router.get("/shifts", (req: Request, res: Response) => {
  try {
    const signups = getAllShiftSignups();
    res.json(signups);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch shift signups" });
  }
});

// GET /shifts/:id - Get a specific shift signup by ID
router.get("/shifts/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid shift signup ID" });
    }

    const signup = getShiftSignupById(id);
    if (!signup) {
      return res.status(404).json({ error: "Shift signup not found" });
    }

    res.json(signup);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch shift signup" });
  }
});

// POST /shifts - Create a new shift signup
router.post("/shifts", (req: Request, res: Response) => {
  try {
    const { volunteerId, shiftId, signupTimestamp } = req.body;

    if (!volunteerId || !shiftId || !signupTimestamp) {
      return res.status(400).json({
        error: "Missing required fields: volunteerId, shiftId, signupTimestamp"
      });
    }

    const newId = insertShiftSignup(
      Number(volunteerId),
      Number(shiftId),
      signupTimestamp
    );

    const newSignup = getShiftSignupById(newId);
    if (!newSignup) {
      return res.status(500).json({ error: "Failed to retrieve created shift signup" });
    }

    res.status(201).json(newSignup);
  } catch (error) {
    res.status(500).json({ error: "Failed to create shift signup" });
  }
});

// PUT /shifts/:id - Update an existing shift signup
router.put("/shifts/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid shift signup ID" });
    }

    const { volunteerId, shiftId, signupTimestamp } = req.body;

    if (!volunteerId || !shiftId || !signupTimestamp) {
      return res.status(400).json({
        error: "Missing required fields: volunteerId, shiftId, signupTimestamp"
      });
    }

    const existingSignup = getShiftSignupById(id);
    if (!existingSignup) {
      return res.status(404).json({ error: "Shift signup not found" });
    }

    updateShiftSignup(
      id,
      Number(volunteerId),
      Number(shiftId),
      signupTimestamp
    );

    const updatedSignup = getShiftSignupById(id);
    if (!updatedSignup) {
      return res.status(500).json({ error: "Failed to retrieve updated shift signup" });
    }

    res.json(updatedSignup);
  } catch (error) {
    res.status(500).json({ error: "Failed to update shift signup" });
  }
});

// DELETE /shifts/:id - Delete a shift signup
router.delete("/shifts/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid shift signup ID" });
    }

    const existingSignup = getShiftSignupById(id);
    if (!existingSignup) {
      return res.status(404).json({ error: "Shift signup not found" });
    }

    deleteShiftSignup(id);
    res.json({ message: "Shift signup deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete shift signup" });
  }
});
