{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteDonation,
  getAllDonations,
  getDonationById,
  insertDonation,
  updateDonation
} from "../db/donations-table";

export const router = Router();

// Get all donations
router.get("/", (req: Request, res: Response) => {
  try {
    const donations = getAllDonations();
    res.json(donations);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch donations" });
  }
});

// Get a donation by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid donation ID" });
    }

    const donation = getDonationById(id);
    if (!donation) {
      return res.status(404).json({ error: "Donation not found" });
    }

    res.json(donation);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch donation" });
  }
});

// Create a new donation
router.post("/", (req: Request, res: Response) => {
  try {
    const { itemName, quantity, date, loggedByUserId } = req.body;

    if (!itemName || !quantity || !date || !loggedByUserId) {
      return res.status(400).json({
        error: "Missing required fields: itemName, quantity, date, loggedByUserId"
      });
    }

    const newId = insertDonation(itemName, quantity, date, loggedByUserId);
    const newDonation = getDonationById(newId);

    if (!newDonation) {
      return res.status(500).json({ error: "Failed to create donation" });
    }

    res.status(201).json(newDonation);
  } catch (error) {
    res.status(500).json({ error: "Failed to create donation" });
  }
});

// Update a donation
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid donation ID" });
    }

    const { itemName, quantity, date, loggedByUserId } = req.body;

    if (!itemName || !quantity || !date || !loggedByUserId) {
      return res.status(400).json({
        error: "Missing required fields: itemName, quantity, date, loggedByUserId"
      });
    }

    const updatedId = updateDonation(id, itemName, quantity, date, loggedByUserId);
    const updatedDonation = getDonationById(updatedId);

    if (!updatedDonation) {
      return res.status(404).json({ error: "Donation not found" });
    }

    res.json(updatedDonation);
  } catch (error) {
    res.status(500).json({ error: "Failed to update donation" });
  }
});

// Delete a donation
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid donation ID" });
    }

    const deletedId = deleteDonation(id);
    if (deletedId === 0) {
      return res.status(404).json({ error: "Donation not found" });
    }

    res.json({ message: "Donation deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete donation" });
  }
});
"}

