{"code":"import { useEffect, useState } from "react";

interface Habit {
  id: number;
  name: string;
  description: string;
  completed: boolean;
}

export function HabitLog() {
  const [habits, setHabits] = useState<Habit[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newHabitName, setNewHabitName] = useState("");
  const [newHabitDescription, setNewHabitDescription] = useState("");

  useEffect(() => {
    fetchHabits();
  }, []);

  const fetchHabits = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/habits-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch habits: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setHabits(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleAddHabit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newHabitName.trim()) return;

    try {
      const response = await fetch("/api/habits-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: newHabitName,
          description: newHabitDescription,
          completed: false
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to add habit: ${response.status} ${response.statusText}`);
      }

      setNewHabitName("");
      setNewHabitDescription("");
      await fetchHabits();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const toggleHabitCompletion = async (id: number) => {
    const habit = habits.find(h => h.id === id);
    if (!habit) return;

    try {
      const response = await fetch(`/api/habits-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...habit,
          completed: !habit.completed
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to update habit: ${response.status} ${response.statusText}`);
      }

      await fetchHabits();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const deleteHabit = async (id: number) => {
    try {
      const response = await fetch(`/api/habits-api/${id}`, {
        method: "DELETE"
      });

      if (!response.ok) {
        throw new Error(`Failed to delete habit: ${response.status} ${response.statusText}`);
      }

      await fetchHabits();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Habit Tracker</h1>

      <form onSubmit={handleAddHabit} style={{ marginBottom: "30px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Habit name"
          value={newHabitName}
          onChange={(e) => setNewHabitName(e.target.value)}
          style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc", width: "100%" }}
        />
        <textarea
          placeholder="Description (optional)"
          value={newHabitDescription}
          onChange={(e) => setNewHabitDescription(e.target.value)}
          style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc", width: "100%", resize: "vertical" }}
        />
        <button type="submit" style={{ padding: "10px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "5px", cursor: "pointer" }}>
          Add Habit
        </button>
      </form>

      {habits.length === 0 ? (
        <p style={{ textAlign: "center", color: "#666" }}>No habits yet. Add your first habit above!</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {habits.map((habit) => (
            <div 
              key={habit.id} 
              style={{ 
                padding: "15px", 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center", 
                backgroundColor: habit.completed ? "#d4edda" : "#f8f9fa"
              }}
            >
              <div>
                <strong>{habit.name}</strong>
                {habit.description && <p style={{ margin: "5px 0 0 0", color: "#666" }}>{habit.description}</p>}
              </div>
              <div style={{ display: "flex", gap: "10px" }}>
                <button 
                  onClick={() => toggleHabitCompletion(habit.id)}
                  style={{ 
                    padding: "5px 10px", 
                    backgroundColor: habit.completed ? "#28a745" : "#ffc107", 
                    color: "white", 
