{"code":"import { useEffect, useState } from "react";

interface Reservation {
  id: number;
  vendorName: string;
  stallNumber: number;
  reservationDate: string;
}

export function StallReservationForm() {
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [vendorName, setVendorName] = useState("");
  const [stallNumber, setStallNumber] = useState("");

  const [editingId, setEditingId] = useState<number | null>(null);

  useEffect(() => {
    fetchReservations();
  }, []);

  const fetchReservations = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/reservations-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch reservations: ${response.status}`);
      }
      const data = await response.json();
      setReservations(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!vendorName.trim() || !stallNumber) {
      setError("Please fill in all fields");
      return;
    }

    try {
      const response = await fetch("/api/reservations-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          vendorName,
          stallNumber: Number(stallNumber),
          reservationDate: new Date().toISOString().split('T')[0]
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to create reservation: ${response.status}`);
      }

      // Reset form
      setVendorName("");
      setStallNumber("");

      // Refresh data
      await fetchReservations();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEdit = (reservation: Reservation) => {
    setEditingId(reservation.id);
    setVendorName(reservation.vendorName);
    setStallNumber(reservation.stallNumber.toString());
  };

  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId === null) return;

    if (!vendorName.trim() || !stallNumber) {
      setError("Please fill in all fields");
      return;
    }

    try {
      const response = await fetch(`/api/reservations-api/${editingId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          vendorName,
          stallNumber: Number(stallNumber),
          reservationDate: new Date().toISOString().split('T')[0]
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to update reservation: ${response.status}`);
      }

      // Reset form
      setEditingId(null);
      setVendorName("");
      setStallNumber("");

      // Refresh data
      await fetchReservations();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/reservations-api/${id}`, {
        method: "DELETE"
      });

      if (!response.ok) {
        throw new Error(`Failed to delete reservation: ${response.status}`);
      }

      // Refresh data
      await fetchReservations();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Stall Reservation</h1>

      <form onSubmit={editingId ? handleUpdate : handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="vendorName" style={{ display: "block", marginBottom: "5px" }}>Vendor Name:</label>
          <input
            id="vendorName"
            type="text"
            value={vendorName}
            onChange={(e) => setVendorName(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="stallNumber" style={{ display: "block", marginBottom: "5px" }}>Stall Number:</label>
          <input
            id="stallNumber"
            type="number"
            value={stallNumber}
            onChange={(e) => setStallNumber(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: "#007bff", 
            color: "white", 
            border: "none", 
            padding: "10px 20px", 
            borderRadius: "4px", 
            cursor: "pointer" 
          }}
        >
          {editingId ? "Update Reservation" : "Create Reservation"}
        </button>
      </form>

      <h2 style={{ textAlign: "center" }}>Current Reservations</h2>

      {reservations.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No reservations yet.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {reservations.map((reservation) => (
            <div 
              key={reservation.id} 
              style={{ 
                padding: "15px", 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center" 
              }}
            >
              <div>
                <strong>{reservation.vendorName}</strong> - Stall #{reservation.stallNumber}
                <br />
                <small>{reservation.reservationDate}</small>
              </div>
              <div>
                <button 
                  onClick={() => handleEdit(reservation)}
                  style={{ 
                    marginRight: "10px", 
                    backgroundColor: "#ffc107", 
                    color: "black", 
                    border: "none", 
                    padding: "5px 10px", 
                    borderRadius: "4px", 
                    cursor: "pointer" 
                  }}
                >
                  Edit
                </button>
                <button 
                  onClick={() => handleDelete(reservation.id)}
                  style={{ 
                    backgroundColor: "#dc3545", 
                    color: "white", 
                    border: "none", 
                    padding: "5px 10px", 
                    borderRadius: "4px", 
                    cursor: "pointer" 
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

