{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const MFA_REQUIRED_PATHS = [
  "/login",
  "/dashboard",
  "/settings",
];

const MFA_REQUIRED_METHODS = ["POST", "PUT", "DELETE"];

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip MFA check for non-protected routes/methods
  const isProtectedPath = MFA_REQUIRED_PATHS.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath || !MFA_REQUIRED_METHODS.includes(req.method)) {
    next();
    return;
  }

  // Check for MFA token in headers
  const authHeader = req.headers["authorization"];
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Validate JWT signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  // Recreate signature for verification
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  // Use timingSafeEqual to prevent timing attacks
  const isValid = timingSafeEqual(
    Buffer.from(signature, "base64url"),
    Buffer.from(expectedSignature, "base64url")
  );

  if (!isValid) {
    res.status(401).json({ error: "Invalid token signature" });
    return;
  }

  // Token is valid, proceed
  next();
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import {
  getAllBookings,
  getBookingById,
  insertBooking,
  updateBooking,
  deleteBooking
} from "../db/bookings-table";

export const router = Router();

// Get all bookings
router.get("/", (req: Request, res: Response) => {
  const bookings = getAllBookings();
  res.json(bookings);
});

// Get a booking by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid booking ID" });
  }

  const booking = getBookingById(id);

  if (!booking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  res.json(booking);
});

// Create a new booking
router.post("/", (req: Request, res: Response) => {
  const { memberId, slotTime, status } = req.body;

  if (!memberId || !slotTime || !status) {
    return res.status(400).json({ error: "Member ID, slot time, and status are required" });
  }

  const id = insertBooking(memberId, slotTime, status);

  res.status(201).json({ id, memberId, slotTime, status });
});

// Update a booking
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { memberId, slotTime, status } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid booking ID" });
  }

  if (!memberId || !slotTime || !status) {
    return res.status(400).json({ error: "Member ID, slot time, and status are required" });
  }

  const existingBooking = getBookingById(id);

  if (!existingBooking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  updateBooking(id, memberId, slotTime, status);

  res.json({ id, memberId, slotTime, status });
});

// Delete a booking
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid booking ID" });
  }

  const existingBooking = getBookingById(id);

  if (!existingBooking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  deleteBooking(id);

  res.json({ message: "Booking deleted successfully" });
});
