{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./dog-park.db");

interface Owner {
  id: number;
  account_id: string;
  email: string;
  password: string;
}

const createOwnersTable = `
  CREATE TABLE IF NOT EXISTS owners (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    account_id TEXT NOT NULL UNIQUE,
    email TEXT NOT NULL UNIQUE,
    password TEXT NOT NULL
  );
`;

db.exec(createOwnersTable);

export const getAllOwners = (): Owner[] => {
  const stmt = db.prepare("SELECT * FROM owners");
  return stmt.all() as unknown as Owner[];
};

export const getOwnerById = (id: number): Owner | undefined => {
  const stmt = db.prepare("SELECT * FROM owners WHERE id = ?");
  return stmt.get(id) as unknown as Owner | undefined;
};

export const insertOwner = (accountId: string, email: string, password: string): number => {
  const stmt = db.prepare(
    "INSERT INTO owners (account_id, email, password) VALUES (?, ?, ?)"
  );
  const result = stmt.run(accountId, email, password);
  return Number(result.lastInsertRowid);
};

export const updateOwner = (id: number, accountId: string, email: string, password: string): number => {
  const stmt = db.prepare(
    "UPDATE owners SET account_id = ?, email = ?, password = ? WHERE id = ?"
  );
  const result = stmt.run(accountId, email, password, id);
  return Number(result.changes);
};

export const deleteOwner = (id: number): number => {
  const stmt = db.prepare("DELETE FROM owners WHERE id = ?");
  const result = stmt.run(id);
  return Number(result.changes);
};

// Seed data
if (getAllOwners().length === 0) {
