{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteMember,
  getAllMembers,
  getMemberById,
  insertMember,
  updateMember
} from "../db/co-op-members-table";

export const router = Router();

// Get all members
router.get("/", (req: Request, res: Response) => {
  try {
    const members = getAllMembers();
    res.json(members);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch members" });
  }
});

// Get a specific member by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid member ID" });
    }

    const member = getMemberById(id);
    if (!member) {
      return res.status(404).json({ error: "Member not found" });
    }

    res.json(member);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch member" });
  }
});

// Create a new member
router.post("/", (req: Request, res: Response) => {
  try {
    const { name, energy_quota } = req.body;

    if (!name || energy_quota === undefined) {
      return res.status(400).json({ error: "Name and energy_quota are required" });
    }

    const id = insertMember(name, energy_quota);
    const newMember = getMemberById(id);

    if (!newMember) {
      return res.status(500).json({ error: "Failed to create member" });
    }

    res.status(201).json(newMember);
  } catch (error) {
    res.status(500).json({ error: "Failed to create member" });
  }
});

// Update a member
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { name, energy_quota } = req.body;

    if (isNaN(id) || !name || energy_quota === undefined) {
      return res.status(400).json({ error: "Invalid input data" });
    }

    const updated = updateMember(id, name, energy_quota);
    if (!updated) {
      return res.status(404).json({ error: "Member not found" });
    }

    const updatedMember = getMemberById(id);
    if (!updatedMember) {
      return res.status(500).json({ error: "Failed to retrieve updated member" });
    }

    res.json(updatedMember);
  } catch (error) {
    res.status(500).json({ error: "Failed to update member" });
  }
});

// Delete a member
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid member ID" });
    }

    const deleted = deleteMember(id);
    if (!deleted) {
      return res.status(404).json({ error: "Member not found" });
    }

    res.json({ message: "Member deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete member" });
  }
});
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./kegs.db");

interface Keg {
  id: number;
  style: string;
  quantity: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS kegs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    style TEXT NOT NULL,
    quantity INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllKegs(): Keg[] {
  const stmt = db.prepare("SELECT * FROM kegs");
  return stmt.all() as unknown as Keg[];
}

export function getKegById(id: number): Keg | undefined {
  const stmt = db.prepare("SELECT * FROM kegs WHERE id = ?");
  return stmt.get(id) as unknown as Keg | undefined;
}

export function insertKeg(style: string, quantity: number): number {
  const stmt = db.prepare("INSERT INTO kegs (style, quantity) VALUES (?, ?)");
  const result = stmt.run(style, quantity);
  return Number(result.lastInsertRowid);
}

export function updateKeg(id: number, style: string, quantity: number): void {
  const stmt = db.prepare("UPDATE kegs SET style = ?, quantity = ? WHERE id = ?");
  stmt.run(style, quantity, id);
}

export function deleteKeg(id: number): void {
  const stmt = db.prepare("DELETE FROM kegs WHERE id = ?");
  stmt.run(id);
}

// Seed data
if (getAllKegs().length === 0) {
  insertKeg("IPA", 120);
  insertKeg("Stout", 80);
  insertKeg("Pilsner", 150);
  insertKeg("Wheat Beer", 90);
  insertKeg("Pale Ale", 110);
}
"}

