{"code":"import { useEffect, useState } from "react";

interface Shift {
  id: number;
  date: string;
  startTime: string;
  endTime: string;
  lifeguards: string[];
}

export function SupervisorDeleteGuard() {
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchShifts();
  }, []);

  const fetchShifts = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/shifts-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch shifts: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setShifts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteGuard = async (shiftId: number, guardName: string) => {
    try {
      const response = await fetch(`/api/shifts-api/${shiftId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          lifeguards: shifts.find(s => s.id === shiftId)?.lifeguards.filter(guard => guard !== guardName) || []
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to update shift: ${response.status} ${response.statusText}`);
      }

      // Refresh the shifts list after deletion
      await fetchShifts();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  if (shifts.length === 0) return <div style={{ textAlign: "center", padding: "20px" }}>No shifts available.</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Supervisor: Remove Lifeguard</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {shifts.map(shift => (
          <div key={shift.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
            <h2>{new Date(shift.date).toLocaleDateString()} - {shift.startTime} to {shift.endTime}</h2>
            <div style={{ marginTop: "10px" }}>
              <strong>Lifeguards:</strong>
              <ul style={{ listStyleType: "none", padding: 0 }}>
                {shift.lifeguards.map((guard, index) => (
                  <li key={index} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "5px" }}>
                    <span>{guard}</span>
                    <button 
                      onClick={() => handleDeleteGuard(shift.id, guard)}
                      style={{ backgroundColor: "#ff4d4d", color: "white", border: "none", borderRadius: "4px", padding: "5px 10px", cursor: "pointer" }}
                    >
                      Remove
                    </button>
                  </li>
                ))}
              </ul>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import { 
  getAllRegistrations,
  getRegistrationById,
  insertRegistration,
  updateRegistration,
  deleteRegistration
} from "../db/registrations-table";

export const router = Router();

// Get all registrations
router.get("/", (req: Request, res: Response) => {
  try {
    const registrations = getAllRegistrations();
    res.json(registrations);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch registrations" });
  }
});

// Get a registration by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid registration ID" });
    }

    const registration = getRegistrationById(id);
    if (!registration) {
      return res.status(404).json({ error: "Registration not found" });
    }

    res.json(registration);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch registration" });
  }
});

// Create a new registration
router.post("/", (req: Request, res: Response) => {
  try {
    const { camperId, sessionId, status } = req.body;

    if (!camperId || !sessionId || !status) {
      return res.status(400).json({ error: "Missing required fields: camperId, sessionId, status" });
    }

    const id = insertRegistration(camperId, sessionId, status);
    const newRegistration = getRegistrationById(id);

    if (!newRegistration) {
      return res.status(500).json({ error: "Failed to create registration" });
    }

    res.status(201).json(newRegistration);
  } catch (error) {
    res.status(500).json({ error: "Failed to create registration" });
  }
});

// Update a registration
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid registration ID" });
    }

    const { camperId, sessionId, status } = req.body;

    if (!camperId || !sessionId || !status) {
      return res.status(400).json({ error: "Missing required fields: camperId, sessionId, status" });
    }

    const existingRegistration = getRegistrationById(id);
    if (!existingRegistration) {
      return res.status(404).json({ error: "Registration not found" });
    }

    updateRegistration(id, camperId, sessionId, status);
    const updatedRegistration = getRegistrationById(id);

    if (!updatedRegistration) {
      return res.status(500).json({ error: "Failed to update registration" });
    }

    res.json(updatedRegistration);
  } catch (error) {
    res.status(500).json({ error: "Failed to update registration" });
  }
});

// Delete a registration
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid registration ID" });
    }

    const existingRegistration = getRegistrationById(id);
    if (!existingRegistration) {
      return res.status(404).json({ error: "Registration not found" });
    }

    deleteRegistration(id);
    res.json({ message: "Registration deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete registration" });
  }
});
