{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/client-workout-tracker.db"
);

interface Workout {
  id: number;
  clientId: number;
  trainerId: number;
  exercise: string;
  date: string;
  notes: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS workouts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    clientId INTEGER NOT NULL,
    trainerId INTEGER NOT NULL,
    exercise TEXT NOT NULL,
    date TEXT NOT NULL,
    notes TEXT
  );
`;

db.exec(createTableSql);

export function getAllWorkouts(): Workout[] {
  const stmt = db.prepare(`SELECT * FROM workouts`);
  return stmt.all() as unknown as Workout[];
}

export function getWorkoutById(id: number): Workout | undefined {
  const stmt = db.prepare(`SELECT * FROM workouts WHERE id = ?`);
  return stmt.get(id) as unknown as Workout | undefined;
}

export function insertWorkout(workout: Omit<Workout, "id">): number {
  const stmt = db.prepare(
    `INSERT INTO workouts (clientId, trainerId, exercise, date, notes) VALUES (?, ?, ?, ?, ?)`
  );
  const result = stmt.run(
    workout.clientId,
    workout.trainerId,
    workout.exercise,
    workout.date,
    workout.notes
  );
  return Number(result.lastInsertRowid);
}

export function updateWorkout(
  id: number,
  workout: Partial<Omit<Workout, "id">>
): boolean {
  const fields = Object.keys(workout);
  if (fields.length === 0) return false;

  const setClause = fields.map(field => `${field} = ?`).join(", ");
  const sql = `UPDATE workouts SET ${setClause} WHERE id = ?`;
  const values = [...Object.values(workout), id];

  const stmt = db.prepare(sql);
  const result = stmt.run(...values);
  return result.changes > 0;
}

export function deleteWorkout(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM workouts WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
}

// Seed data
if (getAllWorkouts().length === 0) {
  insertWorkout({
    clientId: 1,
    trainerId: 101,
    exercise: "Bench Press",
    date: "2023-05-15",
    notes: "Focus on form"
  });

  insertWorkout({
    clientId: 2,
    trainerId: 102,
    exercise: "Squats",
    date: "2023-05-16",
    notes: "Increase weight"
  });

  insertWorkout({
    clientId: 3,
    trainerId: 101,
    exercise: "Deadlifts",
    date: "2023-05-17",
    notes: "Proper breathing technique"
  });

  insertWorkout({
    clientId: 4,
    trainerId: 103,
    exercise: "Shoulder Press",
    date: "2023-05-18",
    notes: "Maintain posture"
  });

  insertWorkout({
    clientId: 5,
    trainerId: 102,
    exercise: "Pull-ups",
    date: "2023-05-19",
    notes: "Use full range of motion"
  });
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as appointmentsRouter } from "../routes/appointments-api";
import { router as exportServiceRouter } from "../routes/export-service";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check ownership for export service routes
  if (!req.path.startsWith("/export")) {
    next();
    return;
  }

  // Check if the user is the owner
  const owner = req.headers["x-owner"];
  if (!owner || typeof owner !== "string") {
    res.status(403).json({ error: "Owner access required" });
    return;
  }

  // In a real implementation, we would verify the owner against a database
  // For now, we'll just check if the owner header matches a known owner
  // This is a simplified example - in practice, you'd have proper authentication logic
  const expectedOwner = process.env.OWNER_ID || "default-owner";

  if (owner !== expectedOwner) {
    res.status(403).json({ error: "Access denied: not the owner" });
    return;
  }

  next();
}
"}

{"code":"import { useEffect, useState } from "react";

interface Slot {
  id: string;
  startTime: string;
  endTime: string;
  claimedBy?: string;
}

export function AirtimeSlotClaimUi() {
  const [slots, setSlots] = useState<Slot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchSlots();
  }, []);

  const fetchSlots = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/scheduling-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch slots: ${response.status}`);
      }
      const data = await response.json();
      setSlots(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleClaimSlot = async (slotId: string) => {
    try {
      const response = await fetch(`/api/scheduling-api/${slotId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ claimedBy: 'current-dj' }),
      });

      if (!response.ok) {
        throw new Error(`Failed to claim slot: ${response.status}`);
      }

      // Refresh the slot list
      await fetchSlots();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const emptyMessage = {
    textAlign: 'center' as const,
    padding: '20px' as const,
    fontStyle: 'italic' as const,
    color: '#666' as const,
  };

  const gridStyle = {
    display: 'flex' as const,
    flexWrap: 'wrap' as const,
    gap: '15px' as const,
    maxWidth: '800px' as const,
    margin: '0 auto' as const,
    padding: '20px' as const,
  };

  const cardStyle = {
    border: '1px solid #ddd' as const,
    borderRadius: '8px' as const,
    padding: '15px' as const,
    width: '100%' as const,
    boxSizing: 'border-box' as const,
    display: 'flex' as const,
    flexDirection: 'column' as const,
    justifyContent: 'space-between' as const,
  };

  const buttonStyle = {
    backgroundColor: '#007bff' as const,
    color: 'white' as const,
    border: 'none' as const,
    borderRadius: '4px' as const,
    padding: '8px 12px' as const,
    cursor: 'pointer' as const,
    marginTop: '10px' as const,
  };

  const timeStyle = {
    fontSize: '1.1em' as const,
    fontWeight: 'bold' as const,
    marginBottom: '5px' as const,
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ fontFamily: 'system-ui, sans-serif', maxWidth: '800px', margin: '0 auto', padding: '20px' }}>
      <h1>Airtime Slot Claim</h1>
      <p>Available slots:</p>

      {slots.length === 0 ? (
        <div style={emptyMessage}>No available slots.</div>
      ) : (
        <div style={gridStyle}>
          {slots.map((slot) => (
            <div key={slot.id} style={cardStyle}>
              <div>
                <div style={timeStyle}>{slot.startTime} - {slot.endTime}</div>
                <div>{slot.claimedBy ? `Claimed by: ${slot.claimedBy}` : 'Available'}</div>
              </div>
              {!slot.claimedBy && (
                <button 
                  style={buttonStyle}
                  onClick={() => handleClaimSlot(slot.id)}
                >
                  Claim Slot
                </button>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

