{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to the emergency access delegation endpoint
  if (req.method !== "POST" || req.path !== "/emergency-access/delegate") {
    next();
    return;
  }

  // Check if the request has a valid authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT secret not configured" });
    return;
  }

  // Simple token validation - in a real implementation, you'd decode and verify
  // the JWT signature using HMAC-SHA256 with the secret
  try {
    // For demonstration purposes, we'll just check if the token matches a
    // predefined expected token (this is not secure in production)
    const expectedToken = createHmac("sha256", secret)
      .update("valid-emergency-access-token")
      .digest("hex");

    const tokenBuffer = Buffer.from(token);
    const expectedBuffer = Buffer.from(expectedToken);

    if (tokenBuffer.length !== expectedBuffer.length || 
        !timingSafeEqual(tokenBuffer, expectedBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token" });
      return;
    }
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  next();
}
"}

