{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./recipe-box.db");

interface Recipe {
  id: number;
  title: string;
  ingredients: string;
  steps: string;
  tags: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS recipes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    ingredients TEXT NOT NULL,
    steps TEXT NOT NULL,
    tags TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllRecipes(): Recipe[] {
  const stmt = db.prepare("SELECT * FROM recipes");
  return stmt.all() as unknown as Recipe[];
}

export function getRecipeById(id: number): Recipe | undefined {
  const stmt = db.prepare("SELECT * FROM recipes WHERE id = ?");
  return stmt.get(id) as unknown as Recipe | undefined;
}

export function insertRecipe(recipe: Omit<Recipe, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO recipes (title, ingredients, steps, tags) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(recipe.title, recipe.ingredients, recipe.steps, recipe.tags);
  return Number(result.lastInsertRowid);
}

export function updateRecipe(id: number, recipe: Partial<Omit<Recipe, "id">>): boolean {
  const fields = [];
  const values = [];

  if (recipe.title !== undefined) {
    fields.push("title = ?");
    values.push(recipe.title);
  }

  if (recipe.ingredients !== undefined) {
    fields.push("ingredients = ?");
    values.push(recipe.ingredients);
  }

  if (recipe.steps !== undefined) {
    fields.push("steps = ?");
    values.push(recipe.steps);
  }

  if (recipe.tags !== undefined) {
    fields.push("tags = ?");
    values.push(recipe.tags);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE recipes SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
}

export function deleteRecipe(id: number): boolean {
  const stmt = db.prepare("DELETE FROM recipes WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

// Seed data
if (getAllRecipes().length === 0) {
  insertRecipe({
