{"code":"import { FC, useState } from "react";

interface Rehearsal {
  id: string;
  title: string;
  date: string;
  conductor: string;
}

export function ConductorOnlyCancelButton({
  rehearsalId,
  currentUserId,
  onRehearsalCancelled
}: {
  rehearsalId: string;
  currentUserId: string;
  onRehearsalCancelled: () => void;
}) {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleCancel() {
    setIsLoading(true);
    setError(null);

    try {
      const response = await fetch(`/api/rehearsal-api/rehearsals/${rehearsalId}`, {
        method: "DELETE",
        headers: {
          "Content-Type": "application/json"
        }
      });

      if (!response.ok) {
        throw new Error(`Failed to cancel rehearsal: ${response.status} ${response.statusText}`);
      }

      onRehearsalCancelled();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setIsLoading(false);
    }
  }

  return (
    <div style={{ maxWidth: 600, margin: "0 auto", padding: 20, fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <button 
        onClick={handleCancel}
        disabled={isLoading}
        style={{
          backgroundColor: "#ff4d4d",
          color: "white",
          border: "none",
          borderRadius: 4,
          padding: "10px 20px",
          fontSize: 16,
          cursor: isLoading ? "not-allowed" : "pointer"
        }}
