{"code":"import { useEffect, useState } from "react";

export function OwnerOnlyHistoryExport() {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [historyData, setHistoryData] = useState<any[]>([]);

  useEffect(() => {
    const fetchHistory = async () => {
      try {
        const response = await fetch('/api/checkouts-api/');
        if (!response.ok) {
          throw new Error(`Failed to fetch history: ${response.status} ${response.statusText}`);
        }
        const data = await response.json();
        setHistoryData(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchHistory();
  }, []);

  const handleExport = async () => {
    try {
      const response = await fetch('/api/history-export-guard', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({}),
      });

      if (!response.ok) {
        throw new Error(`Export failed: ${response.status} ${response.statusText}`);
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'checkout_history.csv';
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: 'center', padding: '20px' }}>
        <p>Error: {error}</p>
      </div>
    );
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Owner-Only History Export</h1>
      <p>Download a CSV of every transaction ever.</p>

      <button 
        onClick={handleExport}
        style={{
          backgroundColor: '#007bff',
          color: 'white',
          border: 'none',
          padding: '10px 20px',
          borderRadius: '5px',
          cursor: 'pointer',
          fontSize: '16px',
          marginBottom: '20px'
        }}
      >
        Export All Transactions to CSV
      </button>

      <h2>Transaction History</h2>
      {historyData.length === 0 ? (
        <p>No transactions found.</p>
      ) : (
        <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '20px' }}>
          <thead>
            <tr style={{ borderBottom: '1px solid #ddd' }}>
              <th style={{ padding: '10px', textAlign: 'left' }}>ID</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Item</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Borrower</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Checkout Date</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Return Date</th>
            </tr>
          </thead>
          <tbody>
            {historyData.map((transaction) => (
              <tr key={transaction.id} style={{ borderBottom: '1px solid #ddd' }}>
                <td style={{ padding: '10px' }}>{transaction.id}</td>
                <td style={{ padding: '10px' }}>{transaction.item}</td>
                <td style={{ padding: '10px' }}>{transaction.borrower}</td>
                <td style={{ padding: '10px' }}>{new Date(transaction.checkoutDate).toLocaleDateString()}</td>
                <td style={{ padding: '10px' }}>{transaction.returnDate ? new Date(transaction.returnDate).toLocaleDateString() : 'Not returned'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface Contact {
  id: string;
  name: string;
  email: string;
  phone: string;
}

interface Deal {
  id: string;
  title: string;
  value: number;
  status: string;
}

interface CustomObject {
  id: string;
  name: string;
  description: string;
}

export function CrmWorkspace() {
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [deals, setDeals] = useState<Deal[]>([]);
  const [customObjects, setCustomObjects] = useState<CustomObject[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [contactsRes, dealsRes, customObjectsRes] = await Promise.all([
          fetch('/api/crm-api/contacts'),
          fetch('/api/crm-api/deals'),
          fetch('/api/crm-api/custom-objects')
        ]);

        if (!contactsRes.ok || !dealsRes.ok || !customObjectsRes.ok) {
          throw new Error('Failed to fetch data');
        }

        const [contactsData, dealsData, customObjectsData] = await Promise.all([
          contactsRes.json(),
          dealsRes.json(),
          customObjectsRes.json()
        ]);

        setContacts(contactsData);
        setDeals(dealsData);
        setCustomObjects(customObjectsData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleAddContact = async (e: React.FormEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);
    const newContact = {
      name: formData.get('name') as string,
      email: formData.get('email') as string,
      phone: formData.get('phone') as string
    };

    try {
      const res = await fetch('/api/crm-api/contacts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newContact)
      });

      if (res.ok) {
        const createdContact = await res.json();
        setContacts([...contacts, createdContact]);
        form.reset();
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteContact = async (id: string) => {
    try {
      const res = await fetch(`/api/crm-api/contacts/${id}`, {
        method: 'DELETE'
      });

      if (res.ok) {
        setContacts(contacts.filter(contact => contact.id !== id));
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleAddDeal = async (e: React.FormEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);
    const newDeal = {
      title: formData.get('title') as string,
      value: Number(formData.get('value')),
      status: formData.get('status') as string
    };

    try {
      const res = await fetch('/api/crm-api/deals', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newDeal)
      });

      if (res.ok) {
        const createdDeal = await res.json();
        setDeals([...deals, createdDeal]);
        form.reset();
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteDeal = async (id: string) => {
    try {
      const res = await fetch(`/api/crm-api/deals/${id}`, {
        method: 'DELETE'
      });

      if (res.ok) {
        setDeals(deals.filter(deal => deal.id !== id));
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleAddCustomObject = async (e: React.FormEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);
    const newCustomObject = {
      name: formData.get('name') as string,
      description: formData.get('description') as string
    };

    try {
      const res = await fetch('/api/crm-api/custom-objects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newCustomObject)
      });

      if (res.ok) {
        const createdCustomObject = await res.json();
        setCustomObjects([...customObjects, createdCustomObject]);
        form.reset();
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteCustomObject = async (id: string) => {
    try {
      const res = await fetch(`/api/crm-api/custom-objects/${id}`, {
        method: 'DELETE'
      });

      if (res.ok) {
        setCustomObjects(customObjects.filter(obj => obj.id !== id));
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
