{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check export requests
  if (req.method !== "POST" || req.path !== "/export") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Basic token structure validation
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  const [header, payload, signature] = parts;

  // Verify signature
  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const signatureBuffer = Buffer.from(signature, "base64url");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

  try {
    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Invalid token signature" });
    return;
  }

  // Decode payload to check ownership
  try {
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());

    if (!decodedPayload.siteId || !decodedPayload.userId) {
      res.status(401).json({ error: "Invalid token payload" });
      return;
    }

    // In a real implementation, we would check if the user owns the site
    // For now, we'll just simulate the check
    const userOwnsSite = true; // This would be replaced with actual DB lookup

    if (!userOwnsSite) {
      res.status(403).json({ error: "Forbidden: User does not own the site" });
      return;
    }

    next();
  } catch (err) {
    res.status(401).json({ error: "Invalid token payload" });
  }
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteReservation,
  getAllReservations,
  getReservationById,
  insertReservation,
  updateReservation
} from "../db/reservations-table";

export const router = Router();

// GET /reservations - Get all reservations
router.get("/reservations", (req: Request, res: Response) => {
  try {
    const reservations = getAllReservations();
    res.json(reservations);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservations" });
  }
});

// GET /reservations/:id - Get a reservation by ID
router.get("/reservations/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const reservation = getReservationById(id);
    if (!reservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    res.json(reservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservation" });
  }
});

// POST /reservations - Create a new reservation
router.post("/reservations", (req: Request, res: Response) => {
  try {
    const { guestId, slotTime, status } = req.body;

    if (!guestId || !slotTime || !status) {
      return res.status(400).json({ error: "Missing required fields: guestId, slotTime, status" });
    }

    const id = insertReservation(guestId, slotTime, status);
    const newReservation = getReservationById(id);

    if (!newReservation) {
      return res.status(500).json({ error: "Failed to create reservation" });
    }

    res.status(201).json(newReservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to create reservation" });
  }
});

// PUT /reservations/:id - Update a reservation
router.put("/reservations/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { guestId, slotTime, status } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    if (!guestId || !slotTime || !status) {
      return res.status(400).json({ error: "Missing required fields: guestId, slotTime, status" });
    }

    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    updateReservation(id, guestId, slotTime, status);
    const updatedReservation = getReservationById(id);

    if (!updatedReservation) {
      return res.status(500).json({ error: "Failed to update reservation" });
    }

    res.json(updatedReservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to update reservation" });
  }
});

// DELETE /reservations/:id - Delete a reservation
router.delete("/reservations/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    deleteReservation(id);
    res.json({ message: "Reservation deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete reservation" });
  }
});
"}

{"code":"import { Router, type Request, type Response } from "express";
import { getAllBatches } from "../db/aging-batches-table";

export const router = Router();

router.get("/export", (req: Request, res: Response) => {
  // Extract ownerId from query parameters
  const ownerIdParam = req.query.ownerId;

  if (!ownerIdParam) {
    return res.status(400).json({ error: "Missing ownerId parameter" });
  }

  const ownerId = Number(ownerIdParam);

  if (isNaN(ownerId)) {
    return res.status(400).json({ error: "Invalid ownerId parameter" });
  }

  // Get all batches from the database
  const batches = getAllBatches();

  // Filter batches by ownerId
  const userBatches = batches.filter(batch => batch.owner_id === ownerId);

  // Generate CSV content
  const csvContent = [
    "id,cheese_type,age_days,owner_id",
    ...userBatches.map(batch => `${batch.id},${batch.cheese_type},${batch.age_days},${batch.owner_id}`)
  ].join("\n");

  // Set response headers for CSV download
  res.setHeader("Content-Type", "text/csv");
  res.setHeader("Content-Disposition", "attachment; filename=cheese_aging_data.csv");

  // Send the CSV content
  res.send(csvContent);
});
"}

