  }

  return (
    <div style={{ maxWidth: 600, margin: '0 auto', padding: 20, fontFamily: 'system-ui, sans-serif' }}>
      <h1>Tool Checkout</h1>

      <form onSubmit={handleCheckout} style={{ marginBottom: 20 }}>
        <input
          type="text"
          value={newToolName}
          onChange={(e) => setNewToolName(e.target.value)}
          placeholder="Enter tool name"
          style={{ width: '100%', padding: 8, marginBottom: 10, borderRadius: 4, border: '1px solid #ccc' }}
        />
        <button 
          type="submit" 
          style={{ 
            backgroundColor: '#007bff', 
            color: 'white', 
            border: 'none', 
            padding: '8px 16px', 
            borderRadius: 4, 
            cursor: 'pointer' 
          }}
        >
          Checkout Tool
        </button>
      </form>

      {checkouts.length === 0 ? (
        <p>No tool checkouts found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
          {checkouts.map((checkout) => (
            <div 
              key={checkout.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: 8, 
                padding: 15, 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center', 
                flexWrap: 'wrap'
              }}
            >
              <div>
                <strong>{checkout.toolName}</strong><br />
                Checked out: {new Date(checkout.checkoutDate).toLocaleDateString()}<br />
                {checkout.returnDate ? (
                  <span>Returned: {new Date(checkout.returnDate).toLocaleDateString()}</span>
                ) : (
                  <span style={{ color: 'green' }}>Not returned yet</span>
                )}
              </div>
              <div style={{ display: 'flex', gap: 5, flexWrap: 'wrap' }}>
                {!checkout.returnDate && (
                  <button 
                    onClick={() => handleReturn(checkout.id)}
                    style={{ 
                      backgroundColor: '#28a745', 
                      color: 'white', 
                      border: 'none', 
                      padding: '4px 8px', 
                      borderRadius: 4, 
                      cursor: 'pointer' 
                    }}
                  >
                    Return
                  </button>
                )}
                <button 
                  onClick={() => handleDelete(checkout.id)}
                  style={{ 
                    backgroundColor: '#dc3545', 
                    color: 'white', 
                    border: 'none', 
                    padding: '4px 8px', 
                    borderRadius: 4, 
                    cursor: 'pointer' 
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

