{"code":"import { Router, type Request, type Response } from "express";
import { db, deleteRoute, getAllRoutes, getRouteById, insertRoute, updateRoute } from "../db/routes-table";

export const router = Router();

// Get all routes for the current user
router.get("/", (req: Request, res: Response) => {
  try {
    const routes = getAllRoutes();
    // Filter routes to only include those belonging to the current user
    // Assuming req.user contains the setterId
    const userRoutes = routes.filter(route => route.setterId === (req as any).user?.setterId);
    res.json(userRoutes);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch routes" });
  }
});

// Get a specific route by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid route ID" });
    }

    const route = getRouteById(id);
    if (!route) {
      return res.status(404).json({ error: "Route not found" });
    }

    // Check if the route belongs to the current user
    if (route.setterId !== (req as any).user?.setterId) {
      return res.status(404).json({ error: "Route not found" });
    }

    res.json(route);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch route" });
  }
});

// Create a new route
router.post("/", (req: Request, res: Response) => {
  try {
    const { name, grade, setterId } = req.body;

    if (!name || !grade || !setterId) {
      return res.status(400).json({ error: "Name, grade, and setterId are required" });
    }

    // Ensure setterId matches the current user
    if (setterId !== (req as any).user?.setterId) {
      return res.status(400).json({ error: "Unauthorized to create route for this setter" });
    }

    const newId = insertRoute(name, grade, setterId);
    const newRoute = getRouteById(newId);

    if (!newRoute) {
      return res.status(500).json({ error: "Failed to create route" });
    }

    res.status(201).json(newRoute);
  } catch (error) {
    res.status(500).json({ error: "Failed to create route" });
  }
});

// Update an existing route
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid route ID" });
    }

    const { name, grade, setterId } = req.body;

    if (!name || !grade || !setterId) {
      return res.status(400).json({ error: "Name, grade, and setterId are required" });
    }

    const existingRoute = getRouteById(id);
    if (!existingRoute) {
      return res.status(404).json({ error: "Route not found" });
    }

    // Check if the route belongs to the current user
    if (existingRoute.setterId !== (req as any).user?.setterId) {
      return res.status(400).json({ error: "Unauthorized to update this route" });
    }

    updateRoute(id, name, grade, setterId);
    const updatedRoute = getRouteById(id);

    if (!updatedRoute) {
      return res.status(500).json({ error: "Failed to update route" });
    }

    res.json(updatedRoute);
  } catch (error) {
    res.status(500).json({ error: "Failed to update route" });
  }
});

// Delete a route
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid route ID" });
    }

    const existingRoute = getRouteById(id);
    if (!existingRoute) {
      return res.status(404).json({ error: "Route not found" });
    }

    // Check if the route belongs to the current user
    if (existingRoute.setterId !== (req as any).user?.setterId) {
      return res.status(400).json({ error: "Unauthorized to delete this route" });
    }

    deleteRoute(id);
    res.json({ message: "Route deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete route" });
  }
});
"}

