{"code":"import { useEffect, useState } from "react";

interface Shift {
  id: string;
  date: string;
  startTime: string;
  endTime: string;
  claimedBy?: string;
}

export function MemberShiftClaimForm() {
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchShifts();
  }, []);

  const fetchShifts = async () => {
    try {
      const response = await fetch('/api/shifts-api/');
      if (!response.ok) {
        throw new Error('Failed to fetch shifts');
      }
      const data = await response.json();
      setShifts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleClaimShift = async (shiftId: string) => {
    try {
      const response = await fetch(`/api/shifts-api/${shiftId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ claimedBy: 'current-member' }),
      });

      if (!response.ok) {
        throw new Error('Failed to claim shift');
      }

      // Refresh the shifts list
      await fetchShifts();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  if (error) {
    return <div>Error: {error}</div>;
  }

  const gridStyle: React.CSSProperties = {
    display: 'flex',
    flexWrap: 'wrap',
    gap: '16px',
    justifyContent: 'center',
  };

  const cardStyle: React.CSSProperties = {
    border: '1px solid #ccc',
    borderRadius: '8px',
    padding: '16px',
    width: '300px',
    boxSizing: 'border-box',
    backgroundColor: '#f9f9f9',
  };

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '16px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Claim a Shift</h1>
      <p>Select an open shift to claim:</p>

      <div style={gridStyle}>
        {shifts.length === 0 ? (
          <p>No open shifts available.</p>
        ) : (
          shifts
            .filter(shift => !shift.claimedBy)
            .map(shift => (
              <div key={shift.id} style={cardStyle}>
                <h3>{new Date(shift.date).toLocaleDateString()}</h3>
                <p>Time: {shift.startTime} - {shift.endTime}</p>
                <button 
                  onClick={() => handleClaimShift(shift.id)}
                  style={{
                    backgroundColor: '#007bff',
                    color: 'white',
                    border: 'none',
                    borderRadius: '4px',
                    padding: '8px 16px',
                    cursor: 'pointer',
                    marginTop: '8px'
                  }}
                >
                  Claim Shift
                </button>
              </div>
            ))
        )}
      </div>
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface Player {
