    fetchAvailableDesks();
  }, []);

  const fetchBookings = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/bookings-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch bookings: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const fetchAvailableDesks = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/bookings-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch available desks: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setAvailableDesks(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleBookDesk = async (date: string) => {
    try {
      const response = await fetch('/api/bookings-api/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          date,
          memberId: 'current-member-id', // This should come from auth context
          deskId: 'desk-1', // This should be dynamic
        }),
      });

      if (!response.ok) {
        throw new Error(`Failed to book desk: ${response.status} ${response.statusText}`);
      }

      await fetchBookings();
      await fetchAvailableDesks();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const formatDate = (dateString: string) => {
    const options: Intl.DateTimeFormatOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    return new Date(dateString).toLocaleDateString(undefined, options);
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Desk Booking Calendar</h1>

      <div style={{ marginBottom: '20px' }}>
        <label htmlFor="datePicker" style={{ display: 'block', marginBottom: '5px' }}>
          Select Date:
        </label>
        <input
          type="date"
          id="datePicker"
          value={selectedDate}
          onChange={(e) => setSelectedDate(e.target.value)}
          style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
        />
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
        {availableDesks.length > 0 ? (
          availableDesks.map((desk) => (
            <div 
              key={desk.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center'
              }}
            >
              <span>{formatDate(desk.date)}</span>
              <button 
                onClick={() => handleBookDesk(desk.date)}
                disabled={!desk.available}
                style={{ 
                  backgroundColor: desk.available ? '#007bff' : '#ccc', 
                  color: 'white', 
                  border: 'none', 
                  padding: '8px 16px', 
                  borderRadius: '4px', 
                  cursor: desk.available ? 'pointer' : 'default'
                }}
              >
                {desk.available ? 'Book Desk' : 'Unavailable'}
              </button>
            </div>
          ))
        ) : (
          <p style={{ textAlign: 'center', padding: '20px' }}>No available desks found.</p>
        )}
      </div>
    </div>
  );
}
"}

{"code":"import { FC, useEffect, useState } from "react";

interface CheckoutRecord {
  id: number;
  userId: number;
  equipmentId: number;
  checkoutDate: string;
  returnDate: string | null;
}

interface User {
  id: number;
  name: string;
  role: string;
}

export function SupervisorDeleteGuard() {
  const [records, setRecords] = useState<CheckoutRecord[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchAllData() {
      try {
        const [recordsResponse, usersResponse] = await Promise.all([
          fetch("/api/checkout-api/"),
          fetch("/api/checkout-api/"), // This is a placeholder - in reality we'd need a separate endpoint for users
        ]);

        if (!recordsResponse.ok || !usersResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const recordsData = await recordsResponse.json();
        const usersData = await usersResponse.json();

        setRecords(recordsData);
        setUsers(usersData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchAllData();
  }, []);

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/supervisor-guard/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error("Supervisor guard rejected the deletion");
      }

      // Remove deleted record from state
      setRecords(records.filter(record => record.id !== id));
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "system-ui, sans-serif" }}>
      <h1>Supervisor Delete Guard</h1>
      <p>Only supervisors can delete checkout records.</p>

      {records.length === 0 ? (
        <p>No checkout records found.</p>
      ) : (
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr style={{ borderBottom: "1px solid #ccc" }}>
              <th style={{ textAlign: "left", padding: "10px" }}>User</th>
              <th style={{ textAlign: "left", padding: "10px" }}>Equipment</th>
              <th style={{ textAlign: "left", padding: "10px" }}>Checkout Date</th>
              <th style={{ textAlign: "left", padding: "10px" }}>Return Date</th>
              <th style={{ textAlign: "left", padding: "10px" }}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {records.map(record => {
              const user = users.find(u => u.id === record.userId);
              return (
                <tr key={record.id} style={{ borderBottom: "1px solid #eee" }}>
                  <td style={{ padding: "10px" }}>{user?.name || "Unknown User"}</td>
                  <td style={{ padding: "10px" }}>{record.equipmentId}</td>
                  <td style={{ padding: "10px" }}>{record.checkoutDate}</td>
                  <td style={{ padding: "10px" }}>{record.returnDate || "Not returned"}</td>
                  <td style={{ padding: "10px" }}>
                    <button 
                      onClick={() => handleDelete(record.id)}
                      style={{ 
                        backgroundColor: "#dc3545", 
                        color: "white", 
                        border: "none", 
                        padding: "5px 10px", 
                        borderRadius: "4px", 
                        cursor: "pointer"
                      }}
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </div>
  );
}
"}

