  }, []);

  const fetchContracts = async () => {
    try {
      const response = await fetch(`/api/contracts-api/`);
      if (!response.ok) throw new Error(`Failed to fetch contracts: ${response.status}`);
      const data = await response.json();
      setContracts(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleDelete = async (contractId: number) => {
    // Check if the contract belongs to the supervisor
    const contract = contracts.find(c => c.id === contractId);
    if (!contract) {
      alert("Contract not found.");
      return;
    }

    if (contract.supervisorId !== supervisorId) {
      alert("You cannot delete a contract that is not assigned to you.");
      return;
    }

    try {
      const response = await fetch(`/api/contracts-api/${contractId}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error(`Failed to delete contract: ${response.status}`);
      }

      // Refresh the list after successful deletion
      await fetchContracts();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  if (contracts.length === 0) return <div style={{ textAlign: "center", padding: "20px" }}>No contracts found.</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "system-ui, sans-serif" }}>
      <h1>Supervisor Contract Management</h1>
      <table style={{ width: "100%", borderCollapse: "collapse", marginBottom: "20px" }}>
        <thead>
          <tr style={{ borderBottom: "1px solid #ccc" }}>
            <th style={{ padding: "10px", textAlign: "left" }}>Title</th>
            <th style={{ padding: "10px", textAlign: "left" }}>Description</th>
            <th style={{ padding: "10px", textAlign: "left" }}>Actions</th>
          </tr>
        </thead>
        <tbody>
          {contracts.map(contract => (
            <tr key={contract.id} style={{ borderBottom: "1px solid #eee" }}>
              <td style={{ padding: "10px" }}>{contract.title}</td>
              <td style={{ padding: "10px" }}>{contract.description}</td>
              <td style={{ padding: "10px" }}>
                <button 
                  onClick={() => handleDelete(contract.id)}
                  style={{ 
                    backgroundColor: "#dc3545", 
                    color: "white", 
                    border: "none", 
                    padding: "5px 10px", 
                    borderRadius: "4px", 
                    cursor: "pointer"
                  }}
                >
                  Delete
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
"}

