{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface AirtimeSlot {
  id: number;
  dj_id: number;
  show_id: number;
  timestamp: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS airtime_slots (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    dj_id INTEGER NOT NULL,
    show_id INTEGER NOT NULL,
    timestamp TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllAirtimeSlots(): AirtimeSlot[] {
  const stmt = db.prepare(`SELECT * FROM airtime_slots`);
  return stmt.all() as unknown as AirtimeSlot[];
}

export function getAirtimeSlotById(id: number): AirtimeSlot | undefined {
  const stmt = db.prepare(`SELECT * FROM airtime_slots WHERE id = ?`);
  return stmt.get(id) as unknown as AirtimeSlot | undefined;
}

export function insertAirtimeSlot(djId: number, showId: number, timestamp: string): number {
  const stmt = db.prepare(
    `INSERT INTO airtime_slots (dj_id, show_id, timestamp) VALUES (?, ?, ?)`
  );
  const result = stmt.run(djId, showId, timestamp);
  return Number(result.lastInsertRowid);
}

export function updateAirtimeSlot(id: number, djId: number, showId: number, timestamp: string): void {
  const stmt = db.prepare(
    `UPDATE airtime_slots SET dj_id = ?, show_id = ?, timestamp = ? WHERE id = ?`
  );
  stmt.run(djId, showId, timestamp, id);
}

export function deleteAirtimeSlot(id: number): void {
  const stmt = db.prepare(`DELETE FROM airtime_slots WHERE id = ?`);
  stmt.run(id);
}

// Sample data insertion
