{"code":"import { useEffect, useState } from "react";

export function OwnerExportPanel() {
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Component mounts, but we don't need to fetch data for export
    // The export functionality is triggered by a button click
    setLoading(false);
  }, []);

  const handleExportClick = async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch('/api/export-service/export', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error(`Export failed: ${response.status} ${response.statusText}`);
      }

      // Get the CSV content from the response
      const csvContent = await response.text();

      // Create a blob and download it
      const blob = new Blob([csvContent], { type: 'text/csv' });
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'bookings_export.csv';
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  return (
    <div style={{
      maxWidth: '600px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <h1 style={{ textAlign: 'center' }}>Owner Export Panel</h1>
      <p style={{ textAlign: 'center' }}>Download a CSV of all bookings</p>

      {error && (
        <div style={{
          backgroundColor: '#ffebee',
          color: '#c62828',
          padding: '10px',
          borderRadius: '4px',
          marginBottom: '10px',
          textAlign: 'center'
        }}>
          {error}
        </div>
      )}

      <button
        onClick={handleExportClick}
        disabled={loading}
        style={{
          display: 'block',
          width: '100%',
          padding: '12px',
          backgroundColor: '#1976d2',
          color: 'white',
          border: 'none',
          borderRadius: '4px',
          fontSize: '16px',
          cursor: loading ? 'not-allowed' : 'pointer',
          marginTop: '20px'
        }}
      >
        {loading ? 'Exporting...' : 'Export All Bookings to CSV'}
      </button>
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface Expense {
  id: number;
  description: string;
  amount: number;
  status: "pending" | "approved" | "rejected";
}

export function ApprovalQueue() {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchExpenses();
  }, []);

  const fetchExpenses = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/expenses-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status}`);
      }
      const data = await response.json();
      setExpenses(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = async (id: number) => {
    try {
      const response = await fetch(`/api/expenses-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "approved" }),
      });
      if (!response.ok) {
        throw new Error(`Failed to approve: ${response.status}`);
      }
      fetchExpenses();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleReject = async (id: number) => {
    try {
      const response = await fetch(`/api/expenses-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "rejected" }),
      });
      if (!response.ok) {
        throw new Error(`Failed to reject: ${response.status}`);
      }
      fetchExpenses();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (expenses.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No pending expense requests.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Pending Expense Requests</h1>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: "15px",
        }}
      >
        {expenses
          .filter((expense) => expense.status === "pending")
          .map((expense) => (
            <div
              key={expense.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: "8px",
                padding: "15px",
                display: "flex",
                flexDirection: "column",
                gap: "10px",
              }}
            >
              <div>
                <strong>Description:</strong> {expense.description}
              </div>
              <div>
                <strong>Amount:</strong> ${expense.amount.toFixed(2)}
              </div>
              <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
                <button
                  onClick={() => handleApprove(expense.id)}
                  style={{
                    backgroundColor: "#4caf50",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "8px 12px",
                    cursor: "pointer",
                  }}
                >
                  Approve
                </button>
                <button
                  onClick={() => handleReject(expense.id)}
                  style={{
                    backgroundColor: "#f44336",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "8px 12px",
                    cursor: "pointer",
                  }}
                >
                  Reject
                </button>
              </div>
            </div>
          ))}
      </div>
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/team-documentation-platform.db"
);

interface Page {
  id: number;
  title: string;
  content: string;
  chapter_id: number;
}

interface Chapter {
  id: number;
  title: string;
  book_id: number;
}

interface Book {
  id: number;
  title: string;
}

const initSql = `
  CREATE TABLE IF NOT EXISTS books (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS chapters (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    book_id INTEGER NOT NULL,
    FOREIGN KEY (book_id) REFERENCES books(id)
  );

  CREATE TABLE IF NOT EXISTS pages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    content TEXT NOT NULL,
    chapter_id INTEGER NOT NULL,
    FOREIGN KEY (chapter_id) REFERENCES chapters(id)
  );
`;

db.exec(initSql);

export function getAllPages(): Page[] {
  const stmt = db.prepare(
    "SELECT * FROM pages ORDER BY id ASC"
  );
  return stmt.all() as unknown as Page[];
}

export function getPageById(id: number): Page | undefined {
  const stmt = db.prepare(
    "SELECT * FROM pages WHERE id = ?"
  );
  return stmt.get(id) as unknown as Page | undefined;
}

export function insertPage(
  title: string,
  content: string,
  chapterId: number
): number {
  const stmt = db.prepare(
    "INSERT INTO pages (title, content, chapter_id) VALUES (?, ?, ?)"
  );
  const result = stmt.run(title, content, chapterId);
  return Number(result.lastInsertRowid);
}

export function updatePage(
  id: number,
  title: string,
  content: string,
  chapterId: number
): void {
  const stmt = db.prepare(
    "UPDATE pages SET title = ?, content = ?, chapter_id = ? WHERE id = ?"
  );
  stmt.run(title, content, chapterId, id);
}

export function deletePage(id: number): void {
  const stmt = db.prepare("DELETE FROM pages WHERE id = ?");
  stmt.run(id);
}

// Seed data
if (getAllPages().length === 0) {
  const bookId = db.prepare(
    "INSERT INTO books (title) VALUES (?)"
  ).run("Getting Started Guide").lastInsertRowid;

  const chapterId1 = db.prepare(
    "INSERT INTO chapters (title, book_id) VALUES (?, ?)"
  ).run("Introduction", Number(bookId)).lastInsertRowid;

  const chapterId2 = db.prepare(
    "INSERT INTO chapters (title, book_id) VALUES (?, ?)"
  ).run("Core Concepts", Number(bookId)).lastInsertRowid;

  insertPage(
    "Welcome",
    "This guide will help you get started with our platform.",
    Number(chapterId1)
  );

  insertPage(
    "Key Features",
    "Our platform offers powerful features for team collaboration.",
    Number(chapterId1)
  );

  insertPage(
    "Data Models",
    "Understanding how data flows through our system.",
    Number(chapterId2)
  );

  insertPage(
    "API Endpoints",
    "List of available API endpoints and their usage.",
    Number(chapterId2)
  );
}
