{"code":"import { Router, type Request, type Response } from "express";
import { db, deleteAsset, getAllAssets, getAssetById, insertAsset, updateAsset } from "../db/assets-table";

export const router = Router();

// Get all assets
router.get("/", (req: Request, res: Response) => {
  try {
    const assets = getAllAssets();
    res.json(assets);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch assets" });
  }
});

// Get asset by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid asset ID" });
    }

    const asset = getAssetById(id);
    if (!asset) {
      return res.status(404).json({ error: "Asset not found" });
    }

    res.json(asset);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch asset" });
  }
});

// Create new asset
router.post("/", (req: Request, res: Response) => {
  try {
    const { name, purchaseDate, owner } = req.body;

    if (!name || !purchaseDate || !owner) {
      return res.status(400).json({ error: "Name, purchase date, and owner are required" });
    }

    const id = insertAsset(name, purchaseDate, owner);
    const newAsset = getAssetById(id);

    if (!newAsset) {
      return res.status(500).json({ error: "Failed to create asset" });
    }

    res.status(201).json(newAsset);
  } catch (error) {
    res.status(500).json({ error: "Failed to create asset" });
  }
});

// Update existing asset
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid asset ID" });
    }

    const { name, purchaseDate, owner } = req.body;

    if (!name || !purchaseDate || !owner) {
      return res.status(400).json({ error: "Name, purchase date, and owner are required" });
    }

    const rowsAffected = updateAsset(id, name, purchaseDate, owner);

    if (rowsAffected === 0) {
      return res.status(404).json({ error: "Asset not found" });
    }

    const updatedAsset = getAssetById(id);

    if (!updatedAsset) {
      return res.status(500).json({ error: "Failed to update asset" });
    }

    res.json(updatedAsset);
  } catch (error) {
    res.status(500).json({ error: "Failed to update asset" });
  }
});

// Delete asset
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid asset ID" });
    }

    const rowsAffected = deleteAsset(id);

    if (rowsAffected === 0) {
      return res.status(404).json({ error: "Asset not found" });
    }

    res.json({ message: "Asset deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete asset" });
  }
});
