{"code":"import { Router, type Request, type Response } from "express";
import { db, deleteKeg, getAllKegs, getKegById, insertKeg, updateKeg } from "../db/kegs-table";

export const router = Router();

// Get all kegs
router.get("/", (req: Request, res: Response) => {
  try {
    const kegs = getAllKegs();
    res.json(kegs);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch kegs" });
  }
});

// Get a specific keg by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid keg ID" });
    }

    const keg = getKegById(id);
    if (!keg) {
      return res.status(404).json({ error: "Keg not found" });
    }

    res.json(keg);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch keg" });
  }
});

// Create a new keg
router.post("/", (req: Request, res: Response) => {
  try {
    const { style, quantity } = req.body;

    if (!style || typeof quantity !== "number") {
      return res.status(400).json({ error: "Style and quantity are required" });
    }

    const id = insertKeg(style, quantity);
    const newKeg = getKegById(id);

    if (!newKeg) {
      return res.status(500).json({ error: "Failed to create keg" });
    }

    res.status(201).json(newKeg);
  } catch (error) {
    res.status(500).json({ error: "Failed to create keg" });
  }
});

// Update a keg
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid keg ID" });
    }

    const { style, quantity } = req.body;

    if (!style || typeof quantity !== "number") {
      return res.status(400).json({ error: "Style and quantity are required" });
    }

    const existingKeg = getKegById(id);
    if (!existingKeg) {
      return res.status(404).json({ error: "Keg not found" });
    }

    updateKeg(id, style, quantity);
    const updatedKeg = getKegById(id);

    if (!updatedKeg) {
      return res.status(500).json({ error: "Failed to update keg" });
    }

    res.json(updatedKeg);
  } catch (error) {
    res.status(500).json({ error: "Failed to update keg" });
  }
});

// Delete a keg
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid keg ID" });
    }

    const existingKeg = getKegById(id);
    if (!existingKeg) {
      return res.status(404).json({ error: "Keg not found" });
    }

    deleteKeg(id);
    res.json({ message: "Keg deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete keg" });
  }
});
"}

