{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./parking-garage.db");

interface Reservation {
  id: number;
  driverId: number;
  spotId: number;
  reservedTime: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS reservations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    driverId INTEGER NOT NULL,
    spotId INTEGER NOT NULL,
    reservedTime TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllReservations(): Reservation[] {
  const stmt = db.prepare("SELECT * FROM reservations");
  return stmt.all() as unknown as Reservation[];
}

export function getReservationById(id: number): Reservation | undefined {
  const stmt = db.prepare("SELECT * FROM reservations WHERE id = ?");
  return stmt.get(id) as unknown as Reservation | undefined;
}

export function insertReservation(
  driverId: number,
  spotId: number,
  reservedTime: string
): number {
  const stmt = db.prepare(
    "INSERT INTO reservations (driverId, spotId, reservedTime) VALUES (?, ?, ?)"
  );
  const result = stmt.run(driverId, spotId, reservedTime);
  return Number(result.lastInsertRowid);
}

export function updateReservation(
  id: number,
  driverId: number,
  spotId: number,
  reservedTime: string
): void {
  const stmt = db.prepare(
    "UPDATE reservations SET driverId = ?, spotId = ?, reservedTime = ? WHERE id = ?"
  );
  stmt.run(driverId, spotId, reservedTime, id);
}

export function deleteReservation(id: number): void {
  const stmt = db.prepare("DELETE FROM reservations WHERE id = ?");
  stmt.run(id);
}

// Seed data
if (getAllReservations().length === 0) {
  insertReservation(1, 101, "2023-06-15T09:00:00Z");
  insertReservation(2, 102, "2023-06-15T10:30:00Z");
  insertReservation(3, 103, "2023-06-15T14:15:00Z");
  insertReservation(4, 104, "2023-06-15T16:45:00Z");
  insertReservation(5, 105, "2023-06-15T18:00:00Z");
}
"}

{"code":"import { useEffect, useState } from "react";

interface Booking {
  id: string;
  date: string;
  startTime: string;
  endTime: string;
  renterName: string;
}

export function BookingCalendar() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [renterName, setRenterName] = useState<string>('');

  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/bookings-api/bookings');
      if (!response.ok) {
        throw new Error(`Failed to fetch bookings: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleBookSlot = async (date: string, startTime: string, endTime: string) => {
    if (!renterName.trim()) {
      setError('Please enter your name to book a slot');
      return;
    }

    try {
      const response = await fetch('/api/bookings-api/bookings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          date,
          startTime,
          endTime,
          renterName
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to book slot: ${response.status} ${response.statusText}`);
      }

      await fetchBookings();
      setRenterName('');
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const getAvailableSlots = () => {
    // Mock available slots - in a real app, this would come from the backend
    const slots = [
      { startTime: '09:00', endTime: '11:00' },
      { startTime: '11:00', endTime: '13:00' },
      { startTime: '13:00', endTime: '15:00' },
      { startTime: '15:00', endTime: '17:00' },
      { startTime: '17:00', endTime: '19:00' },
    ];

    return slots;
  };

  const formatDate = (dateString: string) => {
    const options: Intl.DateTimeFormatOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    return new Date(dateString).toLocaleDateString(undefined, options);
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px' }}>
        <h2>Error</h2>
        <p>{error}</p>
      </div>
    );
  }

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Community Kitchen Booking</h1>
      <p>Available time slots for booking:</p>

      <div style={{ marginBottom: '20px' }}>
        <label htmlFor="date">Select Date: </label>
        <input
          type="date"
          id="date"
          value={selectedDate}
          onChange={(e) => setSelectedDate(e.target.value)}
          style={{ width: '100%', padding: '8px', marginTop: '5px' }}
        />
      </div>

      <div style={{ marginBottom: '20px' }}>
        <label htmlFor="renterName">Your Name: </label>
        <input
          type="text"
          id="renterName"
          value={renterName}
          onChange={(e) => setRenterName(e.target.value)}
          style={{ width: '100%', padding: '8px', marginTop: '5px' }}
        />
      </div>

      <h2>Available Slots</h2>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
        {getAvailableSlots().map((slot, index) => {
          const isBooked = bookings.some(booking => 
            booking.date === selectedDate && 
            booking.startTime === slot.startTime
          );

          return (
            <div 
              key={index} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '10px', 
                width: '150px', 
                backgroundColor: isBooked ? '#f0f0f0' : '#fff'
              }}
            >
              <div style={{ fontWeight: 'bold' }}>{slot.startTime} - {slot.endTime}</div>
              {!isBooked && (
                <button 
                  onClick={() => handleBookSlot(selectedDate, slot.startTime, slot.endTime)}
                  style={{ 
                    marginTop: '10px', 
                    width: '100%', 
                    padding: '5px', 
                    backgroundColor: '#007bff', 
                    color: 'white', 
                    border: 'none', 
                    borderRadius: '4px' 
                  }}
                >
                  Book Slot
                </button>
              )}
              {isBooked && (
                <div style={{ marginTop: '10px', color: '#666' }}>Booked</div>
              )}
            </div>
          );
        })}
      </div>

      <h2>My Bookings</h2>
      {bookings.length === 0 ? (
        <p>No bookings found.</p>
      ) : (
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ borderBottom: '1px solid #ccc' }}>
              <th style={{ textAlign: 'left', padding: '8px' }}>Date</th>
              <th style={{ textAlign: 'left', padding: '8px' }}>Time</th>
              <th style={{ textAlign: 'left', padding: '8px' }}>Renter</th>
            </tr>
          </thead>
          <tbody>
            {bookings.map(booking => (
              <tr key={booking.id} style={{ borderBottom: '1px solid #eee' }}>
                <td style={{ padding: '8px' }}>{formatDate(booking.date)}</td>
                <td style={{ padding: '8px' }}>{booking.startTime} - {booking.endTime}</td>
                <td style={{ padding: '8px' }}>{booking.renterName}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}
"}

