{"code":"import { useEffect, useState } from "react";

interface FileItem {
  id: string;
  name: string;
  size: number;
  lastModified: string;
}

export function FileBrowser() {
  const [files, setFiles] = useState<FileItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newFileName, setNewFileName] = useState("");
  const [newFileSize, setNewFileSize] = useState("");

  useEffect(() => {
    fetchFiles();
  }, []);

  const fetchFiles = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/sync-collaboration-api/files');
      if (!response.ok) {
        throw new Error(`Failed to fetch files: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setFiles(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleCreateFile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newFileName.trim() || !newFileSize) return;

    try {
      const response = await fetch('/api/sync-collaboration-api/files', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: newFileName,
          size: Number(newFileSize),
        }),
      });

      if (!response.ok) {
        throw new Error(`Failed to create file: ${response.status} ${response.statusText}`);
      }

      setNewFileName("");
      setNewFileSize("");
      await fetchFiles();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteFile = async (id: string) => {
    try {
      const response = await fetch(`/api/sync-collaboration-api/files/${id}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error(`Failed to delete file: ${response.status} ${response.statusText}`);
      }

      await fetchFiles();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>File Browser</h1>

      <form onSubmit={handleCreateFile} style={{ marginBottom: '20px', display: 'flex', flexDirection: 'column', gap: '10px' }}>
        <input
          type="text"
          placeholder="File Name"
          value={newFileName}
          onChange={(e) => setNewFileName(e.target.value)}
          style={{ padding: '8px', borderRadius: '4px', border: '1px solid #ccc', width: '100%' }}
        />
        <input
          type="number"
          placeholder="Size (bytes)"
          value={newFileSize}
          onChange={(e) => setNewFileSize(e.target.value)}
          style={{ padding: '8px', borderRadius: '4px', border: '1px solid #ccc', width: '100%' }}
        />
        <button type="submit" style={{ padding: '8px', borderRadius: '4px', backgroundColor: '#007bff', color: 'white', border: 'none', cursor: 'pointer' }}>
          Create File
        </button>
      </form>

      {files.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No files found.</p>
      ) : (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px' }}>
          {files.map((file) => (
            <div key={file.id} style={{
              border: '1px solid #ccc',
              borderRadius: '8px',
              padding: '15px',
              minWidth: '200px',
              maxWidth: '300px',
              backgroundColor: '#f9f9f9'
            }}>
              <h3 style={{ margin: '0 0 10px 0' }}>{file.name}</h3>
              <p style={{ margin: '5px 0' }}>Size: {file.size} bytes</p>
              <p style={{ margin: '5px 0' }}>Last Modified: {new Date(file.lastModified).toLocaleString()}</p>
              <button 
                onClick={() => handleDeleteFile(file.id)}
                style={{
                  marginTop: '10px',
                  padding: '6px 10px',
                  borderRadius: '4px',
                  backgroundColor: '#dc3545',
                  color: 'white',
                  border: 'none',
                  cursor: 'pointer'
                }}
              >
                Delete
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./coop-grocery.db");

interface ShiftRow {
  member_id: number;
  shift_slot_id: number;
  claimed_at: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS shifts (
    member_id INTEGER NOT NULL,
    shift_slot_id INTEGER NOT NULL,
    claimed_at TEXT NOT NULL,
    PRIMARY KEY (member_id, shift_slot_id)
  )
`;

db.exec(createTableSql);

export function getAllShifts(): ShiftRow[] {
  const stmt = db.prepare(`SELECT * FROM shifts`);
  return stmt.all() as unknown as ShiftRow[];
}

export function getShiftById(memberId: number, shiftSlotId: number): ShiftRow | undefined {
  const stmt = db.prepare(`SELECT * FROM shifts WHERE member_id = ? AND shift_slot_id = ?`);
  return stmt.get(memberId, shiftSlotId) as unknown as ShiftRow | undefined;
}

export function insertShift(memberId: number, shiftSlotId: number, claimedAt: string): number {
  const stmt = db.prepare(
    `INSERT INTO shifts (member_id, shift_slot_id, claimed_at) VALUES (?, ?, ?)`
  );
  const result = stmt.run(memberId, shiftSlotId, claimedAt);
  return Number(result.lastInsertRowid);
}

export function updateShift(memberId: number, shiftSlotId: number, claimedAt: string): number {
  const stmt = db.prepare(
    `UPDATE shifts SET claimed_at = ? WHERE member_id = ? AND shift_slot_id = ?`
  );
  const result = stmt.run(claimedAt, memberId, shiftSlotId);
  return Number(result.changes);
}

export function deleteShift(memberId: number, shiftSlotId: number): number {
  const stmt = db.prepare(`DELETE FROM shifts WHERE member_id = ? AND shift_slot_id = ?`);
  const result = stmt.run(memberId, shiftSlotId);
  return Number(result.changes);
}

// Sample data insertion
if (getAllShifts().length === 0) {
  insertShift(1, 101, "2023-05-15T08:00:00Z");
  insertShift(2, 102, "2023-05-15T09:00:00Z");
  insertShift(3, 103, "2023-05-15T10:00:00Z");
  insertShift(4, 104, "2023-05-15T11:00:00Z");
  insertShift(5, 105, "2023-05-15T12:00:00Z");
}
"}

