{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./shifts.db");

interface ShiftRow {
  id: number;
  parentId: number;
  shiftDate: string;
  role: "supervisor" | "parent";
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS shifts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    parentId INTEGER NOT NULL,
    shiftDate TEXT NOT NULL,
    role TEXT NOT NULL CHECK(role IN ('supervisor', 'parent'))
  );
`;

db.exec(createTableSql);

export function getAllShifts(): ShiftRow[] {
  const stmt = db.prepare("SELECT * FROM shifts");
  return stmt.all() as unknown as ShiftRow[];
}

export function getShiftById(id: number): ShiftRow | undefined {
  const stmt = db.prepare("SELECT * FROM shifts WHERE id = ?");
  return stmt.get(id) as unknown as ShiftRow | undefined;
}

export function insertShift(parentId: number, shiftDate: string, role: "supervisor" | "parent"): number {
  const stmt = db.prepare(
    "INSERT INTO shifts (parentId, shiftDate, role) VALUES (?, ?, ?)"
  );
  const result = stmt.run(parentId, shiftDate, role);
  return Number(result.lastInsertRowid);
}

export function updateShift(id: number, parentId: number, shiftDate: string, role: "supervisor" | "parent"): void {
  const stmt = db.prepare(
    "UPDATE shifts SET parentId = ?, shiftDate = ?, role = ? WHERE id = ?"
  );
  stmt.run(parentId, shiftDate, role, id);
}

export function deleteShift(id: number): void {
  const stmt = db.prepare("DELETE FROM shifts WHERE id = ?");
  stmt.run(id);
}

// Insert sample data if table is empty
if (getAllShifts().length === 0) {
  insertShift(1, "2023-06-15", "supervisor");
  insertShift(2, "2023-06-16", "parent");
  insertShift(3, "2023-06-17", "supervisor");
  insertShift(4, "2023-06-18", "parent");
  insertShift(5, "2023-06-19", "supervisor");
}
