{"code":"import { Router, type Request, type Response } from "express";
import { db, deleteHabit, getAllHabits, getHabitById, insertHabit, updateHabit } from "../db/habits-table";

export const router = Router();

// Get all habits
router.get("/", (req: Request, res: Response) => {
  try {
    const habits = getAllHabits();
    res.json(habits);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch habits" });
  }
});

// Get a habit by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid habit ID" });
    }

    const habit = getHabitById(id);
    if (!habit) {
      return res.status(404).json({ error: "Habit not found" });
    }

    res.json(habit);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch habit" });
  }
});

// Create a new habit
router.post("/", (req: Request, res: Response) => {
  try {
    const { userId, habitName, date } = req.body;

    if (!userId || !habitName || !date) {
      return res.status(400).json({ error: "Missing required fields: userId, habitName, date" });
    }

    const id = insertHabit(userId, habitName, date);
    res.status(201).json({ id, userId, habitName, date });
  } catch (error) {
    res.status(500).json({ error: "Failed to create habit" });
  }
});

// Update a habit
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { userId, habitName, date } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid habit ID" });
    }

    if (!userId || !habitName || !date) {
      return res.status(400).json({ error: "Missing required fields: userId, habitName, date" });
    }

    const existingHabit = getHabitById(id);
    if (!existingHabit) {
      return res.status(404).json({ error: "Habit not found" });
    }

    updateHabit(id, userId, habitName, date);
    res.json({ id, userId, habitName, date });
  } catch (error) {
    res.status(500).json({ error: "Failed to update habit" });
  }
});

// Delete a habit
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid habit ID" });
    }

    const existingHabit = getHabitById(id);
    if (!existingHabit) {
      return res.status(404).json({ error: "Habit not found" });
    }

    deleteHabit(id);
    res.json({ message: "Habit deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete habit" });
  }
});
"}

{"code":"import { useEffect, useState } from "react";

interface Plot {
  id: number;
  location: string;
  size: string;
  status: string;
}

interface Reservation {
  id: number;
  plotId: number;
  reservedBy: string;
  startDate: string;
  endDate: string;
}

export function CoordinatorReassignmentPanel() {
  const [plots, setPlots] = useState<Plot[]>([]);
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedReservation, setSelectedReservation] = useState<number | null>(null);
  const [newPlotId, setNewPlotId] = useState<number | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [plotsResponse, reservationsResponse] = await Promise.all([
          fetch("/api/garden-api/plots"),
          fetch("/api/garden-api/reservations")
        ]);

        if (!plotsResponse.ok || !reservationsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const plotsData = await plotsResponse.json();
        const reservationsData = await reservationsResponse.json();

        setPlots(plotsData);
        setReservations(reservationsData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleReassign = async (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedReservation === null || newPlotId === null) return;

    try {
      const response = await fetch(`/api/garden-api/reservations/${selectedReservation}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ plotId: newPlotId })
      });

      if (!response.ok) {
        throw new Error("Failed to reassign plot");
      }

      // Refresh data after successful reassignment
      const [plotsResponse, reservationsResponse] = await Promise.all([
        fetch("/api/garden-api/plots"),
        fetch("/api/garden-api/reservations")
      ]);

      if (!plotsResponse.ok || !reservationsResponse.ok) {
        throw new Error("Failed to refresh data");
      }

      const plotsData = await plotsResponse.json();
      const reservationsData = await reservationsResponse.json();

      setPlots(plotsData);
      setReservations(reservationsData);
      setSelectedReservation(null);
      setNewPlotId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  const availablePlots = plots.filter(plot => plot.status !== "reserved");

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Coordinator Reassignment Panel</h1>

      <div style={{ marginBottom: "20px" }}>
        <h2>Current Reservations</h2>
        {reservations.length === 0 ? (
          <p>No reservations found.</p>
        ) : (
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ borderBottom: "1px solid #ccc" }}>
                <th style={{ textAlign: "left", padding: "8px" }}>Reserved By</th>
                <th style={{ textAlign: "left", padding: "8px" }}>Plot Location</th>
                <th style={{ textAlign: "left", padding: "8px" }}>Start Date</th>
                <th style={{ textAlign: "left", padding: "8px" }}>End Date</th>
              </tr>
            </thead>
            <tbody>
              {reservations.map(reservation => {
                const plot = plots.find(p => p.id === reservation.plotId);
                return (
                  <tr key={reservation.id} style={{ borderBottom: "1px solid #eee" }}>
                    <td style={{ padding: "8px" }}>{reservation.reservedBy}</td>
                    <td style={{ padding: "8px" }}>{plot?.location || "Unknown"}</td>
                    <td style={{ padding: "8px" }}>{reservation.startDate}</td>
                    <td style={{ padding: "8px" }}>{reservation.endDate}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>

      <div style={{ marginTop: "30px" }}>
        <h2>Reassign Plot</h2>
        <form onSubmit={handleReassign}>
          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="reservationSelect" style={{ display: "block", marginBottom: "5px" }}>
              Select Reservation:
            </label>
            <select
              id="reservationSelect"
              value={selectedReservation ?? ""}
              onChange={(e) => setSelectedReservation(Number(e.target.value))}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            >
