{"code":"import { useEffect, useState } from "react";

interface Route {
  id: number;
  name: string;
  description: string;
  setter: string;
  status: 'active' | 'retired';
}

export function RouteLogBoard() {
  const [routes, setRoutes] = useState<Route[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newRoute, setNewRoute] = useState({
    name: '',
    description: '',
    setter: '',
  });

  useEffect(() => {
    fetchRoutes();
  }, []);

  const fetchRoutes = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/routes-api/routes');
      if (!response.ok) {
        throw new Error(`Failed to fetch routes: ${response.status}`);
      }
      const data = await response.json();
      setRoutes(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleCreateRoute = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch('/api/routes-api/routes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newRoute),
      });
      if (!response.ok) {
        throw new Error(`Failed to create route: ${response.status}`);
      }
      setNewRoute({ name: '', description: '', setter: '' });
      fetchRoutes();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleRetireRoute = async (id: number) => {
    try {
      const response = await fetch(`/api/routes-api/routes/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'retired' }),
      });
      if (!response.ok) {
        throw new Error(`Failed to retire route: ${response.status}`);
      }
      fetchRoutes();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteRoute = async (id: number) => {
    try {
      const response = await fetch(`/api/routes-api/routes/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error(`Failed to delete route: ${response.status}`);
      }
      fetchRoutes();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Route Log Board</h1>

      <div style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h2>Create New Route</h2>
        <form onSubmit={handleCreateRoute}>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              placeholder="Route Name"
              value={newRoute.name}
              onChange={(e) => setNewRoute({...newRoute, name: e.target.value})}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              placeholder="Description"
              value={newRoute.description}
              onChange={(e) => setNewRoute({...newRoute, description: e.target.value})}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              placeholder="Setter Name"
              value={newRoute.setter}
              onChange={(e) => setNewRoute({...newRoute, setter: e.target.value})}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
              required
            />
          </div>
          <button type="submit" style={{ padding: '10px 20px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>
            Add Route
          </button>
        </form>
      </div>

      <h2>Current Routes</h2>
      {routes.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No routes found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {routes.map(route => (
            <div key={route.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <h3>{route.name}</h3>
                  <p>{route.description}</p>
                  <p><strong>Setter:</strong> {route.setter}</p>
                  <p><strong>Status:</strong> {route.status}</p>
                </div>
                <div style={{ display: 'flex', gap: '10px' }}>
                  {route.status === 'active' && (
                    <button 
                      onClick={() => handleRetireRoute(route.id)}
                      style={{ padding: '6px 12px', backgroundColor: '#ffc107', color: 'black', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                    >
                      Retire
                    </button>
                  )}
                  <button 
                    onClick={() => handleDeleteRoute(route.id)}
                    style={{ padding: '6px 12px', backgroundColor: '#dc3545', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteMachineReport,
  getAllMachineReports,
  getMachineReportById,
  insertMachineReport,
  updateMachineReport
} from "../db/machine-reports-table";

export const router = Router();

// Get all machine reports
router.get("/", (req: Request, res: Response) => {
  try {
    const reports = getAllMachineReports();
    res.json(reports);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch machine reports" });
  }
});

// Get a specific machine report by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid report ID" });
    }

    const report = getMachineReportById(id);
    if (!report) {
      return res.status(404).json({ error: "Machine report not found" });
    }

    res.json(report);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch machine report" });
  }
});

// Create a new machine report
router.post("/", (req: Request, res: Response) => {
  try {
    const { memberId, machineId, reportText } = req.body;

    if (!memberId || !machineId || !reportText) {
      return res.status(400).json({ error: "Missing required fields: memberId, machineId, reportText" });
    }

    const newId = insertMachineReport(memberId, machineId, reportText);
    const createdReport = getMachineReportById(newId);

    if (!createdReport) {
      return res.status(500).json({ error: "Failed to create machine report" });
    }

    res.status(201).json(createdReport);
  } catch (error) {
    res.status(500).json({ error: "Failed to create machine report" });
  }
});

// Update an existing machine report
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { memberId, machineId, reportText } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid report ID" });
    }

    if (!memberId || !machineId || !reportText) {
      return res.status(400).json({ error: "Missing required fields: memberId, machineId, reportText" });
    }

    const updatedId = updateMachineReport(id, memberId, machineId, reportText);
    const updatedReport = getMachineReportById(updatedId);

    if (!updatedReport) {
      return res.status(404).json({ error: "Machine report not found" });
    }

    res.json(updatedReport);
  } catch (error) {
    res.status(500).json({ error: "Failed to update machine report" });
  }
});

// Delete a machine report
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid report ID" });
    }

    const deletedId = deleteMachineReport(id);
    if (deletedId === 0) {
      return res.status(404).json({ error: "Machine report not found" });
    }

    res.json({ message: "Machine report deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete machine report" });
  }
});
"}

