{"code":"import { useEffect, useState } from "react";

interface Booking {
  id: string;
  roomId: string;
  roomName: string;
  startTime: string;
  endTime: string;
  memberName: string;
}

interface Room {
  id: string;
  name: string;
  capacity: number;
}

export function RoomBookingCalendar() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [rooms, setRooms] = useState<Room[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newBooking, setNewBooking] = useState({
    roomId: "",
    startTime: "",
    endTime: "",
  });

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [bookingsRes, roomsRes] = await Promise.all([
          fetch("/api/bookings-api/"),
          fetch("/api/bookings-api/available-rooms"),
        ]);

        if (!bookingsRes.ok || !roomsRes.ok) {
          throw new Error("Failed to fetch data");
        }

        const bookingsData = await bookingsRes.json();
        const roomsData = await roomsRes.json();

        setBookings(bookingsData);
        setRooms(roomsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setNewBooking({
      ...newBooking,
      [name]: value,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/bookings-api/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(newBooking),
      });

      if (!response.ok) {
        throw new Error("Failed to create booking");
      }

      // Refresh data
      const [bookingsRes, roomsRes] = await Promise.all([
        fetch("/api/bookings-api/"),
        fetch("/api/bookings-api/available-rooms"),
      ]);

      if (!bookingsRes.ok || !roomsRes.ok) {
        throw new Error("Failed to refresh data");
      }

      const bookingsData = await bookingsRes.json();
      const roomsData = await roomsRes.json();

      setBookings(bookingsData);
      setRooms(roomsData);

      // Reset form
      setNewBooking({
        roomId: "",
        startTime: "",
        endTime: "",
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Co-Working Room Booking</h1>

      <h2>Available Rooms</h2>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
        {rooms.map((room) => (
          <div key={room.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "10px", width: "200px" }}>
            <h3>{room.name}</h3>
            <p>Capacity: {room.capacity}</p>
          </div>
        ))}
      </div>

      <h2>Book a Room</h2>
      <form onSubmit={handleSubmit} style={{ marginBottom: "20px" }}>
        <div style={{ marginBottom: "10px" }}>
          <label htmlFor="roomId">Room:</label>
          <select
            id="roomId"
            name="roomId"
            value={newBooking.roomId}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            required
          >
            <option value="">Select a room</option>
            {rooms.map((room) => (
              <option key={room.id} value={room.id}>
                {room.name}
              </option>
            ))}
          </select>
        </div>

        <div style={{ marginBottom: "10px" }}>
          <label htmlFor="startTime">Start Time:</label>
          <input
            type="datetime-local"
            id="startTime"
            name="startTime"
            value={newBooking.startTime}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            required
          />
        </div>

        <div style={{ marginBottom: "10px" }}>
          <label htmlFor="endTime">End Time:</label>
          <input
            type="datetime-local"
            id="endTime"
            name="endTime"
            value={newBooking.endTime}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            required
          />
        </div>

        <button type="submit" style={{ backgroundColor: "#007bff", color: "white", border: "none", padding: "10px 15px", borderRadius: "4px", cursor: "pointer" }}>
          Book Room
        </button>
      </form>

      <h2>Current Bookings</h2>
      {bookings.length === 0 ? (
        <p style={{ textAlign: "center" }}>No current bookings.</p>
      ) : (
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr style={{ borderBottom: "1px solid #ccc" }}>
              <th style={{ padding: "8px", textAlign: "left" }}>Room</th>
              <th style={{ padding: "8px", textAlign: "left" }}>Start Time</th>
              <th style={{ padding: "8px", textAlign: "left" }}>End Time</th>
              <th style={{ padding: "8px", textAlign: "left" }}>Member</th>
            </tr>
          </thead>
          <tbody>
            {bookings.map((booking) => (
              <tr key={booking.id} style={{ borderBottom: "1px solid #ccc" }}>
                <td style={{ padding: "8px" }}>{booking.roomName}</td>
                <td style={{ padding: "8px" }}>{new Date(booking.startTime).toLocaleString()}</td>
                <td style={{ padding: "8px" }}>{new Date(booking.endTime).toLocaleString()}</td>
                <td style={{ padding: "8px" }}>{booking.memberName}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

export function QuestionTimer() {
  const [timeLeft, setTimeLeft] = useState<number>(10);
  const [isActive, setIsActive] = useState<boolean>(true);

  useEffect(() => {
    let interval: NodeJS.Timeout | null = null;

    if (isActive && timeLeft > 0) {
      interval = setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      // Handle timer completion
      console.log("Time's up!");
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isActive, timeLeft]);

  const handleReset = () => {
    setTimeLeft(10);
    setIsActive(true);
  };

  const handlePause = () => {
    setIsActive(false);
  };

  const handleStart = () => {
    setIsActive(true);
  };

  return (
    <div style={{
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      justifyContent: "center",
      minHeight: "100vh",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      backgroundColor: "#f5f5f5",
      padding: "20px",
    }}>
      <div style={{
        backgroundColor: "white",
        borderRadius: "12px",
        padding: "30px",
        boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
        textAlign: "center",
        maxWidth: "400px",
        width: "100%",
      }}>
        <h1 style={{
          color: "#333",
          marginBottom: "20px",
          fontSize: "24px",
        }}>
          Next Question In:
        </h1>

        <div style={{
          fontSize: "64px",
          fontWeight: "bold",
          color: timeLeft <= 3 ? "#ff4757" : "#2ed573",
          marginBottom: "30px",
          fontFamily: "monospace",
        }}>
          {timeLeft}
        </div>

        <div style={{
          display: "flex",
          gap: "10px",
          justifyContent: "center",
          flexWrap: "wrap",
        }}>
          <button 
            onClick={handleStart}
            disabled={isActive}
            style={{
              backgroundColor: "#2ed573",
              color: "white",
              border: "none",
              borderRadius: "8px",
              padding: "10px 20px",
              cursor: isActive ? "default" : "pointer",
              fontSize: "16px",
              fontWeight: "500",
              transition: "background-color 0.2s",
            }}
          >
            Start
          </button>

          <button 
            onClick={handlePause}
            disabled={!isActive}
            style={{
              backgroundColor: "#ffa502",
              color: "white",
              border: "none",
              borderRadius: "8px",
              padding: "10px 20px",
              cursor: !isActive ? "default" : "pointer",
              fontSize: "16px",
              fontWeight: "500",
              transition: "background-color 0.2s",
            }}
          >
            Pause
          </button>

          <button 
