{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "./choir-attendance.db"
);

interface AttendanceRecord {
  id: number;
  member_id: number;
  date: string;
  presence_status: "present" | "absent" | "late";
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS attendance_records (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    member_id INTEGER NOT NULL,
    date TEXT NOT NULL,
    presence_status TEXT NOT NULL CHECK(presence_status IN ('present', 'absent', 'late'))
  )
`;

db.exec(createTableSql);

export function getAllAttendanceRecords(): AttendanceRecord[] {
  const stmt = db.prepare(
    "SELECT * FROM attendance_records ORDER BY date DESC"
  );
  return stmt.all() as unknown as AttendanceRecord[];
}

export function getAttendanceRecordById(id: number): AttendanceRecord | undefined {
  const stmt = db.prepare(
    "SELECT * FROM attendance_records WHERE id = ?"
  );
  return stmt.get(id) as unknown as AttendanceRecord | undefined;
}

export function insertAttendanceRecord(
  member_id: number,
  date: string,
  presence_status: "present" | "absent" | "late"
): number {
  const stmt = db.prepare(
    "INSERT INTO attendance_records (member_id, date, presence_status) VALUES (?, ?, ?)"
  );
  const result = stmt.run(member_id, date, presence_status);
  return Number(result.lastInsertRowid);
}

export function updateAttendanceRecord(
  id: number,
  member_id: number,
  date: string,
  presence_status: "present" | "absent" | "late"
): void {
  const stmt = db.prepare(
    "UPDATE attendance_records SET member_id = ?, date = ?, presence_status = ? WHERE id = ?"
  );
  stmt.run(member_id, date, presence_status, id);
}

export function deleteAttendanceRecord(id: number): void {
  const stmt = db.prepare(
    "DELETE FROM attendance_records WHERE id = ?"
  );
  stmt.run(id);
}

// Seed data
if (getAllAttendanceRecords().length === 0) {
  insertAttendanceRecord(1, "2023-05-01", "present");
  insertAttendanceRecord(2, "2023-05-01", "absent");
  insertAttendanceRecord(3, "2023-05-01", "late");
  insertAttendanceRecord(4, "2023-05-02", "present");
  insertAttendanceRecord(5, "2023-05-02", "present");
}
"}

