{"code":"import { useEffect, useState } from "react";

interface Book {
  id: number;
  title: string;
  author: string;
  isbn: string;
}

interface Checkout {
  id: number;
  bookId: number;
  studentId: number;
  checkoutDate: string;
  dueDate: string;
}

export function CheckoutForm() {
  const [books, setBooks] = useState<Book[]>([]);
  const [checkouts, setCheckouts] = useState<Checkout[]>([]);
  const [selectedBookId, setSelectedBookId] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [booksResponse, checkoutsResponse] = await Promise.all([
          fetch('/api/checkouts-api/'),
          fetch('/api/checkouts-api'),
        ]);

        if (!booksResponse.ok || !checkoutsResponse.ok) {
          throw new Error('Failed to fetch data');
        }

        const booksData = await booksResponse.json();
        const checkoutsData = await checkoutsResponse.json();

        setBooks(booksData);
        setCheckouts(checkoutsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleCheckout = async () => {
    if (selectedBookId === null) return;

    try {
      const response = await fetch('/api/checkouts-api/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          bookId: selectedBookId,
          studentId: 1, // Assuming student ID is 1 for now
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to checkout book');
      }

      // Refresh data after successful checkout
      const [booksResponse, checkoutsResponse] = await Promise.all([
        fetch('/api/checkouts-api/'),
        fetch('/api/checkouts-api'),
      ]);

      if (!booksResponse.ok || !checkoutsResponse.ok) {
        throw new Error('Failed to refresh data');
      }

      const booksData = await booksResponse.json();
      const checkoutsData = await checkoutsResponse.json();

      setBooks(booksData);
      setCheckouts(checkoutsData);
      setSelectedBookId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Book Checkout</h1>

      <div style={{ marginBottom: '20px' }}>
        <h2>Available Books</h2>
        {books.length === 0 ? (
          <p>No books available.</p>
        ) : (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
            {books.map(book => (
              <div 
                key={book.id} 
                style={{ 
                  border: '1px solid #ccc', 
                  borderRadius: '8px', 
                  padding: '10px', 
                  width: '200px', 
                  cursor: 'pointer',
                  backgroundColor: selectedBookId === book.id ? '#e0f7fa' : 'white'
                }}
                onClick={() => setSelectedBookId(book.id)}
              >
                <h3>{book.title}</h3>
                <p>by {book.author}</p>
                <p>ISBN: {book.isbn}</p>
              </div>
            ))}
          </div>
        )}
      </div>

      <div style={{ marginBottom: '20px' }}>
        <h2>Current Checkouts</h2>
        {checkouts.length === 0 ? (
          <p>No active checkouts.</p>
        ) : (
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: '1px solid #ccc' }}>
                <th style={{ textAlign: 'left', padding: '8px' }}>Book Title</th>
                <th style={{ textAlign: 'left', padding: '8px' }}>Checkout Date</th>
                <th style={{ textAlign: 'left', padding: '8px' }}>Due Date</th>
                <th style={{ textAlign: 'left', padding: '8px' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {checkouts.map(checkout => {
                const book = books.find(b => b.id === checkout.bookId);
                return book ? (
                  <tr key={checkout.id} style={{ borderBottom: '1px solid #eee' }}>
                    <td style={{ padding: '8px' }}>{book.title}</td>
                    <td style={{ padding: '8px' }}>{new Date(checkout.checkoutDate).toLocaleDateString()}</td>
                    <td style={{ padding: '8px' }}>{new Date(checkout.dueDate).toLocaleDateString()}</td>
                    <td style={{ padding: '8px' }}>
                      <button 
                        onClick={async () => {
                          const response = await fetch(`/api/checkouts-api/${checkout.id}`, {
                            method: 'PUT',
                            headers: {
                              'Content-Type': 'application/json',
                            },
                            body: JSON.stringify({ returned: true }),
                          });

                          if (!response.ok) {
                            throw new Error('Failed to return book');
                          }

                          // Refresh data after successful return
                          const [booksResponse, checkoutsResponse] = await Promise.all([
                            fetch('/api/checkouts-api/'),
                            fetch('/api/checkouts-api'),
                          ]);

                          if (!booksResponse.ok || !checkoutsResponse.ok) {
                            throw new Error('Failed to refresh data');
                          }

                          const booksData = await booksResponse.json();
                          const checkoutsData = await checkoutsResponse.json();

                          setBooks(booksData);
                          setCheckouts(checkoutsData);
                        }}
                        style={{ 
                          backgroundColor: '#4CAF50', 
                          color: 'white', 
                          border: 'none', 
                          padding: '5px 10px', 
                          borderRadius: '4px', 
                          cursor: 'pointer' 
                        }}
                      >
                        Return
                      </button>
                    </td>
                  </tr>
                ) : null;
              })}
            </tbody>
          </table>
        )}
      </div>

      <div style={{ textAlign: 'center' }}>
        <button 
          onClick={handleCheckout}
          disabled={selectedBookId === null}
          style={{ 
            backgroundColor: selectedBookId !== null ? '#2196F3' : '#ccc', 
            color: 'white', 
            border: 'none', 
            padding: '10px 20px', 
            borderRadius: '4px', 
            cursor: selectedBookId !== null ? 'pointer' : 'default' 
          }}
        >
          Checkout Selected Book
        </button>
      </div>
    </div>
  );
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as machineTrackerApiRouter } from "../routes/machine-tracker-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check fix actions, ignore all other requests
  if (!(req.method === "POST" && req.path === "/api/machines/:id/fix")) {
    next();
    return;
  }

  // Check if user is maintenance staff
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  const expectedToken = createHmac("sha256", secret).update("maintenance_staff").digest("hex");

  try {
    const tokenBuffer = Buffer.from(token, "utf8");
    const expectedBuffer = Buffer.from(expectedToken, "utf8");

    if (tokenBuffer.length !== expectedBuffer.length) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    const isEqual = timingSafeEqual(tokenBuffer, expectedBuffer);

    if (!isEqual) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  next();
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("helpdesk.db");

interface Ticket {
  id: number;
  title: string;
  description: string;
  channel: string;
  status: string;
  created_at: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS tickets (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT NOT NULL,
    channel TEXT NOT NULL,
    status TEXT NOT NULL,
    created_at TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllTickets(): Ticket[] {
  const stmt = db.prepare("SELECT * FROM tickets");
  return stmt.all() as unknown as Ticket[];
}

export function getTicketById(id: number): Ticket | undefined {
  const stmt = db.prepare("SELECT * FROM tickets WHERE id = ?");
  return stmt.get(id) as unknown as Ticket | undefined;
}

export function createTicket(ticket: Omit<Ticket, "id" | "created_at">): number {
  const stmt = db.prepare(
    "INSERT INTO tickets (title, description, channel, status, created_at) VALUES (?, ?, ?, ?, ?)"
  );
  const result = stmt.run(
    ticket.title,
    ticket.description,
    ticket.channel,
    ticket.status,
    new Date().toISOString()
  );
  return Number(result.lastInsertRowid);
}

export function updateTicket(id: number, ticket: Partial<Omit<Ticket, "id" | "created_at">>): boolean {
  const fields = [];
  const values = [];

  if (ticket.title !== undefined) {
    fields.push("title = ?");
    values.push(ticket.title);
  }

  if (ticket.description !== undefined) {
    fields.push("description = ?");
    values.push(ticket.description);
  }

  if (ticket.channel !== undefined) {
    fields.push("channel = ?");
    values.push(ticket.channel);
  }

  if (ticket.status !== undefined) {
    fields.push("status = ?");
    values.push(ticket.status);
  }

  if (fields.length === 0) {
    return false;
  }

  values.push(id);

  const stmt = db.prepare(`UPDATE tickets SET ${fields.join(", ")} WHERE id = ?`);
  const result = stmt.run(...values);

  return result.changes > 0;
}

export function deleteTicket(id: number): boolean {
  const stmt = db.prepare("DELETE FROM tickets WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

// Seed data
if (getAllTickets().length === 0) {
  createTicket({
    title: "Login Issue",
    description: "User unable to login to the system",
    channel: "email",
    status: "open"
  });

  createTicket({
    title: "Payment Failure",
    description: "Credit card payment not processing",
    channel: "phone",
    status: "in_progress"
  });

  createTicket({
    title: "Feature Request",
    description: "Request for new dashboard feature",
    channel: "web_form",
    status: "closed"
  });

  createTicket({
    title: "Account Lockout",
    description: "Multiple failed login attempts",
    channel: "chat",
    status: "open"
  });

  createTicket({
    title: "Data Export Error",
    description: "Exporting reports fails with timeout",
    channel: "email",
    status: "in_progress"
  });
}
"}

