{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteBooking,
  getAllBookings,
  getBookingById,
  insertBooking,
  updateBooking
} from "../db/bookings-table";

export const router = Router();

// Get all bookings
router.get("/", (req: Request, res: Response) => {
  try {
    const bookings = getAllBookings();
    res.json(bookings);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch bookings" });
  }
});

// Get a booking by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const booking = getBookingById(id);
    if (!booking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    res.json(booking);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch booking" });
  }
});

// Create a new booking
router.post("/", (req: Request, res: Response) => {
  try {
    const { memberId, deskId, date } = req.body;

    if (!memberId || !deskId || !date) {
      return res.status(400).json({ error: "Member ID, desk ID, and date are required" });
    }

    const id = insertBooking(memberId, deskId, date);
    const newBooking = getBookingById(id);

    if (!newBooking) {
      return res.status(500).json({ error: "Failed to create booking" });
    }

    res.status(201).json(newBooking);
  } catch (error) {
    res.status(500).json({ error: "Failed to create booking" });
  }
});

// Update a booking
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { memberId, deskId, date } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    if (!memberId || !deskId || !date) {
      return res.status(400).json({ error: "Member ID, desk ID, and date are required" });
    }

    const existingBooking = getBookingById(id);
    if (!existingBooking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    updateBooking(id, memberId, deskId, date);
    const updatedBooking = getBookingById(id);

    if (!updatedBooking) {
      return res.status(500).json({ error: "Failed to update booking" });
    }

    res.json(updatedBooking);
  } catch (error) {
    res.status(500).json({ error: "Failed to update booking" });
  }
});

// Delete a booking (supervisor-only access)
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const existingBooking = getBookingById(id);
    if (!existingBooking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    // In a real application, we would verify supervisor role here
    // For now, we'll just proceed with deletion
    deleteBooking(id);
    res.json({ message: "Booking deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete booking" });
  }
});
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./aquarium.db");

interface Feeding {
  id: number;
  aquariumId: number;
  fishSpecies: string;
  amountFed: number;
  timestamp: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS feedings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    aquariumId INTEGER NOT NULL,
    fishSpecies TEXT NOT NULL,
    amountFed REAL NOT NULL,
    timestamp TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllFeedings(): Feeding[] {
  const stmt = db.prepare("SELECT * FROM feedings");
  return stmt.all() as unknown as Feeding[];
}

export function getFeedingById(id: number): Feeding | undefined {
  const stmt = db.prepare("SELECT * FROM feedings WHERE id = ?");
  return stmt.get(id) as unknown as Feeding | undefined;
}

export function insertFeeding(
  aquariumId: number,
  fishSpecies: string,
  amountFed: number,
  timestamp: string
): number {
  const stmt = db.prepare(
    "INSERT INTO feedings (aquariumId, fishSpecies, amountFed, timestamp) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(aquariumId, fishSpecies, amountFed, timestamp);
  return Number(result.lastInsertRowid);
}

export function updateFeeding(
  id: number,
  aquariumId: number,
  fishSpecies: string,
  amountFed: number,
  timestamp: string
): void {
  const stmt = db.prepare(
    "UPDATE feedings SET aquariumId = ?, fishSpecies = ?, amountFed = ?, timestamp = ? WHERE id = ?"
  );
  stmt.run(aquariumId, fishSpecies, amountFed, timestamp, id);
}

export function deleteFeeding(id: number): void {
  const stmt = db.prepare("DELETE FROM feedings WHERE id = ?");
  stmt.run(id);
}

