      const method = editingId ? 'PUT' : 'POST';
      const url = editingId 
        ? `/api/wiki-page-service/${editingId}`
        : '/api/wiki-page-service/';

      const response = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title, content, ownerId }),
      });

      if (!response.ok) {
        throw new Error(`Failed to save page: ${response.status} ${response.statusText}`);
      }

      // Reset form and reload pages
      setTitle("");
      setContent("");
      setEditingId(null);
      fetchPages();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEdit = (page: Page) => {
    setTitle(page.title);
    setContent(page.content);
    setEditingId(page.id);
    setOwnerId(page.ownerId);
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/wiki-page-service/${id}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error(`Failed to delete page: ${response.status} ${response.statusText}`);
      }

      fetchPages();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const pageListStyle = {
    display: "flex",
    flexDirection: "column" as const,
    gap: "16px",
  };

  const cardStyle = {
    border: "1px solid #ccc",
    borderRadius: "8px",
    padding: "16px",
    maxWidth: "600px",
    margin: "0 auto",
  };

  const inputStyle = {
    width: "100%",
    padding: "8px",
    marginBottom: "12px",
    borderRadius: "4px",
    border: "1px solid #ddd",
  };

  const buttonStyle = {
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: "4px",
    padding: "8px 16px",
    cursor: "pointer",
    marginRight: "8px",
  };

  const deleteButtonStyle = {
    backgroundColor: "#dc3545",
    color: "white",
    border: "none",
    borderRadius: "4px",
    padding: "8px 16px",
    cursor: "pointer",
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1>Wiki Page Editor</h1>

      <form onSubmit={handleSubmit} style={cardStyle}>
        <input
          type="text"
          placeholder="Title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          style={inputStyle}
        />
        <textarea
          placeholder="Content"
          value={content}
          onChange={(e) => setContent(e.target.value)}
          style={{ ...inputStyle, height: "120px" }}
        />
        <input
          type="text"
          placeholder="Owner ID"
          value={ownerId}
          onChange={(e) => setOwnerId(e.target.value)}
          style={inputStyle}
        />
        <button type="submit" style={buttonStyle}>{editingId ? "Update Page" : "Create Page"}</button>
      </form>

      <div style={pageListStyle}>
        <h2>Existing Pages</h2>
        {pages.length === 0 ? (
          <p>No pages found.</p>
        ) : (
          pages.map((page) => (
            <div key={page.id} style={cardStyle}>
              <h3>{page.title}</h3>
              <p>{page.content}</p>
              <p><strong>Owner ID:</strong> {page.ownerId}</p>
              <div>
                <button onClick={() => handleEdit(page)} style={buttonStyle}>Edit</button>
                <button onClick={() => handleDelete(page.id)} style={deleteButtonStyle}>Delete</button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}
"}

