}

export function WebMediaClient() {
  const [mediaLibrary, setMediaLibrary] = useState<MediaItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchMediaLibrary();
  }, []);

  const fetchMediaLibrary = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/media-server/library");
      if (!response.ok) {
        throw new Error(`Failed to fetch media library: ${response.status}`);
      }
      const data = await response.json();
      setMediaLibrary(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleTranscode = async (id: string) => {
    try {
      const response = await fetch(`/api/media-server/transcode`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id }),
      });

      if (!response.ok) {
        throw new Error(`Failed to transcode media: ${response.status}`);
      }

      // Refresh the library after transcoding
      await fetchMediaLibrary();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
