                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "8px 12px",
                    cursor: "pointer",
                  }}
                >
                  Transcode
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
