interface TimesheetRow {
  id: number;
  associate_id: number;
  date: string;
  client: string;
  hours: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS timesheets (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    associate_id INTEGER NOT NULL,
    date TEXT NOT NULL,
    client TEXT NOT NULL,
    hours REAL NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllTimesheets(): TimesheetRow[] {
  const stmt = db.prepare("SELECT * FROM timesheets");
  return stmt.all() as unknown as TimesheetRow[];
}

export function getTimesheetById(id: number): TimesheetRow | undefined {
  const stmt = db.prepare("SELECT * FROM timesheets WHERE id = ?");
  return stmt.get(id) as unknown as TimesheetRow | undefined;
}

export function insertTimesheet(
  associateId: number,
  date: string,
  client: string,
  hours: number
): number {
  const stmt = db.prepare(
    "INSERT INTO timesheets (associate_id, date, client, hours) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(associateId, date, client, hours);
  return Number(result.lastInsertRowid);
}

export function updateTimesheet(
  id: number,
  associateId: number,
  date: string,
  client: string,
  hours: number
): void {
  const stmt = db.prepare(
