{"code":"import { useEffect, useState } from "react";

interface Reservation {
  id: string;
  date: string;
  time: string;
  guestName: string;
  guestEmail: string;
}

interface TimeSlot {
  time: string;
  available: boolean;
}

export function ReservationCalendar() {
  const [date, setDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>([]);
  const [selectedTime, setSelectedTime] = useState<string>('');
  const [guestName, setGuestName] = useState<string>('');
  const [guestEmail, setGuestEmail] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<boolean>(false);

  useEffect(() => {
    fetchTimeSlots();
  }, [date]);

  const fetchTimeSlots = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`/api/reservations-api/reservations?date=${date}`);
      if (!response.ok) {
        throw new Error(`Failed to fetch reservations: ${response.status} ${response.statusText}`);
      }
      const reservations: Reservation[] = await response.json();

      // Generate time slots (9am to 8pm)
      const slots: TimeSlot[] = [];
      for (let hour = 9; hour <= 20; hour++) {
        const time = `${hour}:00`;
        const isAvailable = !reservations.some(r => r.time === time);
        slots.push({ time, available: isAvailable });
      }

      setTimeSlots(slots);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleBookReservation = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedTime || !guestName || !guestEmail) return;

    try {
      const response = await fetch('/api/reservations-api/reservations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          date,
          time: selectedTime,
          guestName,
          guestEmail
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to book reservation: ${response.status} ${response.statusText}`);
      }

      setSuccess(true);
      setGuestName('');
      setGuestEmail('');
      setSelectedTime('');

      // Refresh the time slots
      await fetchTimeSlots();

      // Reset success message after 3 seconds
      setTimeout(() => setSuccess(false), 3000);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Book Your Reservation</h1>

      <div style={{ marginBottom: '20px' }}>
        <label htmlFor="date" style={{ display: 'block', marginBottom: '5px' }}>
          Select Date:
        </label>
        <input
          type="date"
          id="date"
          value={date}
          onChange={(e) => setDate(e.target.value)}
          style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
        />
      </div>

      <h2 style={{ textAlign: 'center' }}>Available Time Slots</h2>

      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px', justifyContent: 'center' }}>
        {timeSlots.length > 0 ? (
          timeSlots.map((slot) => (
            <button
              key={slot.time}
              onClick={() => setSelectedTime(slot.time)}
              disabled={!slot.available}
              style={{
                padding: '10px 15px',
                borderRadius: '8px',
                border: '1px solid #ccc',
                backgroundColor: slot.available ? '#4CAF50' : '#f0f0f0',
                color: slot.available ? 'white' : 'gray',
                cursor: slot.available ? 'pointer' : 'default',
                opacity: slot.available ? 1 : 0.6,
                minWidth: '100px'
              }}
            >
              {slot.time}
            </button>
          ))
        ) : (
          <p>No time slots available for this date.</p>
        )}
      </div>

      <form onSubmit={handleBookReservation} style={{ marginTop: '30px' }}>
        <h2 style={{ textAlign: 'center' }}>Book Now</h2>

        {success && (
          <div style={{ backgroundColor: '#d4edda', color: '#155724', padding: '10px', borderRadius: '4px', marginBottom: '10px' }}>
            Reservation booked successfully!
          </div>
        )}

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="name" style={{ display: 'block', marginBottom: '5px' }}>
            Full Name:
          </label>
          <input
            type="text"
            id="name"
            value={guestName}
            onChange={(e) => setGuestName(e.target.value)}
            required
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="email" style={{ display: 'block', marginBottom: '5px' }}>
            Email Address:
          </label>
          <input
            type="email"
            id="email"
            value={guestEmail}
            onChange={(e) => setGuestEmail(e.target.value)}
            required
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          />
        </div>

        <button
          type="submit"
          disabled={!selectedTime || !guestName || !guestEmail}
          style={{
            width: '100%',
            padding: '12px',
            backgroundColor: selectedTime && guestName && guestEmail ? '#2196F3' : '#ccc',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: selectedTime && guestName && guestEmail ? 'pointer' : 'default'
          }}
        >
          Confirm Reservation
        </button>
      </form>
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface SwapRequest {
  id: string;
  shiftId: string;
  requesterId: string;
  targetUserId: string;
  status: "pending" | "approved" | "rejected";
}

interface Shift {
  id: string;
  date: string;
  startTime: string;
  endTime: string;
  userId: string;
}

export function SwapApprovalQueue() {
  const [swapRequests, setSwapRequests] = useState<SwapRequest[]>([]);
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchSwapRequestsAndShifts() {
      try {
        setLoading(true);
        const [swapRequestsRes, shiftsRes] = await Promise.all([
          fetch("/api/lifeguard-shift-api/swap-requests"),
          fetch("/api/lifeguard-shift-api/shifts"),
        ]);

        if (!swapRequestsRes.ok || !shiftsRes.ok) {
          throw new Error("Failed to fetch data");
        }

        const swapRequestsData = await swapRequestsRes.json();
        const shiftsData = await shiftsRes.json();

        setSwapRequests(swapRequestsData);
        setShifts(shiftsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchSwapRequestsAndShifts();
  }, []);

  const handleApprove = async (swapRequestId: string) => {
    try {
      const res = await fetch(
        `/api/lifeguard-shift-api/swap-requests/${swapRequestId}`,
        {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ status: "approved" }),
        }
      );

      if (!res.ok) {
        throw new Error("Failed to approve swap request");
      }

      // Refresh data
      const [swapRequestsRes, shiftsRes] = await Promise.all([
        fetch("/api/lifeguard-shift-api/swap-requests"),
        fetch("/api/lifeguard-shift-api/shifts"),
      ]);

      if (!swapRequestsRes.ok || !shiftsRes.ok) {
        throw new Error("Failed to refresh data after approval");
      }

      const swapRequestsData = await swapRequestsRes.json();
      const shiftsData = await shiftsRes.json();

      setSwapRequests(swapRequestsData);
      setShifts(shiftsData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleReject = async (swapRequestId: string) => {
    try {
      const res = await fetch(
        `/api/lifeguard-shift-api/swap-requests/${swapRequestId}`,
        {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ status: "rejected" }),
        }
      );

      if (!res.ok) {
        throw new Error("Failed to reject swap request");
      }

      // Refresh data
      const [swapRequestsRes, shiftsRes] = await Promise.all([
        fetch("/api/lifeguard-shift-api/swap-requests"),
        fetch("/api/lifeguard-shift-api/shifts"),
      ]);

      if (!swapRequestsRes.ok || !shiftsRes.ok) {
        throw new Error("Failed to refresh data after rejection");
      }

      const swapRequestsData = await swapRequestsRes.json();
      const shiftsData = await shiftsRes.json();

      setSwapRequests(swapRequestsData);
      setShifts(shiftsData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (swapRequests.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No pending swap requests.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Swap Approval Queue</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {swapRequests.map((request) => {
          const shift = shifts.find((s) => s.id === request.shiftId);

          if (!shift) {
            return null;
          }

          return (
            <div
              key={request.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: "8px",
                padding: "15px",
                display: "flex",
                flexDirection: "column",
                gap: "10px",
              }}
            >
              <div>
                <strong>Shift:</strong> {shift.date} {shift.startTime} - {shift.endTime}
              </div>
              <div>
                <strong>Requester:</strong> {request.requesterId}
              </div>
              <div>
                <strong>Target User:</strong> {request.targetUserId}
              </div>
              <div>
                <strong>Status:</strong> {request.status}
              </div>
              <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
                <button
                  onClick={() => handleApprove(request.id)}
                  style={{
                    backgroundColor: "#4CAF50",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "8px 12px",
                    cursor: "pointer",
                  }}
                >
                  Approve
                </button>
                <button
                  onClick={() => handleReject(request.id)}
                  style={{
                    backgroundColor: "#f44336",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "8px 12px",
                    cursor: "pointer",
                  }}
                >
                  Reject
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply guard to PUT/PATCH/DELETE requests on /tours/* routes
  if (!['PUT', 'PATCH', 'DELETE'].includes(req.method) || !req.path.startsWith('/tours/')) {
    next();
