{"code":"import { FC, useEffect, useState } from "react";

interface Book {
  id: number;
  title: string;
  price: number;
  condition: string;
}

export function ListingForm() {
  const [title, setTitle] = useState("");
  const [price, setPrice] = useState("");
  const [condition, setCondition] = useState("");
  const [books, setBooks] = useState<Book[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    fetchBooks();
  }, []);

  const fetchBooks = async () => {
    try {
      const response = await fetch("/api/books-api/");
      if (!response.ok) throw new Error("Failed to fetch books");
      const data = await response.json();
      setBooks(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || !price || !condition) return;

    try {
      const response = await fetch("/api/books-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          title,
          price: Number(price),
          condition
        })
      });

      if (!response.ok) throw new Error("Failed to add book");
      await fetchBooks();
      setTitle("");
      setPrice("");
      setCondition("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center" }}>Loading...</div>;

  return (
    <div style={{
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      maxWidth: 600,
      margin: "0 auto",
      padding: 20
    }}>
      <h1>Add New Book</h1>
      <form onSubmit={handleSubmit} style={{ marginBottom: 30 }}>
        <div style={{ marginBottom: 15 }}>
          <label htmlFor="title" style={{ display: "block", marginBottom: 5 }}>
            Title
          </label>
          <input
            id="title"
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            style={{ width: "100%", padding: 8, borderRadius: 4, border: "1px solid #ccc" }}
            required
          />
        </div>

        <div style={{ marginBottom: 15 }}>
          <label htmlFor="price" style={{ display: "block", marginBottom: 5 }}>
            Price ($)
          </label>
          <input
            id="price"
            type="number"
            value={price}
            onChange={(e) => setPrice(e.target.value)}
            style={{ width: "100%", padding: 8, borderRadius: 4, border: "1px solid #ccc" }}
            required
            step="0.01"
          />
        </div>

        <div style={{ marginBottom: 15 }}>
          <label htmlFor="condition" style={{ display: "block", marginBottom: 5 }}>
            Condition
          </label>
          <select
            id="condition"
            value={condition}
            onChange={(e) => setCondition(e.target.value)}
            style={{ width: "100%", padding: 8, borderRadius: 4, border: "1px solid #ccc" }}
            required
          >
            <option value="">Select condition</option>
            <option value="new">New</option>
            <option value="like-new">Like New</option>
            <option value="good">Good</option>
            <option value="fair">Fair</option>
            <option value="poor">Poor</option>
          </select>
        </div>

        <button
          type="submit"
          style={{
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            padding: "10px 20px",
            borderRadius: 4,
            cursor: "pointer"
          }}
        >
          Add Book
        </button>
      </form>

      {error && <p style={{ color: "red" }}>{error}</p>}

      <h2>Current Listings</h2>
      {books.length === 0 ? (
        <p>No books listed yet.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {books.map((book) => (
            <div
              key={book.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: 8,
                padding: 15,
                backgroundColor: "#f9f9f9"
              }}
            >
              <div style={{ fontWeight: "bold" }}>{book.title}</div>
