{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./orchestra.db");

interface RehearsalRow {
  id: number;
  date: string;
  time: string;
  confirmed_musician_count: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS rehearsals (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    date TEXT NOT NULL,
    time TEXT NOT NULL,
    confirmed_musician_count INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllRehearsals(): RehearsalRow[] {
  const stmt = db.prepare("SELECT * FROM rehearsals");
  return stmt.all() as unknown as RehearsalRow[];
}

export function getRehearsalById(id: number): RehearsalRow | undefined {
  const stmt = db.prepare("SELECT * FROM rehearsals WHERE id = ?");
  return stmt.get(id) as unknown as RehearsalRow | undefined;
}

export function insertRehearsal(
  date: string,
  time: string,
  confirmedMusicianCount: number
): number {
  const stmt = db.prepare(
    "INSERT INTO rehearsals (date, time, confirmed_musician_count) VALUES (?, ?, ?)"
  );
  const result = stmt.run(date, time, confirmedMusicianCount);
  return Number(result.lastInsertRowid);
}

export function updateRehearsal(
  id: number,
  date: string,
  time: string,
  confirmedMusicianCount: number
): void {
  const stmt = db.prepare(
    "UPDATE rehearsals SET date = ?, time = ?, confirmed_musician_count = ? WHERE id = ?"
  );
  stmt.run(date, time, confirmedMusicianCount, id);
}

export function deleteRehearsal(id: number): void {
  const stmt = db.prepare("DELETE FROM rehearsals WHERE id = ?");
  stmt.run(id);
}

// Seed data
if (getAllRehearsals().length === 0) {
