{"code":"import { useEffect, useState } from "react";

interface DeskBooking {
  id: string;
  date: string;
  memberId: string;
  deskId: string;
}

interface AvailableDesk {
  id: string;
  date: string;
  available: boolean;
}

export function DeskBookingCalendar() {
  const [bookings, setBookings] = useState<DeskBooking[]>([]);
  const [availableDesks, setAvailableDesks] = useState<AvailableDesk[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [memberId, setMemberId] = useState<string>('');

  useEffect(() => {
    fetchBookings();
    fetchAvailableDesks();
  }, []);

  const fetchBookings = async () => {
    try {
      const response = await fetch('/api/bookings-api/');
      if (!response.ok) throw new Error('Failed to fetch bookings');
      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const fetchAvailableDesks = async () => {
    try {
      const response = await fetch('/api/bookings-api/');
      if (!response.ok) throw new Error('Failed to fetch available desks');
      const data = await response.json();
      setAvailableDesks(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleBookDesk = async (deskId: string) => {
    try {
      const response = await fetch('/api/bookings-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          date: selectedDate,
          memberId,
          deskId
        })
      });

      if (!response.ok) throw new Error('Failed to book desk');

      // Refresh data after booking
      await fetchBookings();
      await fetchAvailableDesks();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleCancelBooking = async (bookingId: string) => {
    try {
      const response = await fetch(`/api/bookings-api/${bookingId}`, {
        method: 'DELETE'
      });

      if (!response.ok) throw new Error('Failed to cancel booking');

      // Refresh data after cancellation
      await fetchBookings();
      await fetchAvailableDesks();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;

  const today = new Date().toISOString().split('T')[0];
  const nextWeek = new Date(Date.now() + 6 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

  const filteredBookings = bookings.filter(booking => {
    const bookingDate = new Date(booking.date).toISOString().split('T')[0];
    return bookingDate >= today && bookingDate <= nextWeek;
  });

  const filteredDesks = availableDesks.filter(desk => {
    const deskDate = new Date(desk.date).toISOString().split('T')[0];
    return deskDate >= today && deskDate <= nextWeek;
  });

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Desk Booking Calendar</h1>

      <div style={{ marginBottom: '20px' }}>
        <label htmlFor="memberId" style={{ display: 'block', marginBottom: '5px' }}>
          Member ID:
        </label>
        <input
          id="memberId"
          type="text"
          value={memberId}
          onChange={(e) => setMemberId(e.target.value)}
          style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
        />
      </div>

      <div style={{ marginBottom: '20px' }}>
        <label htmlFor="date" style={{ display: 'block', marginBottom: '5px' }}>
          Select Date:
        </label>
        <input
          id="date"
          type="date"
          value={selectedDate}
          onChange={(e) => setSelectedDate(e.target.value)}
          style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
        />
      </div>

      <h2 style={{ textAlign: 'center' }}>Your Bookings</h2>
      {filteredBookings.length === 0 ? (
        <p style={{ textAlign: 'center' }}>No bookings found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {filteredBookings.map(booking => (
            <div key={booking.id} style={{
              border: '1px solid #ccc',
              borderRadius: '8px',
              padding: '10px',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center'
            }}>
              <span>
                {new Date(booking.date).toLocaleDateString()} - Desk {booking.deskId}
              </span>
              <button
                onClick={() => handleCancelBooking(booking.id)}
                style={{
                  backgroundColor: '#ff4d4d',
                  color: 'white',
                  border: 'none',
                  padding: '5px 10px',
                  borderRadius: '4px',
                  cursor: 'pointer'
                }}
              >
                Cancel
              </button>
            </div>
          ))}
        </div>
      )}

      <h2 style={{ textAlign: 'center', marginTop: '30px' }}>Available Desks</h2>
      {filteredDesks.length === 0 ? (
        <p style={{ textAlign: 'center' }}>No available desks found.</p>
      ) : (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
          {filteredDesks.map(desk => (
            <div key={desk.id} style={{
              border: '1px solid #ccc',
              borderRadius: '8px',
              padding: '10px',
              minWidth: '150px',
              textAlign: 'center'
            }}>
              <p>{new Date(desk.date).toLocaleDateString()}</p>
              <p>Desk {desk.id}</p>
              <button
                onClick={() => handleBookDesk(desk.id)}
                disabled={!memberId}
                style={{
                  backgroundColor: '#4CAF50',
                  color: 'white',
                  border: 'none',
                  padding: '5px 10px',
                  borderRadius: '4px',
                  cursor: 'pointer',
                  marginTop: '5px',
                  opacity: !memberId ? 0.5 : 1
                }}
              >
                Book
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

