{"code":"import { Router, type Request, type Response } from "express";
import { db, deleteReservation, getAllReservations, getReservationById, insertReservation, updateReservation } from "../db/reservations-table";

export const router = Router();

// Get all reservations
router.get("/", (req: Request, res: Response) => {
  try {
    const reservations = getAllReservations();
    res.json(reservations);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservations" });
  }
});

// Get a reservation by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const reservation = getReservationById(id);
    if (!reservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    res.json(reservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservation" });
  }
});

// Create a new reservation
router.post("/", (req: Request, res: Response) => {
  try {
    const { driverId, spotNumber, reservedTime } = req.body;

    if (!driverId || !spotNumber || !reservedTime) {
      return res.status(400).json({ error: "Missing required fields: driverId, spotNumber, reservedTime" });
    }

    const id = insertReservation(driverId, spotNumber, reservedTime);
    res.status(201).json({ id, driverId, spotNumber, reservedTime });
  } catch (error) {
    res.status(500).json({ error: "Failed to create reservation" });
  }
});

// Update a reservation
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const { driverId, spotNumber, reservedTime } = req.body;

    if (!driverId || !spotNumber || !reservedTime) {
      return res.status(400).json({ error: "Missing required fields: driverId, spotNumber, reservedTime" });
    }

    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

