{"code":"import { useEffect, useState } from "react";

interface TimeSlot {
  id: string;
  date: string;
  startTime: string;
  endTime: string;
  available: boolean;
}

export function BookingCalendar() {
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchTimeSlots();
  }, []);

  const fetchTimeSlots = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/rental-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setTimeSlots(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleBookSlot = async (id: string) => {
    try {
      const response = await fetch(`/api/rental-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ available: false }),
      });

      if (!response.ok) {
        throw new Error(`Failed to book slot: ${response.status} ${response.statusText}`);
      }

      // Refresh the list after booking
      await fetchTimeSlots();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (timeSlots.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No available time slots.
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Kitchen Booking Calendar</h1>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
        {timeSlots.map((slot) => (
          <div 
            key={slot.id} 
            style={{ 
              border: "1px solid #ccc", 
              borderRadius: "8px", 
              padding: "15px", 
              width: "100%", 
              maxWidth: "300px", 
              boxSizing: "border-box"
            }}
          >
            <p><strong>Date:</strong> {slot.date}</p>
            <p><strong>Time:</strong> {slot.startTime} - {slot.endTime}</p>
            <button 
              onClick={() => handleBookSlot(slot.id)}
              disabled={!slot.available}
              style={{ 
                backgroundColor: slot.available ? "#007bff" : "#ccc", 
                color: "white", 
                border: "none", 
                borderRadius: "4px", 
                padding: "8px 12px", 
                cursor: slot.available ? "pointer" : "default",
                marginTop: "10px"
              }}
            >
              {slot.available ? "Book Slot" : "Booked"}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import { 
  getAllReservations,
  getReservationById,
  insertReservation,
  updateReservation,
  deleteReservation
} from "../db/reservations-table";
import { 
  getAllRoles,
  getRoleByUserId
} from "../db/role-table";

export const router = Router();

// Get all reservations
router.get("/", (req: Request, res: Response) => {
  try {
    const reservations = getAllReservations();
    res.json(reservations);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservations" });
  }
});

// Get a reservation by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const reservation = getReservationById(id);
    if (!reservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    res.json(reservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservation" });
  }
});

// Create a new reservation
router.post("/", (req: Request, res: Response) => {
  try {
    const { memberId, plotId, reservationDate } = req.body;

    // Validate required fields
    if (!memberId || !plotId || !reservationDate) {
      return res.status(400).json({ error: "Member ID, plot ID, and reservation date are required" });
    }

    // Validate numeric fields
    const memberNumber = Number(memberId);
    const plotNumber = Number(plotId);

    if (isNaN(memberNumber) || isNaN(plotNumber)) {
      return res.status(400).json({ error: "Member ID and plot ID must be numbers" });
    }

    // Check if user has proper role (member)
    const userRole = getRoleByUserId(memberNumber);
    if (!userRole || userRole.role !== "member") {
      return res.status(403).json({ error: "Only members can make reservations" });
    }

    // Insert the reservation
    const newId = insertReservation(memberNumber, plotNumber, reservationDate);

    // Fetch the created reservation to send back
    const createdReservation = getReservationById(newId);

    if (!createdReservation) {
      return res.status(500).json({ error: "Failed to retrieve created reservation" });
    }

    res.status(201).json(createdReservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to create reservation" });
  }
});

// Update a reservation
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const { memberId, plotId, reservationDate } = req.body;

    // Validate required fields
    if (!memberId || !plotId || !reservationDate) {
      return res.status(400).json({ error: "Member ID, plot ID, and reservation date are required" });
    }

    // Validate numeric fields
    const memberNumber = Number(memberId);
    const plotNumber = Number(plotId);

    if (isNaN(memberNumber) || isNaN(plotNumber)) {
      return res.status(400).json({ error: "Member ID and plot ID must be numbers" });
    }

    // Check if reservation exists
    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    // Check if user has proper role (member)
    const userRole = getRoleByUserId(memberNumber);
    if (!userRole || userRole.role !== "member") {
      return res.status(403).json({ error: "Only members can update reservations" });
    }

    // Update the reservation
    const updatedId = updateReservation(id, memberNumber, plotNumber, reservationDate);

    // Fetch the updated reservation to send back
    const updatedReservation = getReservationById(updatedId);

    if (!updatedReservation) {
      return res.status(500).json({ error: "Failed to retrieve updated reservation" });
    }

    res.json(updatedReservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to update reservation" });
  }
});

// Delete a reservation
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const result = deleteReservation(id);

    if (result === 0) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    res.json({ message: "Reservation deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete reservation" });
  }
});
"}

