  const [error, setError] = useState<string | null>(null);
  const [selectedShiftId, setSelectedShiftId] = useState<number | null>(null);
  const [parentName, setParentName] = useState("");

  useEffect(() => {
    fetchShifts();
  }, []);

  const fetchShifts = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/shifts-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch shifts: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setShifts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleSignup = async (shiftId: number) => {
    if (!parentName.trim()) {
      alert('Please enter your name');
      return;
    }

    try {
      const response = await fetch(`/api/shifts-api/${shiftId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ caregiver: parentName }),
      });

      if (!response.ok) {
        throw new Error(`Failed to sign up: ${response.status} ${response.statusText}`);
      }

      // Refresh the shifts list
      await fetchShifts();
      setSelectedShiftId(null);
      setParentName("");
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
