                    <span>Assigned to: {shift.caregiver}</span>
                  ) : (
                    <button 
                      onClick={() => setSelectedShiftId(shift.id)}
                      style={{ backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', padding: '5px 10px' }}
                    >
                      Sign Up
                    </button>
                  )}
                </div>
              </div>

              {selectedShiftId === shift.id && (
                <div style={{ marginTop: '10px', paddingTop: '10px', borderTop: '1px solid #eee' }}>
                  <input
                    type="text"
                    placeholder="Your Name"
                    value={parentName}
                    onChange={(e) => setParentName(e.target.value)}
                    style={{ width: '100%', padding: '8px', marginBottom: '10px', borderRadius: '4px', border: '1px solid #ccc' }}
                  />
                  <div style={{ display: 'flex', gap: '10px' }}>
                    <button 
                      onClick={() => handleSignup(shift.id)}
                      style={{ backgroundColor: '#28a745', color: 'white', border: 'none', borderRadius: '4px', padding: '5px 10px' }}
                    >
                      Confirm Signup
                    </button>
                    <button 
                      onClick={() => setSelectedShiftId(null)}
                      style={{ backgroundColor: '#6c757d', color: 'white', border: 'none', borderRadius: '4px', padding: '5px 10px' }}
