{"code":"import { useEffect, useState } from "react";

interface CommerceRecord {
  id: string;
  name: string;
  description: string;
  price: number;
}

export function CustomStorefront() {
  const [records, setRecords] = useState<CommerceRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newRecord, setNewRecord] = useState({
    name: "",
    description: "",
    price: 0,
  });

  useEffect(() => {
    fetchCommerceRecords();
  }, []);

  const fetchCommerceRecords = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/commerce-api/commerce-records");
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setRecords(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/commerce-api/commerce-records", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newRecord),
      });
      if (!response.ok) {
        throw new Error(`Failed to create: ${response.status} ${response.statusText}`);
      }
      setNewRecord({ name: "", description: "", price: 0 });
      fetchCommerceRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleUpdate = async (id: string, updatedFields: Partial<CommerceRecord>) => {
    try {
      const response = await fetch(`/api/commerce-api/commerce-records/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(updatedFields),
      });
      if (!response.ok) {
        throw new Error(`Failed to update: ${response.status} ${response.statusText}`);
      }
      fetchCommerceRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/commerce-api/commerce-records/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete: ${response.status} ${response.statusText}`);
      }
      fetchCommerceRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Custom Storefront</h1>

      <form onSubmit={handleCreate} style={{ marginBottom: "30px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Name"
          value={newRecord.name}
          onChange={(e) => setNewRecord({...newRecord, name: e.target.value})}
          style={{ width: "100%", padding: "8px" }}
        />
        <textarea
          placeholder="Description"
          value={newRecord.description}
          onChange={(e) => setNewRecord({...newRecord, description: e.target.value})}
          style={{ width: "100%", padding: "8px" }}
        />
        <input
          type="number"
          placeholder="Price"
          value={newRecord.price}
          onChange={(e) => setNewRecord({...newRecord, price: Number(e.target.value)})}
          style={{ width: "100%", padding: "8px" }}
        />
        <button type="submit" style={{ padding: "10px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}>
          Add Item
        </button>
      </form>

      {records.length === 0 ? (
        <p style={{ textAlign: "center", color: "gray" }}>No items found.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
          {records.map((record) => (
            <div key={record.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px", width: "100%", maxWidth: "250px" }}>
              <h3>{record.name}</h3>
              <p>{record.description}</p>
              <p>${record.price.toFixed(2)}</p>
              <div style={{ display: "flex", justifyContent: "space-between", marginTop: "10px" }}>
                <button 
                  onClick={() => handleDelete(record.id)}
                  style={{ padding: "5px 10px", backgroundColor: "#dc3545", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
                >
                  Delete
                </button>
                <button 
                  onClick={() => handleUpdate(record.id, { name: record.name + " (updated)" })}
                  style={{ padding: "5px 10px", backgroundColor: "#28a745", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
                >
                  Update
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

