{"code":"import { Router, type Request, type Response } from "express";
import { getAllShifts, getShiftById, insertShift, updateShift, deleteShift } from "../db/shifts-table";
import { getAllBookings, getBookingById, createBooking, updateBooking, deleteBooking } from "../db/bookings-table";

export const router = Router();

// Get all shifts
router.get("/shifts", (req: Request, res: Response) => {
  try {
    const shifts = getAllShifts();
    res.json(shifts);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch shifts" });
  }
});

// Get a specific shift by ID
router.get("/shifts/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const shift = getShiftById(id);
    if (!shift) {
      return res.status(404).json({ error: "Shift not found" });
    }
    res.json(shift);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch shift" });
  }
});

// Create a new shift
router.post("/shifts", (req: Request, res: Response) => {
  try {
    const { date, capacity } = req.body;
    if (!date || capacity === undefined) {
      return res.status(400).json({ error: "Date and capacity are required" });
    }
    const id = insertShift(date, capacity);
    res.status(201).json({ id, date, capacity });
  } catch (error) {
    res.status(500).json({ error: "Failed to create shift" });
  }
});

// Update a shift
router.put("/shifts/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { date, capacity } = req.body;
    if (!date || capacity === undefined) {
      return res.status(400).json({ error: "Date and capacity are required" });
    }
    updateShift(id, date, capacity);
    res.json({ id, date, capacity });
  } catch (error) {
    res.status(500).json({ error: "Failed to update shift" });
  }
});

// Delete a shift
router.delete("/shifts/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    deleteShift(id);
    res.json({ message: "Shift deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete shift" });
  }
});

// Get all bookings
router.get("/bookings", (req: Request, res: Response) => {
  try {
    const bookings = getAllBookings();
    res.json(bookings);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch bookings" });
  }
});

// Get a specific booking by ID
router.get("/bookings/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const booking = getBookingById(id);
    if (!booking) {
      return res.status(404).json({ error: "Booking not found" });
    }
    res.json(booking);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch booking" });
  }
});

// Create a new booking
router.post("/bookings", (req: Request, res: Response) => {
  try {
    const { lifeguardId, shiftId, status } = req.body;
    if (lifeguardId === undefined || shiftId === undefined || !status) {
      return res.status(400).json({ error: "Lifeguard ID, shift ID, and status are required" });
    }
    const id = createBooking(lifeguardId, shiftId, status);
    res.status(201).json({ id, lifeguardId, shiftId, status });
  } catch (error) {
    res.status(500).json({ error: "Failed to create booking" });
  }
