    return res.status(404).json({ error: "Order not found" });
  }

  res.json(order);
});

// Create new order
router.post("/", (req: Request, res: Response) => {
  const { customerId, flavour, size, date } = req.body;

  if (!customerId || !flavour || !size || !date) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const id = insertOrder(customerId, flavour, size, date);

  res.status(201).json({ id, customerId, flavour, size, date });
});

// Update existing order
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { customerId, flavour, size, date } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid order ID" });
  }

  if (!customerId || !flavour || !size || !date) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const existingOrder = getOrderById(id);

  if (!existingOrder) {
    return res.status(404).json({ error: "Order not found" });
  }

  updateOrder(id, customerId, flavour, size, date);

  res.json({ id, customerId, flavour, size, date });
});

// Delete order
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid order ID" });
  }

  const existingOrder = getOrderById(id);

  if (!existingOrder) {
    return res.status(404).json({ error: "Order not found" });
  }

  deleteOrder(id);

  res.json({ message: "Order deleted successfully" });
});
"}

