{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check ownership for POST requests to the /desks endpoint
  if (req.method !== "POST" || !req.path.startsWith("/desks")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token structure: base64 encoded payload + signature
  const parts = token.split(".");
  if (parts.length !== 2) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  const payload = parts[0];
  const signature = parts[1];

  // Verify signature
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64");

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "base64");
    const actualBuffer = Buffer.from(signature, "base64");

    if (timingSafeEqual(expectedBuffer, actualBuffer)) {
      // Signature is valid, decode payload to check role
      const decodedPayload = Buffer.from(payload, "base64").toString("utf8");
      const payloadObj = JSON.parse(decodedPayload);

      if (payloadObj.role === "owner") {
        next();
      } else {
        res.status(403).json({ error: "Forbidden: Owner role required" });
      }
    } else {
      res.status(401).json({ error: "Invalid token" });
    }
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
  }
}
"}

{"code":"import { useEffect, useState } from "react";

interface MenuItem {
  id: string;
  name: string;
  description: string;
  price: number;
}

interface BoxItem {
  id: string;
  menuItemId: string;
  quantity: number;
}

export function BoxCustomizer() {
  const [menuItems, setMenuItems] = useState<MenuItem[]>([]);
  const [boxItems, setBoxItems] = useState<BoxItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newQuantity, setNewQuantity] = useState<Record<string, number>>({});

  useEffect(() => {
    fetchMenuItems();
    fetchBoxItems();
  }, []);

  const fetchMenuItems = async () => {
    try {
      const response = await fetch("/api/box-customization-api/");
      if (!response.ok) throw new Error("Failed to fetch menu items");
      const data = await response.json();
      setMenuItems(data);
    } catch (err) {
      setError("Error loading menu items");
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchBoxItems = async () => {
    try {
      const response = await fetch("/api/box-customization-api/member");
      if (!response.ok) throw new Error("Failed to fetch box items");
      const data = await response.json();
      setBoxItems(data);
      // Initialize quantities
      const initialQuantities: Record<string, number> = {};
      data.forEach((item: BoxItem) => {
        initialQuantities[item.menuItemId] = item.quantity;
      });
      setNewQuantity(initialQuantities);
    } catch (err) {
      setError("Error loading box items");
      console.error(err);
    }
  };

  const handleQuantityChange = (menuItemId: string, value: string) => {
    const numValue = Number(value);
    if (isNaN(numValue)) return;
    setNewQuantity({
      ...newQuantity,
      [menuItemId]: numValue
    });
  };

  const saveChanges = async () => {
    try {
      const updatedItems = Object.entries(newQuantity)
        .filter(([_, qty]) => qty > 0)
        .map(([menuItemId, quantity]) => ({
          menuItemId,
          quantity
        }));

      const response = await fetch("/api/box-customization-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(updatedItems)
      });

      if (!response.ok) throw new Error("Failed to save changes");

      // Refresh data after successful save
      await fetchMenuItems();
      await fetchBoxItems();
    } catch (err) {
      setError("Error saving changes");
      console.error(err);
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

