{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("reservations.db");

interface Reservation {
  id: number;
  guestId: number;
  slotTime: string;
  status: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS reservations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    guestId INTEGER NOT NULL,
    slotTime TEXT NOT NULL,
    status TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllReservations(): Reservation[] {
  const stmt = db.prepare("SELECT * FROM reservations");
  return stmt.all() as unknown as Reservation[];
}

export function getReservationById(id: number): Reservation | undefined {
  const stmt = db.prepare("SELECT * FROM reservations WHERE id = ?");
  return stmt.get(id) as unknown as Reservation | undefined;
}

export function insertReservation(guestId: number, slotTime: string, status: string): number {
  const stmt = db.prepare(
    "INSERT INTO reservations (guestId, slotTime, status) VALUES (?, ?, ?)"
  );
  const result = stmt.run(guestId, slotTime, status);
  return Number(result.lastInsertRowid);
}

export function updateReservation(id: number, guestId: number, slotTime: string, status: string): void {
  const stmt = db.prepare(
    "UPDATE reservations SET guestId = ?, slotTime = ?, status = ? WHERE id = ?"
  );
  stmt.run(guestId, slotTime, status, id);
}

export function deleteReservation(id: number): void {
  const stmt = db.prepare("DELETE FROM reservations WHERE id = ?");
  stmt.run(id);
}

// Insert sample data if table is empty
if (getAllReservations().length === 0) {
  insertReservation(101, "2023-06-15T14:00:00", "confirmed");
  insertReservation(102, "2023-06-15T16:30:00", "pending");
  insertReservation(103, "2023-06-16T10:00:00", "confirmed");
  insertReservation(104, "2023-06-16T18:00:00", "cancelled");
  insertReservation(105, "2023-06-17T12:00:00", "confirmed");
}
