      return res.status(404).json({ error: "Reassignment not found" });
    }

    updateReassignment(id, supervisorId, sourceHousekeeperId, targetHousekeeperId, roomId);
    const updatedReassignment = getReassignmentById(id);

    if (!updatedReassignment) {
      return res.status(500).json({ error: "Failed to update reassignment" });
    }

    res.json(updatedReassignment);
  } catch (error) {
    res.status(500).json({ error: "Failed to update reassignment" });
  }
});

// Delete a reassignment
router.delete("/reassignments/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reassignment ID" });
    }

    const existingReassignment = getReassignmentById(id);
    if (!existingReassignment) {
      return res.status(404).json({ error: "Reassignment not found" });
    }

    deleteReassignment(id);
    res.json({ message: "Reassignment deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete reassignment" });
  }
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-protected routes/methods
  if (req.method === "GET" && !req.path.includes("/api/")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // Decode payload (simplified for example)
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    const userRole = decodedPayload.role;

    // Check role permissions
    const protectedRoutes = [
      "/api/workflows",
      "/api/data-governance",
      "/api/audit-logs"
    ];

    const isProtectedRoute = protectedRoutes.some(route =>
      req.path.startsWith(route)
    );

    if (isProtectedRoute) {
      if (!userRole) {
        res.status(403).json({ error: "Forbidden" });
        return;
      }

      // Example role-based access control
      if (req.method === "POST" || req.method === "PUT" || req.method === "DELETE") {
        if (userRole !== "admin" && userRole !== "workflow-manager") {
          res.status(403).json({ error: "Forbidden" });
          return;
        }
      }
    }

    // Log audit trail
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} by ${userRole || "unauthenticated"}`);

    next();
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
  }
}
"}

{"code":"import { useEffect, useState } from "react";

interface Shift {
  id: string;
  title: string;
  description: string;
  startTime: string;
  endTime: string;
  claimedBy?: string;
}

interface BoardOwnership {
  id: string;
  shiftId: string;
  memberId: string;
}

export function ShiftClaimBoard() {
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [memberId, setMemberId] = useState("");

  useEffect(() => {
    fetchShifts();
  }, []);

  const fetchShifts = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/shifts-api/shifts');
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setShifts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleClaimShift = async (shiftId: string) => {
    if (!memberId.trim()) {
      setError("Please enter your member ID to claim a shift.");
      return;
    }

    try {
      const response = await fetch(`/api/shifts-api/shifts/${shiftId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ claimedBy: memberId }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // Refresh the shifts list after claiming
      await fetchShifts();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  if (error) {
    return <div>Error: {error}</div>;
  }

  const gridStyle: React.CSSProperties = {
    display: 'flex',
    flexWrap: 'wrap',
    gap: '1rem',
    justifyContent: 'center',
  };

  const cardStyle: React.CSSProperties = {
    border: '1px solid #ccc',
    borderRadius: '8px',
    padding: '1rem',
    width: '300px',
    boxSizing: 'border-box',
    backgroundColor: '#f9f9f9',
  };

  const buttonStyle: React.CSSProperties = {
    backgroundColor: '#4CAF50',
    color: 'white',
    border: 'none',
    padding: '0.5rem 1rem',
    borderRadius: '4px',
    cursor: 'pointer',
    marginTop: '0.5rem',
  };

  const inputStyle: React.CSSProperties = {
    width: '100%',
    padding: '0.5rem',
    marginBottom: '1rem',
    boxSizing: 'border-box',
  };

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', fontFamily: 'system-ui, sans-serif', padding: '1rem' }}>
      <h1>Shift Claim Board</h1>
      <p>Claim an open shift below:</p>

      <input
        type="text"
        placeholder="Enter your Member ID"
        value={memberId}
        onChange={(e) => setMemberId(e.target.value)}
        style={inputStyle}
      />

      {shifts.length === 0 ? (
        <p>No open shifts available.</p>
      ) : (
        <div style={gridStyle}>
          {shifts
            .filter(shift => !shift.claimedBy)
            .map(shift => (
              <div key={shift.id} style={cardStyle}>
                <h3>{shift.title}</h3>
                <p>{shift.description}</p>
                <p><strong>Start:</strong> {new Date(shift.startTime).toLocaleString()}</p>
                <p><strong>End:</strong> {new Date(shift.endTime).toLocaleString()}</p>
                <button onClick={() => handleClaimShift(shift.id)} style={buttonStyle}>Claim Shift</button>
              </div>
            ))}
        </div>
      )}
    </div>
  );
}
