{"code":"import { useEffect, useState } from "react";

interface Doctor {
  id: number;
  name: string;
  specialty: string;
}

interface TimeSlot {
  id: number;
  date: string;
  time: string;
  doctorId: number;
}

interface Appointment {
  id: number;
  patientName: string;
  doctorId: number;
  date: string;
  time: string;
}

export function AppointmentBookingForm() {
  const [doctors, setDoctors] = useState<Doctor[]>([]);
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>([]);
  const [selectedDoctorId, setSelectedDoctorId] = useState<number | null>(null);
  const [selectedTimeSlotId, setSelectedTimeSlotId] = useState<number | null>(null);
  const [patientName, setPatientName] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [doctorsResponse, timeSlotsResponse] = await Promise.all([
          fetch("/api/appointments-api/"),
          fetch("/api/appointments-api/available-time-slots"),
        ]);

        if (!doctorsResponse.ok || !timeSlotsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const doctorsData = await doctorsResponse.json();
        const timeSlotsData = await timeSlotsResponse.json();

        setDoctors(doctorsData);
        setTimeSlots(timeSlotsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleBookAppointment = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedDoctorId || !selectedTimeSlotId || !patientName) {
      setError("Please select a doctor, time slot, and enter your name.");
      return;
    }

    try {
      const response = await fetch("/api/appointments-api/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          patientName,
          doctorId: selectedDoctorId,
          date: timeSlots.find(ts => ts.id === selectedTimeSlotId)?.date || "",
          time: timeSlots.find(ts => ts.id === selectedTimeSlotId)?.time || "",
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to book appointment");
      }

      // Reset form after successful booking
      setSelectedDoctorId(null);
      setSelectedTimeSlotId(null);
      setPatientName("");
      setError(null);

      // Refresh data
      const [doctorsResponse, timeSlotsResponse] = await Promise.all([
        fetch("/api/appointments-api/"),
        fetch("/api/appointments-api/available-time-slots"),
      ]);

      if (!doctorsResponse.ok || !timeSlotsResponse.ok) {
        throw new Error("Failed to refresh data");
      }

      const doctorsData = await doctorsResponse.json();
      const timeSlotsData = await timeSlotsResponse.json();

      setDoctors(doctorsData);
      setTimeSlots(timeSlotsData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const formStyle: React.CSSProperties = {
    maxWidth: "600px",
    margin: "0 auto",
    padding: "20px",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
  };

  const inputGroupStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    marginBottom: "15px",
  };

  const inputStyle: React.CSSProperties = {
    padding: "10px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    fontSize: "16px",
    width: "100%",
  };

  const buttonStyle: React.CSSProperties = {
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    padding: "10px 20px",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "16px",
    width: "100%",
  };

  const selectStyle: React.CSSProperties = {
    padding: "10px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    fontSize: "16px",
    width: "100%",
  };

  if (loading) {
    return <div style={formStyle}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={formStyle}>
        <p>Error: {error}</p>
      </div>
    );
  }

  return (
    <div style={formStyle}>
      <h2>Book an Appointment</h2>
      <form onSubmit={handleBookAppointment}>
        <div style={inputGroupStyle}>
          <label htmlFor="patientName">Your Name:</label>
          <input
            id="patientName"
            type="text"
            value={patientName}
            onChange={(e) => setPatientName(e.target.value)}
            style={inputStyle}
            required
          />
        </div>

        <div style={inputGroupStyle}>
          <label htmlFor="doctor">Select Doctor:</label>
          <select
            id="doctor"
            value={selectedDoctorId || ""}
            onChange={(e) => setSelectedDoctorId(Number(e.target.value))}
            style={selectStyle}
            required
          >
            <option value="">-- Choose a doctor --</option>
            {doctors.map((doctor) => (
              <option key={doctor.id} value={doctor.id}>
                {doctor.name} ({doctor.specialty})
              </option>
            ))}
          </select>
        </div>

        <div style={inputGroupStyle}>
          <label htmlFor="timeSlot">Select Time Slot:</label>
          <select
            id="timeSlot"
            value={selectedTimeSlotId || ""}
            onChange={(e) => setSelectedTimeSlotId(Number(e.target.value))}
            style={selectStyle}
            required
          >
            <option value="">-- Choose a time slot --</option>
            {timeSlots
              .filter((slot) => slot.doctorId === selectedDoctorId)
              .map((slot) => (
                <option key={slot.id} value={slot.id}>
                  {slot.date} at {slot.time}
                </option>
              ))}
          </select>
        </div>

        <button type="submit" style={buttonStyle}>Book Appointment</button>
      </form>
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./signature-platform.db");

interface DocumentRow {
  id: number;
  title: string;
  content: string;
  created_at: string;
  updated_at: string;
}

interface SignatureRequestRow {
  id: number;
  document_id: number;
  signer_email: string;
  status: "pending" | "signed";
  signed_at: string | null;
  created_at: string;
}

const createDocumentsTable = `
  CREATE TABLE IF NOT EXISTS documents (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    content TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );
`;

const createSignatureRequestsTable = `
  CREATE TABLE IF NOT EXISTS signature_requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    document_id INTEGER NOT NULL,
    signer_email TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending',
    signed_at TEXT,
    created_at TEXT NOT NULL,
    FOREIGN KEY (document_id) REFERENCES documents(id)
  );
`;

// Initialize tables
if (!db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='documents';").get()) {
  db.exec(createDocumentsTable);
}

if (!db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='signature_requests';").get()) {
  db.exec(createSignatureRequestsTable);
}

export function getAllDocuments(): DocumentRow[] {
  const stmt = db.prepare("SELECT * FROM documents ORDER BY created_at DESC;");
  return stmt.all() as unknown as DocumentRow[];
}

export function getDocumentById(id: number): DocumentRow | undefined {
  const stmt = db.prepare("SELECT * FROM documents WHERE id = ?;");
  return stmt.get(id) as unknown as DocumentRow | undefined;
}

export function insertDocument(title: string, content: string): number {
  const now = new Date().toISOString();
  const stmt = db.prepare(
    "INSERT INTO documents (title, content, created_at, updated_at) VALUES (?, ?, ?, ?);"
  );
  const result = stmt.run(title, content, now, now);
  return Number(result.lastInsertRowid);
}

export function updateDocument(id: number, title: string, content: string): void {
  const now = new Date().toISOString();
  const stmt = db.prepare(
    "UPDATE documents SET title = ?, content = ?, updated_at = ? WHERE id = ?;"
  );
  stmt.run(title, content, now, id);
}

export function deleteDocument(id: number): void {
  const stmt = db.prepare("DELETE FROM documents WHERE id = ?;");
  stmt.run(id);
}

export function getAllSignatureRequests(): SignatureRequestRow[] {
  const stmt = db.prepare("SELECT * FROM signature_requests ORDER BY created_at DESC;");
  return stmt.all() as unknown as SignatureRequestRow[];
}

export function getSignatureRequestsByDocumentId(documentId: number): SignatureRequestRow[] {
  const stmt = db.prepare("SELECT * FROM signature_requests WHERE document_id = ? ORDER BY created_at DESC;");
  return stmt.all(documentId) as unknown as SignatureRequestRow[];
}

export function insertSignatureRequest(
  documentId: number,
  signerEmail: string
): number {
  const now = new Date().toISOString();
  const stmt = db.prepare(
    "INSERT INTO signature_requests (document_id, signer_email, status, created_at) VALUES (?, ?, 'pending', ?);"
  );
  const result = stmt.run(documentId, signerEmail, now);
  return Number(result.lastInsertRowid);
}

export function updateSignatureRequestStatus(
  id: number,
  status: "pending" | "signed",
  signedAt?: string
): void {
  const stmt = db.prepare(
    "UPDATE signature_requests SET status = ?, signed_at = ? WHERE id = ?;"
  );
  stmt.run(status, signedAt || null, id);
}

export function deleteSignatureRequest(id: number): void {
  const stmt = db.prepare("DELETE FROM signature_requests WHERE id = ?;");
  stmt.run(id);
}

// Seed data
if (getAllDocuments().length === 0) {
  const doc1Id = insertDocument(
    "Employment Contract",
    "This agreement is made between the employer and employee..."
  );
  insertSignatureRequest(doc1Id, "employee@example.com");

  const doc2Id = insertDocument(
    "Service Agreement",
    "The service provider agrees to deliver services to the client..."
  );
  insertSignatureRequest(doc2Id, "client@example.com");

  const doc3Id = insertDocument(
    "NDA Document",
    "Confidentiality agreement between parties..."
  );
  insertSignatureRequest(doc3Id, "partner@example.com");
}
"}

