{"code":"import { useEffect, useState } from "react";

interface Walk {
  id: string;
  dogName: string;
  ownerName: string;
  walkDate: string;
  walkTime: string;
  status: "pending" | "accepted" | "declined";
}

export function WalkAcceptDeclineView() {
  const [walks, setWalks] = useState<Walk[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchWalks();
  }, []);

  const fetchWalks = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/walks-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch walks: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setWalks(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleAccept = async (id: string) => {
    try {
      const response = await fetch(`/api/walks-api/accept/${id}`, {
        method: "PUT",
      });
      if (!response.ok) {
        throw new Error(`Failed to accept walk: ${response.status} ${response.statusText}`);
      }
      fetchWalks(); // Refresh the list
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDecline = async (id: string) => {
    try {
      const response = await fetch(`/api/walks-api/decline/${id}`, {
        method: "PUT",
      });
      if (!response.ok) {
        throw new Error(`Failed to decline walk: ${response.status} ${response.statusText}`);
      }
      fetchWalks(); // Refresh the list
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (walks.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No walks available.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Walk Accept/Decline</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {walks.map((walk) => (
          <div
            key={walk.id}
            style={{
              border: "1px solid #ccc",
              borderRadius: "8px",
              padding: "15px",
              backgroundColor: "#f9f9f9",
            }}
          >
            <div style={{ marginBottom: "10px" }}>
              <strong>Dog:</strong> {walk.dogName}
            </div>
            <div style={{ marginBottom: "10px" }}>
              <strong>Owner:</strong> {walk.ownerName}
            </div>
            <div style={{ marginBottom: "10px" }}>
              <strong>Date:</strong> {walk.walkDate}
            </div>
            <div style={{ marginBottom: "10px" }}>
              <strong>Time:</strong> {walk.walkTime}
            </div>
            <div style={{ marginBottom: "10px" }}>
              <strong>Status:</strong> {walk.status}
            </div>
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                gap: "10px",
                flexWrap: "wrap",
              }}
            >
              <button
                onClick={() => handleAccept(walk.id)}
                style={{
                  padding: "8px 16px",
                  backgroundColor: "#4caf50",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  cursor: "pointer",
                }}
              >
                Accept
              </button>
              <button
                onClick={() => handleDecline(walk.id)}
                style={{
                  padding: "8px 16px",
                  backgroundColor: "#f44336",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  cursor: "pointer",
                }}
              >
                Decline
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./inventory.db");

interface Item {
  id: number;
  name: string;
  description: string;
  locationId: number;
  documentId: number | null;
}

interface Location {
  id: number;
  name: string;
  description: string;
}

interface Document {
  id: number;
  filename: string;
  path: string;
  uploadedAt: string;
}

const initSql = `
  CREATE TABLE IF NOT EXISTS items (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT,
    locationId INTEGER NOT NULL,
    documentId INTEGER,
    FOREIGN KEY (locationId) REFERENCES locations (id),
    FOREIGN KEY (documentId) REFERENCES documents (id)
  );

  CREATE TABLE IF NOT EXISTS locations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT
  );

  CREATE TABLE IF NOT EXISTS documents (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    filename TEXT NOT NULL,
    path TEXT NOT NULL,
    uploadedAt TEXT NOT NULL
  );
`;

db.exec(initSql);

export function getAllItems(): Item[] {
  const stmt = db.prepare(`SELECT * FROM items`);
  return stmt.all() as unknown as Item[];
}

export function getItemById(id: number): Item | undefined {
  const stmt = db.prepare(`SELECT * FROM items WHERE id = ?`);
  return stmt.get(id) as unknown as Item | undefined;
}

export function insertItem(item: Omit<Item, "id">): number {
  const stmt = db.prepare(
    `INSERT INTO items (name, description, locationId, documentId) VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(item.name, item.description, item.locationId, item.documentId);
  return Number(result.lastInsertRowid);
}

export function updateItem(id: number, item: Partial<Omit<Item, "id">>): boolean {
  const fields = [];
  const values = [];

  if (item.name !== undefined) {
    fields.push("name = ?");
    values.push(item.name);
  }
  if (item.description !== undefined) {
    fields.push("description = ?");
    values.push(item.description);
  }
  if (item.locationId !== undefined) {
    fields.push("locationId = ?");
    values.push(item.locationId);
  }
  if (item.documentId !== undefined) {
    fields.push("documentId = ?");
    values.push(item.documentId);
  }

  if (fields.length === 0) return false;

  values.push(id);
  const sql = `UPDATE items SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);
  return true;
}

export function deleteItem(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM items WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
}

// Sample data initialization
if (getAllItems().length === 0) {
  const locationIds = [1, 2, 3];
  const documentIds = [1, 2];

  // Insert sample locations
  const locationStmt = db.prepare(
    `INSERT INTO locations (name, description) VALUES (?, ?)`
  );
  locationStmt.run("Living Room", "Main living area");
  locationStmt.run("Kitchen", "Cooking area");
  locationStmt.run("Garage", "Storage space");

  // Insert sample documents
  const documentStmt = db.prepare(
    `INSERT INTO documents (filename, path, uploadedAt) VALUES (?, ?, ?)`
  );
  documentStmt.run(
    "manual.pdf",
    "/docs/manual.pdf",
    new Date().toISOString()
  );
  documentStmt.run(
    "specs.txt",
    "/docs/specs.txt",
    new Date().toISOString()
  );

  // Insert sample items
  const itemStmt = db.prepare(
    `INSERT INTO items (name, description, locationId, documentId) VALUES (?, ?, ?, ?)`
  );
  itemStmt.run(
    "Sofa",
    "Comfortable seating",
    locationIds[0],
    documentIds[0]
  );
  itemStmt.run(
    "Refrigerator",
    "Large food storage",
    locationIds[1],
    documentIds[1]
  );
  itemStmt.run(
    "Car",
    "Vehicle for transportation",
    locationIds[2],
    null
  );
  itemStmt.run(
    "Lamp",
    "Desk lighting",
    locationIds[0],
    null
  );
  itemStmt.run(
    "Dishwasher",
    "Appliance for cleaning dishes",
    locationIds[1],
    documentIds[0]
  );
}
"}

