  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedRoomId, setSelectedRoomId] = useState<number | null>(null);
  const [targetHousekeeperId, setTargetHousekeeperId] = useState<number>(0);

  useEffect(() => {
    fetchRooms();
  }, []);

  const fetchRooms = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/housekeeping-api/rooms");
      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }
      const data = await response.json();
      setRooms(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleReassign = async () => {
    if (selectedRoomId === null || targetHousekeeperId === 0) return;

    try {
      const response = await fetch(`/api/housekeeping-api/rooms/${selectedRoomId}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          housekeeperId: targetHousekeeperId,
        }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }

      // Refresh the room list after successful reassignment
      await fetchRooms();
      setSelectedRoomId(null);
      setTargetHousekeeperId(0);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Supervisor Reassignment Panel</h1>

      <div style={{ marginBottom: "20px" }}>
        <label htmlFor="roomSelect" style={{ display: "block", marginBottom: "5px" }}>
          Select Room:
        </label>
        <select
          id="roomSelect"
          value={selectedRoomId ?? ""}
          onChange={(e) => setSelectedRoomId(Number(e.target.value))}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="">-- Choose a room --</option>
          {rooms.map((room) => (
            <option key={room.id} value={room.id}>
              {room.roomNumber} ({room.status})
            </option>
          ))}
        </select>
      </div>

      <div style={{ marginBottom: "20px" }}>
        <label htmlFor="housekeeperSelect" style={{ display: "block", marginBottom: "5px" }}>
          Assign To Housekeeper:
        </label>
        <select
          id="housekeeperSelect"
          value={targetHousekeeperId}
          onChange={(e) => setTargetHousekeeperId(Number(e.target.value))}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="0">-- Choose a housekeeper --</option>
          <option value="1">Housekeeper 1</option>
          <option value="2">Housekeeper 2</option>
          <option value="3">Housekeeper 3</option>
        </select>
      </div>

      <button
        onClick={handleReassign}
        disabled={!selectedRoomId || targetHousekeeperId === 0}
        style={{
          backgroundColor: "#007bff",
          color: "white",
          border: "none",
          padding: "10px 20px",
          borderRadius: "4px",
          cursor: "pointer",
          width: "100%",
          fontSize: "16px",
        }}
      >
        Reassign Room
      </button>

      {rooms.length === 0 && !loading && (
        <p style={{ textAlign: "center", padding: "20px" }}>No rooms available.</p>
      )}
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteShortUrl,
  getAllShortUrls,
  getShortUrlById,
  insertShortUrl,
  updateShortUrlVisit
} from "../db/short-urls-table";

export const router = Router();

// GET /api/short-urls - Get all short URLs
router.get("/short-urls", (req: Request, res: Response) => {
  try {
    const shortUrls = getAllShortUrls();
    return res.json(shortUrls);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// GET /api/short-urls/:id - Get a short URL by ID
router.get("/short-urls/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID" });
    }

    const shortUrl = getShortUrlById(id);
    if (!shortUrl) {
      return res.status(404).json({ error: "Short URL not found" });
    }

    return res.json(shortUrl);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// POST /api/short-urls - Create a new short URL
router.post("/short-urls", (req: Request, res: Response) => {
  try {
    const { shortCode, targetUrl } = req.body;

    if (!shortCode || !targetUrl) {
      return res.status(400).json({ error: "shortCode and targetUrl are required" });
    }

    const id = insertShortUrl(shortCode, targetUrl);
    return res.status(201).json({ id, shortCode, targetUrl });
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// PUT /api/short-urls/:id/visit - Record a visit to a short URL
router.put("/short-urls/:id/visit", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID" });
    }

    const shortUrl = getShortUrlById(id);
    if (!shortUrl) {
      return res.status(404).json({ error: "Short URL not found" });
    }

    const { country } = req.body;
    updateShortUrlVisit(id, country || null);
    return res.json({ message: "Visit recorded" });
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// DELETE /api/short-urls/:id - Delete a short URL
router.delete("/short-urls/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID" });
    }

    const shortUrl = getShortUrlById(id);
    if (!shortUrl) {
      return res.status(404).json({ error: "Short URL not found" });
    }

    deleteShortUrl(id);
    return res.json({ message: "Short URL deleted" });
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});
"}

{"code":"import { Router, type Request, type Response } from "express";
import { getAllBookings } from "../db/bookings-table";

const router = Router();

router.get("/export", (req: Request, res: Response) => {
  // Check for owner token
  const ownerToken = req.headers["x-owner-token"];
  if (ownerToken !== "secret-owner-token") {
    return res.status(401).json({ error: "Unauthorized" });
  }

  // Get all bookings
  const bookings = getAllBookings();

  // Generate CSV content
  let csvContent = "id,guest_id,room_id,check_in_date,check_out_date\n";
  for (const booking of bookings) {
    csvContent += `${booking.id},${booking.guest_id},${booking.room_id},${booking.check_in_date},${booking.check_out_date}\n`;
  }

  // Send CSV response
  res.setHeader("Content-Type", "text/csv");
  res.setHeader("Content-Disposition", "attachment; filename=bookings.csv");
  res.status(200).send(csvContent);
});

export { router };
"}

