{"code":"import { useEffect, useState } from "react";

interface Doctor {
  id: number;
  name: string;
  specialty: string;
}

interface TimeSlot {
  id: number;
  date: string;
  time: string;
  doctorId: number;
}

interface Appointment {
  id: number;
  date: string;
  time: string;
  doctorId: number;
  patientName: string;
}

export function AppointmentBookingView() {
  const [doctors, setDoctors] = useState<Doctor[]>([]);
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>([]);
  const [selectedDoctorId, setSelectedDoctorId] = useState<number | null>(null);
  const [selectedTimeSlotId, setSelectedTimeSlotId] = useState<number | null>(null);
  const [patientName, setPatientName] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [appointments, setAppointments] = useState<Appointment[]>([]);

  useEffect(() => {
    fetchDoctors();
    fetchAppointments();
  }, []);

  const fetchDoctors = async () => {
    try {
      const response = await fetch('/api/appointments-api/');
      if (!response.ok) throw new Error('Failed to fetch doctors');
      const data = await response.json();
      setDoctors(data);
    } catch (err) {
      setError('Error loading doctors');
    } finally {
      setLoading(false);
    }
  };

  const fetchTimeSlots = async (doctorId: number) => {
    try {
      const response = await fetch(`/api/appointments-api/${doctorId}`);
      if (!response.ok) throw new Error('Failed to fetch time slots');
      const data = await response.json();
      setTimeSlots(data);
    } catch (err) {
      setError('Error loading time slots');
    }
  };

  const fetchAppointments = async () => {
    try {
      const response = await fetch('/api/appointments-api/');
      if (!response.ok) throw new Error('Failed to fetch appointments');
      const data = await response.json();
      setAppointments(data);
    } catch (err) {
      setError('Error loading appointments');
    }
  };

  const handleDoctorSelect = (doctorId: number) => {
    setSelectedDoctorId(doctorId);
    fetchTimeSlots(doctorId);
    setSelectedTimeSlotId(null);
  };

  const handleTimeSlotSelect = (timeSlotId: number) => {
    setSelectedTimeSlotId(timeSlotId);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedDoctorId || !selectedTimeSlotId || !patientName) return;

    try {
      const response = await fetch('/api/appointments-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          doctorId: selectedDoctorId,
          timeSlotId: selectedTimeSlotId,
          patientName
        })
      });

      if (!response.ok) throw new Error('Failed to book appointment');

      // Reset form
      setSelectedDoctorId(null);
      setSelectedTimeSlotId(null);
      setPatientName("");
      setTimeSlots([]);
      fetchAppointments();
    } catch (err) {
      setError('Error booking appointment');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  return (
    <div style={{
      maxWidth: '600px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <h1 style={{ textAlign: 'center' }}>Book an Appointment</h1>

      {error && <p style={{ color: 'red', textAlign: 'center' }}>{error}</p>}

      <form onSubmit={handleSubmit} style={{ marginBottom: '30px' }}>
        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="patientName" style={{ display: 'block', marginBottom: '5px' }}>
            Your Name
          </label>
          <input
            id="patientName"
            type="text"
            value={patientName}
            onChange={(e) => setPatientName(e.target.value)}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>
            Select Doctor
          </label>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
            {doctors.map(doctor => (
              <button
                key={doctor.id}
                type="button"
                onClick={() => handleDoctorSelect(doctor.id)}
                style={{
                  padding: '10px 15px',
                  borderRadius: '8px',
                  border: '1px solid #ccc',
                  backgroundColor: selectedDoctorId === doctor.id ? '#007bff' : '#fff',
                  color: selectedDoctorId === doctor.id ? '#fff' : '#000',
                  cursor: 'pointer'
                }}
              >
                {doctor.name}
              </button>
            ))}
          </div>
        </div>

        {selectedDoctorId && (
          <div style={{ marginBottom: '15px' }}>
            <label style={{ display: 'block', marginBottom: '5px' }}>
              Available Time Slots
            </label>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
              {timeSlots.length > 0 ? (
                timeSlots.map(slot => (
                  <button
                    key={slot.id}
                    type="button"
                    onClick={() => handleTimeSlotSelect(slot.id)}
                    style={{
                      padding: '10px 15px',
                      borderRadius: '8px',
                      border: '1px solid #ccc',
                      backgroundColor: selectedTimeSlotId === slot.id ? '#28a745' : '#fff',
                      color: selectedTimeSlotId === slot.id ? '#fff' : '#000',
                      cursor: 'pointer'
                    }}
                  >
                    {slot.date} {slot.time}
                  </button>
                ))
              ) : (
                <p>No time slots available</p>
              )}
            </div>
          </div>
        )}

        <button
          type="submit"
          disabled={!selectedTimeSlotId || !patientName}
          style={{
            padding: '12px 20px',
            backgroundColor: '#007bff',
            color: '#fff',
            border: 'none',
            borderRadius: '4px',
            cursor: selectedTimeSlotId && patientName ? 'pointer' : 'default'
          }}
        >
          Book Appointment
        </button>
      </form>

      <h2 style={{ textAlign: 'center' }}>Your Appointments</h2>
      {appointments.length > 0 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {appointments.map(appointment => (
            <div 
              key={appointment.id}
              style={{
                padding: '15px',
                border: '1px solid #ccc',
                borderRadius: '8px',
                backgroundColor: '#f8f9fa'
              }}
            >
              <div><strong>Date:</strong> {appointment.date}</div>
              <div><strong>Time:</strong> {appointment.time}</div>
              <div><strong>Doctor:</strong> {doctors.find(d => d.id === appointment.doctorId)?.name || 'Unknown'}</div>
              <div><strong>Patient:</strong> {appointment.patientName}</div>
            </div>
          ))}
        </div>
      ) : (
        <p style={{ textAlign: 'center' }}>No appointments booked yet.</p>
      )}
    </div>
  );
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply scope checking to GET requests to /members/:id
  if (req.method !== "GET" || !req.path.startsWith("/members/")) {
    next();
    return;
  }

  // Extract user ID from request (assuming it's set by auth middleware)
  const authenticatedUserId = (req as any).user?.id;

  // If no authenticated user, allow request to proceed (let other middleware handle it)
  if (!authenticatedUserId) {
    next();
    return;
  }

  // Extract target member ID from URL path
  const pathParts = req.path.split("/");
  const targetMemberId = pathParts[3];

  // If no target member ID, allow request to proceed
  if (!targetMemberId) {
    next();
    return;
  }

  // Check if the authenticated user is trying to access their own data
  if (authenticatedUserId === targetMemberId) {
    next();
    return;
  }

  // If the authenticated user is not accessing their own data, reject the request
  res.status(403).json({ error: "Forbidden: Access denied" });
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

const createTableSql = `
  CREATE TABLE IF NOT EXISTS commerce_records (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    type TEXT NOT NULL,
    data TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
  )
`;

db.exec(createTableSql);

export interface CommerceRecord {
  id: number;
  type: string;
  data: string;
  created_at: string;
  updated_at: string;
}

export function getAllRecords(): CommerceRecord[] {
  const stmt = db.prepare(`SELECT * FROM commerce_records`);
  return stmt.all() as unknown as CommerceRecord[];
}

export function getRecordById(id: number): CommerceRecord | undefined {
  const stmt = db.prepare(`SELECT * FROM commerce_records WHERE id = ?`);
  return stmt.get(id) as unknown as CommerceRecord | undefined;
}

export function insertRecord(type: string, data: string): number {
  const stmt = db.prepare(
    `INSERT INTO commerce_records (type, data) VALUES (?, ?)`
  );
  const result = stmt.run(type, data);
  return Number(result.lastInsertRowid);
}

export function updateRecord(id: number, type: string, data: string): boolean {
  const stmt = db.prepare(
    `UPDATE commerce_records SET type = ?, data = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?`
  );
  const result = stmt.run(type, data, id);
  return result.changes > 0;
}

export function deleteRecord(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM commerce_records WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
}

// Seed data
if (getAllRecords().length === 0) {
  insertRecord("product", "{\"name\": \"Wireless Headphones\", \"price\": 99.99}");
  insertRecord("order", "{\"customer_id\": 123, \"items\": [\"Wireless Headphones\"]}");
  insertRecord("product", "{\"name\": \"Smartphone\", \"price\": 699.99}");
  insertRecord("order", "{\"customer_id\": 456, \"items\": [\"Smartphone\"]}");
  insertRecord("product", "{\"name\": \"Laptop\", \"price\": 1299.99}");
}
"}

