  title: string;
  year: number;
  rating?: number;
}

export function RatingEntryForm() {
  const [movies, setMovies] = useState<Movie[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedMovieId, setSelectedMovieId] = useState<number | null>(null);
  const [rating, setRating] = useState<number | null>(null);

  useEffect(() => {
    fetchMovies();
  }, []);

  const fetchMovies = async () => {
    try {
      const response = await fetch("/api/watchlist-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch movies: ${response.status}`);
      }
      const data = await response.json();
      setMovies(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleRatingSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedMovieId === null || rating === null) return;

    try {
      const response = await fetch(`/api/watchlist-api/${selectedMovieId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ rating }),
      });

      if (!response.ok) {
        throw new Error(`Failed to update movie rating: ${response.status}`);
      }

      // Refresh the movie list
      await fetchMovies();
      setSelectedMovieId(null);
      setRating(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Rate Movies</h1>

      {movies.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No movies found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {movies
            .filter(movie => !movie.rating)
            .map(movie => (
              <div key={movie.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px", backgroundColor: "#f9f9f9" }}>
                <h3>{movie.title} ({movie.year})</h3>
                <button 
                  onClick={() => {
                    setSelectedMovieId(movie.id);
                    setRating(null);
                  }}
                  style={{ 
                    backgroundColor: "#007bff", 
                    color: "white", 
                    border: "none", 
                    borderRadius: "4px", 
                    padding: "8px 12px", 
                    cursor: "pointer", 
                    marginTop: "10px"
                  }}
                >
                  Rate This Movie
                </button>
              </div>
            ))}
        </div>
      )}

      {selectedMovieId !== null && (
        <form onSubmit={handleRatingSubmit} style={{ marginTop: "20px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px", backgroundColor: "#f9f9f9" }}>
          <h2>Rate Movie</h2>
          <p>Select a rating for the movie:</p>
          <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
            {[1, 2, 3, 4, 5].map(star => (
              <button
                key={star}
                type="button"
                onClick={() => setRating(star)}
                style={{ 
                  backgroundColor: rating && rating >= star ? "gold" : "lightgray", 
                  border: "none", 
                  borderRadius: "4px", 
                  padding: "8px 12px", 
                  cursor: "pointer"
                }}
              >
                {star}
              </button>
            ))}
          </div>
          <button 
            type="submit" 
            disabled={rating === null}
            style={{ 
              backgroundColor: "#28a745", 
              color: "white", 
              border: "none", 
              borderRadius: "4px", 
              padding: "10px 15px", 
              cursor: "pointer", 
              marginTop: "15px",
              opacity: rating === null ? 0.5 : 1
            }}
          >
            Submit Rating
          </button>
        </form>
      )}
    </div>
  );
}
