export const db = new DatabaseSync("recipe-box.db");

interface Recipe {
  id: number;
  title: string;
  ingredients: string;
  tags: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS recipes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    ingredients TEXT NOT NULL,
    tags TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllRecipes(): Recipe[] {
  const stmt = db.prepare("SELECT * FROM recipes");
  return stmt.all() as unknown as Recipe[];
}

export function getRecipeById(id: number): Recipe | undefined {
  const stmt = db.prepare("SELECT * FROM recipes WHERE id = ?");
  return stmt.get(id) as unknown as Recipe | undefined;
}

export function insertRecipe(title: string, ingredients: string, tags: string): number {
  const stmt = db.prepare(
    "INSERT INTO recipes (title, ingredients, tags) VALUES (?, ?, ?)"
  );
  const result = stmt.run(title, ingredients, tags);
  return Number(result.lastInsertRowid);
}

export function updateRecipe(id: number, title: string, ingredients: string, tags: string): number {
  const stmt = db.prepare(
    "UPDATE recipes SET title = ?, ingredients = ?, tags = ? WHERE id = ?"
  );
  const result = stmt.run(title, ingredients, tags, id);
  return Number(result.changes);
}

export function deleteRecipe(id: number): number {
  const stmt = db.prepare("DELETE FROM recipes WHERE id = ?");
  const result = stmt.run(id);
  return Number(result.changes);
}

