{"code":"import { useEffect, useState } from "react";

export function DeleteConfirmation() {
  const [photoId, setPhotoId] = useState<string | null>(null);
  const [photo, setPhoto] = useState<{ id: string; title: string } | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [confirming, setConfirming] = useState(false);

  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const id = urlParams.get("id");

    if (!id) {
      setError("No photo ID provided.");
      setLoading(false);
      return;
    }

    setPhotoId(id);

    fetch(`/api/photos-api/${id}`)
      .then(res => {
        if (!res.ok) throw new Error("Failed to fetch photo");
        return res.json();
      })
      .then(data => {
        setPhoto({ id: data.id, title: data.title });
        setLoading(false);
      })
      .catch(err => {
        setError(err.message);
        setLoading(false);
      });
  }, []);

  const handleDelete = () => {
    if (!photoId) return;

    setConfirming(true);

    fetch(`/api/photos-api/${photoId}`, { method: "DELETE" })
      .then(res => {
        if (!res.ok) throw new Error("Failed to delete photo");
        window.location.href = "/";
      })
      .catch(err => {
        setError(err.message);
        setConfirming(false);
      });
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px" }}>
        <h1>Error</h1>
        <p>{error}</p>
      </div>
    );
  }

  if (!photo) {
    return (
      <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px" }}>
        <h1>Photo Not Found</h1>
        <p>The requested photo could not be found.</p>
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px" }}>
      <h1>Delete Photo</h1>
      <p>Are you sure you want to delete the photo titled:</p>
      <div style={{ backgroundColor: "#f0f0f0", padding: "15px", borderRadius: "8px", marginBottom: "20px" }}>
        <strong>{photo.title}</strong>
      </div>
      <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
        <button 
          onClick={() => window.history.back()}
          style={{ flex: 1, minWidth: "120px", padding: "10px", backgroundColor: "#ccc", border: "none", borderRadius: "4px" }}
        >
          Cancel
        </button>
        <button 
          onClick={handleDelete}
          disabled={confirming}
          style={{ flex: 1, minWidth: "120px", padding: "10px", backgroundColor: "#d32f2f", color: "white", border: "none", borderRadius: "4px" }}
        >
          {confirming ? "Deleting..." : "Delete Photo"}
        </button>
      </div>
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface Plot {
  id: number;
  status: "available" | "reserved";
  current_reservation: string | null;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS plots (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    status TEXT NOT NULL,
    current_reservation TEXT
  )
`;

db.exec(createTableSql);

export function getAllPlots(): Plot[] {
  const stmt = db.prepare(`SELECT * FROM plots`);
  return stmt.all() as unknown as Plot[];
}

export function getPlotById(id: number): Plot | undefined {
  const stmt = db.prepare(`SELECT * FROM plots WHERE id = ?`);
  return stmt.get(id) as unknown as Plot | undefined;
}

export function insertPlot(plot: Omit<Plot, "id">): number {
  const stmt = db.prepare(
    `INSERT INTO plots (status, current_reservation) VALUES (?, ?)`
  );
  const result = stmt.run(plot.status, plot.current_reservation);
  return Number(result.lastInsertRowid);
}

export function updatePlot(id: number, plot: Partial<Plot>): boolean {
  const stmt = db.prepare(
    `UPDATE plots SET status = ?, current_reservation = ? WHERE id = ?`
  );
  const result = stmt.run(
    plot.status ?? "",
    plot.current_reservation ?? null,
    id
  );
  return result.changes > 0;
}

export function deletePlot(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM plots WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
}

// Sample data initialization
if (getAllPlots().length === 0) {
  insertPlot({
    status: "available",
    current_reservation: null
  });
  insertPlot({
    status: "reserved",
    current_reservation: "John Doe"
  });
  insertPlot({
    status: "available",
    current_reservation: null
  });
  insertPlot({
    status: "reserved",
    current_reservation: "Jane Smith"
  });
  insertPlot({
    status: "available",
    current_reservation: null
  });
}
