{"code":"import { useEffect, useState } from "react";

interface Device {
  id: string;
  name: string;
  type: string;
  status: "on" | "off";
}

export function DeviceDashboard() {
  const [devices, setDevices] = useState<Device[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchDevices();
  }, []);

  const fetchDevices = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/automation-engine/");
      if (!response.ok) {
        throw new Error(`Failed to fetch devices: ${response.status}`);
      }
      const data = await response.json();
      setDevices(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const toggleDevice = async (id: string, currentStatus: "on" | "off") => {
    try {
      const response = await fetch(`/api/automation-engine/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: currentStatus === "on" ? "off" : "on" }),
      });
      if (!response.ok) {
        throw new Error(`Failed to update device: ${response.status}`);
      }
      await fetchDevices();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const deleteDevice = async (id: string) => {
    try {
      const response = await fetch(`/api/automation-engine/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete device: ${response.status}`);
      }
      await fetchDevices();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Device Dashboard</h1>
      {devices.length === 0 ? (
        <p style={{ textAlign: "center", color: "#666" }}>No devices found.</p>
      ) : (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "15px",
          }}
        >
          {devices.map((device) => (
            <div
              key={device.id}
              style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "15px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                flexWrap: "wrap",
              }}
            >
              <div>
                <h3>{device.name}</h3>
                <p>Type: {device.type}</p>
                <p>Status: {device.status}</p>
              </div>
              <div style={{ display: "flex", gap: "10px" }}>
                <button
                  onClick={() => toggleDevice(device.id, device.status)}
                  style={{
                    backgroundColor: device.status === "on" ? "#ff4d4d" : "#50c878",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "8px 12px",
                    cursor: "pointer",
                  }}
                >
                  {device.status === "on" ? "Turn Off" : "Turn On"}
                </button>
                <button
                  onClick={() => deleteDevice(device.id)}
                  style={{
                    backgroundColor: "#808080",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "8px 12px",
                    cursor: "pointer",
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
