{"code":"import { useEffect, useState } from "react";

interface Comment {
  id: string;
  photoId: string;
  author: string;
  content: string;
  createdAt: string;
}

interface Photo {
  id: string;
  title: string;
  description: string;
  imageUrl: string;
  createdAt: string;
}

export function CommentBox() {
  const [photo, setPhoto] = useState<Photo | null>(null);
  const [comments, setComments] = useState<Comment[]>([]);
  const [newComment, setNewComment] = useState({
    author: "",
    content: ""
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [photoId, setPhotoId] = useState("1"); // Default photo ID

  useEffect(() => {
    const fetchPhotoAndComments = async () => {
      try {
        setLoading(true);
        const photoResponse = await fetch(`/api/photos-api/${photoId}`);
        if (!photoResponse.ok) throw new Error("Failed to fetch photo");
        const photoData: Photo = await photoResponse.json();
        setPhoto(photoData);

        const commentsResponse = await fetch(`/api/photos-api/${photoId}/comments`);
        if (!commentsResponse.ok) throw new Error("Failed to fetch comments");
        const commentsData: Comment[] = await commentsResponse.json();
        setComments(commentsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchPhotoAndComments();
  }, [photoId]);

  const handleAddComment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newComment.author.trim() || !newComment.content.trim()) return;

    try {
      const response = await fetch(`/api/photos-api/${photoId}/comments`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          author: newComment.author,
          content: newComment.content
        })
      });

      if (!response.ok) throw new Error("Failed to add comment");

      // Refresh comments after adding
      const commentsResponse = await fetch(`/api/photos-api/${photoId}/comments`);
      if (!commentsResponse.ok) throw new Error("Failed to fetch comments");
      const commentsData: Comment[] = await commentsResponse.json();
      setComments(commentsData);

      // Reset form
      setNewComment({ author: "", content: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  if (!photo) return <div style={{ textAlign: "center", padding: "20px" }}>No photo found</div>;

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>Photo Comments</h1>

      <div style={styles.photoCard}>
        <img 
          src={photo.imageUrl} 
          alt={photo.title} 
          style={styles.photoImage} 
        />
        <h2>{photo.title}</h2>
        <p>{photo.description}</p>
      </div>

      <form onSubmit={handleAddComment} style={styles.commentForm}>
        <input
          type="text"
          placeholder="Your Name"
          value={newComment.author}
          onChange={(e) => setNewComment({...newComment, author: e.target.value})}
          style={styles.input}
        />
        <textarea
          placeholder="Add a comment..."
          value={newComment.content}
          onChange={(e) => setNewComment({...newComment, content: e.target.value})}
          style={styles.textarea}
        />
        <button type="submit" style={styles.submitButton}>Add Comment</button>
      </form>

      <div style={styles.commentsSection}>
        <h3>Comments ({comments.length})</h3>
        {comments.length === 0 ? (
          <p style={styles.noComments}>No comments yet. Be the first to comment!</p>
        ) : (
          <div style={styles.commentsList}>
            {comments.map(comment => (
              <div key={comment.id} style={styles.commentCard}>
                <strong>{comment.author}</strong>
                <p>{comment.content}</p>
                <small>{new Date(comment.createdAt).toLocaleString()}</small>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

const styles = {
