{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteBoxCustomization,
  getAllBoxCustomizations,
  getBoxCustomizationById,
  insertBoxCustomization,
  updateBoxCustomization
} from "../db/box-customizations-table";

export const router = Router();

// Get all box customizations
router.get("/", (req: Request, res: Response) => {
  try {
    const customizations = getAllBoxCustomizations();
    return res.json(customizations);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch customizations" });
  }
});

// Get a specific box customization by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID provided" });
  }

  const customization = getBoxCustomizationById(id);

  if (!customization) {
    return res.status(404).json({ error: "Customization not found" });
  }

  return res.json(customization);
});

// Create a new box customization
router.post("/", (req: Request, res: Response) => {
  const { memberId, contents } = req.body;

  if (!memberId || !contents) {
    return res.status(400).json({ error: "Member ID and contents are required" });
  }

  try {
    const id = insertBoxCustomization(Number(memberId), contents);
    return res.status(201).json({ id, memberId, contents });
  } catch (error) {
    return res.status(500).json({ error: "Failed to create customization" });
  }
});

// Update an existing box customization
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { memberId, contents } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID provided" });
  }

  if (!memberId || !contents) {
    return res.status(400).json({ error: "Member ID and contents are required" });
  }

  try {
    updateBoxCustomization(id, Number(memberId), contents);
    return res.json({ id, memberId, contents });
  } catch (error) {
    return res.status(500).json({ error: "Failed to update customization" });
  }
});

// Delete a box customization
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID provided" });
  }

  try {
    deleteBoxCustomization(id);
    return res.json({ message: "Customization deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete customization" });
  }
});
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "./time_tracking.db"
);

export interface TimeEntry {
  id: number;
  description: string;
  hours: number;
  rate: number;
  budget_id: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS time_entries (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    description TEXT NOT NULL,
    hours REAL NOT NULL,
    rate REAL NOT NULL,
    budget_id INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllTimeEntries(): TimeEntry[] {
  const stmt = db.prepare(
    "SELECT * FROM time_entries ORDER BY id ASC"
  );
  return stmt.all() as unknown as TimeEntry[];
}

export function getTimeEntryById(id: number): TimeEntry | undefined {
  const stmt = db.prepare(
    "SELECT * FROM time_entries WHERE id = ?"
  );
  return stmt.get(id) as unknown as TimeEntry | undefined;
}

export function insertTimeEntry(
  description: string,
  hours: number,
  rate: number,
  budget_id: number
): number {
  const stmt = db.prepare(
    "INSERT INTO time_entries (description, hours, rate, budget_id) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(description, hours, rate, budget_id);
  return Number(result.lastInsertRowid);
}

export function updateTimeEntry(
  id: number,
  description: string,
  hours: number,
  rate: number,
  budget_id: number
): void {
  const stmt = db.prepare(
    "UPDATE time_entries SET description = ?, hours = ?, rate = ?, budget_id = ? WHERE id = ?"
  );
  stmt.run(description, hours, rate, budget_id, id);
}

export function deleteTimeEntry(id: number): void {
  const stmt = db.prepare("DELETE FROM time_entries WHERE id = ?");
  stmt.run(id);
}

// Seed data
if (getAllTimeEntries().length === 0) {
