{"code":"import type { Request, Response, NextFunction } from "express";
import { router } from "../routes/machine-tracker-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply this guard to POST requests to the /fix endpoint
  if (req.method !== "POST" || req.path !== "/fix") {
    return next();
  }

  // Check if the user is a maintenance staff member
  const isMaintenanceStaff = req.body.isMaintenanceStaff;
  if (!isMaintenanceStaff) {
    res.status(403).send("Access denied: Only maintenance staff can perform fixes.");
    return;
  }

  // If the user is a maintenance staff member, proceed to the next middleware or route handler
  next();
}
"}

