import { router as reservationsRouter } from "../routes/reservations-api";
import { router as exportServiceRouter } from "../routes/export-service";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply to export service routes
  if (!req.path.startsWith('/export')) {
    next();
    return;
  }

  // Check if user has owner role
  const userRole = req.headers['x-user-role'] as string | undefined;

  if (userRole !== 'owner') {
