{"code":"import { Router, type Request, type Response } from "express";
import { 
  getAllSubmissions,
  getSubmissionById,
  insertSubmission,
  updateSubmission,
  deleteSubmission
} from "../db/submissions-table";
import { 
  getAllExports,
  getExportById,
  insertExport,
  updateExport,
  deleteExport
} from "../db/exports-table";

export const router = Router();

// Get all submissions for the author
router.get("/submissions", (req: Request, res: Response) => {
  try {
    const submissions = getAllSubmissions();
    res.json(submissions);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch submissions" });
  }
});

// Get a specific submission by ID
router.get("/submissions/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid submission ID" });
    }

    const submission = getSubmissionById(id);
    if (!submission) {
      return res.status(404).json({ error: "Submission not found" });
    }

    res.json(submission);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch submission" });
  }
});

// Create a new submission
router.post("/submissions", (req: Request, res: Response) => {
  try {
    const { manuscriptText, authorId } = req.body;

    if (!manuscriptText || !authorId) {
      return res.status(400).json({ error: "Manuscript text and author ID are required" });
    }

    const newId = insertSubmission(manuscriptText, authorId);
    const newSubmission = getSubmissionById(newId);

    if (!newSubmission) {
      return res.status(500).json({ error: "Failed to create submission" });
    }

    res.status(201).json(newSubmission);
  } catch (error) {
    res.status(500).json({ error: "Failed to create submission" });
  }
});

// Update a submission
router.put("/submissions/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { manuscriptText, authorId } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid submission ID" });
    }

    if (!manuscriptText || !authorId) {
      return res.status(400).json({ error: "Manuscript text and author ID are required" });
    }

    const updatedId = updateSubmission(id, manuscriptText, authorId);
    const updatedSubmission = getSubmissionById(updatedId);

    if (!updatedSubmission) {
      return res.status(404).json({ error: "Submission not found" });
    }

    res.json(updatedSubmission);
  } catch (error) {
    res.status(500).json({ error: "Failed to update submission" });
  }
});

// Delete a submission
router.delete("/submissions/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid submission ID" });
    }

    const deletedId = deleteSubmission(id);

    if (deletedId === 0) {
      return res.status(404).json({ error: "Submission not found" });
    }

    res.json({ message: "Submission deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete submission" });
  }
});

// Get all exports for the author
router.get("/exports", (req: Request, res: Response) => {
  try {
    const exports = getAllExports();
    res.json(exports);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch exports" });
  }
});

// Get a specific export by ID
router.get("/exports/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid export ID" });
    }

    const exportRecord = getExportById(id);
    if (!exportRecord) {
      return res.status(404).json({ error: "Export not found" });
    }

    res.json(exportRecord);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch export" });
  }
});

// Create a new export
router.post("/exports", (req: Request, res: Response) => {
  try {
    const { authorId, manuscriptId, exportDate, format } = req.body;

    if (!authorId || !manuscriptId || !exportDate || !format) {
      return res.status(400).json({ error: "Author ID, manuscript ID, export date and format are required" });
    }

    const newId = insertExport(authorId, manuscriptId, exportDate, format);
    const newExport = getExportById(newId);

    if (!newExport) {
      return res.status(500).json({ error: "Failed to create export" });
    }

    res.status(201).json(newExport);
  } catch (error) {
    res.status(500).json({ error: "Failed to create export" });
  }
});

// Update an export
router.put("/exports/:id", (req: Request, res: Response) => {
  try {
