export const db = new DatabaseSync("./coop-grocery.db");

interface WaiverRow {
  board_member_id: number;
  claimed_member_id: number;
  waived_slot_id: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS waivers (
    board_member_id INTEGER NOT NULL,
    claimed_member_id INTEGER NOT NULL,
    waived_slot_id INTEGER NOT NULL,
    PRIMARY KEY (board_member_id, claimed_member_id, waived_slot_id)
  )
`;

db.exec(createTableSql);

export function getAllWaivers(): WaiverRow[] {
  const stmt = db.prepare("SELECT * FROM waivers");
  return stmt.all() as unknown as WaiverRow[];
}

export function getWaiverById(
  boardMemberId: number,
  claimedMemberId: number,
  waivedSlotId: number
): WaiverRow | undefined {
  const stmt = db.prepare(
    "SELECT * FROM waivers WHERE board_member_id = ? AND claimed_member_id = ? AND waived_slot_id = ?"
  );
  return stmt.get(boardMemberId, claimedMemberId, waivedSlotId) as unknown as WaiverRow | undefined;
}

export function insertWaiver(
  boardMemberId: number,
  claimedMemberId: number,
  waivedSlotId: number
): number {
  const stmt = db.prepare(
    "INSERT INTO waivers (board_member_id, claimed_member_id, waived_slot_id) VALUES (?, ?, ?)"
  );
  const result = stmt.run(boardMemberId, claimedMemberId, waivedSlotId);
  return Number(result.lastInsertRowid);
}

export function updateWaiver(
  boardMemberId: number,
  claimedMemberId: number,
  waivedSlotId: number,
  newBoardMemberId: number,
  newClaimedMemberId: number,
  newWaivedSlotId: number
): number {
  const stmt = db.prepare(
    "UPDATE waivers SET board_member_id = ?, claimed_member_id = ?, waived_slot_id = ? WHERE board_member_id = ? AND claimed_member_id = ? AND waived_slot_id = ?"
  );
  const result = stmt.run(
    newBoardMemberId,
    newClaimedMemberId,
    newWaivedSlotId,
    boardMemberId,
    claimedMemberId,
    waivedSlotId
  );
  return Number(result.changes);
}

export function deleteWaiver(
  boardMemberId: number,
  claimedMemberId: number,
  waivedSlotId: number
): number {
  const stmt = db.prepare(
    "DELETE FROM waivers WHERE board_member_id = ? AND claimed_member_id = ? AND waived_slot_id = ?"
  );
  const result = stmt.run(boardMemberId, claimedMemberId, waivedSlotId);
  return Number(result.changes);
}

