{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteCheckout,
  getAllCheckouts,
  getCheckoutById,
  insertCheckout,
  updateCheckout
} from "../db/checkouts-table";

export const router = Router();

// Get all checkouts
router.get("/", (req: Request, res: Response) => {
  try {
    const checkouts = getAllCheckouts();
    res.json(checkouts);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch checkouts" });
  }
});

// Get a checkout by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid checkout ID" });
    }

    const checkout = getCheckoutById(id);
    if (!checkout) {
      return res.status(404).json({ error: "Checkout not found" });
    }

    res.json(checkout);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch checkout" });
  }
});

// Create a new checkout
router.post("/", (req: Request, res: Response) => {
  try {
    const { studentId, bookIsbn, date } = req.body;

    if (!studentId || !bookIsbn || !date) {
      return res.status(400).json({ error: "Missing required fields: studentId, bookIsbn, date" });
    }

    const id = insertCheckout(Number(studentId), bookIsbn, date);
    res.status(201).json({ id, studentId, bookIsbn, date });
  } catch (error) {
    res.status(500).json({ error: "Failed to create checkout" });
  }
});

// Update a checkout
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { studentId, bookIsbn, date } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid checkout ID" });
    }

    if (!studentId || !bookIsbn || !date) {
      return res.status(400).json({ error: "Missing required fields: studentId, bookIsbn, date" });
    }

    const existingCheckout = getCheckoutById(id);
    if (!existingCheckout) {
      return res.status(404).json({ error: "Checkout not found" });
    }

    updateCheckout(id, Number(studentId), bookIsbn, date);
    res.json({ id, studentId, bookIsbn, date });
  } catch (error) {
    res.status(500).json({ error: "Failed to update checkout" });
  }
});

// Delete a checkout
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid checkout ID" });
    }

    const existingCheckout = getCheckoutById(id);
    if (!existingCheckout) {
      return res.status(404).json({ error: "Checkout not found" });
    }

    deleteCheckout(id);
    res.json({ message: "Checkout deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete checkout" });
  }
});
"}

