{"code":"import { useEffect, useState } from "react";

interface Desk {
  id: string;
  location: string;
  isAvailable: boolean;
}

interface Booking {
  id: string;
  deskId: string;
  memberId: string;
  date: string;
}

export function DeskBookingView() {
  const [desks, setDesks] = useState<Desk[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);

  useEffect(() => {
    fetchDesks();
    fetchBookings();
  }, []);

  const fetchDesks = async () => {
    try {
      const response = await fetch('/api/bookings-api/');
      if (!response.ok) throw new Error('Failed to fetch desks');
      const data = await response.json();
      setDesks(data);
    } catch (err) {
      setError('Error loading desks');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchBookings = async () => {
    try {
      const response = await fetch('/api/bookings-api/');
      if (!response.ok) throw new Error('Failed to fetch bookings');
      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError('Error loading bookings');
      console.error(err);
    }
  };

  const handleBookDesk = async (deskId: string) => {
    try {
      const response = await fetch('/api/bookings-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          deskId,
          memberId: 'member-123', // In a real app, this would come from auth
          date: selectedDate
        })
      });

      if (!response.ok) throw new Error('Failed to book desk');

      await fetchDesks();
      await fetchBookings();
    } catch (err) {
      setError('Error booking desk');
      console.error(err);
    }
  };

  const handleCancelBooking = async (bookingId: string) => {
    try {
      const response = await fetch(`/api/bookings-api/${bookingId}`, {
        method: 'DELETE'
      });

      if (!response.ok) throw new Error('Failed to cancel booking');

      await fetchDesks();
      await fetchBookings();
    } catch (err) {
      setError('Error cancelling booking');
      console.error(err);
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;

  const today = new Date().toISOString().split('T')[0];
  const tomorrow = new Date(Date.now() + 86400000).toISOString().split('T')[0];
  const dayAfterTomorrow = new Date(Date.now() + 172800000).toISOString().split('T')[0];

  const availableDesks = desks.filter(desk => desk.isAvailable);
  const userBookings = bookings.filter(booking => booking.memberId === 'member-123');

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Desk Booking</h1>

      <div style={{ marginBottom: '20px' }}>
        <label htmlFor="date-select" style={{ display: 'block', marginBottom: '5px' }}>
          Select Date:
        </label>
        <select 
          id="date-select"
          value={selectedDate}
          onChange={(e) => setSelectedDate(e.target.value)}
          style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
        >
          <option value={today}>Today</option>
          <option value={tomorrow}>Tomorrow</option>
          <option value={dayAfterTomorrow}>Day after tomorrow</option>
        </select>
      </div>

      <h2 style={{ marginTop: '30px' }}>Available Desks</h2>

      {availableDesks.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No desks available for this date.</p>
      ) : (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px' }}>
          {availableDesks.map(desk => (
            <div 
              key={desk.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                width: '200px', 
                backgroundColor: '#f9f9f9'
              }}
            >
              <h3 style={{ margin: '0 0 10px 0' }}>Desk {desk.id}</h3>
              <p style={{ margin: '0 0 10px 0' }}>{desk.location}</p>
              <button 
                onClick={() => handleBookDesk(desk.id)}
                style={{ 
                  backgroundColor: '#007bff', 
                  color: 'white', 
                  border: 'none', 
                  padding: '8px 12px', 
                  borderRadius: '4px', 
                  cursor: 'pointer', 
                  width: '100%'
                }}
              >
                Book This Desk
              </button>
            </div>
          ))}
        </div>
      )}

      <h2 style={{ marginTop: '30px' }}>Your Bookings</h2>

      {userBookings.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>You have no bookings for this date.</p>
      ) : (
        <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '20px' }}>
          <thead>
            <tr style={{ borderBottom: '1px solid #ccc' }}>
              <th style={{ padding: '10px', textAlign: 'left' }}>Desk ID</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Location</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {userBookings.map(booking => {
              const desk = desks.find(d => d.id === booking.deskId);
              return (
                <tr key={booking.id} style={{ borderBottom: '1px solid #eee' }}>
                  <td style={{ padding: '10px' }}>{desk?.id || 'Unknown'}</td>
                  <td style={{ padding: '10px' }}>{desk?.location || 'Unknown'}</td>
                  <td style={{ padding: '10px' }}>
                    <button 
                      onClick={() => handleCancelBooking(booking.id)}
                      style={{ 
                        backgroundColor: '#dc3545', 
                        color: 'white', 
                        border: 'none', 
                        padding: '5px 10px', 
                        borderRadius: '4px', 
                        cursor: 'pointer'
                      }}
                    >
                      Cancel
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </div>
  );
}
"}

