{"code":"import { Router, type Request, type Response } from "express";
import { Room, getRoom, getAllRooms, updatePlayerCount } from "../db/rooms-table";

export const router = Router();

router.get("/rooms", (req: Request, res: Response) => {
  const rooms = getAllRooms();
  res.json(rooms);
});

router.get("/rooms/:roomCode", (req: Request, res: Response) => {
  const roomCode = req.params.roomCode;
  const room = getRoom(roomCode);
  if (room) {
    res.json(room);
  } else {
    res.status(404).send(`Room with code ${roomCode} not found.`);
  }
});

router.post("/rooms/:roomCode/join", (req: Request, res: Response) => {
  const roomCode = req.params.roomCode;
  const room = getRoom(roomCode);
  if (room) {
    updatePlayerCount(roomCode, room.playerCount + 1);
    res.status(200).send(`Joined room ${roomCode}. New player count: ${room.playerCount + 1}`);
  } else {
    res.status(404).send(`Room with code ${roomCode} not found.`);
  }
});

router.post("/rooms/:roomCode/leave", (req: Request, res: Response) => {
  const roomCode = req.params.roomCode;
  const room = getRoom(roomCode);
  if (room && room.playerCount > 0) {
    updatePlayerCount(roomCode, room.playerCount - 1);
    res.status(200).send(`Left room ${roomCode}. New player count: ${room.playerCount - 1}`);
  } else if (room) {
    res.status(400).send(`Room with code ${roomCode} has no players to leave.`);
  } else {
    res.status(404).send(`Room with code ${roomCode} not found.`);
  }
});
"}

{"code":"import { useEffect, useState } from "react";

interface Reservation {
  id: string;
  date: string;
  time: string;
  guestCount: number;
}

interface TimeSlot {
  time: string;
  available: boolean;
}

export function ReservationCalendar() {
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedDate, setSelectedDate] = useState<string>("");
  const [selectedTime, setSelectedTime] = useState<string>("");
  const [guestCount, setGuestCount] = useState<number>(2);
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>([]);

  useEffect(() => {
    fetchReservations();
  }, []);

  const fetchReservations = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/reservations-api/reservations');
      if (!response.ok) {
        throw new Error('Failed to fetch reservations');
      }
      const data = await response.json();
      setReservations(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleDateChange = (date: string) => {
    setSelectedDate(date);
    // In a real app, we would fetch available times for this date
    // For now, we'll simulate with static data
    const mockTimeSlots: TimeSlot[] = [
      { time: '12:00', available: true },
      { time: '13:00', available: false },
      { time: '14:00', available: true },
      { time: '15:00', available: true },
      { time: '16:00', available: false },
      { time: '17:00', available: true },
    ];
    setTimeSlots(mockTimeSlots);
    setSelectedTime("");
  };

  const handleTimeChange = (time: string) => {
    setSelectedTime(time);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedDate || !selectedTime) return;

    try {
      const response = await fetch('/api/reservations-api/reservations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          date: selectedDate,
          time: selectedTime,
          guestCount,
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to create reservation');
      }

      // Refresh the list
      await fetchReservations();

      // Reset form
      setSelectedDate("");
      setSelectedTime("");
      setGuestCount(2);
      setTimeSlots([]);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Book Your Tasting Room Reservation</h1>

      <div style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h2>Available Dates</h2>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
          {["2023-06-15", "2023-06-16", "2023-06-17", "2023-06-18", "2023-06-19"].map(date => (
            <button
              key={date}
              onClick={() => handleDateChange(date)}
              style={{
                padding: '10px 15px',
                border: '1px solid #007bff',
                backgroundColor: selectedDate === date ? '#007bff' : 'white',
                color: selectedDate === date ? 'white' : '#007bff',
                borderRadius: '4px',
                cursor: 'pointer',
                flex: '1 1 auto',
                minWidth: '100px'
              }}
            >
              {date}
            </button>
          ))}
        </div>

        {selectedDate && (
          <>
            <h2 style={{ marginTop: '20px' }}>Available Times</h2>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
              {timeSlots.map(slot => (
                <button
                  key={slot.time}
                  onClick={() => handleTimeChange(slot.time)}
                  disabled={!slot.available}
                  style={{
                    padding: '10px 15px',
                    border: '1px solid #007bff',
                    backgroundColor: selectedTime === slot.time ? '#007bff' : slot.available ? 'white' : '#f8f9fa',
                    color: selectedTime === slot.time ? 'white' : slot.available ? '#007bff' : '#6c757d',
                    borderRadius: '4px',
                    cursor: slot.available ? 'pointer' : 'default',
                    flex: '1 1 auto',
                    minWidth: '100px'
                  }}
                >
                  {slot.time} {slot.available ? '' : '(booked)'}
                </button>
              ))}
            </div>

            <form onSubmit={handleSubmit} style={{ marginTop: '20px' }}>
              <div style={{ marginBottom: '15px' }}>
                <label htmlFor="guestCount" style={{ display: 'block', marginBottom: '5px' }}>
                  Number of Guests:
                </label>
                <input
                  id="guestCount"
                  type="number"
                  min="1"
                  max="10"
                  value={guestCount}
                  onChange={(e) => setGuestCount(Number(e.target.value))}
                  style={{ width: '100%', padding: '8px', border: '1px solid #ccc', borderRadius: '4px' }}
                />
              </div>

              <button
                type="submit"
                disabled={!selectedTime}
                style={{
                  padding: '10px 20px',
                  backgroundColor: selectedTime ? '#28a745' : '#6c757d',
                  color: 'white',
                  border: 'none',
                  borderRadius: '4px',
                  cursor: selectedTime ? 'pointer' : 'default',
                  fontSize: '16px'
                }}
              >
                Book Reservation
              </button>
            </form>
          </>
        )}
      </div>

      <h2>Upcoming Reservations</h2>
      {reservations.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No upcoming reservations.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {reservations.map(reservation => (
            <div 
              key={reservation.id} 
              style={{ 
                padding: '15px', 
                border: '1px solid #ddd', 
                borderRadius: '8px', 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center'
              }}
            >
              <div>
                <strong>{reservation.date}</strong> at {reservation.time} ({reservation.guestCount} guests)
              </div>
              <button 
                onClick={async () => {
                  await fetch(`/api/reservations-api/reservations/${reservation.id}`, { method: 'DELETE' });
                  await fetchReservations();
                }}
                style={{ 
                  padding: '5px 10px', 
                  backgroundColor: '#dc3545', 
                  color: 'white', 
                  border: 'none', 
                  borderRadius: '4px', 
                  cursor: 'pointer'
                }}
              >
                Cancel
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

