{"code":"import { useEffect, useState } from "react";

interface Slot {
  id: string;
  showId: string;
  startTime: string;
  endTime: string;
  claimedBy?: string;
}

interface Show {
  id: string;
  title: string;
}

export function AirtimeSlotClaimUi() {
  const [slots, setSlots] = useState<Slot[]>([]);
  const [shows, setShows] = useState<Show[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchSlots();
    fetchShows();
  }, []);

  const fetchSlots = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/scheduling-api/');
      if (!response.ok) throw new Error('Failed to fetch slots');
      const data = await response.json();
      setSlots(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const fetchShows = async () => {
    try {
      const response = await fetch('/api/scheduling-api/shows');
      if (!response.ok) throw new Error('Failed to fetch shows');
      const data = await response.json();
      setShows(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleClaimSlot = async (slotId: string) => {
    try {
      const response = await fetch(`/api/scheduling-api/${slotId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ claimedBy: 'current-dj' }),
      });

      if (!response.ok) throw new Error('Failed to claim slot');
      await fetchSlots(); // Refresh the list
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;

  const unclaimedSlots = slots.filter(slot => !slot.claimedBy);

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Airtime Slot Claim</h1>

      {unclaimedSlots.length === 0 ? (
        <p style={{ textAlign: 'center' }}>No available slots to claim.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {unclaimedSlots.map(slot => {
            const show = shows.find(s => s.id === slot.showId);
            return (
              <div key={slot.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div>
                    <h3>{show?.title || 'Unknown Show'}</h3>
                    <p>{new Date(slot.startTime).toLocaleTimeString()} - {new Date(slot.endTime).toLocaleTimeString()}</p>
                  </div>
                  <button 
                    onClick={() => handleClaimSlot(slot.id)}
                    style={{ backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', padding: '8px 16px', cursor: 'pointer' }}
                  >
                    Claim Slot
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
"}

