  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchHabits = async () => {
      try {
        const response = await fetch('/api/habits-api/');
        if (!response.ok) throw new Error('Failed to fetch habits');
        const data = await response.json();
        setHabits(data);
      } catch (err) {
        setError('Failed to load habits');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    const fetchLogs = async () => {
      try {
        const response = await fetch(`/api/habits-api/123/${selectedDate}`);
        if (!response.ok) throw new Error('Failed to fetch logs');
        const data = await response.json();
        setLogs(data);
      } catch (err) {
        setError('Failed to load logs');
        console.error(err);
      }
    };

    fetchHabits();
    fetchLogs();
  }, [selectedDate]);

  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSelectedDate(e.target.value);
  };

  const handleHabitToggle = (habitId: string) => {
    setSelectedHabits(prev => 
      prev.includes(habitId)
        ? prev.filter(id => id !== habitId)
        : [...prev, habitId]
    );
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch('/api/habits-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          date: selectedDate,
          habitIds: selectedHabits
        })
      });

      if (!response.ok) throw new Error('Failed to save log');

      // Refresh data after successful submission
      const logsResponse = await fetch(`/api/habits-api/123/${selectedDate}`);
      if (logsResponse.ok) {
        const logsData = await logsResponse.json();
        setLogs(logsData);
      }

      setSelectedHabits([]);
    } catch (err) {
      setError('Failed to save log');
      console.error(err);
    }
  };

  const handleDelete = async (logId: string) => {
    try {
      const response = await fetch(`/api/habits-api/${logId}`, {
        method: 'DELETE'
      });

      if (!response.ok) throw new Error('Failed to delete log');

      // Refresh data after successful deletion
      const logsResponse = await fetch(`/api/habits-api/123/${selectedDate}`);
      if (logsResponse.ok) {
        const logsData = await logsResponse.json();
        setLogs(logsData);
      }
    } catch (err) {
      setError('Failed to delete log');
      console.error(err);
    }
