{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply authentication to POST requests to the login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if credentials are provided
  if (!req.body || !req.body.username || !req.body.password) {
    res.status(401).json({ error: "Username and password required" });
    return;
  }

  // In a real system, we would check the credentials against a database
  // For this basic implementation, we'll just accept any non-empty credentials
  const { username, password } = req.body;

  if (username.trim() === "" || password.trim() === "") {
    res.status(401).json({ error: "Invalid credentials" });
    return;
  }

  // If we get here, credentials are valid
  next();
}
"}

