{"code":"import { useEffect, useState } from "react";

interface Article {
  id: string;
  title: string;
  url: string;
  content: string;
  createdAt: string;
}

export function ReadingList() {
  const [articles, setArticles] = useState<Article[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchArticles();
  }, []);

  const fetchArticles = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/content-extraction-service/');
      if (!response.ok) {
        throw new Error(`Failed to fetch articles: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setArticles(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const deleteArticle = async (id: string) => {
    try {
      const response = await fetch(`/api/content-extraction-service/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error(`Failed to delete article: ${response.status} ${response.statusText}`);
      }
      // Refresh the list after deletion
      await fetchArticles();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>
        Error: {error}
      </div>
    );
  }

  if (articles.length === 0) {
    return (
      <div style={{ textAlign: 'center', padding: '20px' }}>
        No articles saved yet.
      </div>
    );
  }

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif',
    }}>
      <h1 style={{ textAlign: 'center' }}>Saved Articles</h1>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        {articles.map((article) => (
          <div 
            key={article.id}
            style={{
              border: '1px solid #ccc',
              borderRadius: '8px',
              padding: '15px',
              backgroundColor: '#f9f9f9',
            }}
          >
            <h2 style={{ margin: '0 0 10px 0' }}>{article.title}</h2>
            <p style={{ margin: '0 0 10px 0' }}>
              <a 
                href={article.url}
                target="_blank"
                rel="noopener noreferrer"
                style={{ color: '#0066cc' }}
              >
                View Original
              </a>
            </p>
            <p style={{ margin: '0 0 10px 0' }}>
              {article.content.substring(0, 200)}...
            </p>
            <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
              <button
                onClick={() => deleteArticle(article.id)}
                style={{
                  backgroundColor: '#ff4d4d',
                  color: 'white',
                  border: 'none',
                  borderRadius: '4px',
                  padding: '5px 10px',
                  cursor: 'pointer',
                }}
              >
                Delete
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
"}

