{"code":"import { useEffect, useState } from "react";

interface Shift {
  id: string;
  slotId: string;
  date: string;
  startTime: string;
  endTime: string;
  position: string;
  claimedBy?: string;
}

interface Waiver {
  boardMemberId: string;
  claimedMemberId: string;
  waivedSlotId: string;
}

export function ShiftClaimBoard() {
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [memberId, setMemberId] = useState("");
  const [waivers, setWaivers] = useState<Waiver[]>([]);

  useEffect(() => {
    fetchShifts();
    fetchWaivers();
  }, []);

  const fetchShifts = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/shifts-api/shifts');
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setShifts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const fetchWaivers = async () => {
    try {
      const response = await fetch('/api/shifts-api/waivers');
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setWaivers(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleClaimShift = async (shiftId: string, slotId: string) => {
    if (!memberId) {
      alert('Please enter your member ID first');
      return;
    }

    try {
      const response = await fetch(
        `/api/shifts-api/shifts/${memberId}/${slotId}`,
        {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ shiftId }),
        }
      );

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // Refresh the shifts list
      fetchShifts();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleReleaseShift = async (slotId: string) => {
    if (!memberId) {
      alert('Please enter your member ID first');
      return;
    }

    try {
      const response = await fetch(
        `/api/shifts-api/shifts/${memberId}/${slotId}`,
        {
          method: 'DELETE',
        }
      );

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // Refresh the shifts list
      fetchShifts();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleCreateWaiver = async (boardMemberId: string, claimedMemberId: string, waivedSlotId: string) => {
    try {
      const response = await fetch('/api/shifts-api/waivers', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ boardMemberId, claimedMemberId, waivedSlotId }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // Refresh the waivers list
      fetchWaivers();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteWaiver = async (boardMemberId: string, claimedMemberId: string, waivedSlotId: string) => {
    try {
      const response = await fetch(
        `/api/shifts-api/waivers/${boardMemberId}/${claimedMemberId}/${waivedSlotId}`,
        {
          method: 'DELETE',
        }
      );

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // Refresh the waivers list
      fetchWaivers();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Shift Claim Board</h1>

      <div style={{ marginBottom: '20px' }}>
        <label htmlFor="memberId" style={{ display: 'block', marginBottom: '5px' }}>
          Your Member ID:
        </label>
        <input
          id="memberId"
          type="text"
          value={memberId}
          onChange={(e) => setMemberId(e.target.value)}
          style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
        />
      </div>

      <h2>Open Shifts</h2>
      {shifts.length === 0 ? (
        <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No open shifts available.</p>
      ) : (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
          {shifts.map((shift) => (
            <div key={shift.id} style={{
              border: '1px solid #ccc',
              borderRadius: '8px',
              padding: '10px',
              minWidth: '200px',
              flex: '1 1 calc(50% - 10px)',
            }}>
              <h3>{shift.position}</h3>
              <p><strong>Date:</strong> {shift.date}</p>
              <p><strong>Time:</strong> {shift.startTime} - {shift.endTime}</p>
              {shift.claimedBy ? (
                <p><strong>Claimed by:</strong> {shift.claimedBy}</p>
              ) : (
                <button
                  onClick={() => handleClaimShift(shift.id, shift.slotId)}
                  style={{
                    backgroundColor: '#007bff',
                    color: 'white',
                    border: 'none',
                    padding: '8px 12px',
                    borderRadius: '4px',
                    cursor: 'pointer',
                  }}
                >
                  Claim Shift
                </button>
              )}
            </div>
          ))}
        </div>
      )}

      <h2>My Waivers</h2>
      {waivers.length === 0 ? (
        <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No waivers found.</p>
      ) : (
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ borderBottom: '1px solid #ccc' }}>
              <th style={{ padding: '8px', textAlign: 'left' }}>Board Member</th>
              <th style={{ padding: '8px', textAlign: 'left' }}>Claimed Member</th>
              <th style={{ padding: '8px', textAlign: 'left' }}>Slot ID</th>
              <th style={{ padding: '8px', textAlign: 'left' }}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {waivers.map((waiver, index) => (
              <tr key={index} style={{ borderBottom: '1px solid #eee' }}>
                <td style={{ padding: '8px' }}>{waiver.boardMemberId}</td>
                <td style={{ padding: '8px' }}>{waiver.claimedMemberId}</td>
                <td style={{ padding: '8px' }}>{waiver.waivedSlotId}</td>
                <td style={{ padding: '8px' }}>
                  <button
                    onClick={() => handleDeleteWaiver(waiver.boardMemberId, waiver.claimedMemberId, waiver.waivedSlotId)}
                    style={{
                      backgroundColor: '#dc3545',
                      color: 'white',
                      border: 'none',
                      padding: '4px 8px',
                      borderRadius: '4px',
                      cursor: 'pointer',
                      marginRight: '5px',
                    }}
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <h2>Create Waiver</h2>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
        <input
          type="text"
          placeholder="Board Member ID"
          style={{ padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
        />
        <input
          type="text"
          placeholder="Claimed Member ID"
          style={{ padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
        />
        <input
          type="text"
          placeholder="Slot ID"
          style={{ padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
        />
        <button
          onClick={() => {
            // In a real app, we'd get values from the inputs above
            // For now, just showing how to call the API
            alert('In a real implementation, this would create a waiver');
          }}
          style={{
            backgroundColor: '#28a745',
            color: 'white',
            border: 'none',
            padding: '8px 12px',
            borderRadius: '4px',
            cursor: 'pointer',
          }}
