{"code":"import { useEffect, useState } from "react";

interface Book {
  id: number;
  title: string;
  author: string;
  status: 'not_started' | 'in_progress' | 'completed';
}

export function ReadingProgressView() {
  const [books, setBooks] = useState<Book[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchBooks();
  }, []);

  const fetchBooks = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/books-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch books: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setBooks(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const updateBookStatus = async (id: number, status: Book['status']) => {
    try {
      const response = await fetch(`/api/books-api/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ status }),
      });

      if (!response.ok) {
        throw new Error(`Failed to update book: ${response.status} ${response.statusText}`);
      }

      // Refresh the list after successful update
      await fetchBooks();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const deleteBook = async (id: number) => {
    try {
      const response = await fetch(`/api/books-api/${id}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error(`Failed to delete book: ${response.status} ${response.statusText}`);
      }

      // Refresh the list after successful deletion
      await fetchBooks();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (books.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No books found.</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Reading Progress</h1>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        {books.map(book => (
          <div key={book.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div>
                <h3 style={{ margin: '0 0 5px 0' }}>{book.title}</h3>
                <p style={{ margin: '0 0 5px 0', color: '#666' }}>{book.author}</p>
                <p style={{ margin: '0', color: '#666' }}>
                  Status: <span style={{ textTransform: 'capitalize' }}>{book.status.replace('_', ' ')}</span>
                </p>
              </div>
              <div style={{ display: 'flex', gap: '10px' }}>
                <button 
                  onClick={() => updateBookStatus(book.id, 'not_started')}
                  style={{ padding: '5px 10px', backgroundColor: '#f0f0f0', border: 'none', borderRadius: '4px' }}
                >
                  Not Started
                </button>
                <button 
                  onClick={() => updateBookStatus(book.id, 'in_progress')}
                  style={{ padding: '5px 10px', backgroundColor: '#f0f0f0', border: 'none', borderRadius: '4px' }}
                >
                  In Progress
                </button>
                <button 
                  onClick={() => updateBookStatus(book.id, 'completed')}
                  style={{ padding: '5px 10px', backgroundColor: '#f0f0f0', border: 'none', borderRadius: '4px' }}
                >
                  Completed
                </button>
                <button 
                  onClick={() => deleteBook(book.id)}
                  style={{ padding: '5px 10px', backgroundColor: '#ffdddd', border: 'none', borderRadius: '4px' }}
                >
                  Delete
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
