      <h2 style={{ textAlign: "center" }}>Available Beds</h2>

      {beds.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>
          No beds available.
        </p>
      ) : (
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            gap: "10px",
            justifyContent: "center",
