            <div
              key={bed.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: "8px",
                padding: "10px",
                minWidth: "150px",
                textAlign: "center",
                backgroundColor: bed.isAvailable ? "#f0fff0" : "#fff0f0",
