    padding: "8px",
    marginBottom: "12px",
    borderRadius: "4px",
    border: "1px solid #ddd",
    boxSizing: "border-box"
  };

  const buttonStyle: React.CSSProperties = {
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: "4px",
    padding: "8px 16px",
    cursor: "pointer",
    marginRight: "8px"
