{"code":"import { Router, type Request, type Response } from "express";
import { Order, insertOrder, getOrders, getOrderById } from "../db/orders-table";

export const router = Router();

router.get("/orders", (req: Request, res: Response) => {
  const orders = getOrders();
  res.json(orders);
});

router.get("/orders/:customerId", (req: Request, res: Response) => {
  const customerId = Number(req.params.customerId);
  const order = getOrderById(customerId);
  if (order) {
    res.json(order);
  } else {
    res.status(404).send(`Order with customer ID ${customerId} not found.`);
  }
});

router.post("/orders", (req: Request, res: Response) => {
  const order: Order = req.body;
  insertOrder(order);
  res.status(201).send("Order created successfully.");
});

router.put("/orders/:customerId", (req: Request, res: Response) => {
  const customerId = Number(req.params.customerId);
  const updatedOrder: Partial<Order> = req.body;
  const order = getOrderById(customerId);
  if (order) {
    if (updatedOrder.status === "completed") {
      order.status = updatedOrder.status;
      res.send(`Order with customer ID ${customerId} marked as completed.`);
    } else {
      res.status(400).send("Only status update to 'completed' is allowed.");
    }
  } else {
    res.status(404).send(`Order with customer ID ${customerId} not found.`);
  }
});
"}

