{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./walks.db");

interface WalkRow {
  id: number;
  ownerId: number;
  walkerId: number;
  date: string;
  status: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS walks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ownerId INTEGER NOT NULL,
    walkerId INTEGER NOT NULL,
    date TEXT NOT NULL,
    status TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllWalks(): WalkRow[] {
  const stmt = db.prepare("SELECT * FROM walks");
  return stmt.all() as unknown as WalkRow[];
}

export function getWalkById(id: number): WalkRow | undefined {
  const stmt = db.prepare("SELECT * FROM walks WHERE id = ?");
  return stmt.get(id) as unknown as WalkRow | undefined;
}

export function insertWalk(ownerId: number, walkerId: number, date: string, status: string): number {
  const stmt = db.prepare(
    "INSERT INTO walks (ownerId, walkerId, date, status) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(ownerId, walkerId, date, status);
  return Number(result.lastInsertRowid);
}

export function updateWalk(id: number, ownerId: number, walkerId: number, date: string, status: string): void {
  const stmt = db.prepare(
    "UPDATE walks SET ownerId = ?, walkerId = ?, date = ?, status = ? WHERE id = ?"
  );
  stmt.run(ownerId, walkerId, date, status, id);
}

export function deleteWalk(id: number): void {
  const stmt = db.prepare("DELETE FROM walks WHERE id = ?");
  stmt.run(id);
}

// Insert sample data if table is empty
if (getAllWalks().length === 0) {
  insertWalk(1, 2, "2023-06-15", "scheduled");
  insertWalk(3, 1, "2023-06-16", "completed");
  insertWalk(2, 3, "2023-06-17", "pending");
  insertWalk(4, 2, "2023-06-18", "scheduled");
  insertWalk(5, 1, "2023-06-19", "pending");
}
"}

