{"code":"import { useEffect, useState } from "react";

interface Shift {
  id: number;
  title: string;
  description: string;
  startTime: string;
  endTime: string;
  claimedBy?: string;
}

export function ShiftClaimBoard() {
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchShifts();
  }, []);

  const fetchShifts = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/shifts-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch shifts: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setShifts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleClaimShift = async (id: number) => {
    try {
      const response = await fetch(`/api/shifts-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ claimedBy: "current-user" }),
      });

      if (!response.ok) {
        throw new Error(`Failed to claim shift: ${response.status} ${response.statusText}`);
      }

      // Refresh the shifts list
      await fetchShifts();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (shifts.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No open shifts available.
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Open Shifts</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {shifts
          .filter(shift => !shift.claimedBy)
          .map(shift => (
            <div 
              key={shift.id} 
              style={{ 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                padding: "15px", 
                display: "flex", 
                flexDirection: "column", 
                gap: "10px"
              }}
            >
              <h2 style={{ margin: "0", fontSize: "1.2em" }}>{shift.title}</h2>
              <p style={{ margin: "0", color: "#555" }}>{shift.description}</p>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: "0.9em", color: "#666" }}>
                <span>{new Date(shift.startTime).toLocaleString()}</span>
                <span>{new Date(shift.endTime).toLocaleString()}</span>
              </div>
              <button 
                onClick={() => handleClaimShift(shift.id)}
                style={{ 
                  alignSelf: "flex-start", 
                  backgroundColor: "#007bff", 
                  color: "white", 
                  border: "none", 
                  borderRadius: "4px", 
                  padding: "8px 12px", 
                  cursor: "pointer", 
                  fontSize: "1em"
                }}
              >
                Claim Shift
              </button>
            </div>
          ))}
      </div>
    </div>
  );
}
"}

