{"code":"import { useEffect, useState } from "react";

interface Shift {
  id: string;
  startTime: string;
  endTime: string;
  claimedBy?: string;
}

export function ShiftClaimBoard() {
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchShifts();
  }, []);

  const fetchShifts = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/shifts-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch shifts: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setShifts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleClaim = async (shiftId: string) => {
    try {
      const response = await fetch(`/api/shifts-api/${shiftId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ claimedBy: "current-user" }),
      });

      if (!response.ok) {
        throw new Error(`Failed to claim shift: ${response.status} ${response.statusText}`);
      }

      // Refresh the shifts list
      await fetchShifts();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleUnclaim = async (shiftId: string) => {
    try {
      const response = await fetch(`/api/shifts-api/${shiftId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ claimedBy: null }),
      });

      if (!response.ok) {
        throw new Error(`Failed to unclaim shift: ${response.status} ${response.statusText}`);
      }

      // Refresh the shifts list
      await fetchShifts();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (shifts.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No open shifts available for today.
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Open Shifts</h1>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
        {shifts.map((shift) => (
          <div 
            key={shift.id} 
            style={{ 
              border: "1px solid #ccc", 
              borderRadius: "8px", 
              padding: "15px", 
              width: "100%", 
              maxWidth: "300px"
            }}
          >
            <div style={{ marginBottom: "10px" }}>
              <strong>Start:</strong> {new Date(shift.startTime).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}
            </div>
            <div style={{ marginBottom: "10px" }}>
              <strong>End:</strong> {new Date(shift.endTime).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}
            </div>
            <div style={{ marginBottom: "10px" }}>
              {shift.claimedBy ? (
                <span>Claimed by: {shift.claimedBy}</span>
              ) : (
                <span>Open for claiming</span>
              )}
            </div>
            <div>
              {shift.claimedBy ? (
                <button 
                  onClick={() => handleUnclaim(shift.id)}
                  style={{ 
                    backgroundColor: "#f44336", 
                    color: "white", 
                    border: "none", 
                    padding: "8px 12px", 
                    borderRadius: "4px", 
                    cursor: "pointer"
                  }}
                >
                  Unclaim
                </button>
              ) : (
                <button 
                  onClick={() => handleClaim(shift.id)}
                  style={{ 
                    backgroundColor: "#4CAF50", 
                    color: "white", 
                    border: "none", 
                    padding: "8px 12px", 
                    borderRadius: "4px", 
                    cursor: "pointer"
                  }}
                >
                  Claim
                </button>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "./backend/src/db/short-urls.db"
);

interface ShortUrlRow {
  id: number;
  short_code: string;
  target_url: string;
  created_at: string;
  visits: number;
  last_visit_at: string | null;
  last_visit_country: string | null;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS short_urls (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    short_code TEXT UNIQUE NOT NULL,
    target_url TEXT NOT NULL,
    created_at TEXT NOT NULL,
    visits INTEGER DEFAULT 0,
    last_visit_at TEXT,
    last_visit_country TEXT
  )
`;

db.exec(createTableSql);

export function getAllShortUrls(): ShortUrlRow[] {
  const stmt = db.prepare(`SELECT * FROM short_urls ORDER BY created_at DESC`);
  return stmt.all() as unknown as ShortUrlRow[];
}

export function getShortUrlById(id: number): ShortUrlRow | undefined {
  const stmt = db.prepare(
    `SELECT * FROM short_urls WHERE id = ?`
  );
  return stmt.get(id) as ShortUrlRow | undefined;
}

export function insertShortUrl(
  shortCode: string,
  targetUrl: string
): number {
  const stmt = db.prepare(
    `INSERT INTO short_urls (short_code, target_url, created_at) VALUES (?, ?, datetime('now'))`
  );
  const result = stmt.run(shortCode, targetUrl);
  return Number(result.lastInsertRowid);
}

export function updateShortUrlVisit(
  id: number,
  country: string | null
): void {
  const stmt = db.prepare(
    `UPDATE short_urls SET visits = visits + 1, last_visit_at = datetime('now'), last_visit_country = ? WHERE id = ?`
  );
  stmt.run(country, id);
}

export function deleteShortUrl(id: number): void {
  const stmt = db.prepare(`DELETE FROM short_urls WHERE id = ?`);
  stmt.run(id);
}

// Insert sample data if table is empty
if (getAllShortUrls().length === 0) {
  const sampleData = [
    { shortCode: "abc123", targetUrl: "https://example.com" },
    { shortCode: "xyz789", targetUrl: "https://github.com" },
    { shortCode: "def456", targetUrl: "https://stackoverflow.com" },
    { shortCode: "ghi789", targetUrl: "https://nodejs.org" },
    { shortCode: "jkl012", targetUrl: "https://typescriptlang.org" }
  ];

  for (const { shortCode, targetUrl } of sampleData) {
    insertShortUrl(shortCode, targetUrl);
  }
}
"}

