{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteRegistration,
  getAllRegistrations,
  getRegistrationById,
  insertRegistration,
  updateRegistration
} from "../db/registrations-table";

export const router = Router();

// Get all registrations
router.get("/", (req: Request, res: Response) => {
  const registrations = getAllRegistrations();
  res.json(registrations);
});

// Get a registration by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid registration ID" });
  }

  const registration = getRegistrationById(id);

  if (!registration) {
    return res.status(404).json({ error: "Registration not found" });
  }

  res.json(registration);
});

// Create a new registration
router.post("/", (req: Request, res: Response) => {
  const { camperId, sessionDate, parentContactId } = req.body;

  if (!camperId || !sessionDate || !parentContactId) {
    return res.status(400).json({ error: "Missing required fields: camperId, sessionDate, parentContactId" });
  }

  const newId = insertRegistration(camperId, sessionDate, parentContactId);

  // Fetch the created registration to send back
  const createdRegistration = getRegistrationById(newId);

  if (!createdRegistration) {
    return res.status(500).json({ error: "Failed to retrieve created registration" });
  }

  res.status(201).json(createdRegistration);
});

// Update a registration
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { camperId, sessionDate, parentContactId } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid registration ID" });
  }

  if (!camperId || !sessionDate || !parentContactId) {
    return res.status(400).json({ error: "Missing required fields: camperId, sessionDate, parentContactId" });
  }

  const existingRegistration = getRegistrationById(id);

  if (!existingRegistration) {
    return res.status(404).json({ error: "Registration not found" });
  }

  updateRegistration(id, camperId, sessionDate, parentContactId);

  const updatedRegistration = getRegistrationById(id);

  if (!updatedRegistration) {
    return res.status(500).json({ error: "Failed to retrieve updated registration" });
  }

  res.json(updatedRegistration);
});

// Delete a registration
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid registration ID" });
  }

  const existingRegistration = getRegistrationById(id);

  if (!existingRegistration) {
    return res.status(404).json({ error: "Registration not found" });
  }

  deleteRegistration(id);

  res.json({ message: "Registration deleted successfully" });
});
"}

