{"code":"import { useEffect, useState } from "react";

interface Reservation {
  id: number;
  vendorName: string;
  stallNumber: number;
  reservationDate: string;
}

export function StallReservationForm() {
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [vendorName, setVendorName] = useState("");
  const [stallNumber, setStallNumber] = useState("");

  useEffect(() => {
    fetchReservations();
  }, []);

  const fetchReservations = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/reservations-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch reservations: ${response.status}`);
      }
      const data = await response.json();
      setReservations(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const newReservation = {
        vendorName,
        stallNumber: Number(stallNumber),
        reservationDate: new Date().toISOString().split('T')[0]
      };

      const response = await fetch("/api/reservations-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newReservation)
      });

      if (!response.ok) {
        throw new Error(`Failed to create reservation: ${response.status}`);
      }

      // Reset form
      setVendorName("");
      setStallNumber("");

      // Refresh reservations
      await fetchReservations();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Weekend Stall Reservation</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="vendorName" style={{ display: "block", marginBottom: "5px" }}>
            Vendor Name
          </label>
          <input
            id="vendorName"
            type="text"
            value={vendorName}
            onChange={(e) => setVendorName(e.target.value)}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="stallNumber" style={{ display: "block", marginBottom: "5px" }}>
            Stall Number
          </label>
          <input
            id="stallNumber"
            type="number"
            value={stallNumber}
            onChange={(e) => setStallNumber(e.target.value)}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: "#007bff", 
            color: "white", 
            border: "none", 
            padding: "10px 20px", 
            borderRadius: "4px", 
            cursor: "pointer" 
          }}
        >
          Reserve Stall
        </button>
      </form>

      <h2 style={{ textAlign: "center" }}>Current Reservations</h2>

      {reservations.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No reservations yet.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {reservations.map((reservation) => (
            <div 
              key={reservation.id} 
              style={{ 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                padding: "15px", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center" 
              }}
            >
              <div>
                <strong>{reservation.vendorName}</strong><br />
                Stall #{reservation.stallNumber}<br />
                Reserved on: {reservation.reservationDate}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

