    member_id INTEGER NOT NULL,
    machine_id INTEGER NOT NULL,
    report_timestamp TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllReports(): Report[] {
  const stmt = db.prepare(`
    SELECT * FROM reports
  `);
  return stmt.all() as unknown as Report[];
}

export function getReportById(id: number): Report | undefined {
  const stmt = db.prepare(`
    SELECT * FROM reports WHERE id = ?
  `);
  return stmt.get(id) as unknown as Report | undefined;
}

export function insertReport(
  member_id: number,
  machine_id: number,
  report_timestamp: string
): number {
  const stmt = db.prepare(`
    INSERT INTO reports (member_id, machine_id, report_timestamp)
    VALUES (?, ?, ?)
  `);
  const result = stmt.run(member_id, machine_id, report_timestamp);
  return Number(result.lastInsertRowid);
}

