{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./auditions.db");

interface Audition {
  actor_id: number;
  show_id: number;
  slot_id: number;
  casting_note: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS auditions (
    actor_id INTEGER NOT NULL,
    show_id INTEGER NOT NULL,
    slot_id INTEGER NOT NULL,
    casting_note TEXT NOT NULL,
    PRIMARY KEY (actor_id, show_id, slot_id)
  )
`;

db.exec(createTableSql);

export function getAllAuditions(): Audition[] {
  const stmt = db.prepare("SELECT * FROM auditions");
  return stmt.all() as unknown as Audition[];
}

export function getAuditionById(
  actorId: number,
  showId: number,
  slotId: number
): Audition | undefined {
  const stmt = db.prepare(
    "SELECT * FROM auditions WHERE actor_id = ? AND show_id = ? AND slot_id = ?"
  );
  return stmt.get(actorId, showId, slotId) as unknown as Audition | undefined;
}

export function insertAudition(
  audition: Omit<Audition, "casting_note"> & { casting_note?: string }
): number {
  const sql = `
    INSERT OR REPLACE INTO auditions (actor_id, show_id, slot_id, casting_note)
    VALUES (?, ?, ?, ?)
  `;
  const result = db.prepare(sql).run(
    audition.actor_id,
    audition.show_id,
    audition.slot_id,
    audition.casting_note || ""
  );
  return Number(result.lastInsertRowid);
}

export function updateAudition(
  actorId: number,
  showId: number,
  slotId: number,
  castingNote: string
): number {
  const sql = `
    UPDATE auditions
    SET casting_note = ?
    WHERE actor_id = ? AND show_id = ? AND slot_id = ?
  `;
  const result = db.prepare(sql).run(castingNote, actorId, showId, slotId);
  return Number(result.changes);
}

export function deleteAudition(
  actorId: number,
  showId: number,
  slotId: number
): number {
  const sql = "DELETE FROM auditions WHERE actor_id = ? AND show_id = ? AND slot_id = ?";
  const result = db.prepare(sql).run(actorId, showId, slotId);
  return Number(result.changes);
}

// Insert sample data if table is empty
