{"code":"import { useEffect, useState } from "react";

interface AuditRecord {
  id: string;
  dogName: string;
  ownerName: string;
  checkInTime: string;
  checkOutTime?: string;
}

export function SupervisorMode() {
  const [records, setRecords] = useState<AuditRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchAuditTrail();
  }, []);

  const fetchAuditTrail = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/audit-trail-service/');
      if (!response.ok) {
        throw new Error(`Failed to fetch audit trail: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setRecords(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/audit-trail-service/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error(`Failed to delete record: ${response.status} ${response.statusText}`);
      }
      // Refresh the list after deletion
      fetchAuditTrail();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (records.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No audit records found.</div>;
  }

  return (
    <div style={{
      fontFamily: 'system-ui, sans-serif',
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
    }}>
      <h1 style={{ textAlign: 'center' }}>Audit Trail</h1>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
        {records.map((record) => (
          <div 
            key={record.id}
            style={{
              border: '1px solid #ccc',
              borderRadius: '8px',
              padding: '15px',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
            }}
          >
            <div>
              <p><strong>Dog Name:</strong> {record.dogName}</p>
              <p><strong>Owner Name:</strong> {record.ownerName}</p>
              <p><strong>Check In:</strong> {new Date(record.checkInTime).toLocaleString()}</p>
              {record.checkOutTime && (
                <p><strong>Check Out:</strong> {new Date(record.checkOutTime).toLocaleString()}</p>
              )}
            </div>
            <button 
              onClick={() => handleDelete(record.id)}
              style={{
                backgroundColor: '#ff4d4d',
                color: 'white',
                border: 'none',
                borderRadius: '4px',
                padding: '8px 12px',
                cursor: 'pointer',
              }}
            >
              Delete
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
"}

