      const response = await fetch("/api/attendance-records-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newRecord)
      });
      if (!response.ok) {
        throw new Error(`Failed to create record: ${response.status}`);
      }
      // Reset form
      setNewRecord({
        singerName: "",
        date: "",
        status: "present"
