{"code":"import { Router, type Request, type Response } from "express";
import { getRoomById } from "../db/rooms-table";
import { getReassignmentById, insertReassignment } from "../db/reassignments-table";

export const router = Router();

router.post("/reassignments", (req: Request, res: Response) => {
  const { supervisorId, sourceHousekeeperId, targetHousekeeperId, roomId } = req.body;

  // Validate input
  if (
    typeof supervisorId !== "number" ||
    typeof sourceHousekeeperId !== "number" ||
    typeof targetHousekeeperId !== "number" ||
    typeof roomId !== "number"
  ) {
    return res.status(400).json({ error: "Invalid input data" });
  }

  // Check if the target housekeeper already has the room assigned
  const room = getRoomById(roomId);
  if (!room) {
    return res.status(404).json({ error: "Room not found" });
  }

  if (room.assigned_housekeeper_id === targetHousekeeperId) {
    return res.status(400).json({ error: "Target housekeeper already has this room assigned" });
  }

  // Proceed with reassignment
  const reassignmentId = insertReassignment(
    supervisorId,
    sourceHousekeeperId,
    targetHousekeeperId,
    roomId
  );

  return res.status(201).json({ id: reassignmentId });
});
"}

{"code":"import { useEffect, useState } from "react";

export function MeetingRoomUi() {
  const [sessionData, setSessionData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newSessionId, setNewSessionId] = useState("");
  const [screenShareActive, setScreenShareActive] = useState(false);
  const [reaction, setReaction] = useState<"like" | "love" | "laugh" | null>(null);
  const [pollQuestion, setPollQuestion] = useState("");
  const [pollOptions, setPollOptions] = useState([""]);
  const [chatMessage, setChatMessage] = useState("");
  const [chatMessages, setChatMessages] = useState<any[]>([]);

  // Fetch session data
  useEffect(() => {
    const fetchSession = async () => {
      try {
        const response = await fetch(`/api/conferencing-server/`);
        if (!response.ok) throw new Error(`Failed to fetch sessions: ${await response.text()}`);
        const data = await response.json();
        setSessionData(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchSession();
  }, []);

  const handleCreateSession = async () => {
    try {
      const response = await fetch(`/api/conferencing-server/create-session`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({}),
      });
      if (!response.ok) throw new Error(`Failed to create session: ${await response.text()}`);
      const data = await response.json();
      setNewSessionId(data.id);
      // Refresh session list
      const refreshResponse = await fetch(`/api/conferencing-server/`);
      if (refreshResponse.ok) {
        const refreshedData = await refreshResponse.json();
        setSessionData(refreshedData);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleJoinSession = async (id: string) => {
    try {
      const response = await fetch(`/api/conferencing-server/session/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "join" }),
      });
      if (!response.ok) throw new Error(`Failed to join session: ${await response.text()}`);
      window.location.href = `/meeting/${id}`;
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEndSession = async (id: string) => {
    try {
      const response = await fetch(`/api/conferencing-server/session/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) throw new Error(`Failed to end session: ${await response.text()}`);
      // Refresh session list
      const refreshResponse = await fetch(`/api/conferencing-server/`);
      if (refreshResponse.ok) {
        const refreshedData = await refreshResponse.json();
        setSessionData(refreshedData);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const toggleScreenShare = () => {
    setScreenShareActive(!screenShareActive);
  };

  const sendReaction = (type: "like" | "love" | "laugh") => {
    setReaction(type);
    setTimeout(() => setReaction(null), 2000);
  };

  const createPoll = async () => {
    try {
      const response = await fetch(`/api/conferencing-server/session/${sessionData?.[0]?.id}/poll`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ question: pollQuestion, options: pollOptions }),
      });
      if (!response.ok) throw new Error(`Failed to create poll: ${await response.text()}`);
      setPollQuestion("");
      setPollOptions([""]);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const sendMessage = async () => {
    if (!chatMessage.trim()) return;
    try {
      const response = await fetch(`/api/conferencing-server/session/${sessionData?.[0]?.id}/chat`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: chatMessage }),
      });
      if (!response.ok) throw new Error(`Failed to send message: ${await response.text()}`);
      setChatMessage("");
      // In a real app, we'd update chatMessages here
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Meeting Room</h1>

      <div style={{ marginBottom: "20px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <button onClick={handleCreateSession} style={{ padding: "10px 15px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "5px", cursor: "pointer" }}>
          Create New Session
        </button>

        {newSessionId && (
          <div style={{ backgroundColor: "#d4edda", padding: "10px", borderRadius: "5px", color: "#155724" }}>
            Created session ID: {newSessionId}
          </div>
        )}
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h2>Active Sessions</h2>
        {sessionData && sessionData.length > 0 ? (
          <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
            {sessionData.map((session: any) => (
              <div key={session.id} style={{ border: "1px solid #ccc", padding: "10px", borderRadius: "5px", minWidth: "200px" }}>
                <p><strong>ID:</strong> {session.id}</p>
                <p><strong>Status:</strong> {session.status}</p>
                <div style={{ marginTop: "10px", display: "flex", gap: "5px" }}>
                  <button 
                    onClick={() => handleJoinSession(session.id)}
                    style={{ padding: "5px 10px", backgroundColor: "#28a745", color: "white", border: "none", borderRadius: "3px", cursor: "pointer" }}
                  >
                    Join
                  </button>
                  <button 
                    onClick={() => handleEndSession(session.id)}
                    style={{ padding: "5px 10px", backgroundColor: "#dc3545", color: "white", border: "none", borderRadius: "3px", cursor: "pointer" }}
                  >
                    End
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p>No active sessions found.</p>
        )}
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h2>Controls</h2>
        <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
          <button 
            onClick={toggleScreenShare}
            style={{ padding: "10px 15px", backgroundColor: screenShareActive ? "#dc3545" : "#007bff", color: "white", border: "none", borderRadius: "5px", cursor: "pointer" }}
          >
            {screenShareActive ? "Stop Sharing" : "Start Sharing Screen"}
          </button>

          <div style={{ display: "flex", gap: "5px" }}>
            <button 
              onClick={() => sendReaction("like")}
              style={{ padding: "5px 10px", backgroundColor: "#17a2b8", color: "white", border: "none", borderRadius: "3px", cursor: "pointer" }}
            >
              👍 Like
            </button>
            <button 
              onClick={() => sendReaction("love")}
              style={{ padding: "5px 10px", backgroundColor: "#17a2b8", color: "white", border: "none", borderRadius: "3px", cursor: "pointer" }}
            >
              ❤️ Love
            </button>
            <button 
              onClick={() => sendReaction("laugh")}
              style={{ padding: "5px 10px", backgroundColor: "#17a2b8", color: "white", border: "none", borderRadius: "3px", cursor: "pointer" }}
            >
              😂 Laugh
            </button>
          </div>
        </div>

        {reaction && (
          <div style={{ marginTop: "10px", padding: "10px", backgroundColor: "#f8f9fa", borderRadius: "5px" }}>
            Sent reaction: {reaction}
          </div>
        )}
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h2>Poll</h2>
        <input 
          type="text" 
          placeholder="Poll question" 
          value={pollQuestion}
          onChange={(e) => setPollQuestion(e.target.value)}
          style={{ width: "100%", padding: "10px", marginBottom: "10px" }}
        />

        <div style={{ marginBottom: "10px" }}>
          {pollOptions.map((option, index) => (
            <input 
              key={index}
              type="text" 
              placeholder={`Option ${index + 1}`}
              value={option}
              onChange={(e) => {
                const newOptions = [...pollOptions];
                newOptions[index] = e.target.value;
                setPollOptions(newOptions);
              }}
              style={{ width: "100%", padding: "10px", marginBottom: "5px" }}
            />
          ))}
          <button 
            onClick={() => setPollOptions([...pollOptions, ""])}
            style={{ padding: "5px 10px", backgroundColor: "#6c757d", color: "white", border: "none", borderRadius: "3px", cursor: "pointer" }}
          >
            Add Option
          </button>
        </div>

        <button 
          onClick={createPoll}
          style={{ padding: "10px 15px", backgroundColor: "#28a745", color: "white", border: "none", borderRadius: "5px", cursor: "pointer" }}
        >
          Create Poll
        </button>
      </div>

      <div>
        <h2>Chat</h2>
        <div style={{ height: "200px", overflowY: "auto", border: "1px solid #ccc", padding: "10px", marginBottom: "10px" }}>
          {chatMessages.length > 0 ? (
            chatMessages.map((msg, i) => (
              <div key={i} style={{ marginBottom: "5px" }}>
                <strong>{msg.user}:</strong> {msg.text}
              </div>
            ))
          ) : (
            <p>No messages yet.</p>
          )}
        </div>

        <div style={{ display: "flex", gap: "10px" }}>
          <input 
            type="text" 
            placeholder="Type your message..." 
            value={chatMessage}
            onChange={(e) => setChatMessage(e.target.value)}
            style={{ flex: 1, padding: "10px" }}
          />
          <button 
            onClick={sendMessage}
            style={{ padding: "10px 15px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "5px", cursor: "pointer" }}
          >
            Send
          </button>
        </div>
      </div>
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface Show {
  id: string;
  title: string;
}

interface Slot {
  id: string;
  time: string;
  showId: string;
}

interface Audition {
  actorId: string;
  showId: string;
  slotId: string;
}

export function AuditionSignupForm() {
  const [shows, setShows] = useState<Show[]>([]);
  const [slots, setSlots] = useState<Slot[]>([]);
  const [selectedShowId, setSelectedShowId] = useState<string | null>(null);
  const [selectedSlotId, setSelectedSlotId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    fetchShows();
  }, []);

  const fetchShows = async () => {
    try {
      const response = await fetch("/api/auditions-api/");
      if (!response.ok) throw new Error("Failed to fetch shows");
      const data = await response.json();
      setShows(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const fetchSlots = async (showId: string) => {
    try {
      const response = await fetch(`/api/auditions-api/${showId}`);
      if (!response.ok) throw new Error("Failed to fetch slots");
      const data = await response.json();
      setSlots(data);
      setSelectedShowId(showId);
      setSelectedSlotId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleSignup = async () => {
    if (!selectedShowId || !selectedSlotId) return;

    try {
      const response = await fetch(`/api/auditions-api/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          actorId: "currentActorId", // This would come from auth context in a real app
          showId: selectedShowId,
          slotId: selectedSlotId
        })
      });

      if (!response.ok) throw new Error("Failed to sign up for audition");
      setSuccess(true);
      setTimeout(() => {
        setSuccess(false);
        fetchShows();
      }, 2000);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={containerStyle}>
      <h1>Audition Signup</h1>

      {success && (
        <div style={{ backgroundColor: "lightgreen", padding: "10px", borderRadius: "5px", marginBottom: "10px" }}>
          Successfully signed up!
        </div>
      )}

      <div style={{ marginBottom: "20px" }}>
        <h2>Select a Show</h2>
        <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
          {shows.map((show) => (
            <button
              key={show.id}
              onClick={() => fetchSlots(show.id)}
              style={showButtonStyle}
            >
              {show.title}
            </button>
          ))}
        </div>
      </div>

      {selectedShowId && (
        <div style={{ marginBottom: "20px" }}>
          <h2>Select a Time Slot</h2>
          <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
            {slots.length > 0 ? (
              slots.map((slot) => (
                <button
                  key={slot.id}
                  onClick={() => setSelectedSlotId(slot.id)}
                  style={slotButtonStyle(selectedSlotId === slot.id)}
                >
                  {slot.time}
                </button>
              ))
            ) : (
              <p>No available slots</p>
            )}
          </div>
        </div>
      )}

      {selectedSlotId && (
        <button
          onClick={handleSignup}
          style={signupButtonStyle}
        >
          Sign Up for Audition
        </button>
      )}
    </div>
  );
}

const containerStyle = {
  maxWidth: "600px",
  margin: "0 auto",
  padding: "20px",
  fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
};

const showButtonStyle = {
  padding: "10px 15px",
  border: "1px solid #ccc",
  borderRadius: "5px",
  backgroundColor: "#f9f9f9",
  cursor: "pointer"
};

const slotButtonStyle = (isSelected: boolean) => ({
  padding: "10px 15px",
  border: isSelected ? "2px solid #007bff" : "1px solid #ccc",
  borderRadius: "5px",
  backgroundColor: isSelected ? "#e3f2fd" : "#f9f9f9",
  cursor: "pointer"
});

const signupButtonStyle = {
  padding: "12px 20px",
  backgroundColor: "#007bff",
  color: "white",
  border: "none",
  borderRadius: "5px",
  cursor: "pointer",
  fontSize: "16px",
  width: "100%"
};
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./bike-share-fleet.db");

interface Record {
  id: number;
  bike_id: number;
  mechanic_id: number;
  description: string;
  status: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS records (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    bike_id INTEGER NOT NULL,
    mechanic_id INTEGER NOT NULL,
    description TEXT NOT NULL,
    status TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllRecords(): Record[] {
  const stmt = db.prepare("SELECT * FROM records");
  return stmt.all() as unknown as Record[];
}

export function getRecordById(id: number): Record | undefined {
  const stmt = db.prepare("SELECT * FROM records WHERE id = ?");
  return stmt.get(id) as Record | undefined;
}

export function insertRecord(
  bikeId: number,
  mechanicId: number,
  description: string,
  status: string
): number {
  const stmt = db.prepare(
    "INSERT INTO records (bike_id, mechanic_id, description, status) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(bikeId, mechanicId, description, status);
  return Number(result.lastInsertRowid);
}

export function updateRecord(
  id: number,
  bikeId: number,
  mechanicId: number,
  description: string,
  status: string
): void {
  const stmt = db.prepare(
    "UPDATE records SET bike_id = ?, mechanic_id = ?, description = ?, status = ? WHERE id = ?"
  );
  stmt.run(bikeId, mechanicId, description, status, id);
}

export function deleteRecord(id: number): void {
  const stmt = db.prepare("DELETE FROM records WHERE id = ?");
  stmt.run(id);
}

// Insert sample data if table is empty
if (getAllRecords().length === 0) {
  insertRecord(1, 101, "Replace brake pads", "Completed");
  insertRecord(2, 102, "Oil change", "In Progress");
  insertRecord(3, 103, "Tire patch", "Pending");
  insertRecord(4, 101, "Chain lubrication", "Completed");
  insertRecord(5, 104, "Wheel alignment", "Pending");
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import { Order, insertOrder, getOrders, getOrderById } from "../db/orders-table";

export const router = Router();

router.get("/orders", (req: Request, res: Response) => {
  const orders = getOrders();
  res.json(orders);
});

router.get("/orders/:customerId", (req: Request, res: Response) => {
  const customerId = Number(req.params.customerId);
  const order = getOrderById(customerId);
  if (order) {
    res.json(order);
  } else {
    res.status(404).send(`Order with customer ID ${customerId} not found.`);
  }
});

router.post("/orders", (req: Request, res: Response) => {
  const order: Order = req.body;
  insertOrder(order);
  res.status(201).send("Order created successfully.");
});

router.put("/orders/:customerId", (req: Request, res: Response) => {
  const customerId = Number(req.params.customerId);
  const updatedOrder: Partial<Order> = req.body;
  const order = getOrderById(customerId);
  if (order) {
    if (updatedOrder.status === "completed") {
      order.status = updatedOrder.status;
      res.send(`Order with customer ID ${customerId} marked as completed.`);
    } else {
      res.status(400).send("Only status update to 'completed' is allowed.");
    }
  } else {
    res.status(404).send(`Order with customer ID ${customerId} not found.`);
  }
});
"}

{"code":"import { useEffect, useState } from "react";

export function OwnerOnlyExportPanel() {
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await fetch('/api/usage-api');
        if (!response.ok) {
          throw new Error(`Failed to fetch data: ${response.status} ${response.statusText}`);
        }
        const result = await response.json();
        setData(result);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleDownload = () => {
    // Convert data to CSV format
    const headers = ['Member ID', 'Usage (kWh)', 'Date'];
    const csvContent = [
      headers.join(','),
      ...data.map(row => `${row.memberId},${row.usageKwh},${row.date}`)
    ].join('\n');

    // Create a Blob and download link
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'usage-data.csv');
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui' }}>
      <h1 style={{ textAlign: 'center' }}>Owner-Only Export Panel</h1>
      <p style={{ textAlign: 'center' }}>Download the full dataset as CSV</p>

      <div style={{ textAlign: 'center', marginBottom: '20px' }}>
        <button 
          onClick={handleDownload}
          style={{ 
            backgroundColor: '#007bff', 
            color: 'white', 
            border: 'none', 
            padding: '10px 20px', 
            borderRadius: '5px', 
            cursor: 'pointer' 
          }}
        >
          Download CSV
        </button>
      </div>

      <div style={{ 
        border: '1px solid #ccc', 
        borderRadius: '5px', 
        padding: '10px', 
        overflowX: 'auto' 
      }}>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ backgroundColor: '#f2f2f2' }}>
              <th style={{ border: '1px solid #ddd', padding: '8px' }}>Member ID</th>
              <th style={{ border: '1px solid #ddd', padding: '8px' }}>Usage (kWh)</th>
              <th style={{ border: '1px solid #ddd', padding: '8px' }}>Date</th>
            </tr>
          </thead>
          <tbody>
            {data.length === 0 ? (
              <tr>
                <td colSpan={3} style={{ textAlign: 'center', padding: '10px' }}>
                  No data available
                </td>
              </tr>
            ) : (
              data.map((row, index) => (
                <tr key={index}>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{row.memberId}</td>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{row.usageKwh}</td>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{row.date}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply RBAC to POST, PUT, DELETE requests to commerce routes
  const isCommerceRoute = req.path.startsWith('/api/commerce');
  const isProtectedMethod = ['POST', 'PUT', 'DELETE'].includes(req.method);

  if (!isCommerceRoute || !isProtectedMethod) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: 'Server configuration error: JWT_SECRET not set' });
    return;
  }

  // Simple token validation (in a real system, you'd decode and verify JWT)
  const expectedToken = createHmac('sha256', secret).update(req.method + req.path).digest('hex');

  try {
    const expectedBuffer = Buffer.from(expectedToken);
    const actualBuffer = Buffer.from(token);

    if (actualBuffer.length !== expectedBuffer.length) {
      res.status(401).json({ error: 'Invalid token' });
      return;
    }

    const isValid = timingSafeEqual(expectedBuffer, actualBuffer);

    if (!isValid) {
      res.status(401).json({ error: 'Invalid token' });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: 'Invalid token' });
  }
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to the override path
  if (req.method !== "POST" || req.path !== "/override") {
    next();
    return;
  }

  // Check if the request has the required header
  const authHeader = req.headers["authorization"];
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation - in a real system, you'd decode and verify
  // the JWT signature properly. For this simplified example, we'll just
  // check if it matches a known valid token format.
  const expectedToken = createHmac("sha256", secret)
    .update("attendant_token")
    .digest("hex");

  const tokenBuffer = Buffer.from(token);
  const expectedBuffer = Buffer.from(expectedToken);

  try {
    // Use timingSafeEqual to prevent timing attacks
    if (timingSafeEqual(tokenBuffer, expectedBuffer)) {
      next();
    } else {
      res.status(401).json({ error: "Unauthorized" });
    }
  } catch {
    res.status(401).json({ error: "Unauthorized" });
  }
}
"}

