  const { memberId, kwhUsed, date } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid event ID" });
  }

  if (!memberId || !kwhUsed || !date) {
    return res.status(400).json({ error: "Member ID, kWh used, and date are required" });
  }

  const existingEvent = getUsageEventById(id);

  if (!existingEvent) {
    return res.status(404).json({ error: "Usage event not found" });
  }

  updateUsageEvent(id, memberId, kwhUsed, date);

  return res.json({ id, memberId, kwhUsed, date });
});

