  const [shows, setShows] = useState<Show[]>([]);
  const [auditions, setAuditions] = useState<Audition[]>([]);
  const [selectedShowId, setSelectedShowId] = useState<number | null>(null);
  const [actorName, setActorName] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchShows = async () => {
      try {
        const response = await fetch('/api/auditions-api/auditions');
        if (!response.ok) throw new Error('Failed to fetch shows');
        const data = await response.json();
        setShows(data);
      } catch (err) {
        setError('Error loading shows');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    const fetchAuditions = async () => {
      try {
        const response = await fetch('/api/auditions-api/auditions');
        if (!response.ok) throw new Error('Failed to fetch auditions');
        const data = await response.json();
        setAuditions(data);
      } catch (err) {
        setError('Error loading auditions');
        console.error(err);
      }
    };

    fetchShows();
    fetchAuditions();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedShowId || !actorName) return;

    try {
      const response = await fetch('/api/auditions-api/auditions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          showId: selectedShowId,
          actorName
        })
      });

      if (!response.ok) throw new Error('Failed to sign up');

      // Refresh data
      const showsResponse = await fetch('/api/auditions-api/auditions');
      const showsData = await showsResponse.json();
      setShows(showsData);

      const auditionsResponse = await fetch('/api/auditions-api/auditions');
      const auditionsData = await auditionsResponse.json();
      setAuditions(auditionsData);

      // Reset form
      setSelectedShowId(null);
      setActorName("");
    } catch (err) {
      setError('Error signing up');
      console.error(err);
    }
  };

  const handleDelete = async (actorId: number, showId: number) => {
    try {
      const response = await fetch(`/api/auditions-api/auditions/${actorId}/${showId}`, {
        method: 'DELETE'
      });

      if (!response.ok) throw new Error('Failed to delete audition');

      // Refresh data
      const auditionsResponse = await fetch('/api/auditions-api/auditions');
      const auditionsData = await auditionsResponse.json();
      setAuditions(auditionsData);
    } catch (err) {
      setError('Error deleting audition');
      console.error(err);
    }
