{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./community-pool.db");

interface Shift {
  id: number;
  date: string;
  capacity: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS shifts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    date TEXT NOT NULL,
    capacity INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllShifts(): Shift[] {
  const stmt = db.prepare("SELECT * FROM shifts");
  return stmt.all() as unknown as Shift[];
}

export function getShiftById(id: number): Shift | undefined {
  const stmt = db.prepare("SELECT * FROM shifts WHERE id = ?");
  return stmt.get(id) as unknown as Shift | undefined;
}

export function insertShift(date: string, capacity: number): number {
  const stmt = db.prepare(
    "INSERT INTO shifts (date, capacity) VALUES (?, ?)"
  );
  const result = stmt.run(date, capacity);
  return Number(result.lastInsertRowid);
}

export function updateShift(id: number, date: string, capacity: number): void {
  const stmt = db.prepare(
    "UPDATE shifts SET date = ?, capacity = ? WHERE id = ?"
  );
  stmt.run(date, capacity, id);
}

export function deleteShift(id: number): void {
  const stmt = db.prepare("DELETE FROM shifts WHERE id = ?");
  stmt.run(id);
}

// Insert sample data if table is empty
if (getAllShifts().length === 0) {
  insertShift("2023-06-15", 4);
  insertShift("2023-06-16", 6);
  insertShift("2023-06-17", 5);
  insertShift("2023-06-18", 3);
  insertShift("2023-06-19", 7);
}
"}

