        if (!response.ok) {
          throw new Error(`Failed to fetch export data: ${response.status} ${response.statusText}`);
        }
        const data = await response.json();
        setExportData(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchExportData();
  }, []);

  const handleDownload = async () => {
    try {
      const response = await fetch('/api/export-service/history', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error(`Failed to download export data: ${response.status} ${response.statusText}`);
      }

      const blob = await response.blob();
