  date: string;
}

export function MemberOnlyView() {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [description, setDescription] = useState("");
  const [amount, setAmount] = useState("");
  const [date, setDate] = useState("");

  useEffect(() => {
    fetchExpenses();
  }, []);

  const fetchExpenses = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/expenses-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setExpenses(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const newExpense = {
        description,
        amount: Number(amount),
        date,
      };
      const response = await fetch('/api/expenses-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newExpense),
      });
      if (!response.ok) {
        throw new Error(`Failed to submit: ${response.status} ${response.statusText}`);
      }
      setDescription("");
      setAmount("");
      setDate("");
      await fetchExpenses();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/expenses-api/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error(`Failed to delete: ${response.status} ${response.statusText}`);
      }
      await fetchExpenses();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>My Expenses</h1>

      {expenses.length === 0 ? (
        <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No expenses submitted yet.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {expenses.map(expense => (
            <div key={expense.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <div>
                  <strong>{expense.description}</strong>
                  <br />
                  Amount: ${expense.amount.toFixed(2)}
                  <br />
                  Date: {new Date(expense.date).toLocaleDateString()}
                </div>
                <button 
                  onClick={() => handleDelete(expense.id)}
                  style={{ backgroundColor: '#ff4d4d', color: 'white', border: 'none', borderRadius: '4px', padding: '5px 10px' }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      <h2 style={{ marginTop: '30px', textAlign: 'center' }}>Submit New Expense</h2>
      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
        <input
          type="text"
          placeholder="Description"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          required
        />
        <input
          type="number"
          placeholder="Amount"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
          style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          required
          step="0.01"
        />
        <input
          type="date"
          value={date}
          onChange={(e) => setDate(e.target.value)}
          style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          required
        />
        <button 
          type="submit" 
          style={{ backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', padding: '10px', cursor: 'pointer' }}
        >
          Submit Expense
        </button>
      </form>
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./equipment.db");

interface EquipmentStock {
  id: number;
  name: string;
  stock_count: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS equipment_stock (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    stock_count INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllEquipment(): EquipmentStock[] {
  const stmt = db.prepare(`SELECT * FROM equipment_stock`);
  return stmt.all() as unknown as EquipmentStock[];
}

export function getEquipmentById(id: number): EquipmentStock | undefined {
  const stmt = db.prepare(`SELECT * FROM equipment_stock WHERE id = ?`);
  return stmt.get(id) as unknown as EquipmentStock | undefined;
}

export function insertEquipment(name: string, stock_count: number): number {
  const stmt = db.prepare(
    `INSERT INTO equipment_stock (name, stock_count) VALUES (?, ?)`
  );
  const result = stmt.run(name, stock_count);
  return Number(result.lastInsertRowid);
}

export function updateEquipment(
  id: number,
  name: string,
  stock_count: number
): void {
  const stmt = db.prepare(
    `UPDATE equipment_stock SET name = ?, stock_count = ? WHERE id = ?`
  );
  stmt.run(name, stock_count, id);
}

export function deleteEquipment(id: number): void {
  const stmt = db.prepare(`DELETE FROM equipment_stock WHERE id = ?`);
  stmt.run(id);
}

// Seed data
if (getAllEquipment().length === 0) {
  insertEquipment("Camera Body", 5);
  insertEquipment("Lens Kit", 12);
  insertEquipment("Tripod", 8);
  insertEquipment("Flash Unit", 15);
  insertEquipment("Microphone", 10);
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import { insertDocument, getDocumentById, getAllDocuments } from "../db/documents-table";

export const router = Router();

router.post("/documents", (req: Request, res: Response) => {
  const { title, content, metadata } = req.body;
  if (typeof title !== "string" || typeof content !== "string" || typeof metadata !== "string") {
    res.status(400).send("Invalid input");
    return;
  }
  insertDocument(title, content, metadata);
  res.status(201).send("Document inserted");
});

router.get("/documents/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    res.status(400).send("Invalid document ID");
    return;
  }
  const document = getDocumentById(id);
  if (document) {
    res.json(document);
  } else {
    res.status(404).send("Document not found");
  }
});

router.get("/documents", (req: Request, res: Response) => {
  const documents = getAllDocuments();
  res.json(documents);
});
"}
